  customers: {
    keyPath: 'id',
    indexes: [
      { name: 'by_orgId', keyPath: 'organizationId' },
      { name: 'by_membershipTier', keyPath: 'membershipTier' },
    ],
  },

  orders: {
    keyPath: 'id',
    indexes: [
      { name: 'by_customerId', keyPath: 'customerId' },
      { name: 'by_orgId', keyPath: 'organizationId' },
      { name: 'by_storeId', keyPath: 'storeId' },
      { name: 'by_status', keyPath: 'status' },
