{"file_path": "/Users/tsiontesfaye/Projects/EaglePoint/retail-ops/repo/src/infrastructure/broadcast/broadcastManager.js", "content": "/**
 * BroadcastChannel wrapper for cross-tab coordination.
 *
 * Channels:
 *   - 'retailops:state'  — general state changes (lock, logout, version publish)
 *   - 'retailops:queue'  — queue leader election and heartbeat
 *
 * Message types (EVENT_TYPES) are declared here so all consumers
 * reference the same constants rather than magic strings.
 *
 * In Node 18 test environments, BroadcastChannel is shimmed in tests/setup.js.
 */

export const CHANNEL_NAMES = /** @type {const} */ ({
  STATE: 'retailops:state',
  QUEUE: 'retailops:queue',
});

export const EVENT_TYPES = /** @type {const} */ ({
  // Auth / session
  SESSION_LOCKED: 'session_locked',
  SESSION_UNLOCKED: 'session_unlocked',
  SESSION_LOGGED_OUT: 'session_logged_out',

  // Master data
  VERSION_PUBLISHED: 'version_published',

  // Queue leadership
  QUEUE_LEADER_CLAIM: 'queue_leader_claim',
  QUEUE_LEADER_HEARTBEAT: 'queue_leader_heartbeat',
  QUEUE_LEADER_RELEASE: 'queue_leader_release',

  // Risk / notifications
  RISK_CASE_UPDATED: 'risk_case_updated',
  NOTIFICATION_SENT: 'notification_sent',
});

/** @type {Map<string, BroadcastChannel>} */
const _channels = new Map();

/**
 * Opens a named BroadcastChannel (or returns the cached one).
 *
 * @param {string} name  One of CHANNEL_NAMES
 * @returns {BroadcastChannel}
 */
export function getChannel(name) {
  if (!_channels.has(name)) {
    _channels.set(name, new BroadcastChannel(name));
  }
  return _channels.get(name);
}

/**
 * Posts a typed message on the given channel.
 *
 * @param {string} channelName
 * @param {string} type  One of EVENT_TYPES
 * @param {unknown} [payload]
 */
export function broadcast(channelName, type, payload = null) {
  const channel = getChannel(channelName);
  channel.postMessage({ type, payload, timestamp: Date.now() });
}

/**
 * Registers a message listener on a channel.
 * Returns a cleanup function that removes the listener.
 *
 * @param {string} channelName
 * @param {(event: { type: string; payload: unknown; timestamp: number }) => void} handler
 * @returns {() => void}  cleanup function
 */
export function subscribe(channelName, handler) {
  const channel = getChannel(channelName);
  const wrapper = (event) => handler(event.data);
  channel.addEventListener('message', wrapper);
  return () => channel.removeEventListener('message', wrapper);
}

/**
 * Closes all open BroadcastChannels.
 * Called on logout or test teardown.
 */
export function closeAll() {
  for (const [, channel] of _channels) {
    channel.close();
  }
  _channels.clear();
}
"}

