          diff.push({ store: name, action: 'update', record });
        }
      }

      for (const [id, record] of existingMap) {
        if (!incomingMap.has(id)) {
          diff.push({ store: name, action: 'delete', record });
        }
      }
    }

    return diff;
  }
}
