    return cases.filter((c) => c.status === RISK_CASE_STATUSES.OPEN || c.status === RISK_CASE_STATUSES.IN_REVIEW);
  }

  // ── Private ──────────────────────────────────────────────────────────────────

  async _getOrThrow(caseId) {
