 * SchedulerService — periodic background tasks.
 *
 * Responsibilities:
 *   - queue retry processing       (every 30 seconds while leading)
 *   - ticket SLA overdue checks    (every 5 minutes while leading)
 *   - missed work reconciliation   (on startup)
 *
 * Multi-tab leader election:
 *   Only one tab should run the scheduler at a time.
 *   We use BroadcastChannel heartbeats with a leader timestamp in LocalStorage.
 *   If this tab wins the leader election it starts timers;
 *   other tabs stand by and take over if the leader goes silent.
 */

import { schedule, cancel, cancelAll } from '../infrastructure/scheduler/timerManager.js';
import {
  broadcast,
  subscribe,
  CHANNEL_NAMES,
  EVENT_TYPES,
} from '../infrastructure/broadcast/broadcastManager.js';
import { notificationService } from './NotificationService.js';
import { ticketService } from './TicketService.js';

const LEADER_KEY = 'retailops:queue_leader';
const LEADER_TTL_MS = 10_000;     // leader must heartbeat within 10 s
const HEARTBEAT_INTERVAL_MS = 5_000;
const QUEUE_CHECK_INTERVAL_MS = 30_000;
const OVERDUE_CHECK_INTERVAL_MS = 5 * 60_000;

export class SchedulerService {
  constructor() {
    this._isLeader = false;
    this._tabId = `tab_${Date.now()}_${Math.random().toString(36).slice(2, 6)}`;
    this._unsubscribe = null;
  }

  /**
   * Starts the scheduler.
   * - Reconciles any missed work from before the last app close.
   * - Participates in leader election.
   */
  async start() {
    await this._reconcileMissedWork();
    this._listenForLeaderEvents();
    this._attemptLeaderClaim();
  }

  /**
   * Stops all scheduler activity and releases leadership.
   */
  stop() {
    cancelAll();
    if (this._isLeader) {
      localStorage.removeItem(LEADER_KEY);
      broadcast(CHANNEL_NAMES.QUEUE, EVENT_TYPES.QUEUE_LEADER_RELEASE, { tabId: this._tabId });
      this._isLeader = false;
    }
    if (this._unsubscribe) {
      this._unsubscribe();
      this._unsubscribe = null;
    }
  }

  // ── Leader election ───────────────────────────────────────────────────────────

  _attemptLeaderClaim() {
    const existing = this._readLeaderState();
    const now = Date.now();

    if (!existing || now - existing.timestamp > LEADER_TTL_MS) {
      this._becomeLeader();
    } else {
      // Another tab is leading; stand by.
      schedule('scheduler:standby_check', () => this._attemptLeaderClaim(), LEADER_TTL_MS + 1000);
    }
  }

  _becomeLeader() {
    this._isLeader = true;
    this._writeLeaderState();
    broadcast(CHANNEL_NAMES.QUEUE, EVENT_TYPES.QUEUE_LEADER_CLAIM, { tabId: this._tabId });

    schedule('scheduler:heartbeat', () => this._heartbeat(), HEARTBEAT_INTERVAL_MS);
    schedule('scheduler:queue_check', () => this._processQueue(), QUEUE_CHECK_INTERVAL_MS);
    schedule('scheduler:overdue_check', () => this._checkOverdue(), OVERDUE_CHECK_INTERVAL_MS);
  }

  _heartbeat() {
    if (!this._isLeader) return;
    this._writeLeaderState();
    broadcast(CHANNEL_NAMES.QUEUE, EVENT_TYPES.QUEUE_LEADER_HEARTBEAT, { tabId: this._tabId });
    schedule('scheduler:heartbeat', () => this._heartbeat(), HEARTBEAT_INTERVAL_MS);
  }

  _listenForLeaderEvents() {
    this._unsubscribe = subscribe(CHANNEL_NAMES.QUEUE, (event) => {
      if (event.type === EVENT_TYPES.QUEUE_LEADER_CLAIM && event.payload.tabId !== this._tabId) {
        // Another tab won the election; yield.
        this._isLeader = false;
        cancel('scheduler:heartbeat');
        cancel('scheduler:queue_check');
        cancel('scheduler:overdue_check');
      }
      if (event.type === EVENT_TYPES.QUEUE_LEADER_RELEASE) {
        // Leader stepped down; try to claim.
        this._attemptLeaderClaim();
      }
    });
  }

  _readLeaderState() {
    try {
      const raw = localStorage.getItem(LEADER_KEY);
      return raw ? JSON.parse(raw) : null;
    } catch {
      return null;
    }
  }

  _writeLeaderState() {
    try {
      localStorage.setItem(LEADER_KEY, JSON.stringify({ tabId: this._tabId, timestamp: Date.now() }));
    } catch {
      // LocalStorage write failure is non-fatal.
    }
  }

  // ── Periodic tasks ────────────────────────────────────────────────────────────

  async _processQueue() {
    if (!this._isLeader) return;
    try {
      await notificationService.processDueItems();
    } catch (err) {
      console.error('[SchedulerService] Queue processing error:', err);
    }
    schedule('scheduler:queue_check', () => this._processQueue(), QUEUE_CHECK_INTERVAL_MS);
  }

  async _checkOverdue() {
    if (!this._isLeader) return;
    try {
      await ticketService.evaluateOverdue();
    } catch (err) {
      console.error('[SchedulerService] Overdue check error:', err);
    }
    schedule('scheduler:overdue_check', () => this._checkOverdue(), OVERDUE_CHECK_INTERVAL_MS);
  }

  /**
   * On startup, immediately processes items that should have fired while the app was closed.
   */
  async _reconcileMissedWork() {
    try {
      await notificationService.processDueItems();
      await ticketService.evaluateOverdue();
    } catch (err) {
      console.error('[SchedulerService] Startup reconciliation error:', err);
    }
  }
}

export const schedulerService = new SchedulerService();
