{"file_path": "/Users/tsiontesfaye/Projects/EaglePoint/retail-ops/repo/src/app/router/Router.svelte", "content": "<script>
  import { onMount, onDestroy } from 'svelte';
  import { routes, DEFAULT_ROUTE, PUBLIC_ROUTES, ROLE_ROUTES } from './routes.js';
  import { currentPath, navigate } from '../stores/ui.js';
  import { isAuthenticated, isGuest, currentRole } from '../stores/auth.js';

  let CurrentPage = null;

  function resolvePageComponent(path, authenticated, guest, role) {
    // Unauthenticated users are redirected to login.
    if (!authenticated && !guest && !PUBLIC_ROUTES.has(path)) {
      navigate('/login');
      return routes['/login'];
    }

    // Check role-based access.
    if (authenticated && role) {
      const allowed = ROLE_ROUTES[role] ?? new Set();
      if (!PUBLIC_ROUTES.has(path) && !allowed.has(path)) {
        // Redirect to a default accessible route for the role.
        const defaultForRole = [...allowed][0] ?? '/login';
        navigate(defaultForRole);
        return routes[defaultForRole] ?? routes[DEFAULT_ROUTE];
      }
    }

    return routes[path] ?? routes[DEFAULT_ROUTE];
  }

  function onHashChange() {
    const path = window.location.hash.slice(1) || DEFAULT_ROUTE;
    currentPath.set(path);
  }

  onMount(() => {
    onHashChange();
    window.addEventListener('hashchange', onHashChange);
  });

  onDestroy(() => {
    window.removeEventListener('hashchange', onHashChange);
  });

  $: CurrentPage = resolvePageComponent($currentPath, $isAuthenticated, $isGuest, $currentRole);
</script>

{#if CurrentPage}
  <svelte:component this={CurrentPage} />
{:else}
  <div style="display:flex;align-items:center;justify-content:center;height:100vh;">
    <p>Loading…</p>
  </div>
{/if}
"}

