{"file_path": "/Users/tsiontesfaye/Projects/EaglePoint/retail-ops/repo/src/pages/LoginPage.svelte", "content": "<script>
  import { authService } from '../services/AuthService.js';
  import { syncAuthStores } from '../app/stores/auth.js';
  import { navigate, showToast, isLoading } from '../app/stores/ui.js';

  let username = '';
  let password = '';
  let error = '';

  async function handleLogin() {
    error = '';
    isLoading.set(true);
    try {
      await authService.login(username, password);
      syncAuthStores(authService);
      navigate('/crm');
    } catch (err) {
      error = err.message;
    } finally {
      isLoading.set(false);
    }
  }

  function handleGuestLogin() {
    authService.createGuestSession((reason) => {
      showToast('info', reason);
      navigate('/login');
    });
    syncAuthStores(authService);
    navigate('/crm');
  }
