  import { onMount } from 'svelte';
  import Router from './app/router/Router.svelte';
  import { isAuthenticated, isGuest, syncAuthStores } from './app/stores/auth.js';
  import { toast, isLoading, restoreColumnLayouts, navigate } from './app/stores/ui.js';
  import { restoreSelectedStore } from './app/stores/org.js';
  import { authService } from './services/AuthService.js';
  import { schedulerService } from './services/SchedulerService.js';
  import { initDB } from './infrastructure/db/db.js';

  let dbReady = false;
  let dbError = null;

  onMount(async () => {
    try {
      await initDB();
      dbReady = true;

      restoreColumnLayouts();
      restoreSelectedStore();

      // Start scheduler (leader election handles multi-tab exclusivity).
      await schedulerService.start();
    } catch (err) {
      dbError = err.message;
      console.error('[App] Startup error:', err);
    }
  });

  // Handle inactivity on user interaction.
  function onActivity() {
    if ($isAuthenticated) {
      authService.resetInactivityTimer();
    }
  }
</script>

<svelte:window on:click={onActivity} on:keydown={onActivity} />

{#if dbError}
  <div class="db-error">
    <h2>Database Error</h2>
    <p>{dbError}</p>
    <button on:click={() => window.location.reload()}>Reload</button>
  </div>
{:else if !dbReady}
  <div class="startup-screen">
    <p>Initializing…</p>
  </div>
{:else}
  <div class="app-shell">
    <!-- Global loading overlay -->
    {#if $isLoading}
      <div class="loading-overlay">
        <div class="spinner"></div>
      </div>
    {/if}

    <!-- Toast notifications -->
    {#if $toast}
      <div class="toast toast--{$toast.type}">
        {$toast.message}
      </div>
    {/if}

    <!-- Navigation sidebar (shown when authenticated) -->
    {#if $isAuthenticated || $isGuest}
      <nav class="sidebar">
        <div class="logo">RetailOps</div>
        <a href="#/crm">CRM</a>
        <a href="#/orders">Orders</a>
        <a href="#/master-data">Master Data</a>
        <a href="#/messages">Messages</a>
        {#if $isAuthenticated}
          <a href="#/nlp">NLP Analysis</a>
          <a href="#/risk-review">Risk Review</a>
          <a href="#/org-setup">Org Setup</a>
          <a href="#/admin">Admin</a>
        {/if}
      </nav>
    {/if}

    <main class="content">
      <Router />
    </main>
  </div>
{/if}

<style>
  :global(*, *::before, *::after) { box-sizing: border-box; margin: 0; padding: 0; }
  :global(body) { font-family: system-ui, -apple-system, sans-serif; background: #f5f5f5; color: #1a1a1a; }

  .db-error, .startup-screen {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    min-height: 100vh;
    gap: 1rem;
  }

  .app-shell {
    display: flex;
    min-height: 100vh;
    position: relative;
  }

  .sidebar {
    width: 200px;
    background: #1e293b;
    color: #e2e8f0;
    padding: 1rem;
    display: flex;
    flex-direction: column;
    gap: 0.25rem;
    flex-shrink: 0;
  }

  .sidebar .logo {
    font-weight: 700;
    font-size: 1.125rem;
    padding: 0.5rem 0;
    margin-bottom: 0.75rem;
    color: #fff;
  }

  .sidebar a {
    display: block;
    padding: 0.5rem 0.75rem;
    border-radius: 4px;
