{
  "name": "retailops-console",
  "version": "1.0.0",
  "description": "RetailOps Insight & Compliance Console — fully offline Svelte SPA",
  "type": "module",
  "scripts": {
    "dev": "vite",
    "build": "vite build",
    "preview": "vite preview",
    "test": "vitest run",
    "test:watch": "vitest",
    "test:ui": "vitest --ui",
    "test:coverage": "vitest run --coverage"
  },
  "dependencies": {
    "svelte": "^4.2.12"
  },
  "devDependencies": {
    "@sveltejs/vite-plugin-svelte": "^3.1.0",
    "@testing-library/jest-dom": "^6.4.2",
    "@testing-library/svelte": "^4.2.2",
    "@testing-library/user-event": "^14.5.2",
    "@vitest/coverage-v8": "^1.6.0",
    "@vitest/ui": "^1.6.0",
    "fake-indexeddb": "^5.0.0",
    "jsdom": "^24.0.0",
    "vite": "^5.2.0",
    "vitest": "^1.6.0"
  },
  "engines": {
    "node": ">=18.0.0"
  }
}

1	/**
2	 * Global test setup for RetailOps Console
3	 *
4	 * Configures:
5	 *   - fake-indexeddb  : shims globalThis.indexedDB for Node 18
6	 *   - BroadcastChannel: lightweight mock for cross-tab coordination tests
7	 *   - Web Crypto      : Node 18 ships globalThis.crypto natively; no polyfill needed
8	 */
9	
10	import 'fake-indexeddb/auto';
11	import '@testing-library/jest-dom';
12	
13	// ── BroadcastChannel mock ─────────────────────────────────────────────────────
14	// jsdom does not implement BroadcastChannel; provide a simple in-process mock.
15	if (typeof globalThis.BroadcastChannel === 'undefined') {
16	  const registry = new Map(); // name → Set<instance>
17	
18	  class BroadcastChannelMock {
19	    constructor(name) {
20	      this.name = name;
21	      this._closed = false;
22	      this._handlers = [];
23	
24	      if (!registry.has(name)) registry.set(name, new Set());
25	      registry.get(name).add(this);
26	    }
27	
28	    postMessage(data) {
29	      if (this._closed) return;
30	      const peers = registry.get(this.name) ?? new Set();
31	      for (const peer of peers) {
32	        if (peer !== this && !peer._closed) {
33	          const evt = { data, type: 'message' };
34	          peer._handlers.forEach((fn) => fn(evt));
35	          if (typeof peer.onmessage === 'function') peer.onmessage(evt);
36	        }
37	      }
38	    }
39	
40	    addEventListener(_type, fn) {
41	      this._handlers.push(fn);
42	    }
43	
44	    removeEventListener(_type, fn) {
45	      this._handlers = this._handlers.filter((h) => h !== fn);
46	    }
47	
48	    close() {
49	      this._closed = true;
50	      registry.get(this.name)?.delete(this);
51	    }
52	  }
53	
54	  globalThis.BroadcastChannel = BroadcastChannelMock;
55	}
56	
57	// ── Crypto sanity-check ───────────────────────────────────────────────────────
58	// Node 18 exposes globalThis.crypto.subtle; assert it exists so tests fail
59	// with a clear message rather than cryptic undefined errors.
60	if (!globalThis.crypto?.subtle) {
61	  throw new Error(
62	    'globalThis.crypto.subtle is not available. ' +
63	      'Ensure you are running Node 18+ or have a Web Crypto polyfill installed.',
64	  );
65	}
