1	/**
2	 * SchedulerService — periodic background tasks.
3	 *
4	 * Responsibilities:
5	 *   - queue retry processing       (every 30 seconds while leading)
6	 *   - ticket SLA overdue checks    (every 5 minutes while leading)
7	 *   - missed work reconciliation   (on startup)
8	 *
9	 * Multi-tab leader election:
10	 *   Only one tab should run the scheduler at a time.
11	 *   We use BroadcastChannel heartbeats with a leader timestamp in LocalStorage.
12	 *   If this tab wins the leader election it starts timers;
13	 *   other tabs stand by and take over if the leader goes silent.
14	 */
15	
16	import { schedule, cancel, cancelAll } from '../infrastructure/scheduler/timerManager.js';
17	import {
18	  broadcast,
19	  subscribe,
20	  CHANNEL_NAMES,
21	  EVENT_TYPES,
22	} from '../infrastructure/broadcast/broadcastManager.js';
23	import { notificationService } from './NotificationService.js';
24	import { ticketService } from './TicketService.js';
25	
26	const LEADER_KEY = 'retailops:queue_leader';
27	const LEADER_TTL_MS = 10_000;     // leader must heartbeat within 10 s
28	const HEARTBEAT_INTERVAL_MS = 5_000;
29	const QUEUE_CHECK_INTERVAL_MS = 30_000;
30	const OVERDUE_CHECK_INTERVAL_MS = 5 * 60_000;
31	
32	export class SchedulerService {
33	  constructor() {
34	    this._isLeader = false;
35	    this._tabId = `tab_${Date.now()}_${Math.random().toString(36).slice(2, 6)}`;
36	    this._unsubscribe = null;
37	  }
38	
39	  /**
40	   * Starts the scheduler.
41	   * - Reconciles any missed work from before the last app close.
42	   * - Participates in leader election.
43	   */
44	  async start() {
45	    await this._reconcileMissedWork();
46	    this._listenForLeaderEvents();
47	    this._attemptLeaderClaim();
48	  }
49	
50	  /**
51	   * Stops all scheduler activity and releases leadership.
52	   */
53	  stop() {
54	    cancelAll();
55	    if (this._isLeader) {
56	      localStorage.removeItem(LEADER_KEY);
57	      broadcast(CHANNEL_NAMES.QUEUE, EVENT_TYPES.QUEUE_LEADER_RELEASE, { tabId: this._tabId });
58	      this._isLeader = false;
59	    }
60	    if (this._unsubscribe) {
61	      this._unsubscribe();
62	      this._unsubscribe = null;
63	    }
64	  }
65	
66	  // ── Leader election ───────────────────────────────────────────────────────────
67	
68	  _attemptLeaderClaim() {
69	    const existing = this._readLeaderState();
70	    const now = Date.now();
71	
72	    if (!existing || now - existing.timestamp > LEADER_TTL_MS) {
73	      this._becomeLeader();
74	    } else {
75	      // Another tab is leading; stand by.
76	      schedule('scheduler:standby_check', () => this._attemptLeaderClaim(), LEADER_TTL_MS + 1000);
77	    }
78	  }
79	
80	  _becomeLeader() {
81	    this._isLeader = true;
82	    this._writeLeaderState();
83	    broadcast(CHANNEL_NAMES.QUEUE, EVENT_TYPES.QUEUE_LEADER_CLAIM, { tabId: this._tabId });
84	
85	    schedule('scheduler:heartbeat', () => this._heartbeat(), HEARTBEAT_INTERVAL_MS);
86	    schedule('scheduler:queue_check', () => this._processQueue(), QUEUE_CHECK_INTERVAL_MS);
87	    schedule('scheduler:overdue_check', () => this._checkOverdue(), OVERDUE_CHECK_INTERVAL_MS);
88	  }
89	
90	  _heartbeat() {
91	    if (!this._isLeader) return;
92	    this._writeLeaderState();
93	    broadcast(CHANNEL_NAMES.QUEUE, EVENT_TYPES.QUEUE_LEADER_HEARTBEAT, { tabId: this._tabId });
94	    schedule('scheduler:heartbeat', () => this._heartbeat(), HEARTBEAT_INTERVAL_MS);
95	  }
96	
97	  _listenForLeaderEvents() {
98	    this._unsubscribe = subscribe(CHANNEL_NAMES.QUEUE, (event) => {
99	      if (event.type === EVENT_TYPES.QUEUE_LEADER_CLAIM && event.payload.tabId !== this._tabId) {
100	        // Another tab won the election; yield.
101	        this._isLeader = false;
102	        cancel('scheduler:heartbeat');
103	        cancel('scheduler:queue_check');
104	        cancel('scheduler:overdue_check');
105	      }
106	      if (event.type === EVENT_TYPES.QUEUE_LEADER_RELEASE) {
107	        // Leader stepped down; try to claim.
108	        this._attemptLeaderClaim();
109	      }
110	    });
111	  }
112	
113	  _readLeaderState() {
114	    try {
115	      const raw = localStorage.getItem(LEADER_KEY);
116	      return raw ? JSON.parse(raw) : null;
117	    } catch {
118	      return null;
119	    }
120	  }
121	
122	  _writeLeaderState() {
123	    try {
124	      localStorage.setItem(LEADER_KEY, JSON.stringify({ tabId: this._tabId, timestamp: Date.now() }));
125	    } catch {
126	      // LocalStorage write failure is non-fatal.
127	    }
128	  }
129	
130	  // ── Periodic tasks ────────────────────────────────────────────────────────────
131	
132	  async _processQueue() {
133	    if (!this._isLeader) return;
134	    try {
135	      await notificationService.processDueItems();
136	    } catch (err) {
137	      console.error('[SchedulerService] Queue processing error:', err);
138	    }
139	    schedule('scheduler:queue_check', () => this._processQueue(), QUEUE_CHECK_INTERVAL_MS);
140	  }
141	
142	  async _checkOverdue() {
143	    if (!this._isLeader) return;
144	    try {
145	      await ticketService.evaluateOverdue();
146	    } catch (err) {
147	      console.error('[SchedulerService] Overdue check error:', err);
148	    }
149	    schedule('scheduler:overdue_check', () => this._checkOverdue(), OVERDUE_CHECK_INTERVAL_MS);
150	  }
151	
152	  /**
153	   * On startup, immediately processes items that should have fired while the app was closed.
