14	import { UserRepository } from '../repositories/implementations/UserRepository.js';
15	import { cryptoService } from './CryptoService.js';
16	import { auditService } from './AuditService.js';
17	import { generateId } from '../utils/idGenerator.js';
18	import { validatePassword, isValidRole } from '../utils/validation.js';
19	import { ROLES, VALIDATION } from '../utils/constants.js';
20	import { cancel, schedule } from '../infrastructure/scheduler/timerManager.js';
21	import {
22	  broadcast,
23	  subscribe,
24	  CHANNEL_NAMES,
25	  EVENT_TYPES,
26	} from '../infrastructure/broadcast/broadcastManager.js';
27	
28	const LOCK_TIMER_KEY = 'auth:auto_lock';
29	const GUEST_TIMER_KEY = 'auth:guest_expiry';
30	
31	export class AuthService {
32	  constructor() {
33	    this._userRepo = new UserRepository();
34	    /** @type {object | null} Currently active user record. */
35	    this._currentUser = null;
36	    /** @type {boolean} */
37	    this._isLocked = false;
38	    /** @type {boolean} */
39	    this._isGuestSession = false;
40	
41	    // Listen for lock events broadcast from other tabs.
42	    subscribe(CHANNEL_NAMES.STATE, (event) => {
43	      if (event.type === EVENT_TYPES.SESSION_LOCKED) {
44	        this._isLocked = true;
45	      } else if (event.type === EVENT_TYPES.SESSION_LOGGED_OUT) {
46	        this._currentUser = null;
47	        this._isLocked = false;
48	        cryptoService.clearSessionKey();
49	      }
50	    });
51	  }
52	
53	  // ── Login / logout ───────────────────────────────────────────────────────────
54	
55	  /**
56	   * Authenticates a user with username and password.
57	   * Derives the session encryption key on success.
58	   *
59	   * @param {string} username
60	   * @param {string} password
61	   * @returns {Promise<object>}  The authenticated user record.
62	   * @throws {Error} On invalid credentials or deactivated account.
63	   */
64	  async login(username, password) {
65	    const user = await this._userRepo.findByUsername(username);
66	
67	    if (!user) throw new Error('Invalid username or password.');
68	    if (!user.isActive) throw new Error('Account is deactivated.');
69	
70	    const valid = await cryptoService.verifyPassword(password, user.passwordSalt, user.passwordHash);
71	    if (!valid) throw new Error('Invalid username or password.');
72	
73	    await cryptoService.deriveSessionKey(password, user.passwordSalt);
74	
75	    this._currentUser = user;
76	    this._isLocked = false;
77	    this._isGuestSession = false;
78	
79	    this._resetLockTimer();
80	
81	    await auditService.log({
82	      actorId: user.id,
83	      action: 'login',
84	      entityType: 'user',
85	      entityId: user.id,
86	    });
87	
88	    return user;
89	  }
90	
91	  /**
92	   * Logs out the current user and clears all session state.
93	   * @returns {Promise<void>}
94	   */
95	  async logout() {
96	    if (this._currentUser) {
97	      await auditService.log({
98	        actorId: this._currentUser.id,
99	        action: 'logout',
100	        entityType: 'user',
101	        entityId: this._currentUser.id,
102	      });
103	    }
104	
105	    cancel(LOCK_TIMER_KEY);
106	    cancel(GUEST_TIMER_KEY);
107	    cryptoService.clearSessionKey();
108	
109	    this._currentUser = null;
110	    this._isLocked = false;
111	    this._isGuestSession = false;
112	
113	    broadcast(CHANNEL_NAMES.STATE, EVENT_TYPES.SESSION_LOGGED_OUT);
114	  }
115	
116	  // ── Guest session ────────────────────────────────────────────────────────────
117	
118	  /**
119	   * Creates a temporary read-only guest session.
120	   * Hard-expires after 30 minutes and auto-redirects to login.
121	   *
122	   * @param {(reason: string) => void} onExpiry  Called when the guest session expires.
123	   * @returns {{ id: string; role: string; isGuest: true }}
124	   */
125	  createGuestSession(onExpiry) {
126	    const guestUser = {
127	      id: `guest_${Date.now()}`,
128	      username: 'guest',
129	      role: ROLES.GUEST,
130	      organizationNodeId: null,
131	      isActive: true,
132	      isGuest: true,
133	      guestExpiresAt: Date.now() + VALIDATION.GUEST_TRIAL_MINUTES * 60_000,
134	    };
135	
136	    this._currentUser = guestUser;
137	    this._isGuestSession = true;
138	
139	    schedule(
140	      GUEST_TIMER_KEY,
141	      async () => {
142	        await this.logout();
143	        onExpiry('Guest trial expired after 30 minutes.');
144	      },
145	      VALIDATION.GUEST_TRIAL_MINUTES * 60_000,
146	    );
147	
148	    return guestUser;
149	  }
150	
151	  // ── Inactivity lock ──────────────────────────────────────────────────────────
152	
153	  /**
154	   * Resets the inactivity auto-lock timer.
155	   * Must be called on every user interaction.
156	   */
157	  resetInactivityTimer() {
158	    if (!this._currentUser || this._isGuestSession) return;
159	    this._resetLockTimer();
160	  }
161	
162	  /** @private */
163	  _resetLockTimer() {
164	    schedule(
165	      LOCK_TIMER_KEY,
166	      () => {
167	        this.lockSession();
168	        broadcast(CHANNEL_NAMES.STATE, EVENT_TYPES.SESSION_LOCKED);
169	      },
170	      VALIDATION.AUTO_LOCK_MINUTES * 60_000,
171	    );
172	  }
173	
174	  /**
175	   * Locks the session — encrypted data becomes inaccessible until unlock.
176	   */
177	  lockSession() {
178	    cryptoService.clearSessionKey();
179	    this._isLocked = true;
180	  }
181	
182	  /**
183	   * Unlocks the session by re-deriving the encryption key.
184	   *
185	   * @param {string} password
186	   * @returns {Promise<boolean>}
187	   */
188	  async unlockSession(password) {
189	    if (!this._currentUser) throw new Error('No active session to unlock.');
190	
191	    const user = await this._userRepo.findById(this._currentUser.id);
192	    if (!user) throw new Error('User record not found.');
193	
194	    const valid = await cryptoService.verifyPassword(password, user.passwordSalt, user.passwordHash);
195	    if (!valid) return false;
196	
197	    await cryptoService.deriveSessionKey(password, user.passwordSalt);
198	    this._isLocked = false;
199	    this._resetLockTimer();
200	    broadcast(CHANNEL_NAMES.STATE, EVENT_TYPES.SESSION_UNLOCKED);
201	    return true;
202	  }
203	
204	  // ── Account management ───────────────────────────────────────────────────────
205	
206	  /**
207	   * Creates a new user account.
208	   *
209	   * @param {{ username: string; password: string; role: string; organizationNodeId: string }} params
210	   * @returns {Promise<object>}
211	   */
212	  async createUser({ username, password, role, organizationNodeId }) {
213	    this._assertPermission('administrator');
214	
215	    const pwValidation = validatePassword(password);
216	    if (!pwValidation.valid) throw new Error(pwValidation.errors.join(' '));
217	    if (!isValidRole(role)) throw new Error(`Invalid role: ${role}`);
218	
219	    const { hash, salt } = await cryptoService.hashNewPassword(password);
220	
221	    const user = {
222	      id: generateId(),
223	      username,
224	      passwordHash: hash,
225	      passwordSalt: salt,
226	      role,
227	      organizationNodeId,
228	      isActive: true,
229	      isGuest: false,
230	      guestExpiresAt: null,
231	      lockoutUntil: null,
232	      createdAt: Date.now(),
233	      updatedAt: Date.now(),
234	    };
235	
236	    await this._userRepo.create(user);
237	    await auditService.log({
238	      actorId: this._currentUser?.id ?? 'system',
239	      action: 'create_user',
240	      entityType: 'user',
241	      entityId: user.id,
242	      metadata: { username, role },
243	    });
244	
245	    return user;
246	  }
247	
248	  /**
249	   * Changes a user's password and re-encrypts all their sensitive data.
250	   *
251	   * @param {string} userId
252	   * @param {string} oldPassword
253	   * @param {string} newPassword
254	   * @param {Array<{ ciphertext: string; iv: string }>} encryptedFields
255	   * @returns {Promise<Array<{ ciphertext: string; iv: string; algorithmVersion: string }>>}
256	   */
257	  async changePassword(userId, oldPassword, newPassword, encryptedFields = []) {
258	    const pwValidation = validatePassword(newPassword);
259	    if (!pwValidation.valid) throw new Error(pwValidation.errors.join(' '));
260	
261	    const user = await this._userRepo.findById(userId);
262	    if (!user) throw new Error('User not found.');
263	
264	    const valid = await cryptoService.verifyPassword(oldPassword, user.passwordSalt, user.passwordHash);
265	    if (!valid) throw new Error('Old password is incorrect.');
266	
267	    const { hash, salt } = await cryptoService.hashNewPassword(newPassword);
268	
269	    // Re-encrypt all sensitive fields before committing the password change.
270	    const reEncrypted = await cryptoService.rotateEncryptedFields(
271	      encryptedFields,
272	      oldPassword,
273	      user.passwordSalt,
274	      newPassword,
275	    );
276	
277	    await this._userRepo.update(userId, {
278	      ...user,
279	      passwordHash: hash,
280	      passwordSalt: salt,
281	      updatedAt: Date.now(),
282	    });
283	
284	    // Re-derive session key with new password.
285	    await cryptoService.deriveSessionKey(newPassword, salt);
286	
287	    await auditService.log({
288	      actorId: userId,
289	      action: 'change_password',
290	      entityType: 'user',
291	      entityId: userId,
292	    });
293	
294	    return reEncrypted;
295	  }
296	
297	  /**
298	   * Deactivates a user account.
299	   * @param {string} userId
300	   * @returns {Promise<void>}
301	   */
302	  async deactivateAccount(userId) {
303	    this._assertPermission('administrator');
304	
305	    const user = await this._userRepo.findById(userId);
306	    if (!user) throw new Error('User not found.');
307	
308	    await this._userRepo.update(userId, { ...user, isActive: false, updatedAt: Date.now() });
309	
310	    await auditService.log({
311	      actorId: this._currentUser?.id ?? 'system',
312	      action: 'deactivate_account',
313	      entityType: 'user',
314	      entityId: userId,
315	    });
316	  }
317	
318	  // ── State accessors ──────────────────────────────────────────────────────────
319	
320	  /** @returns {object | null} */
321	  getCurrentUser() {
322	    return this._currentUser;
323	  }
324	
325	  /** @returns {boolean} */
326	  isAuthenticated() {
327	    return this._currentUser !== null && !this._isGuestSession;
328	  }
329	
330	  /** @returns {boolean} */
331	  isLocked() {
332	    return this._isLocked;
333	  }
334	
335	  /** @returns {boolean} */
336	  isGuest() {
337	    return this._isGuestSession;
338	  }
339	
340	  /**
341	   * Returns true if the current user has the given role or Administrator access.
342	   * @param {string} requiredRole
343	   * @returns {boolean}
344	   */
345	  hasRole(requiredRole) {
346	    if (!this._currentUser) return false;
347	    if (this._currentUser.role === ROLES.ADMINISTRATOR) return true;
348	    return this._currentUser.role === requiredRole;
349	  }
350	
351	  // ── Private helpers ──────────────────────────────────────────────────────────
352	
353	  /**
354	   * Throws if the current user does not have the required role.
355	   * @param {string} requiredRole
356	   */
357	  _assertPermission(requiredRole) {
358	    if (!this.hasRole(requiredRole)) {
359	      throw new Error(`Permission denied. Required role: ${requiredRole}`);
360	    }
361	  }
362	}
