1	/**
2	 * Timer manager for the Scheduler service.
3	 *
4	 * Provides a thin wrapper around setTimeout / clearTimeout so that:
5	 *   1. All active timers can be cleared at once (e.g. on tab close or test teardown).
6	 *   2. Individual timers can be cancelled by their handle.
7	 *   3. The module is independently unit-testable with fake timers.
8	 */
9	
10	/** @type {Map<string, ReturnType<typeof setTimeout>>} */
11	const _timers = new Map();
12	
13	/**
14	 * Schedules a callback to fire after `delayMs` milliseconds.
15	 * If a timer with the same `key` already exists it is replaced.
16	 *
17	 * @param {string} key       Unique identifier for this timer.
18	 * @param {() => void} fn    Callback to invoke.
19	 * @param {number} delayMs   Delay in milliseconds.
20	 */
21	export function schedule(key, fn, delayMs) {
22	  if (_timers.has(key)) {
23	    clearTimeout(_timers.get(key));
24	  }
25	  const handle = setTimeout(() => {
26	    _timers.delete(key);
27	    fn();
28	  }, delayMs);
29	  _timers.set(key, handle);
30	}
31	
32	/**
33	 * Cancels a scheduled timer by key.
34	 * Safe to call even if the timer does not exist.
35	 *
36	 * @param {string} key
37	 */
38	export function cancel(key) {
39	  if (_timers.has(key)) {
40	    clearTimeout(_timers.get(key));
41	    _timers.delete(key);
42	  }
43	}
44	
45	/**
46	 * Cancels all active timers.
47	 * Use on teardown (logout, tab close, test cleanup).
48	 */
49	export function cancelAll() {
50	  for (const [, handle] of _timers) {
51	    clearTimeout(handle);
52	  }
53	  _timers.clear();
54	}
55	
56	/**
57	 * Returns the number of currently active timers.
58	 * Useful in tests.
59	 * @returns {number}
60	 */
61	export function activeCount() {
62	  return _timers.size;
63	}
