88	  /**
89	   * Adjusts stored value by delta (positive = credit, negative = debit).
90	   * Blocks negative balance.
91	   *
92	   * @param {string} customerId
93	   * @param {number} delta
94	   * @param {string} actorId
95	   * @returns {Promise<object>}
