1	import { MasterDataRepository } from '../repositories/implementations/MasterDataRepository.js';
2	import { auditService } from './AuditService.js';
3	import { generateId } from '../utils/idGenerator.js';
4	import { validateReasonNote } from '../utils/validation.js';
5	import { MASTER_DATA_ENTITY_TYPES } from '../utils/constants.js';
6	
7	/**
8	 * MasterDataService — versioned master data lifecycle management.
9	 *
10	 * One active version per (entityType, organizationId) at a time.
11	 * Publish operations use optimistic concurrency: if the active version
12	 * changed since the editor loaded, the publish is rejected.
13	 */
14	export class MasterDataService {
15	  constructor() {
16	    this._repo = new MasterDataRepository();
17	  }
18	
19	  /**
20	   * Creates and immediately publishes a new version of a master data entity.
21	   * Atomically deactivates the previous active version.
22	   *
23	   * @param {{ entityType: string; entityId: string; organizationId: string; payload: object; reasonNote: string; createdBy: string; expectedActiveVersionId: string | null }} params
24	   * @returns {Promise<object>}
25	   */
26	  async publishVersion({ entityType, entityId, organizationId, payload, reasonNote, createdBy, expectedActiveVersionId }) {
27	    this._assertValidEntityType(entityType);
28	
29	    const noteCheck = validateReasonNote(reasonNote);
30	    if (!noteCheck.valid) throw new Error(noteCheck.error);
31	
32	    // Optimistic concurrency check.
33	    const currentActive = await this._repo.findActiveVersion(entityType, organizationId);
34	    const currentActiveId = currentActive?.id ?? null;
35	    if (currentActiveId !== (expectedActiveVersionId ?? null)) {
36	      throw new Error(
37	        'Concurrency conflict: the active version changed since you loaded this form. Please reload.',
38	      );
39	    }
40	
41	    const history = await this._repo.findVersionHistory(entityId);
42	    const nextVersion = history.length > 0 ? history[0].versionNumber + 1 : 1;
43	
44	    const newVersion = {
45	      id: generateId(),
46	      organizationId,
47	      entityType,
48	      entityId,
49	      versionNumber: nextVersion,
50	      payload,
51	      reasonNote,
52	      isActive: true,
53	      createdBy,
54	      createdAt: Date.now(),
55	    };
56	
57	    await this._repo.atomicVersionSwitch(currentActiveId, newVersion);
58	
59	    await auditService.log({
60	      actorId: createdBy,
61	      action: 'publish_version',
62	      entityType,
63	      entityId,
64	      metadata: { versionNumber: nextVersion, previousActiveId: currentActiveId },
65	    });
66	
67	    return newVersion;
68	  }
69	
70	  /**
71	   * Returns the currently active version for an entity type in an org.
72	   * @param {string} entityType
73	   * @param {string} organizationId
74	   * @returns {Promise<object | null>}
75	   */
76	  async getActiveVersion(entityType, organizationId) {
77	    this._assertValidEntityType(entityType);
78	    return this._repo.findActiveVersion(entityType, organizationId);
79	  }
80	
81	  /**
82	   * Returns all historical versions for an entity, newest first.
83	   * @param {string} entityId
84	   * @returns {Promise<object[]>}
85	   */
86	  async getVersionHistory(entityId) {
87	    return this._repo.findVersionHistory(entityId);
88	  }
89	
90	  /**
91	   * Returns all active versions for an organization.
92	   * @param {string} organizationId
93	   * @returns {Promise<object[]>}
94	   */
95	  async getAllActiveVersions(organizationId) {
96	    return this._repo.findActiveVersionsByOrg(organizationId);
97	  }
98	
99	  /**
100	   * Validates that an entity type string is recognized.
101	   * @param {string} entityType
102	   */
103	  _assertValidEntityType(entityType) {
104	    const valid = Object.values(MASTER_DATA_ENTITY_TYPES);
105	    if (!valid.includes(entityType)) {
106	      throw new Error(`Unknown entity type: '${entityType}'. Valid: ${valid.join(', ')}`);
107	    }
108	  }
109	}
