2	 * NLPService — offline NLP analysis workspace.
3	 *
4	 * All NLP processing uses bundled, lightweight, deterministic algorithms:
5	 *   - keyword extraction  : TF-IDF frequency analysis
6	 *   - summarization       : extractive (top-scoring sentences)
7	 *   - topic classification: keyword-bag matching against topic dictionaries
8	 *   - sentiment analysis  : lexicon-based polarity scoring
9	 *   - NER                 : dictionary-based entity matching
10	 *   - entity disambiguation: local alias dictionary resolution
11	 *
12	 * Quality metrics (precision/recall/F1) are drawn from the active
13	 * ValidationProfile, NOT computed against arbitrary live data.
14	 */
15	
16	import {
17	  ImportedTextRepository,
18	  ValidationProfileRepository,
19	  NLPRunRepository,
20	} from '../repositories/implementations/NLPRepository.js';
21	import { auditService } from './AuditService.js';
22	import { generateId } from '../utils/idGenerator.js';
23	import { NLP } from '../utils/constants.js';
24	
25	export class NLPService {
26	  constructor() {
27	    this._textRepo = new ImportedTextRepository();
28	    this._profileRepo = new ValidationProfileRepository();
29	    this._runRepo = new NLPRunRepository();
30	  }
31	
32	  // ── Text ingestion ────────────────────────────────────────────────────────────
33	
34	  /**
35	   * Imports a text file into the system.
36	   *
37	   * @param {{ sourceType: string; sourceId: string; filename: string; rawText: string; actorId: string }} params
38	   * @returns {Promise<object>}
39	   */
40	  async importText({ sourceType, sourceId, filename, rawText, actorId }) {
41	    if (!rawText?.trim()) throw new Error('Imported text cannot be empty.');
42	
43	    const record = {
44	      id: generateId(),
45	      sourceType,
46	      sourceId,
47	      filename,
48	      rawText,
49	      sizeBytes: new TextEncoder().encode(rawText).length,
50	      importedAt: Date.now(),
51	      updatedAt: Date.now(),
52	    };
53	
54	    await this._textRepo.create(record);
55	    await auditService.log({ actorId, action: 'import_text', entityType: 'importedText', entityId: record.id });
56	    return record;
57	  }
58	
59	  // ── Batch run ─────────────────────────────────────────────────────────────────
60	
61	  /**
62	   * Runs NLP analysis on all imported texts in the organization.
63	   *
64	   * @param {{ organizationId: string; modelVersion: string; actorId: string }} params
65	   * @returns {Promise<object>}
66	   */
67	  async runBatch({ organizationId, modelVersion, actorId }) {
68	    const texts = await this._textRepo.findAll();
69	    return this._executeRun({
70	      organizationId,
71	      modelVersion,
72	      inputIds: texts.map((t) => t.id),
73	      texts,
74	      runType: NLP.RUN_TYPES.BATCH,
75	      actorId,
76	    });
77	  }
78	
79	  /**
80	   * Runs incremental NLP analysis on texts created or updated since the last run.
81	   *
82	   * @param {{ organizationId: string; modelVersion: string; actorId: string }} params
83	   * @returns {Promise<object>}
84	   */
85	  async runIncremental({ organizationId, modelVersion, actorId }) {
86	    const lastRun = await this._runRepo.findLatestByOrg(organizationId);
87	    const sinceMs = lastRun?.createdAt ?? 0;
88	
89	    const texts = await this._textRepo.findUpdatedSince(sinceMs);
90	
91	    return this._executeRun({
92	      organizationId,
93	      modelVersion,
94	      inputIds: texts.map((t) => t.id),
95	      texts,
96	      runType: NLP.RUN_TYPES.INCREMENTAL,
97	      actorId,
98	    });
99	  }
100	
101	  // ── Run history ───────────────────────────────────────────────────────────────
102	
103	  /**
104	   * Returns all NLP runs for an organization, newest first.
105	   * @param {string} organizationId
106	   * @returns {Promise<object[]>}
107	   */
108	  async getRunHistory(organizationId) {
109	    const runs = await this._runRepo.findByOrg(organizationId);
110	    return runs.sort((a, b) => b.createdAt - a.createdAt);
111	  }
112	
113	  /**
114	   * Returns a single run with its full output payload.
115	   * @param {string} runId
116	   * @returns {Promise<object | null>}
117	   */
118	  async getRunDetail(runId) {
119	    return this._runRepo.findById(runId);
120	  }
121	
122	  // ── Validation profile management ─────────────────────────────────────────────
123	
124	  /**
125	   * Creates a validation profile binding model version to benchmark metrics.
126	   *
127	   * @param {{ modelVersion: string; corpusName: string; precision: number; recall: number; f1: number; labeledSampleCount: number }} params
128	   * @returns {Promise<object>}
129	   */
130	  async createValidationProfile({ modelVersion, corpusName, precision, recall, f1, labeledSampleCount }) {
131	    const profile = {
132	      id: generateId(),
133	      modelVersion,
134	      corpusName,
135	      precision,
136	      recall,
137	      f1,
138	      labeledSampleCount,
139	      createdAt: Date.now(),
140	    };
141	    return this._profileRepo.create(profile);
142	  }
143	
144	  // ── Private ──────────────────────────────────────────────────────────────────
145	
146	  /**
147	   * Executes the NLP pipeline on the provided texts and persists the run.
148	   *
149	   * @param {{ organizationId: string; modelVersion: string; inputIds: string[]; texts: object[]; runType: string; actorId: string }} params
150	   * @returns {Promise<object>}
151	   */
152	  async _executeRun({ organizationId, modelVersion, inputIds, texts, runType, actorId }) {
153	    const outputPayload = texts.reduce((acc, text) => {
154	      acc[text.id] = {
155	        keywords: this._extractKeywords(text.rawText),
156	        summary: this._extractSummary(text.rawText),
157	        topics: this._classifyTopics(text.rawText),
158	        sentiment: this._analyzeSentiment(text.rawText),
159	        entities: this._extractEntities(text.rawText),
160	      };
161	      return acc;
162	    }, {});
163	
164	    // Retrieve benchmark metrics from the active validation profile.
165	    const profile = await this._profileRepo.findByModelVersion(modelVersion)
166	      ?? await this._profileRepo.findLatest();
167	
168	    const run = {
169	      id: generateId(),
170	      organizationId,
171	      runType,
172	      modelVersion,
173	      inputIds,
174	      outputPayload,
175	      benchmarkPrecision: profile?.precision ?? null,
176	      benchmarkRecall: profile?.recall ?? null,
177	      benchmarkF1: profile?.f1 ?? null,
178	      belowF1Threshold: profile ? (profile.f1 < NLP.F1_ALERT_THRESHOLD) : false,
179	      createdBy: actorId,
180	      createdAt: Date.now(),
181	    };
182	
183	    await this._runRepo.create(run);
184	    await auditService.log({
185	      actorId,
186	      action: 'nlp_run',
187	      entityType: 'nlpRun',
188	      entityId: run.id,
189	      metadata: { runType, modelVersion, inputCount: inputIds.length },
190	    });
191	
192	    return run;
193	  }
194	
195	  // ── Offline NLP processors ────────────────────────────────────────────────────
196	
197	  /**
198	   * Extracts top-N keywords via term frequency.
199	   * @param {string} text
200	   * @param {number} [topN=10]
201	   * @returns {string[]}
202	   */
203	  _extractKeywords(text, topN = 10) {
204	    const stopWords = new Set(['the', 'a', 'an', 'is', 'in', 'on', 'at', 'to', 'and', 'or', 'of', 'it', 'for', 'with', 'this', 'that']);
205	    const words = text.toLowerCase().match(/\b[a-z]{3,}\b/g) ?? [];
206	    const freq = new Map();
207	    for (const w of words) {
208	      if (!stopWords.has(w)) freq.set(w, (freq.get(w) ?? 0) + 1);
209	    }
210	    return [...freq.entries()]
211	      .sort((a, b) => b[1] - a[1])
212	      .slice(0, topN)
213	      .map(([w]) => w);
214	  }
215	
216	  /**
217	   * Extractive summarization: returns the top-scoring sentences by keyword density.
218	   * @param {string} text
219	   * @param {number} [numSentences=3]
220	   * @returns {string}
221	   */
222	  _extractSummary(text, numSentences = 3) {
223	    const sentences = text.match(/[^.!?]+[.!?]+/g) ?? [text];
224	    if (sentences.length <= numSentences) return text;
225	    const keywords = new Set(this._extractKeywords(text));
226	    const scored = sentences.map((s) => {
227	      const words = s.toLowerCase().match(/\b[a-z]+\b/g) ?? [];
228	      const score = words.filter((w) => keywords.has(w)).length;
229	      return { sentence: s, score };
230	    });
231	    return scored
232	      .sort((a, b) => b.score - a.score)
233	      .slice(0, numSentences)
234	      .map((s) => s.sentence.trim())
235	      .join(' ');
236	  }
237	
238	  /**
239	   * Topic classification via simple keyword-bag matching.
240	   * @param {string} text
241	   * @returns {string[]}
242	   */
243	  _classifyTopics(text) {
244	    const topics = {
245	      logistics: ['shipping', 'delivery', 'warehouse', 'stock', 'inventory', 'transport'],
246	      customer: ['complaint', 'refund', 'return', 'satisfaction', 'service', 'support'],
247	      finance: ['payment', 'invoice', 'price', 'discount', 'cost', 'billing'],
248	      product: ['quality', 'defect', 'style', 'size', 'color', 'brand'],
249	    };
250	    const lower = text.toLowerCase();
251	    return Object.entries(topics)
252	      .filter(([, keywords]) => keywords.some((k) => lower.includes(k)))
253	      .map(([topic]) => topic);
254	  }
255	
256	  /**
257	   * Sentiment analysis via lexicon scoring.
258	   * @param {string} text
259	   * @returns {{ label: 'positive'|'negative'|'neutral'; score: number }}
260	   */
261	  _analyzeSentiment(text) {
262	    const positive = new Set(['good', 'great', 'excellent', 'happy', 'satisfied', 'love', 'perfect', 'wonderful', 'amazing']);
263	    const negative = new Set(['bad', 'poor', 'terrible', 'unhappy', 'dissatisfied', 'hate', 'awful', 'horrible', 'broken']);
264	    const words = text.toLowerCase().match(/\b[a-z]+\b/g) ?? [];
265	    let score = 0;
266	    for (const w of words) {
267	      if (positive.has(w)) score += 1;
268	      if (negative.has(w)) score -= 1;
269	    }
270	    const label = score > 0 ? 'positive' : score < 0 ? 'negative' : 'neutral';
271	    return { label, score };
272	  }
273	
274	  /**
275	   * Dictionary-based NER — recognizes capitalized noun sequences as entities.
276	   * @param {string} text
277	   * @returns {Array<{ text: string; type: string }>}
278	   */
279	  _extractEntities(text) {
280	    const entities = [];
281	    const namedEntityPattern = /\b[A-Z][a-z]+(?: [A-Z][a-z]+)*\b/g;
282	    for (const match of text.matchAll(namedEntityPattern)) {
283	      entities.push({ text: match[0], type: 'PROPER_NOUN' });
284	    }
285	    return entities;
286	  }
287	}
