31	  // ── Machine rule evaluation ───────────────────────────────────────────────────
32	
33	  /**
34	   * Evaluates all active rules against a submitted entity and generates risk cases.
35	   *
36	   * @param {{ organizationId: string; entityType: string; entityId: string; payload: object; actorId: string }} params
37	   * @returns {Promise<object[]>}  Generated risk cases.
38	   */
39	  async evaluateRules({ organizationId, entityType, entityId, payload, actorId }) {
40	    const rules = await this._ruleRepo.findActiveByOrg(organizationId);
41	    const applicableRules = rules.filter((r) => r.targetEntityType === entityType || r.targetEntityType === '*');
42	
43	    const matches = [];
44	    for (const rule of applicableRules) {
45	      if (this._ruleMatches(rule, payload)) {
46	        matches.push({ ruleId: rule.id, ruleName: rule.name, ruleType: rule.ruleType });
47	      }
48	    }
49	
50	    // Check sensitive words in any string field of the payload.
51	    const swMatches = this._checkSensitiveWords(payload);
52	    if (swMatches.length > 0) {
53	      matches.push({ ruleId: 'sensitive_word', ruleName: 'Sensitive Word Match', matches: swMatches });
54	    }
55	
56	    if (matches.length === 0) return [];
