58	    const riskCase = {
59	      id: generateId(),
60	      organizationId,
61	      sourceType: entityType,
62	      sourceId: entityId,
63	      ruleMatches: matches,
64	      status: RISK_CASE_STATUSES.OPEN,
65	      outcomeCode: null,
66	      resolutionComment: null,
67	      assignedReviewerId: null,
68	      createdAt: Date.now(),
69	      resolvedAt: null,
70	    };
71	
72	    await this._caseRepo.create(riskCase);
73	    await auditService.log({
74	      actorId,
75	      action: 'risk_case_created',
76	      entityType: 'riskCase',
