95	   *
96	   * @param {{ organizationId: string; itemId: string; windowMs?: number; frequencyThreshold?: number }} params
97	   * @returns {Promise<{ flagged: boolean; reason: string | null; evidence: object }>}
98	   */
99	  async evaluateBiddingHeuristics({ organizationId, itemId, windowMs = 60 * 60_000, frequencyThreshold = 10 }) {
100	    const now = Date.now();
101	    const events = await this._bidRepo.findByItemInWindow(itemId, now - windowMs, now);
102	
103	    if (events.length >= frequencyThreshold) {
104	      return {
105	        flagged: true,
106	        reason: `Bid frequency ${events.length} exceeds threshold ${frequencyThreshold} within ${windowMs / 60_000} minutes.`,
107	        evidence: { eventCount: events.length, windowMs, frequencyThreshold },
108	      };
109	    }
