117	      if (count >= Math.floor(frequencyThreshold * 0.5)) {
118	        return {
119	          flagged: true,
120	          reason: `Device fingerprint '${fp}' appears ${count} times — possible coordinated activity.`,
121	          evidence: { fingerprint: fp, count },
122	        };
123	      }
124	    }
125	
126	    return { flagged: false, reason: null, evidence: {} };
127	  }
