129	  // ── Case management ───────────────────────────────────────────────────────────
130	
131	  /**
132	   * Assigns a risk case to a reviewer.
133	   * @param {string} caseId
134	   * @param {string} reviewerId
135	   * @returns {Promise<object>}
136	   */
137	  async assignCase(caseId, reviewerId) {
