145	  /**
146	   * Resolves a risk case with an outcome code and comment.
147	   * Both outcome code and comment are required.
148	   *
149	   * @param {{ caseId: string; outcomeCode: string; resolutionComment: string; reviewerId: string }} params
150	   * @returns {Promise<object>}
151	   */
152	  async resolveCase({ caseId, outcomeCode, resolutionComment, reviewerId }) {
153	    if (!isValidOutcomeCode(outcomeCode)) {
154	      throw new Error(`Invalid outcome code: '${outcomeCode}'. Valid: ${Object.values(OUTCOME_CODES).join(', ')}`);
155	    }
156	    if (!resolutionComment?.trim()) {
157	      throw new Error('Resolution comment is required to close a risk case.');
158	    }
