188	   * @param {string} reviewerId
189	   * @returns {Promise<object>}
190	   */
191	  async dismissCase(caseId, resolutionComment, reviewerId) {
192	    if (!resolutionComment?.trim()) throw new Error('Comment required to dismiss a risk case.');
193	
194	    const riskCase = await this._getOrThrow(caseId);
195	    this._assertNotClosed(riskCase);
196	
197	    const updated = {
198	      ...riskCase,
199	      status: RISK_CASE_STATUSES.DISMISSED,
200	      outcomeCode: OUTCOME_CODES.FALSE_POSITIVE,
201	      resolutionComment,
202	      assignedReviewerId: reviewerId,
203	      resolvedAt: Date.now(),
204	    };
205	
206	    await this._caseRepo.update(caseId, updated);
207	    return updated;
208	  }
209	
210	  /**
211	   * Returns all open and in-review risk cases for an organization.
212	   * @param {string} organizationId
213	   * @returns {Promise<object[]>}
214	   */
215	  async getInbox(organizationId) {
216	    const cases = await this._caseRepo.findByOrg(organizationId);
217	    return cases.filter((c) => c.status === RISK_CASE_STATUSES.OPEN || c.status === RISK_CASE_STATUSES.IN_REVIEW);
218	  }
219	
220	  // ── Private ──────────────────────────────────────────────────────────────────
221	
222	  async _getOrThrow(caseId) {
223	    const c = await this._caseRepo.findById(caseId);
224	    if (!c) throw new Error(`Risk case '${caseId}' not found.`);
225	    return c;
226	  }
227	
228	  _assertNotClosed(riskCase) {
229	    if (riskCase.status === RISK_CASE_STATUSES.RESOLVED || riskCase.status === RISK_CASE_STATUSES.DISMISSED) {
