233	
234	  /**
235	   * Evaluates a single rule against a payload.
236	   * @param {object} rule
237	   * @param {object} payload
238	   * @returns {boolean}
239	   */
240	  _ruleMatches(rule, payload) {
241	    if (rule.ruleType === 'field_contains') {
242	      const { field, value } = rule.parameters;
243	      const fieldValue = String(payload[field] ?? '').toLowerCase();
244	      return fieldValue.includes(String(value).toLowerCase());
245	    }
246	    if (rule.ruleType === 'field_exceeds') {
247	      const { field, threshold } = rule.parameters;
248	      return Number(payload[field] ?? 0) > threshold;
249	    }
250	    return false;
251	  }
252	
253	  /**
254	   * Scans all string fields in a payload for sensitive word matches.
255	   * @param {object} payload
256	   * @returns {string[]}  Matched words.
257	   */
258	  _checkSensitiveWords(payload) {
259	    if (this._sensitiveWords.length === 0) return [];
260	    const text = Object.values(payload)
261	      .filter((v) => typeof v === 'string')
262	      .join(' ')
263	      .toLowerCase();
264	    return this._sensitiveWords.filter((word) => text.includes(word));
265	  }
266	}
