11	/** Terminal states that cannot be transitioned out of. */
12	const TERMINAL_STATES = new Set([TICKET_STATUSES.CLOSED]);
13	
14	/** Valid forward transitions. */
15	const TRANSITIONS = new Map([
16	  [TICKET_STATUSES.OPEN, [TICKET_STATUSES.IN_PROGRESS, TICKET_STATUSES.CLOSED]],
17	  [TICKET_STATUSES.IN_PROGRESS, [TICKET_STATUSES.RESOLVED, TICKET_STATUSES.CLOSED]],
18	  [TICKET_STATUSES.RESOLVED, [TICKET_STATUSES.CLOSED]],
19	  [TICKET_STATUSES.CLOSED, []],
20	]);
