22	export class TicketService {
23	  constructor() {
24	    this._ticketRepo = new TicketRepository();
25	    this._eventRepo = new TicketEventRepository();
26	  }
27	
28	  /**
29	   * Creates a new after-sales ticket.
30	   *
31	   * @param {{ customerId: string; orderId?: string; organizationId: string; storeId: string; subject: string; description: string; category: string; priority: string; actorId: string; slaHours?: number }} params
32	   * @returns {Promise<object>}
33	   */
34	  async createTicket({ customerId, orderId, organizationId, storeId, subject, description, category, priority, actorId, slaHours = VALIDATION.DEFAULT_TICKET_SLA_HOURS }) {
35	    if (!subject?.trim()) throw new Error('Subject is required.');
36	    if (!description?.trim()) throw new Error('Description is required.');
37	    if (!category?.trim()) throw new Error('Category is required.');
38	    if (!isValidTicketPriority(priority)) throw new Error(`Invalid priority: ${priority}`);
39	
40	    const now = Date.now();
41	    const ticket = {
42	      id: generateId(),
43	      customerId,
44	      orderId: orderId ?? null,
45	      organizationId,
46	      storeId,
47	      subject,
48	      description,
49	      category,
50	      priority,
51	      status: TICKET_STATUSES.OPEN,
52	      slaDueAt: now + slaHours * 60 * 60 * 1000,
53	      isOverdue: false,
54	      assignedTo: null,
55	      createdAt: now,
56	      updatedAt: now,
57	      resolvedAt: null,
58	      closedBy: null,
59	    };
60	
61	    await this._ticketRepo.create(ticket);
62	    await this._appendEvent({ ticketId: ticket.id, type: TICKET_EVENT_TYPES.CREATED, actorId });
63	    await auditService.log({ actorId, action: 'create_ticket', entityType: 'ticket', entityId: ticket.id });
64	
65	    return ticket;
66	  }
67	
68	  /**
69	   * Assigns a ticket to an agent.
70	   * @param {string} ticketId
71	   * @param {string} assigneeId
72	   * @param {string} actorId
73	   * @returns {Promise<object>}
74	   */
75	  async assignTicket(ticketId, assigneeId, actorId) {
76	    const ticket = await this._getOrThrow(ticketId);
77	    this._assertNotTerminal(ticket);
78	
79	    const updated = { ...ticket, assignedTo: assigneeId, status: TICKET_STATUSES.IN_PROGRESS, updatedAt: Date.now() };
80	    await this._ticketRepo.update(ticketId, updated);
81	    await this._appendEvent({ ticketId, type: TICKET_EVENT_TYPES.ASSIGNED, actorId, comment: `Assigned to ${assigneeId}` });
82	    return updated;
83	  }
84	
85	  /**
86	   * Transitions a ticket to a new status.
87	   * @param {string} ticketId
88	   * @param {string} newStatus
89	   * @param {string} actorId
90	   * @param {string} [comment]
91	   * @returns {Promise<object>}
92	   */
93	  async transitionTicket(ticketId, newStatus, actorId, comment) {
94	    const ticket = await this._getOrThrow(ticketId);
95	    this._assertNotTerminal(ticket);
96	
97	    const allowed = TRANSITIONS.get(ticket.status) ?? [];
98	    if (!allowed.includes(newStatus)) {
99	      throw new Error(`Invalid transition: ${ticket.status} → ${newStatus}`);
100	    }
101	
102	    const now = Date.now();
103	    const patch = { status: newStatus, updatedAt: now };
104	    if (newStatus === TICKET_STATUSES.RESOLVED) patch.resolvedAt = now;
105	    if (newStatus === TICKET_STATUSES.CLOSED) patch.closedBy = actorId;
106	
107	    const updated = { ...ticket, ...patch };
108	    await this._ticketRepo.update(ticketId, updated);
109	    await this._appendEvent({ ticketId, type: newStatus, actorId, comment });
110	    return updated;
111	  }
112	
113	  /**
114	   * Evaluates all open/in-progress tickets against their SLA due times.
115	   * Marks overdue tickets and appends an overdue event.
116	   *
117	   * @returns {Promise<object[]>}  Tickets newly marked overdue.
118	   */
119	  async evaluateOverdue() {
120	    const nowMs = Date.now();
121	    const due = await this._ticketRepo.findDueForOverdueCheck(nowMs);
122	
123	    const results = [];
124	    for (const ticket of due) {
125	      const updated = { ...ticket, isOverdue: true, updatedAt: nowMs };
126	      await this._ticketRepo.update(ticket.id, updated);
127	      await this._appendEvent({ ticketId: ticket.id, type: TICKET_EVENT_TYPES.OVERDUE, actorId: 'system' });
128	      results.push(updated);
129	    }
130	    return results;
131	  }
132	
133	  /**
134	   * Returns all overdue tickets.
135	   * @returns {Promise<object[]>}
136	   */
137	  async getOverdue() {
138	    return this._ticketRepo.findOverdue();
139	  }
140	
141	  /**
142	   * Returns ticket with its full event history.
143	   * @param {string} ticketId
144	   * @returns {Promise<{ ticket: object; events: object[] }>}
145	   */
146	  async getTicketDetail(ticketId) {
147	    const ticket = await this._getOrThrow(ticketId);
148	    const events = await this._eventRepo.findByTicket(ticketId);
149	    return { ticket, events: events.sort((a, b) => a.createdAt - b.createdAt) };
150	  }
151	
152	  /**
153	   * Returns all tickets for a customer.
154	   * @param {string} customerId
155	   * @returns {Promise<object[]>}
156	   */
157	  async getByCustomer(customerId) {
158	    return this._ticketRepo.findByCustomer(customerId);
159	  }
160	
161	  /**
162	   * Returns all tickets for a store.
163	   * @param {string} storeId
164	   * @returns {Promise<object[]>}
165	   */
166	  async getByStore(storeId) {
167	    return this._ticketRepo.findByStore(storeId);
168	  }
169	
170	  // ── Private ──────────────────────────────────────────────────────────────────
171	
172	  async _getOrThrow(id) {
173	    const t = await this._ticketRepo.findById(id);
174	    if (!t) throw new Error(`Ticket '${id}' not found.`);
175	    return t;
176	  }
177	
178	  _assertNotTerminal(ticket) {
179	    if (TERMINAL_STATES.has(ticket.status)) {
180	      throw new Error(`Ticket '${ticket.id}' is in terminal state '${ticket.status}' and cannot be modified.`);
181	    }
182	  }
183	
184	  async _appendEvent({ ticketId, type, actorId, comment = '' }) {
185	    const event = {
186	      id: generateId(),
187	      ticketId,
188	      type,
189	      comment,
190	      actorId,
191	      createdAt: Date.now(),
192	    };
193	    return this._eventRepo.create(event);
194	  }
195	}
