17	    this._notifRepo = new NotificationRepository();
18	  }
19	
20	  // ── Channel configuration ─────────────────────────────────────────────────────
21	
22	  /**
23	   * Creates or updates a notification channel.
24	   * Only 'in_app' channels are supported in the offline runtime.
25	   *
26	   * @param {{ organizationId: string; name: string; type?: string; isEnabled?: boolean }} params
27	   * @returns {Promise<object>}
28	   */
29	  async upsertChannel({ organizationId, name, type = 'in_app', isEnabled = true }) {
30	    const channel = {
31	      id: generateId(),
32	      organizationId,
33	      name,
34	      type,
35	      isEnabled,
36	      createdAt: Date.now(),
37	      updatedAt: Date.now(),
38	    };
39	    return this._channelRepo.upsert(channel);
40	  }
41	
42	  /**
43	   * Subscribes a user to an event type on a channel.
44	   * @param {{ userId: string; channelId: string; eventType: string; filters?: object }} params
45	   * @returns {Promise<object>}
46	   */
47	  async subscribe({ userId, channelId, eventType, filters = {} }) {
48	    const sub = {
49	      id: generateId(),
50	      userId,
51	      channelId,
52	      eventType,
53	      filters,
54	      isEnabled: true,
55	    };
56	    return this._subscriptionRepo.upsert(sub);
57	  }
58	
59	  // ── Queueing ──────────────────────────────────────────────────────────────────
60	
61	  /**
62	   * Queues a notification message for a recipient.
63	   * Deduplicates using an idempotency key derived from the source event.
64	   *
65	   * @param {{ organizationId: string; recipientUserId: string; templateId: string; channelId: string; vars: Record<string, string>; eventSourceKey: string }} params
66	   * @returns {Promise<object>}
67	   */
68	  async enqueue({ organizationId, recipientUserId, templateId, channelId, vars, eventSourceKey }) {
69	    const idempotencyKey = generateIdempotencyKey(eventSourceKey);
70	
71	    // Deduplication: skip if an identical key already exists in non-failed state.
72	    const existing = await this._queueRepo.findAll();
73	    const duplicate = existing.find(
74	      (item) => item.idempotencyKey === idempotencyKey && item.status !== QUEUE_STATUSES.FAILED,
75	    );
76	    if (duplicate) return duplicate;
77	
78	    let renderedBody;
79	    try {
80	      renderedBody = await templateService.renderTemplate(templateId, vars);
81	    } catch (err) {
82	      // Template rendering failure creates a Draft item for manual review.
83	      const draftItem = {
84	        id: generateId(),
85	        organizationId,
86	        recipientUserId,
87	        templateId,
88	        channelId,
89	        payload: vars,
90	        renderedBody: null,
91	        status: QUEUE_STATUSES.DRAFT,
92	        retryCount: 0,
93	        nextRetryAt: null,
94	        failureReason: err.message,
95	        idempotencyKey,
96	        createdAt: Date.now(),
97	        updatedAt: Date.now(),
98	      };
99	      return this._queueRepo.create(draftItem);
100	    }
101	
102	    const item = {
103	      id: generateId(),
104	      organizationId,
105	      recipientUserId,
106	      templateId,
107	      channelId,
108	      payload: vars,
109	      renderedBody,
110	      status: QUEUE_STATUSES.QUEUED,
111	      retryCount: 0,
112	      nextRetryAt: Date.now(), // process immediately
113	      failureReason: null,
114	      idempotencyKey,
115	      createdAt: Date.now(),
116	      updatedAt: Date.now(),
117	    };
118	
119	    return this._queueRepo.create(item);
120	  }
121	
122	  // ── Queue processing ──────────────────────────────────────────────────────────
123	
124	  /**
125	   * Processes all queue items due for delivery.
126	   * Called by SchedulerService (single-tab leader only).
127	   *
128	   * @returns {Promise<{ sent: number; failed: number }>}
129	   */
130	  async processDueItems() {
131	    const due = await this._queueRepo.findDueForRetry(Date.now());
132	    let sent = 0;
133	    let failed = 0;
134	
135	    for (const item of due) {
136	      try {
137	        await this._deliverItem(item);
138	        await this._queueRepo.update(item.id, {
139	          ...item,
140	          status: QUEUE_STATUSES.SENT,
141	          updatedAt: Date.now(),
142	        });
143	        sent++;
144	      } catch (err) {
145	        await this._handleDeliveryFailure(item, err.message);
146	        failed++;
147	      }
148	    }
149	
150	    return { sent, failed };
151	  }
152	
153	  // ── Inbox ─────────────────────────────────────────────────────────────────────
154	
155	  /**
156	   * Returns all notifications for a user, newest first.
157	   * @param {string} userId
158	   * @returns {Promise<object[]>}
159	   */
160	  async getInbox(userId) {
161	    const notifications = await this._notifRepo.findByUser(userId);
162	    return notifications.sort((a, b) => b.createdAt - a.createdAt);
163	  }
164	
165	  /**
166	   * Marks a notification as read.
167	   * @param {string} notificationId
168	   * @returns {Promise<void>}
169	   */
170	  async markRead(notificationId) {
171	    const notif = await this._notifRepo.findById(notificationId);
172	    if (!notif) throw new Error('Notification not found.');
173	    await this._notifRepo.update(notificationId, { ...notif, read: true });
174	  }
175	
176	  // ── Private ──────────────────────────────────────────────────────────────────
177	
178	  /**
179	   * Materialises a queue item into the recipient's in-app notification inbox.
180	   * "Sent" in an offline system means: written to local notifications store.
181	   * @param {object} item
182	   */
183	  async _deliverItem(item) {
184	    if (!item.renderedBody) throw new Error('Cannot deliver item with no rendered body.');
185	
186	    const notification = {
187	      id: generateId(),
188	      userId: item.recipientUserId,
189	      type: 'queue_delivery',
190	      title: 'New message',
191	      body: item.renderedBody,
192	      read: false,
193	      createdAt: Date.now(),
194	    };
195	
196	    await this._notifRepo.create(notification);
197	    await auditService.log({
198	      actorId: 'system',
199	      action: 'notification_sent',
200	      entityType: 'messageQueue',
201	      entityId: item.id,
202	    });
203	  }
204	
205	  /**
206	   * Increments retry count and schedules next attempt, or marks as Failed.
207	   * @param {object} item
208	   * @param {string} reason
209	   */
210	  async _handleDeliveryFailure(item, reason) {
211	    const newRetryCount = item.retryCount + 1;
212	
213	    if (newRetryCount >= MAX_RETRIES) {
214	      await this._queueRepo.update(item.id, {
215	        ...item,
216	        status: QUEUE_STATUSES.FAILED,
217	        retryCount: newRetryCount,
218	        failureReason: reason,
219	        nextRetryAt: null,
220	        updatedAt: Date.now(),
221	      });
222	    } else {
223	      const delayMinutes = RETRY_SCHEDULE_MINUTES[newRetryCount - 1] ?? RETRY_SCHEDULE_MINUTES.at(-1);
224	      const nextRetryAt = Date.now() + delayMinutes * 60_000;
225	      await this._queueRepo.update(item.id, {
226	        ...item,
227	        retryCount: newRetryCount,
228	        failureReason: reason,
229	        nextRetryAt,
230	        updatedAt: Date.now(),
231	      });
232	    }
233	  }
234	}
