2	import { auditService } from './AuditService.js';
3	import { generateId } from '../utils/idGenerator.js';
4	import { ORG_NODE_TYPES, VALID_PARENT_CHILD } from '../utils/constants.js';
5	
6	export class OrgService {
7	  constructor() {
8	    this._repo = new OrgRepository();
9	  }
10	
11	  /**
12	   * Creates a new organization hierarchy node.
13	   * Validates single-parent constraint and valid parent-child type pairing.
14	   *
15	   * @param {{ parentId: string | null; type: string; name: string; organizationId: string; actorId: string }} params
16	   * @returns {Promise<object>}
17	   */
18	  async createNode({ parentId, type, name, organizationId, actorId }) {
19	    if (!Object.values(ORG_NODE_TYPES).includes(type)) {
20	      throw new Error(`Invalid node type: ${type}`);
21	    }
22	
23	    if (parentId) {
24	      const parent = await this._repo.findById(parentId);
25	      if (!parent) throw new Error('Parent node not found.');
26	      if (!this.validateParentChildType(parent.type, type)) {
27	        throw new Error(`Invalid parent-child combination: ${parent.type} → ${type}`);
28	      }
29	    } else if (type !== ORG_NODE_TYPES.COMPANY) {
30	      throw new Error('Only company nodes may have no parent.');
31	    }
32	
33	    const node = {
34	      id: generateId(),
35	      parentId: parentId ?? null,
36	      type,
37	      name,
38	      organizationId,
39	      createdAt: Date.now(),
40	      updatedAt: Date.now(),
41	    };
42	
43	    await this._repo.create(node);
44	    await auditService.log({ actorId, action: 'create_org_node', entityType: 'org', entityId: node.id });
45	    return node;
46	  }
47	
48	  /**
49	   * Updates a node's name.
50	   * Type and parentId changes are not permitted to prevent structural corruption.
51	   *
52	   * @param {string} nodeId
53	   * @param {{ name: string }} data
54	   * @param {string} actorId
55	   * @returns {Promise<object>}
56	   */
57	  async updateNode(nodeId, { name }, actorId) {
58	    const node = await this._repo.findById(nodeId);
59	    if (!node) throw new Error('Node not found.');
60	
61	    const updated = { ...node, name, updatedAt: Date.now() };
62	    await this._repo.update(nodeId, updated);
63	    await auditService.log({ actorId, action: 'update_org_node', entityType: 'org', entityId: nodeId });
64	    return updated;
65	  }
66	
67	  /**
68	   * Deletes a leaf node. Rejects deletion if the node has children.
69	   *
70	   * @param {string} nodeId
71	   * @param {string} actorId
72	   * @returns {Promise<void>}
73	   */
74	  async deleteNode(nodeId, actorId) {
75	    const children = await this._repo.findByParent(nodeId);
76	    if (children.length > 0) throw new Error('Cannot delete a node with children.');
77	
78	    await this._repo.delete(nodeId);
79	    await auditService.log({ actorId, action: 'delete_org_node', entityType: 'org', entityId: nodeId });
80	  }
81	
82	  /**
83	   * Returns the full tree for an organization as a flat array.
84	   * @param {string} organizationId
85	   * @returns {Promise<object[]>}
86	   */
87	  async getTree(organizationId) {
88	    return this._repo.findByOrganization(organizationId);
89	  }
90	
91	  /**
92	   * Returns all nodes in the subtree rooted at nodeId (inclusive).
93	   * @param {string} nodeId
94	   * @returns {Promise<object[]>}
95	   */
96	  async getSubtree(nodeId) {
97	    const result = [];
98	    const root = await this._repo.findById(nodeId);
99	    if (!root) return result;
100	
101	    const queue = [root];
102	    while (queue.length > 0) {
103	      const current = queue.shift();
104	      result.push(current);
105	      const children = await this._repo.findByParent(current.id);
106	      queue.push(...children);
107	    }
108	
109	    return result;
110	  }
111	
112	  /**
113	   * Returns all node IDs the given user is allowed to access.
114	   * @param {{ organizationNodeId: string }} user
115	   * @returns {Promise<string[]>}
116	   */
117	  async getScopedNodeIds(user) {
118	    const subtree = await this.getSubtree(user.organizationNodeId);
119	    return subtree.map((n) => n.id);
120	  }
121	
122	  /**
123	   * Validates that childType is a valid child of parentType.
124	   * @param {string} parentType
125	   * @param {string} childType
126	   * @returns {boolean}
127	   */
128	  validateParentChildType(parentType, childType) {
129	    return VALID_PARENT_CHILD.get(parentType) === childType;
130	  }
131	}
