28	   */
29	  async createStyle({ organizationId, sku, colorId, sizeId, seasonId, brandId, supplierId, storeId, warehouseId, actorId }) {
30	    await this._validateReferences({ colorId, sizeId, seasonId, brandId, supplierId });
31	
32	    const style = {
33	      id: generateId(),
34	      organizationId,
35	      sku,
36	      colorId,
37	      sizeId,
38	      seasonId,
39	      brandId,
40	      supplierId,
