53	  /**
54	   * Updates a style SKU after validating all referenced entities.
55	   *
56	   * @param {string} styleId
57	   * @param {object} data
58	   * @param {string} actorId
59	   * @returns {Promise<object>}
60	   */
61	  async updateStyle(styleId, data, actorId) {
62	    const existing = await this._styleRepo.findById(styleId);
63	    if (!existing) throw new Error('Style not found.');
64	
65	    await this._validateReferences({
