44	   * @param {string} templateId
45	   * @param {{ name?: string; body?: string; isCompact?: boolean }} data
46	   * @param {string} actorId
47	   * @returns {Promise<object>}
48	   */
49	  async updateTemplate(templateId, data, actorId) {
50	    const existing = await this._repo.findById(templateId);
51	    if (!existing) throw new Error('Template not found.');
52	
53	    const newBody = data.body ?? existing.body;
54	    const detectedPlaceholders = extractPlaceholders(newBody);
55	
56	    const updated = {
57	      ...existing,
58	      ...data,
59	      body: newBody,
60	      placeholders: detectedPlaceholders,
61	      updatedAt: Date.now(),
62	    };
63	
64	    await this._repo.update(templateId, updated);
