8	/**
9	 * MasterDataService — versioned master data lifecycle management.
10	 *
11	 * One active version per (entityType, organizationId) at a time.
12	 * Publish operations use optimistic concurrency: if the active version
13	 * changed since the editor loaded, the publish is rejected.
14	 *
15	 * RBAC:
16	 *   - publishVersion → ADMINISTRATOR or STORE_MANAGER
17	 *   - all reads       → any authenticated user
18	 */
19	export class MasterDataService {
20	  constructor() {
21	    this._repo = new MasterDataRepository();
22	  }
23	
24	  /**
25	   * Creates and immediately publishes a new version of a master data entity.
26	   * Atomically deactivates the previous active version.
27	   * Requires: ADMINISTRATOR or STORE_MANAGER role.
28	   *
29	   * @param {{ entityType: string; entityId: string; organizationId: string; payload: object; reasonNote: string; createdBy: string; expectedActiveVersionId: string | null }} params
30	   * @returns {Promise<object>}
31	   */
32	  async publishVersion({ entityType, entityId, organizationId, payload, reasonNote, createdBy, expectedActiveVersionId }) {
33	    const actor = this._requireRole(ROLES.STORE_MANAGER);
34	    this._assertOrgScope(actor, organizationId);
35	    this._assertValidEntityType(entityType);
36	
37	    const noteCheck = validateReasonNote(reasonNote);
38	    if (!noteCheck.valid) throw new Error(noteCheck.error);
39	
40	    if (!payload || typeof payload !== 'object') throw new Error('Payload must be a non-null object.');
41	
42	    // Optimistic concurrency check.
43	    const currentActive = await this._repo.findActiveVersion(entityType, organizationId);
44	    const currentActiveId = currentActive?.id ?? null;
45	    if (currentActiveId !== (expectedActiveVersionId ?? null)) {
46	      throw new Error(
47	        'Concurrency conflict: the active version changed since you loaded this form. Please reload.',
48	      );
49	    }
50	
51	    const history = await this._repo.findVersionHistory(entityId);
52	    const nextVersion = history.length > 0 ? history[0].versionNumber + 1 : 1;
53	
54	    const newVersion = {
55	      id: generateId(),
56	      organizationId,
57	      entityType,
58	      entityId,
59	      versionNumber: nextVersion,
60	      payload,
61	      reasonNote,
62	      isActive: true,
63	      createdBy,
64	      createdAt: Date.now(),
65	    };
66	
67	    await this._repo.atomicVersionSwitch(currentActiveId, newVersion);
68	
69	    await auditService.log({
70	      actorId: createdBy,
71	      action: 'publish_version',
72	      entityType,
73	      entityId,
74	      metadata: { versionNumber: nextVersion, previousActiveId: currentActiveId, organizationId },
75	    });
76	
77	    return newVersion;
78	  }
