  let adminUsername = '';
  let adminPassword = '';
  let orgName = '';
  let error = '';

  async function handleBootstrap() {
    error = '';
    isLoading.set(true);
    try {
      await bootstrapService.bootstrap({ adminUsername, adminPassword, orgName });
      showToast('success', 'System initialized. Please sign in with your new administrator account.');
      navigate('/login');
    } catch (err) {
      error = err.message;
    } finally {
      isLoading.set(false);
    }
