  /** @type {string} */
  export let status;
  /** @type {'order'|'ticket'|'queue'|'risk'|'generic'} */
  export let domain = 'generic';

  const ORDER_COLORS = {
    draft:       'neutral',
    placed:      'blue',
    in_progress: 'yellow',
    ready:       'green',
    completed:   'green-dark',
    canceled:    'red',
  };

  const TICKET_COLORS = {
    open:        'blue',
    in_progress: 'yellow',
    resolved:    'green',
    closed:      'neutral',
  };

  const QUEUE_COLORS = {
    Queued:      'blue',
    Sent:        'green-dark',
    Failed:      'red',
    Draft:       'neutral',
  };

  const RISK_COLORS = {
    open:        'red',
    in_review:   'yellow',
    resolved:    'green',
    dismissed:   'neutral',
  };

  $: colorMap = domain === 'order'
    ? ORDER_COLORS
    : domain === 'ticket'
    ? TICKET_COLORS
    : domain === 'queue'
    ? QUEUE_COLORS
    : domain === 'risk'
    ? RISK_COLORS
    : {};

  $: color = colorMap[status] ?? 'neutral';
  $: label = status.replace(/_/g, ' ');
