1	import { TicketRepository, TicketEventRepository } from '../repositories/implementations/TicketRepository.js';
2	import { auditService } from './AuditService.js';
3	import { authService } from './AuthService.js';
4	import { notificationService } from './NotificationService.js';
5	import { generateId } from '../utils/idGenerator.js';
6	import {
7	  ROLES,
8	  TICKET_STATUSES,
9	  TICKET_EVENT_TYPES,
10	  VALIDATION,
11	} from '../utils/constants.js';
12	import { isValidTicketPriority } from '../utils/validation.js';
13	
14	/** Terminal states that cannot be transitioned out of. */
15	const TERMINAL_STATES = new Set([TICKET_STATUSES.CLOSED]);
16	
17	/** Valid forward transitions. */
18	const TRANSITIONS = new Map([
19	  [TICKET_STATUSES.OPEN, [TICKET_STATUSES.IN_PROGRESS, TICKET_STATUSES.CLOSED]],
20	  [TICKET_STATUSES.IN_PROGRESS, [TICKET_STATUSES.RESOLVED, TICKET_STATUSES.CLOSED]],
21	  [TICKET_STATUSES.RESOLVED, [TICKET_STATUSES.CLOSED]],
22	  [TICKET_STATUSES.CLOSED, []],
23	]);
24	
25	export class TicketService {
26	  constructor() {
27	    this._ticketRepo = new TicketRepository();
28	    this._eventRepo = new TicketEventRepository();
29	  }
30	
31	  /**
32	   * Creates a new after-sales ticket.
33	   * Requires: ADMINISTRATOR or STORE_MANAGER role.
34	   *
35	   * @param {{ customerId: string; orderId?: string; organizationId: string; storeId: string; subject: string; description: string; category: string; priority: string; actorId: string; slaHours?: number }} params
36	   * @returns {Promise<object>}
37	   */
38	  async createTicket({ customerId, orderId, organizationId, storeId, subject, description, category, priority, actorId, slaHours = VALIDATION.DEFAULT_TICKET_SLA_HOURS }) {
39	    const actor = this._requireRole(ROLES.STORE_MANAGER);
40	    this._assertOrgScope(actor, storeId);
41	
42	    if (!subject?.trim()) throw new Error('Subject is required.');
43	    if (!description?.trim()) throw new Error('Description is required.');
44	    if (!category?.trim()) throw new Error('Category is required.');
45	    if (!isValidTicketPriority(priority)) throw new Error(`Invalid priority: '${priority}'. Valid: low, medium, high`);
46	
47	    const now = Date.now();
48	    const ticket = {
49	      id: generateId(),
50	      customerId,
51	      orderId: orderId ?? null,
52	      organizationId,
53	      storeId,
54	      subject,
55	      description,
56	      category,
57	      priority,
58	      status: TICKET_STATUSES.OPEN,
59	      slaDueAt: now + slaHours * 60 * 60 * 1000,
60	      isOverdue: false,
61	      assignedTo: null,
62	      createdAt: now,
63	      updatedAt: now,
64	      resolvedAt: null,
65	      closedBy: null,
66	    };
67	
68	    await this._ticketRepo.create(ticket);
69	    await this._appendEvent({ ticketId: ticket.id, type: TICKET_EVENT_TYPES.CREATED, actorId });
70	    await auditService.log({ actorId, action: 'create_ticket', entityType: 'ticket', entityId: ticket.id });
71	
72	    return ticket;
73	  }
74	
75	  /**
76	   * Assigns a ticket to an agent.
77	   * Requires: ADMINISTRATOR or STORE_MANAGER role.
78	   *
79	   * @param {string} ticketId
80	   * @param {string} assigneeId
81	   * @param {string} actorId
82	   * @returns {Promise<object>}
83	   */
84	  async assignTicket(ticketId, assigneeId, actorId) {
85	    this._requireRole(ROLES.STORE_MANAGER);
86	
87	    const ticket = await this._getOrThrow(ticketId);
88	    this._assertNotTerminal(ticket);
89	
90	    const updated = { ...ticket, assignedTo: assigneeId, status: TICKET_STATUSES.IN_PROGRESS, updatedAt: Date.now() };
91	    await this._ticketRepo.update(ticketId, updated);
92	    await this._appendEvent({ ticketId, type: TICKET_EVENT_TYPES.ASSIGNED, actorId, comment: `Assigned to ${assigneeId}` });
93	    await auditService.log({ actorId, action: 'assign_ticket', entityType: 'ticket', entityId: ticketId, metadata: { assigneeId } });
94	
95	    // Notify the assignee (non-fatal; failure recorded in audit log).
96	    await notificationService.notifyUser(assigneeId, {
97	      type: 'ticket_assigned',
98	      title: 'Ticket assigned to you',
99	      body: `Ticket "${ticket.subject}" has been assigned to you.`,
100	    }).catch((err) => {
101	      auditService.log({
102	        actorId,
103	        action: 'notification_failed',
104	        entityType: 'ticket',
105	        entityId: ticketId,
106	        metadata: { error: err.message, trigger: 'assign' },
107	      }).catch(() => {});
108	    });
109	
110	    return updated;
111	  }
112	
113	  /**
114	   * Transitions a ticket to a new status.
115	   * Requires: ADMINISTRATOR or STORE_MANAGER role.
116	   *
117	   * @param {string} ticketId
118	   * @param {string} newStatus
119	   * @param {string} actorId
120	   * @param {string} [comment]
121	   * @returns {Promise<object>}
122	   */
123	  async transitionTicket(ticketId, newStatus, actorId, comment) {
124	    this._requireRole(ROLES.STORE_MANAGER);
125	
126	    const ticket = await this._getOrThrow(ticketId);
127	    this._assertNotTerminal(ticket);
128	
129	    const allowed = TRANSITIONS.get(ticket.status) ?? [];
130	    if (!allowed.includes(newStatus)) {
131	      throw new Error(`Invalid transition: ${ticket.status} → ${newStatus}. Allowed: ${allowed.join(', ')}`);
132	    }
133	
134	    const now = Date.now();
135	    const patch = { status: newStatus, updatedAt: now };
136	    if (newStatus === TICKET_STATUSES.RESOLVED) patch.resolvedAt = now;
137	    if (newStatus === TICKET_STATUSES.CLOSED) patch.closedBy = actorId;
138	
139	    const updated = { ...ticket, ...patch };
140	    await this._ticketRepo.update(ticketId, updated);
141	    await this._appendEvent({ ticketId, type: newStatus, actorId, comment });
142	    await auditService.log({ actorId, action: 'transition_ticket', entityType: 'ticket', entityId: ticketId, metadata: { from: ticket.status, to: newStatus } });
143	
144	    // Notify assignee of status change (non-fatal; failure recorded in audit log).
145	    if (ticket.assignedTo && ticket.assignedTo !== actorId) {
146	      await notificationService.notifyUser(ticket.assignedTo, {
147	        type: 'ticket_status',
148	        title: `Ticket ${newStatus.replace('_', ' ')}`,
149	        body: `Ticket "${ticket.subject}" is now ${newStatus.replace('_', ' ')}.`,
150	      }).catch((err) => {
151	        auditService.log({
152	          actorId,
153	          action: 'notification_failed',
154	          entityType: 'ticket',
155	          entityId: ticketId,
156	          metadata: { error: err.message, trigger: 'transition', newStatus },
157	        }).catch(() => {});
158	      });
159	    }
160	
161	    return updated;
162	  }
163	
164	  /**
165	   * Evaluates all open/in-progress tickets against their SLA due times.
166	   * Marks overdue tickets and appends an overdue event.
167	   *
168	   * @returns {Promise<object[]>}  Tickets newly marked overdue.
169	   */
170	  async evaluateOverdue() {
171	    const nowMs = Date.now();
172	    const due = await this._ticketRepo.findDueForOverdueCheck(nowMs);
173	
174	    const results = [];
175	    for (const ticket of due) {
176	      const updated = { ...ticket, isOverdue: true, updatedAt: nowMs };
177	      await this._ticketRepo.update(ticket.id, updated);
178	      await this._appendEvent({ ticketId: ticket.id, type: TICKET_EVENT_TYPES.OVERDUE, actorId: 'system' });
179	      results.push(updated);
180	    }
181	    return results;
182	  }
183	
184	  /**
185	   * Returns all overdue tickets.
186	   * Requires: any authenticated user.
187	   *
188	   * @returns {Promise<object[]>}
189	   */
190	  async getOverdue() {
191	    this._requireAuth();
192	    return this._ticketRepo.findOverdue();
193	  }
194	
195	  /**
196	   * Returns ticket with its full event history.
197	   * Requires: any authenticated user.
198	   *
199	   * @param {string} ticketId
200	   * @returns {Promise<{ ticket: object; events: object[] }>}
201	   */
202	  async getTicketDetail(ticketId) {
203	    this._requireAuth();
204	    const ticket = await this._getOrThrow(ticketId);
205	    const events = await this._eventRepo.findByTicket(ticketId);
206	    return { ticket, events: events.sort((a, b) => a.createdAt - b.createdAt) };
207	  }
208	
209	  /**
210	   * Returns all tickets for a customer.
211	   * Requires: any authenticated user.
212	   *
213	   * @param {string} customerId
214	   * @returns {Promise<object[]>}
215	   */
216	  async getByCustomer(customerId) {
217	    this._requireAuth();
218	    return this._ticketRepo.findByCustomer(customerId);
219	  }
220	
221	  /**
222	   * Returns all tickets for a store.
223	   * Requires: any authenticated user.
224	   *
225	   * @param {string} storeId
226	   * @returns {Promise<object[]>}
227	   */
228	  async getByStore(storeId) {
229	    this._requireAuth();
230	    return this._ticketRepo.findByStore(storeId);
231	  }
232	
233	  // ── Private ──────────────────────────────────────────────────────────────────
234	
235	  async _getOrThrow(id) {
236	    const t = await this._ticketRepo.findById(id);
237	    if (!t) throw new Error(`Ticket '${id}' not found.`);
238	    return t;
239	  }
240	
241	  _assertNotTerminal(ticket) {
242	    if (TERMINAL_STATES.has(ticket.status)) {
243	      throw new Error(`Ticket '${ticket.id}' is in terminal state '${ticket.status}' and cannot be modified.`);
244	    }
245	  }
246	
247	  async _appendEvent({ ticketId, type, actorId, comment = '' }) {
248	    const event = {
249	      id: generateId(),
250	      ticketId,
251	      type,
252	      comment,
253	      actorId,
254	      createdAt: Date.now(),
255	    };
256	    return this._eventRepo.create(event);
257	  }
258	
259	  _requireRole(...allowedRoles) {
260	    const user = authService.getCurrentUser();
261	    if (!user) throw new Error('Authentication required.');
262	    if (user.role === ROLES.ADMINISTRATOR) return user;
263	    if (allowedRoles.length > 0 && !allowedRoles.includes(user.role)) {
264	      throw new Error(`Permission denied. Required role(s): ${allowedRoles.join(', ')}`);
265	    }
266	    return user;
267	  }
268	
269	  _requireAuth() {
270	    const user = authService.getCurrentUser();
271	    if (!user) throw new Error('Authentication required.');
272	    return user;
273	  }
274	
275	  _assertOrgScope(actor, targetOrgId) {
276	    if (actor.role === ROLES.ADMINISTRATOR) return;
277	    if (!actor.organizationNodeId) throw new Error('Actor has no organization assigned.');
278	    if (targetOrgId !== actor.organizationNodeId) {
279	      throw new Error('Scope violation: you can only access data within your assigned organization.');
280	    }
281	  }
282	}
283	
284	export const ticketService = new TicketService();
285	

