    await seedRefs();
    authService._currentUser = { id: 'other-mgr', role: ROLES.STORE_MANAGER, organizationNodeId: 'other-org' };
    const svc = new StyleService();
    await expect(svc.createStyle(buildStyle())).rejects.toThrow(/scope/i);
  });
});
