181	
182	    const newCount = customer.ratingCount + 1;
183	    const newAverage = (customer.ratingAverage * customer.ratingCount + rating) / newCount;
184	    const updated = { ...customer, ratingAverage: Math.round(newAverage * 10) / 10, ratingCount: newCount, updatedAt: Date.now() };
185	    await this._repo.update(customerId, updated);
186	    await auditService.log({ actorId, action: 'add_rating', entityType: 'customer', entityId: customerId, metadata: { rating } });
