13	export class NotificationService {
14	  constructor() {
15	    this._channelRepo = new NotificationChannelRepository();
16	    this._subscriptionRepo = new NotificationSubscriptionRepository();
17	    this._queueRepo = new MessageQueueRepository();
18	    this._notifRepo = new NotificationRepository();
