21	  // ── Channel configuration ─────────────────────────────────────────────────────
22	
23	  /**
24	   * Creates or updates a notification channel.
25	   * Only 'in_app' channels are supported in the offline runtime.
26	   * Requires: ADMINISTRATOR or STORE_MANAGER role.
27	   *
28	   * @param {{ organizationId: string; name: string; type?: string; isEnabled?: boolean }} params
29	   * @returns {Promise<object>}
30	   */
31	  async upsertChannel({ organizationId, name, type = 'in_app', isEnabled = true }) {
32	    this._requireRole(ROLES.STORE_MANAGER);
33	
34	    if (!name?.trim()) throw new Error('Channel name is required.');
35	
36	    const channel = {
37	      id: generateId(),
38	      organizationId,
39	      name,
40	      type,
41	      isEnabled,
42	      createdAt: Date.now(),
43	      updatedAt: Date.now(),
44	    };
45	    return this._channelRepo.upsert(channel);
46	  }
47	
48	  /**
49	   * Subscribes a user to an event type on a channel.
50	   * Requires: any authenticated user.
51	   *
52	   * @param {{ userId: string; channelId: string; eventType: string; filters?: object }} params
53	   * @returns {Promise<object>}
54	   */
55	  async subscribe({ userId, channelId, eventType, filters = {} }) {
56	    this._requireAuth();
57	
58	    if (!eventType?.trim()) throw new Error('Event type is required.');
59	
60	    const sub = {
61	      id: generateId(),
62	      userId,
63	      channelId,
64	      eventType,
65	      filters,
66	      isEnabled: true,
67	    };
68	    return this._subscriptionRepo.upsert(sub);
69	  }
70	
71	  // ── Queueing ──────────────────────────────────────────────────────────────────
72	
73	  /**
74	   * Queues a notification message for a recipient.
75	   * Deduplicates using an idempotency key derived from the source event.
76	   * Requires: any authenticated user.
77	   *
78	   * @param {{ organizationId: string; recipientUserId: string; templateId: string; channelId: string; vars: Record<string, string>; eventSourceKey: string }} params
79	   * @returns {Promise<object>}
80	   */
81	  async enqueue({ organizationId, recipientUserId, templateId, channelId, vars, eventSourceKey }) {
82	    this._requireAuth();
83	
84	    if (!eventSourceKey?.trim()) throw new Error('eventSourceKey is required for deduplication.');
85	
86	    const idempotencyKey = generateIdempotencyKey(eventSourceKey);
87	
88	    // Deduplication: skip if an identical key already exists in non-failed state.
89	    const existing = await this._queueRepo.findAll();
90	    const duplicate = existing.find(
91	      (item) => item.idempotencyKey === idempotencyKey && item.status !== QUEUE_STATUSES.FAILED,
92	    );
93	    if (duplicate) return duplicate;
94	
95	    let renderedBody;
96	    try {
97	      renderedBody = await templateService.renderTemplate(templateId, vars);
98	    } catch (err) {
99	      // Only missing-placeholder errors produce a Draft (they may be resolved later).
100	      // Hard constraint violations (compact overflow, etc.) must propagate.
101	      if (!err.message.startsWith('Missing template variables')) throw err;
102	      // Template rendering failure creates a Draft item for manual review.
103	      const draftItem = {
104	        id: generateId(),
105	        organizationId,
106	        recipientUserId,
107	        templateId,
108	        channelId,
109	        payload: vars,
110	        renderedBody: null,
111	        status: QUEUE_STATUSES.DRAFT,
112	        retryCount: 0,
113	        nextRetryAt: null,
114	        failureReason: err.message,
115	        idempotencyKey,
116	        createdAt: Date.now(),
117	        updatedAt: Date.now(),
118	      };
119	      return this._queueRepo.create(draftItem);
120	    }
121	
122	    const item = {
123	      id: generateId(),
124	      organizationId,
125	      recipientUserId,
126	      templateId,
127	      channelId,
128	      payload: vars,
129	      renderedBody,
130	      status: QUEUE_STATUSES.QUEUED,
131	      retryCount: 0,
132	      nextRetryAt: Date.now(), // process immediately
133	      failureReason: null,
134	      idempotencyKey,
135	      createdAt: Date.now(),
136	      updatedAt: Date.now(),
137	    };
138	
139	    return this._queueRepo.create(item);
140	  }
141	
142	  // ── Direct in-app notification ────────────────────────────────────────────────
143	
144	  /**
145	   * Creates an in-app notification directly for a user — no template required.
146	   * Used by other services (OrderService, TicketService) to notify on state changes.
147	   *
148	   * @param {string} userId  Recipient user ID.
149	   * @param {{ type?: string; title: string; body: string }} params
150	   * @returns {Promise<object>}
151	   */
152	  async notifyUser(userId, { type = 'system', title, body }) {
153	    if (!userId) throw new Error('userId is required.');
154	    if (!title?.trim()) throw new Error('Notification title is required.');
155	    if (!body?.trim()) throw new Error('Notification body is required.');
156	
157	    const notification = {
158	      id: generateId(),
159	      userId,
160	      type,
161	      title,
162	      body,
163	      read: false,
164	      createdAt: Date.now(),
165	    };
166	
167	    await this._notifRepo.create(notification);
168	    await auditService.log({
169	      actorId: 'system',
170	      action: 'notification_sent',
171	      entityType: 'notification',
172	      entityId: notification.id,
173	      metadata: { userId, type },
174	    });
175	
176	    return notification;
177	  }
178	
179	  // ── Queue processing ──────────────────────────────────────────────────────────
180	
181	  /**
182	   * Processes all queue items due for delivery.
183	   * Called by SchedulerService (single-tab leader only).
184	   *
185	   * @returns {Promise<{ sent: number; failed: number }>}
186	   */
187	  async processDueItems() {
188	    const due = await this._queueRepo.findDueForRetry(Date.now());
189	    let sent = 0;
190	    let failed = 0;
191	
192	    for (const item of due) {
193	      try {
194	        await this._deliverItem(item);
195	        await this._queueRepo.update(item.id, {
196	          ...item,
197	          status: QUEUE_STATUSES.SENT,
198	          updatedAt: Date.now(),
199	        });
200	        sent++;
201	      } catch (err) {
202	        await this._handleDeliveryFailure(item, err.message);
203	        failed++;
204	      }
205	    }
206	
207	    return { sent, failed };
208	  }
209	
210	  // ── Inbox ─────────────────────────────────────────────────────────────────────
211	
212	  /**
213	   * Returns all notifications for a user, newest first.
214	   * Requires: any authenticated user (own inbox only).
215	   *
216	   * @param {string} userId
217	   * @returns {Promise<object[]>}
218	   */
219	  async getInbox(userId) {
220	    const actor = this._requireAuth();
221	    // Non-admin users can only view their own inbox.
222	    if (actor.role !== ROLES.ADMINISTRATOR && actor.id !== userId) {
223	      throw new Error('Permission denied: you can only view your own inbox.');
224	    }
225	    const notifications = await this._notifRepo.findByUser(userId);
226	    return notifications.sort((a, b) => b.createdAt - a.createdAt);
227	  }
228	
229	  /**
230	   * Marks a notification as read.
231	   * Requires: any authenticated user (own notification only).
232	   *
233	   * @param {string} notificationId
234	   * @returns {Promise<void>}
235	   */
236	  async markRead(notificationId) {
237	    const actor = this._requireAuth();
238	    const notif = await this._notifRepo.findById(notificationId);
239	    if (!notif) throw new Error('Notification not found.');
240	    if (actor.role !== ROLES.ADMINISTRATOR && actor.id !== notif.userId) {
241	      throw new Error('Permission denied: you can only mark your own notifications as read.');
242	    }
243	    await this._notifRepo.update(notificationId, { ...notif, read: true });
244	  }
245	
246	  // ── Private ──────────────────────────────────────────────────────────────────
247	
248	  /**
249	   * Materialises a queue item into the recipient's in-app notification inbox.
250	   * "Sent" in an offline system means: written to local notifications store.
251	   * @param {object} item
252	   */
253	  async _deliverItem(item) {
254	    if (!item.renderedBody) throw new Error('Cannot deliver item with no rendered body.');
255	
256	    const notification = {
257	      id: generateId(),
258	      userId: item.recipientUserId,
259	      type: 'queue_delivery',
260	      title: 'New message',
261	      body: item.renderedBody,
262	      read: false,
263	      createdAt: Date.now(),
264	    };
265	
266	    await this._notifRepo.create(notification);
267	    await auditService.log({
268	      actorId: 'system',
269	      action: 'notification_sent',
270	      entityType: 'messageQueue',
271	      entityId: item.id,
272	    });
273	  }
274	
275	  /**
276	   * Increments retry count and schedules next attempt, or marks as Failed.
277	   * Retry schedule: 1 min, 5 min, 15 min → then Failed.
278	   *
279	   * @param {object} item
280	   * @param {string} reason
281	   */
282	  async _handleDeliveryFailure(item, reason) {
283	    const newRetryCount = item.retryCount + 1;
284	
285	    if (newRetryCount >= MAX_RETRIES) {
286	      await this._queueRepo.update(item.id, {
287	        ...item,
288	        status: QUEUE_STATUSES.FAILED,
289	        retryCount: newRetryCount,
290	        failureReason: reason,
291	        nextRetryAt: null,
292	        updatedAt: Date.now(),
293	      });
294	    } else {
295	      const delayMinutes = RETRY_SCHEDULE_MINUTES[newRetryCount - 1] ?? RETRY_SCHEDULE_MINUTES.at(-1);
296	      const nextRetryAt = Date.now() + delayMinutes * 60_000;
297	      await this._queueRepo.update(item.id, {
298	        ...item,
299	        retryCount: newRetryCount,
300	        failureReason: reason,
301	        nextRetryAt,
302	        updatedAt: Date.now(),
303	      });
304	    }
305	  }
306	
307	  _requireRole(...allowedRoles) {
308	    const user = authService.getCurrentUser();
309	    if (!user) throw new Error('Authentication required.');
310	    if (user.role === ROLES.ADMINISTRATOR) return user;
311	    if (allowedRoles.length > 0 && !allowedRoles.includes(user.role)) {
312	      throw new Error(`Permission denied. Required role(s): ${allowedRoles.join(', ')}`);
313	    }
314	    return user;
315	  }
316	
317	  _requireAuth() {
318	    const user = authService.getCurrentUser();
319	    if (!user) throw new Error('Authentication required.');
320	    return user;
321	  }
322	}
