1	import {
2	  RiskRuleRepository,
3	  RiskCaseRepository,
4	  BidEventRepository,
5	  LinkedAccountRepository,
6	} from '../repositories/implementations/RiskRepository.js';
7	import { auditService } from './AuditService.js';
8	import { authService } from './AuthService.js';
9	import { generateId } from '../utils/idGenerator.js';
10	import { ROLES, RISK_CASE_STATUSES, OUTCOME_CODES } from '../utils/constants.js';
11	import { isValidOutcomeCode, validateImageFile } from '../utils/validation.js';
12	
13	/**
14	 * RiskReviewService — risk case evaluation, bid signal analysis, and resolution.
15	 *
16	 * RBAC:
17	 *   - evaluateRules, validateImage, evaluateBiddingHeuristics → ADMINISTRATOR or STORE_MANAGER
18	 *   - ingestBidEvent, ingestLinkedAccount                     → ADMINISTRATOR or STORE_MANAGER
19	 *   - assignCase, resolveCase, dismissCase                    → ADMINISTRATOR or REVIEWER
20	 *   - getInbox                                                → ADMINISTRATOR or REVIEWER
21	 */
22	export class RiskReviewService {
23	  constructor() {
24	    this._ruleRepo = new RiskRuleRepository();
25	    this._caseRepo = new RiskCaseRepository();
26	    this._bidRepo = new BidEventRepository();
27	    this._linkedRepo = new LinkedAccountRepository();
28	
29	    /** @type {string[]} Sensitive word dictionary (loaded from app config). */
30	    this._sensitiveWords = [];
31	  }
32	
33	  /**
34	   * Loads the sensitive word dictionary from a plain array.
35	   * Words are lowercased for matching.
36	   * @param {string[]} words
37	   */
38	  loadSensitiveWordDictionary(words) {
39	    if (!Array.isArray(words)) throw new Error('Sensitive word dictionary must be an array.');
40	    this._sensitiveWords = words.map((w) => w.toLowerCase());
41	  }
42	
43	  // ── Machine rule evaluation ───────────────────────────────────────────────────
44	
45	  /**
46	   * Evaluates all active rules against a submitted entity and generates risk cases.
47	   * Requires: ADMINISTRATOR or STORE_MANAGER role.
48	   *
49	   * @param {{ organizationId: string; entityType: string; entityId: string; payload: object; actorId: string }} params
50	   * @returns {Promise<object[]>}  Generated risk cases.
51	   */
52	  async evaluateRules({ organizationId, entityType, entityId, payload, actorId }) {
53	    this._requireRole(ROLES.STORE_MANAGER);
54	
55	    if (!entityType?.trim()) throw new Error('entityType is required.');
56	    if (!entityId?.trim()) throw new Error('entityId is required.');
57	    if (!payload || typeof payload !== 'object') throw new Error('payload must be a non-null object.');
58	
59	    const rules = await this._ruleRepo.findActiveByOrg(organizationId);
60	    const applicableRules = rules.filter((r) => r.targetEntityType === entityType || r.targetEntityType === '*');
61	
62	    const matches = [];
63	    for (const rule of applicableRules) {
64	      if (this._ruleMatches(rule, payload)) {
65	        matches.push({ ruleId: rule.id, ruleName: rule.name, ruleType: rule.ruleType });
66	      }
67	    }
68	
69	    // Check sensitive words in any string field of the payload.
70	    const swMatches = this._checkSensitiveWords(payload);
71	    if (swMatches.length > 0) {
72	      matches.push({ ruleId: 'sensitive_word', ruleName: 'Sensitive Word Match', matches: swMatches });
73	    }
74	
75	    if (matches.length === 0) return [];
76	
77	    const riskCase = {
78	      id: generateId(),
79	      organizationId,
80	      sourceType: entityType,
81	      sourceId: entityId,
82	      ruleMatches: matches,
83	      status: RISK_CASE_STATUSES.OPEN,
84	      outcomeCode: null,
85	      resolutionComment: null,
86	      assignedReviewerId: null,
87	      createdAt: Date.now(),
88	      resolvedAt: null,
89	    };
90	
91	    await this._caseRepo.create(riskCase);
92	    await auditService.log({
93	      actorId,
94	      action: 'risk_case_created',
95	      entityType: 'riskCase',
96	      entityId: riskCase.id,
97	      metadata: { sourceType: entityType, ruleMatchCount: matches.length },
98	    });
99	
100	    return [riskCase];
101	  }
102	
103	  /**
104	   * Validates an image file before ingestion.
105	   * Checks MIME type, magic bytes, and size.
106	   * Requires: ADMINISTRATOR or STORE_MANAGER role.
107	   *
108	   * @param {File} file
109	   * @returns {Promise<{ valid: boolean; error: string | null }>}
110	   */
111	  async validateImage(file) {
112	    this._requireRole(ROLES.STORE_MANAGER);
113	    return validateImageFile(file);
114	  }
115	
116	  /**
117	   * Evaluates shill/abnormal bidding heuristics for a given item.
118	   * Device fingerprint clustering is best-effort only.
119	   * Requires: ADMINISTRATOR or STORE_MANAGER role.
120	   *
121	   * @param {{ organizationId: string; itemId: string; windowMs?: number; frequencyThreshold?: number }} params
122	   * @returns {Promise<{ flagged: boolean; reason: string | null; evidence: object }>}
123	   */
124	  async evaluateBiddingHeuristics({ organizationId, itemId, windowMs = 60 * 60_000, frequencyThreshold = 10 }) {
125	    this._requireRole(ROLES.STORE_MANAGER);
126	
127	    if (!itemId?.trim()) throw new Error('itemId is required.');
128	
129	    const now = Date.now();
130	    const events = await this._bidRepo.findByItemInWindow(itemId, now - windowMs, now);
131	
132	    if (events.length >= frequencyThreshold) {
133	      return {
134	        flagged: true,
135	        reason: `Bid frequency ${events.length} exceeds threshold ${frequencyThreshold} within ${windowMs / 60_000} minutes.`,
136	        evidence: { eventCount: events.length, windowMs, frequencyThreshold },
137	      };
138	    }
139	
140	    // Check for fingerprint clustering (best-effort heuristic).
141	    const fingerprints = new Map();
142	    for (const e of events) {
143	      if (e.deviceFingerprint) {
144	        fingerprints.set(e.deviceFingerprint, (fingerprints.get(e.deviceFingerprint) ?? 0) + 1);
145	      }
146	    }
147	    for (const [fp, count] of fingerprints) {
148	      if (count >= Math.floor(frequencyThreshold * 0.5)) {
149	        return {
150	          flagged: true,
151	          reason: `Device fingerprint '${fp}' appears ${count} times — possible coordinated activity (best-effort signal).`,
152	          evidence: { fingerprint: fp, count, isBestEffort: true },
153	        };
154	      }
155	    }
156	
157	    return { flagged: false, reason: null, evidence: {} };
158	  }
159	
160	  // ── Bid / linked account ingestion ───────────────────────────────────────────
161	
162	  /**
163	   * Ingests a bid event for analysis.
164	   * Requires: ADMINISTRATOR or STORE_MANAGER role.
165	   *
166	   * @param {{ organizationId: string; userId: string; itemId: string; deviceFingerprint?: string; bidAmount: number; actorId: string }} params
167	   * @returns {Promise<object>}
168	   */
169	  async ingestBidEvent({ organizationId, userId, itemId, deviceFingerprint = null, bidAmount, actorId }) {
170	    this._requireRole(ROLES.STORE_MANAGER);
171	
172	    if (!userId?.trim()) throw new Error('userId is required.');
173	    if (!itemId?.trim()) throw new Error('itemId is required.');
174	    if (typeof bidAmount !== 'number' || bidAmount <= 0) throw new Error('bidAmount must be a positive number.');
175	
176	    const event = {
177	      id: generateId(),
178	      organizationId,
179	      userId,
180	      itemId,
181	      deviceFingerprint,
182	      bidAmount,
183	      createdAt: Date.now(),
184	    };
185	
186	    await this._bidRepo.create(event);
187	    await auditService.log({
188	      actorId,
189	      action: 'ingest_bid_event',
190	      entityType: 'bidEvent',
191	      entityId: event.id,
192	      metadata: { userId, itemId, bidAmount },
193	    });
194	
195	    return event;
196	  }
197	
198	  /**
199	   * Records a linked account relationship as evidence.
200	   * Requires: ADMINISTRATOR or STORE_MANAGER role.
201	   *
202	   * @param {{ organizationId: string; primaryUserId: string; linkedUserId: string; evidenceType: string; evidenceDetails: string; actorId: string }} params
203	   * @returns {Promise<object>}
204	   */
205	  async ingestLinkedAccount({ organizationId, primaryUserId, linkedUserId, evidenceType, evidenceDetails, actorId }) {
206	    this._requireRole(ROLES.STORE_MANAGER);
207	
208	    if (!primaryUserId?.trim()) throw new Error('primaryUserId is required.');
209	    if (!linkedUserId?.trim()) throw new Error('linkedUserId is required.');
210	    if (primaryUserId === linkedUserId) throw new Error('primaryUserId and linkedUserId must differ.');
211	    if (!evidenceType?.trim()) throw new Error('evidenceType is required.');
212	    if (!evidenceDetails?.trim()) throw new Error('evidenceDetails is required.');
213	
214	    const link = {
215	      id: generateId(),
216	      organizationId,
217	      primaryUserId,
218	      linkedUserId,
219	      evidenceType,
220	      evidenceDetails,
221	      createdAt: Date.now(),
222	    };
223	
224	    await this._linkedRepo.create(link);
225	    await auditService.log({
226	      actorId,
227	      action: 'ingest_linked_account',
228	      entityType: 'linkedAccount',
229	      entityId: link.id,
230	      metadata: { primaryUserId, linkedUserId, evidenceType },
231	    });
232	
233	    return link;
234	  }
235	
236	  // ── Case management ───────────────────────────────────────────────────────────
237	
238	  /**
239	   * Assigns a risk case to a reviewer.
240	   * Requires: ADMINISTRATOR or REVIEWER role.
241	   *
242	   * @param {string} caseId
243	   * @param {string} reviewerId
244	   * @param {string} actorId
245	   * @returns {Promise<object>}
246	   */
247	  async assignCase(caseId, reviewerId, actorId) {
248	    this._requireRole(ROLES.REVIEWER);
249	
250	    const riskCase = await this._getOrThrow(caseId);
