265	  /**
266	   * Resolves a risk case with an outcome code and comment.
267	   * Both outcome code and comment are REQUIRED — no case may close without them.
268	   * Requires: ADMINISTRATOR or REVIEWER role.
269	   *
270	   * @param {{ caseId: string; outcomeCode: string; resolutionComment: string; reviewerId: string }} params
271	   * @returns {Promise<object>}
272	   */
273	  async resolveCase({ caseId, outcomeCode, resolutionComment, reviewerId }) {
274	    this._requireRole(ROLES.REVIEWER);
275	
276	    if (!isValidOutcomeCode(outcomeCode)) {
277	      throw new Error(`Invalid outcome code: '${outcomeCode}'. Valid: ${Object.values(OUTCOME_CODES).join(', ')}`);
278	    }
279	    if (!resolutionComment?.trim()) {
280	      throw new Error('Resolution comment is required to close a risk case.');
281	    }
282	
283	    const riskCase = await this._getOrThrow(caseId);
284	    this._assertNotClosed(riskCase);
285	
286	    const updated = {
287	      ...riskCase,
288	      status: RISK_CASE_STATUSES.RESOLVED,
289	      outcomeCode,
290	      resolutionComment,
291	      assignedReviewerId: reviewerId,
292	      resolvedAt: Date.now(),
293	    };
294	
295	    await this._caseRepo.update(caseId, updated);
296	    await auditService.log({
297	      actorId: reviewerId,
298	      action: 'resolve_risk_case',
299	      entityType: 'riskCase',
300	      entityId: caseId,
301	      metadata: { outcomeCode },
302	    });
303	
304	    return updated;
305	  }
306	
307	  /**
308	   * Dismisses a risk case as a false positive.
309	   * Comment is required.
310	   * Requires: ADMINISTRATOR or REVIEWER role.
311	   *
312	   * @param {string} caseId
313	   * @param {string} resolutionComment
314	   * @param {string} reviewerId
315	   * @returns {Promise<object>}
316	   */
317	  async dismissCase(caseId, resolutionComment, reviewerId) {
318	    this._requireRole(ROLES.REVIEWER);
319	
320	    if (!resolutionComment?.trim()) throw new Error('Comment required to dismiss a risk case.');
321	
322	    const riskCase = await this._getOrThrow(caseId);
323	    this._assertNotClosed(riskCase);
324	
325	    const updated = {
326	      ...riskCase,
327	      status: RISK_CASE_STATUSES.DISMISSED,
328	      outcomeCode: OUTCOME_CODES.FALSE_POSITIVE,
329	      resolutionComment,
330	      assignedReviewerId: reviewerId,
331	      resolvedAt: Date.now(),
332	    };
333	
334	    await this._caseRepo.update(caseId, updated);
335	    await auditService.log({
336	      actorId: reviewerId,
337	      action: 'dismiss_risk_case',
338	      entityType: 'riskCase',
339	      entityId: caseId,
340	    });
341	    return updated;
342	  }
343	
344	  /**
345	   * Returns all open and in-review risk cases for an organization.
346	   * Requires: ADMINISTRATOR or REVIEWER role.
347	   *
348	   * @param {string} organizationId
349	   * @returns {Promise<object[]>}
350	   */
351	  async getInbox(organizationId) {
352	    this._requireRole(ROLES.REVIEWER);
353	    const cases = await this._caseRepo.findByOrg(organizationId);
354	    return cases.filter((c) => c.status === RISK_CASE_STATUSES.OPEN || c.status === RISK_CASE_STATUSES.IN_REVIEW);
355	  }
356	
357	  // ── Private ──────────────────────────────────────────────────────────────────
358	
359	  async _getOrThrow(caseId) {
360	    const c = await this._caseRepo.findById(caseId);
361	    if (!c) throw new Error(`Risk case '${caseId}' not found.`);
362	    return c;
363	  }
364	
365	  _assertNotClosed(riskCase) {
366	    if (riskCase.status === RISK_CASE_STATUSES.RESOLVED || riskCase.status === RISK_CASE_STATUSES.DISMISSED) {
367	      throw new Error(`Risk case '${riskCase.id}' is already closed (${riskCase.status}).`);
368	    }
369	  }
370	
371	  _ruleMatches(rule, payload) {
372	    if (rule.ruleType === 'field_contains') {
373	      const { field, value } = rule.parameters;
374	      const fieldValue = String(payload[field] ?? '').toLowerCase();
375	      return fieldValue.includes(String(value).toLowerCase());
376	    }
377	    if (rule.ruleType === 'field_exceeds') {
378	      const { field, threshold } = rule.parameters;
379	      return Number(payload[field] ?? 0) > threshold;
380	    }
381	    return false;
382	  }
383	
384	  _checkSensitiveWords(payload) {
385	    if (this._sensitiveWords.length === 0) return [];
386	    const text = Object.values(payload)
387	      .filter((v) => typeof v === 'string')
388	      .join(' ')
389	      .toLowerCase();
390	    return this._sensitiveWords.filter((word) => text.includes(word));
391	  }
392	
393	  _requireRole(...allowedRoles) {
394	    const user = authService.getCurrentUser();
395	    if (!user) throw new Error('Authentication required.');
396	    if (user.role === ROLES.ADMINISTRATOR) return user;
397	    if (allowedRoles.length > 0 && !allowedRoles.includes(user.role)) {
398	      throw new Error(`Permission denied. Required role(s): ${allowedRoles.join(', ')}`);
399	    }
400	    return user;
401	  }
402	}
