9	/** States for which a notification is sent on transition. */
10	const NOTIFY_ON_STATUS = new Set([
11	  ORDER_STATUSES.IN_PROGRESS,
12	  ORDER_STATUSES.READY,
13	  ORDER_STATUSES.COMPLETED,
14	  ORDER_STATUSES.CANCELED,
15	]);
16	
17	/** Terminal states that cannot be transitioned out of. */
18	const TERMINAL_STATES = new Set([ORDER_STATUSES.COMPLETED, ORDER_STATUSES.CANCELED]);
19	
20	export class OrderService {
21	  constructor() {
22	    this._orderRepo = new OrderRepository();
23	    this._eventRepo = new OrderEventRepository();
24	    this._customerRepo = new CustomerRepository();
25	  }
26	
27	  /**
28	   * Creates a new order for a customer.
29	   * Reads customer allergy/restriction flags and attaches them to the order.
30	   * Requires: ADMINISTRATOR or STORE_MANAGER role.
31	   *
32	   * @param {{ customerId: string; organizationId: string; storeId: string; actorId: string }} params
33	   * @returns {Promise<object>}
34	   */
35	  async createOrder({ customerId, organizationId, storeId, actorId }) {
36	    const actor = this._requireRole(ROLES.STORE_MANAGER);
37	    this._assertOrgScope(actor, storeId);
38	
39	    const customer = await this._customerRepo.findById(customerId);
40	    if (!customer) throw new Error('Customer not found.');
41	
42	    // Build restriction flags as warning metadata (non-blocking).
43	    const restrictionFlags = {
44	      hasAllergies: customer.allergiesCiphertext !== null,
45	      hasMaterialRestrictions: customer.materialRestrictionsCiphertext !== null,
46	      // Decrypted values are loaded by UI on demand (masked by default).
47	    };
48	
49	    const order = {
50	      id: generateId(),
51	      customerId,
52	      organizationId,
53	      storeId,
54	      status: ORDER_STATUSES.DRAFT,
55	      restrictionFlags,
56	      createdAt: Date.now(),
57	      updatedAt: Date.now(),
58	    };
59	
60	    await this._orderRepo.create(order);
61	    await this._appendEvent({ orderId: order.id, type: 'created', actorId });
62	    await auditService.log({ actorId, action: 'create_order', entityType: 'order', entityId: order.id });
63	
64	    return order;
65	  }
66	
67	  /**
68	   * Transitions an order to the next status.
69	   * Validates the transition is legal. Triggers notifications on key state changes.
70	   * Requires: ADMINISTRATOR or STORE_MANAGER role.
71	   *
72	   * @param {string} orderId
73	   * @param {string} newStatus
74	   * @param {string} actorId
75	   * @returns {Promise<object>}
76	   */
77	  async transitionOrder(orderId, newStatus, actorId) {
78	    this._requireRole(ROLES.STORE_MANAGER);
79	
80	    const order = await this._orderRepo.findById(orderId);
81	    if (!order) throw new Error('Order not found.');
82	
83	    if (TERMINAL_STATES.has(order.status)) {
84	      throw new Error(`Order ${orderId} is in terminal state '${order.status}' and cannot be transitioned.`);
85	    }
86	
87	    const allowed = ORDER_TRANSITIONS.get(order.status) ?? [];
88	    if (!allowed.includes(newStatus)) {
89	      throw new Error(
90	        `Invalid transition: ${order.status} → ${newStatus}. Allowed: ${allowed.join(', ')}`,
91	      );
92	    }
93	
94	    const updated = { ...order, status: newStatus, updatedAt: Date.now() };
95	    await this._orderRepo.update(orderId, updated);
96	    await this._appendEvent({ orderId, type: 'status_changed', actorId, metadata: { from: order.status, to: newStatus } });
97	    await auditService.log({ actorId, action: 'transition_order', entityType: 'order', entityId: orderId, metadata: { from: order.status, to: newStatus } });
98	
99	    // Notify actor on significant state changes.
100	    if (NOTIFY_ON_STATUS.has(newStatus)) {
101	      const label = {
102	        [ORDER_STATUSES.IN_PROGRESS]: 'now in progress',
103	        [ORDER_STATUSES.READY]: 'ready for pickup',
104	        [ORDER_STATUSES.COMPLETED]: 'completed',
105	        [ORDER_STATUSES.CANCELED]: 'canceled',
106	      }[newStatus];
107	      await notificationService.notifyUser(actorId, {
108	        type: 'order_status',
109	        title: `Order ${newStatus.replace('_', ' ')}`,
110	        body: `Order ${orderId} is ${label}.`,
111	      }).catch((err) => {
112	        // Notification failure is non-fatal but must be recorded for observability.
113	        auditService.log({
114	          actorId,
115	          action: 'notification_failed',
116	          entityType: 'order',
117	          entityId: orderId,
118	          metadata: { error: err.message, triggerStatus: newStatus },
119	        }).catch(() => {}); // If the audit store itself is broken, nothing more can be done.
120	      });
121	    }
122	
123	    return updated;
124	  }
125	
126	  /**
127	   * Returns all orders for a customer.
128	   * Requires: any authenticated user.
129	   *
130	   * @param {string} customerId
131	   * @returns {Promise<object[]>}
132	   */
133	  async getByCustomer(customerId) {
134	    this._requireAuth();
135	    return this._orderRepo.findByCustomer(customerId);
136	  }
137	
138	  /**
139	   * Returns a single order with its events.
140	   * Requires: any authenticated user.
141	   *
142	   * @param {string} orderId
143	   * @returns {Promise<{ order: object; events: object[] } | null>}
144	   */
145	  async getOrderDetail(orderId) {
146	    this._requireAuth();
147	    const order = await this._orderRepo.findById(orderId);
148	    if (!order) return null;
149	    const events = await this._eventRepo.findByOrder(orderId);
150	    return { order, events };
151	  }
152	
153	  /**
154	   * Returns all orders for a store.
155	   * Requires: any authenticated user.
156	   *
157	   * @param {string} storeId
158	   * @returns {Promise<object[]>}
159	   */
160	  async getByStore(storeId) {
161	    this._requireAuth();
162	    return this._orderRepo.findByStore(storeId);
163	  }
164	
165	  // ── Private ──────────────────────────────────────────────────────────────────
166	
167	  async _appendEvent({ orderId, type, actorId, metadata = {} }) {
168	    const event = {
169	      id: generateId(),
170	      orderId,
171	      type,
172	      actorId,
173	      metadata,
174	      createdAt: Date.now(),
175	    };
176	    return this._eventRepo.create(event);
177	  }
178	
179	  _requireRole(...allowedRoles) {
180	    const user = authService.getCurrentUser();
181	    if (!user) throw new Error('Authentication required.');
182	    if (user.role === ROLES.ADMINISTRATOR) return user;
183	    if (allowedRoles.length > 0 && !allowedRoles.includes(user.role)) {
184	      throw new Error(`Permission denied. Required role(s): ${allowedRoles.join(', ')}`);
185	    }
186	    return user;
187	  }
188	
189	  _requireAuth() {
190	    const user = authService.getCurrentUser();
191	    if (!user) throw new Error('Authentication required.');
192	    return user;
193	  }
194	
195	  _assertOrgScope(actor, targetOrgId) {
196	    if (actor.role === ROLES.ADMINISTRATOR) return;
197	    if (!actor.organizationNodeId) throw new Error('Actor has no organization assigned.');
198	    if (targetOrgId !== actor.organizationNodeId) {
199	      throw new Error('Scope violation: you can only access data within your assigned organization.');
200	    }
201	  }
202	}
