12	// ── Password ──────────────────────────────────────────────────────────────────
13	
14	/**
15	 * Validates a plaintext password against business rules.
16	 * Rules: min 12 chars, at least one digit, at least one symbol.
17	 *
18	 * @param {string} password
19	 * @returns {{ valid: boolean; errors: string[] }}
20	 */
21	export function validatePassword(password) {
22	  const errors = [];
23	  if (typeof password !== 'string' || password.length < VALIDATION.PASSWORD_MIN_LENGTH) {
24	    errors.push(`Password must be at least ${VALIDATION.PASSWORD_MIN_LENGTH} characters.`);
25	  }
26	  if (!/\d/.test(password)) errors.push('Password must contain at least one number.');
27	  if (!/[^A-Za-z0-9]/.test(password)) errors.push('Password must contain at least one symbol.');
28	  return { valid: errors.length === 0, errors };
29	}
