31	// ── Reason note ───────────────────────────────────────────────────────────────
32	
33	/**
34	 * Validates a master-data change reason note.
35	 * Must be at least 10 non-whitespace-only characters.
36	 *
37	 * @param {string} note
38	 * @returns {{ valid: boolean; error: string | null }}
39	 */
40	export function validateReasonNote(note) {
41	  if (typeof note !== 'string') return { valid: false, error: 'Reason note must be a string.' };
42	  const trimmed = note.trim();
43	  if (trimmed.length < VALIDATION.REASON_NOTE_MIN_LENGTH) {
44	    return {
45	      valid: false,
46	      error: `Reason note must be at least ${VALIDATION.REASON_NOTE_MIN_LENGTH} non-whitespace characters.`,
47	    };
48	  }
49	  return { valid: true, error: null };
50	}
51	
52	// ── Allergy / restriction fields ──────────────────────────────────────────────
53	
54	/**
55	 * Validates the plaintext value of an allergy or material restriction field.
56	 * Must be validated BEFORE encryption.
57	 *
58	 * @param {string} value
59	 * @returns {{ valid: boolean; error: string | null }}
60	 */
61	export function validateAllergyField(value) {
62	  if (typeof value !== 'string') return { valid: false, error: 'Must be a string.' };
63	  if (value.length > VALIDATION.ALLERGY_MAX_CHARS) {
64	    return {
65	      valid: false,
66	      error: `Field must not exceed ${VALIDATION.ALLERGY_MAX_CHARS} characters.`,
67	    };
68	  }
69	  return { valid: true, error: null };
70	}
