72	// ── Stored value ──────────────────────────────────────────────────────────────
73	
74	/**
75	 * Validates a stored value in USD to 2 decimal places.
76	 * Rejects negative values.
77	 *
78	 * @param {number} value
79	 * @returns {{ valid: boolean; error: string | null }}
80	 */
81	export function validateStoredValue(value) {
82	  if (typeof value !== 'number' || isNaN(value)) {
83	    return { valid: false, error: 'Stored value must be a number.' };
84	  }
85	  if (value < 0) return { valid: false, error: 'Stored value cannot be negative.' };
86	  const rounded = Math.round(value * 100) / 100;
87	  if (rounded !== value) {
88	    return { valid: false, error: 'Stored value must have at most 2 decimal places.' };
89	  }
90	  return { valid: true, error: null };
91	}
