93	// ── Points ────────────────────────────────────────────────────────────────────
94	
95	/**
96	 * @param {number} points
97	 * @returns {{ valid: boolean; error: string | null }}
98	 */
99	export function validatePoints(points) {
100	  if (!Number.isInteger(points) || points < 0) {
101	    return { valid: false, error: 'Points must be a non-negative integer.' };
102	  }
103	  return { valid: true, error: null };
104	}
