107	
108	/**
109	 * @param {number} rating
110	 * @returns {{ valid: boolean; error: string | null }}
111	 */
112	export function validateRating(rating) {
113	  if (!Number.isInteger(rating) || rating < VALIDATION.RATING_MIN || rating > VALIDATION.RATING_MAX) {
114	    return {
115	      valid: false,
116	      error: `Rating must be an integer between ${VALIDATION.RATING_MIN} and ${VALIDATION.RATING_MAX}.`,
117	    };
118	  }
119	  return { valid: true, error: null };
120	}
