123	
124	/**
125	 * Validates the rendered (post-substitution) body of a compact notice.
126	 *
127	 * @param {string} renderedBody
128	 * @returns {{ valid: boolean; error: string | null }}
129	 */
130	export function validateCompactNoticeLength(renderedBody) {
131	  if (typeof renderedBody !== 'string') return { valid: false, error: 'Body must be a string.' };
132	  if (renderedBody.length > VALIDATION.COMPACT_NOTICE_MAX_CHARS) {
133	    return {
134	      valid: false,
135	      error: `Compact notice must not exceed ${VALIDATION.COMPACT_NOTICE_MAX_CHARS} characters after substitution (got ${renderedBody.length}).`,
136	    };
137	  }
138	  return { valid: true, error: null };
139	}
