141	// ── Template placeholders ─────────────────────────────────────────────────────
142	
143	const PLACEHOLDER_REGEX = /\{(\w+)\}/g;
144	
145	/**
146	 * Extracts all placeholder names from a template body.
147	 *
148	 * @param {string} body
149	 * @returns {string[]}
150	 */
151	export function extractPlaceholders(body) {
152	  return [...new Set([...body.matchAll(PLACEHOLDER_REGEX)].map((m) => m[1]))];
153	}
154	
155	/**
156	 * Validates that all declared placeholders have values in the substitution map.
157	 *
158	 * @param {string[]} placeholders  - placeholder names declared on the template
159	 * @param {Record<string, string>} vars - substitution values
160	 * @returns {{ valid: boolean; missing: string[] }}
161	 */
162	export function validatePlaceholders(placeholders, vars) {
163	  const missing = placeholders.filter((p) => !(p in vars) || vars[p] == null);
164	  return { valid: missing.length === 0, missing };
165	}
