167	/**
168	 * Performs variable substitution on a template body.
169	 * Throws if any placeholder remains unresolved.
170	 *
171	 * @param {string} body
172	 * @param {Record<string, string>} vars
173	 * @returns {string}
174	 */
175	export function renderTemplate(body, vars) {
176	  return body.replace(PLACEHOLDER_REGEX, (_match, key) => {
177	    if (!(key in vars)) throw new Error(`Unresolved placeholder: {${key}}`);
178	    return String(vars[key]);
179	  });
180	}
