182	// ── Image file ────────────────────────────────────────────────────────────────
183	
184	/**
185	 * Validates an image file by MIME type, magic bytes, and size.
186	 *
187	 * @param {{ name: string; type: string; size: number; arrayBuffer: () => Promise<ArrayBuffer> }} file
188	 * @returns {Promise<{ valid: boolean; error: string | null }>}
189	 */
190	export async function validateImageFile(file) {
191	  if (!ALLOWED_IMAGE_MIME.includes(file.type)) {
192	    return { valid: false, error: 'Only PNG and JPEG images are allowed.' };
193	  }
194	  if (file.size > VALIDATION.MAX_IMAGE_BYTES) {
195	    return { valid: false, error: 'Image must not exceed 5 MB.' };
196	  }
197	
198	  const buffer = await file.arrayBuffer();
199	  const bytes = new Uint8Array(buffer.slice(0, 4));
200	
201	  const isPng = PNG_MAGIC.every((b, i) => bytes[i] === b);
202	  const isJpeg = JPEG_MAGIC.every((b, i) => bytes[i] === b);
203	
204	  if (!isPng && !isJpeg) {
205	    return { valid: false, error: 'File signature does not match PNG or JPEG.' };
206	  }
207	  return { valid: true, error: null };
208	}
