235	
236	const VALID_ROLES = new Set(Object.values(ROLES));
237	
238	/**
239	 * @param {string} role
240	 * @returns {boolean}
241	 */
242	export function isValidRole(role) {
243	  return VALID_ROLES.has(role);
244	}
