246	// ── Ticket priority ───────────────────────────────────────────────────────────
247	
248	const VALID_PRIORITIES = new Set(Object.values(TICKET_PRIORITIES));
249	
250	/**
251	 * @param {string} priority
252	 * @returns {boolean}
253	 */
