1	import { OrgRepository } from '../repositories/implementations/OrgRepository.js';
2	import { auditService } from './AuditService.js';
3	import { authService } from './AuthService.js';
4	import { generateId } from '../utils/idGenerator.js';
5	import { ROLES, ORG_NODE_TYPES, VALID_PARENT_CHILD } from '../utils/constants.js';
6	
7	/**
8	 * OrgService — organization hierarchy management.
9	 *
10	 * RBAC:
11	 *   - createNode, updateNode, deleteNode → ADMINISTRATOR only
12	 *   - reads → any authenticated user
13	 */
14	export class OrgService {
15	  constructor() {
16	    this._repo = new OrgRepository();
17	  }
18	
19	  /**
20	   * Creates a new organization hierarchy node.
21	   * Validates single-parent constraint and valid parent-child type pairing.
22	   * Requires: ADMINISTRATOR role.
23	   *
24	   * @param {{ parentId: string | null; type: string; name: string; organizationId: string; actorId: string }} params
25	   * @returns {Promise<object>}
26	   */
27	  async createNode({ parentId, type, name, organizationId, actorId }) {
28	    this._requireRole(ROLES.ADMINISTRATOR);
29	
30	    if (!name?.trim()) throw new Error('Node name is required.');
31	    if (!Object.values(ORG_NODE_TYPES).includes(type)) {
32	      throw new Error(`Invalid node type: '${type}'. Valid: ${Object.values(ORG_NODE_TYPES).join(', ')}`);
33	    }
34	
35	    if (parentId) {
36	      const parent = await this._repo.findById(parentId);
37	      if (!parent) throw new Error('Parent node not found.');
38	      if (!this.validateParentChildType(parent.type, type)) {
39	        throw new Error(`Invalid parent-child combination: ${parent.type} → ${type}`);
40	      }
41	    } else if (type !== ORG_NODE_TYPES.COMPANY) {
42	      throw new Error('Only company nodes may have no parent.');
43	    }
44	
45	    const node = {
46	      id: generateId(),
47	      parentId: parentId ?? null,
48	      type,
49	      name,
50	      organizationId,
51	      createdAt: Date.now(),
52	      updatedAt: Date.now(),
53	    };
54	
55	    await this._repo.create(node);
56	    await auditService.log({ actorId, action: 'create_org_node', entityType: 'org', entityId: node.id, metadata: { type, name } });
57	    return node;
58	  }
59	
60	  /**
61	   * Updates a node's name only.
62	   * Type and parentId changes are not permitted to prevent structural corruption.
63	   * Requires: ADMINISTRATOR role.
64	   *
65	   * @param {string} nodeId
66	   * @param {{ name: string }} data
67	   * @param {string} actorId
68	   * @returns {Promise<object>}
69	   */
70	  async updateNode(nodeId, { name }, actorId) {
71	    this._requireRole(ROLES.ADMINISTRATOR);
72	
73	    if (!name?.trim()) throw new Error('Node name is required.');
74	
75	    const node = await this._repo.findById(nodeId);
76	    if (!node) throw new Error('Node not found.');
77	
78	    const updated = { ...node, name, updatedAt: Date.now() };
79	    await this._repo.update(nodeId, updated);
80	    await auditService.log({ actorId, action: 'update_org_node', entityType: 'org', entityId: nodeId });
81	    return updated;
82	  }
83	
84	  /**
85	   * Deletes a leaf node. Rejects deletion if the node has children.
86	   * Requires: ADMINISTRATOR role.
87	   *
88	   * @param {string} nodeId
89	   * @param {string} actorId
90	   * @returns {Promise<void>}
91	   */
92	  async deleteNode(nodeId, actorId) {
93	    this._requireRole(ROLES.ADMINISTRATOR);
94	
95	    const children = await this._repo.findByParent(nodeId);
96	    if (children.length > 0) throw new Error('Cannot delete a node with children. Delete child nodes first.');
97	
98	    await this._repo.delete(nodeId);
99	    await auditService.log({ actorId, action: 'delete_org_node', entityType: 'org', entityId: nodeId });
100	  }
101	
102	  /**
103	   * Returns the full tree for an organization as a flat array.
104	   * Requires: any authenticated user.
105	   *
106	   * @param {string} organizationId
107	   * @returns {Promise<object[]>}
108	   */
109	  async getTree(organizationId) {
110	    this._requireAuth();
111	    return this._repo.findByOrganization(organizationId);
112	  }
113	
114	  /**
115	   * Returns all nodes in the subtree rooted at nodeId (inclusive).
116	   * Requires: any authenticated user.
117	   *
118	   * @param {string} nodeId
119	   * @returns {Promise<object[]>}
120	   */
121	  async getSubtree(nodeId) {
122	    this._requireAuth();
123	    const result = [];
124	    const root = await this._repo.findById(nodeId);
125	    if (!root) return result;
126	
127	    const queue = [root];
128	    while (queue.length > 0) {
129	      const current = queue.shift();
130	      result.push(current);
131	      const children = await this._repo.findByParent(current.id);
132	      queue.push(...children);
133	    }
134	
135	    return result;
136	  }
137	
138	  /**
139	   * Returns all node IDs the given user is allowed to access
140	   * (all nodes in the subtree rooted at user.organizationNodeId).
141	   * Requires: any authenticated user.
142	   *
143	   * @param {{ organizationNodeId: string }} user
144	   * @returns {Promise<string[]>}
145	   */
146	  async getScopedNodeIds(user) {
147	    this._requireAuth();
148	    if (!user.organizationNodeId) return [];
149	    const subtree = await this.getSubtree(user.organizationNodeId);
150	    return subtree.map((n) => n.id);
151	  }
152	
153	  /**
154	   * Validates that childType is a valid child of parentType.
155	   * @param {string} parentType
156	   * @param {string} childType
157	   * @returns {boolean}
158	   */
159	  validateParentChildType(parentType, childType) {
160	    return VALID_PARENT_CHILD.get(parentType) === childType;
161	  }
162	
163	  // ── Private helpers ──────────────────────────────────────────────────────────
164	
165	  _requireRole(...allowedRoles) {
166	    const user = authService.getCurrentUser();
167	    if (!user) throw new Error('Authentication required.');
168	    if (user.role === ROLES.ADMINISTRATOR) return user;
169	    if (allowedRoles.length > 0 && !allowedRoles.includes(user.role)) {
170	      throw new Error(`Permission denied. Required role(s): ${allowedRoles.join(', ')}`);
171	    }
172	    return user;
173	  }
174	
175	  _requireAuth() {
176	    const user = authService.getCurrentUser();
177	    if (!user) throw new Error('Authentication required.');
178	    return user;
179	  }
180	}
181	
182	export const orgService = new OrgService();
