1	import { ImportExportRepository } from '../repositories/implementations/ImportExportRepository.js';
2	import { cryptoService } from './CryptoService.js';
3	import { auditService } from './AuditService.js';
4	import { authService } from './AuthService.js';
5	import { DB_VERSION } from '../infrastructure/db/schema.js';
6	import { ROLES } from '../utils/constants.js';
7	
8	/**
9	 * ImportExportService — encrypted backup/restore with schema validation.
10	 *
11	 * Protected stores (sessions, auditLogs) are excluded from export and
12	 * never overwritten during import.
13	 *
14	 * RBAC: ADMINISTRATOR only.
15	 */
16	export class ImportExportService {
17	  constructor() {
18	    this._repo = new ImportExportRepository();
19	  }
20	
21	  /**
22	   * Exports all non-protected stores as an encrypted JSON backup file.
23	   * Uses a separate backup passphrase (not the login password).
24	   * Requires: ADMINISTRATOR role.
25	   *
26	   * @param {{ actorId: string; backupPassphrase: string }} params
27	   * @returns {Promise<Blob>}  A downloadable .json Blob.
28	   */
29	  async exportBackup({ actorId, backupPassphrase }) {
30	    this._requireRole(ROLES.ADMINISTRATOR);
31	
32	    if (!backupPassphrase?.trim()) throw new Error('Backup passphrase is required.');
33	
34	    const snapshot = await this._repo.exportAll();
35	
36	    const envelope = {
37	      schemaVersion: DB_VERSION,
38	      exportedAt: Date.now(),
39	      exportedBy: actorId,
40	      data: snapshot,
41	    };
42	
43	    const { key, saltHex } = await cryptoService.deriveBackupKey(backupPassphrase);
44	    const { ciphertext, iv } = await cryptoService.encryptBackup(JSON.stringify(envelope), key);
45	
46	    const backupFile = JSON.stringify({
47	      version: DB_VERSION,
48	      saltHex,
49	      iv,
50	      ciphertext,
51	    });
52	
53	    await auditService.log({
54	      actorId,
55	      action: 'export_backup',
56	      entityType: 'system',
57	      entityId: 'backup',
58	      metadata: { schemaVersion: DB_VERSION },
59	    });
60	
61	    return new Blob([backupFile], { type: 'application/json' });
62	  }
63	
64	  /**
65	   * Reads and decrypts an import file, validates its schema, and returns
66	   * the preview diff without applying changes.
67	   * Requires: ADMINISTRATOR role.
68	   *
69	   * @param {{ file: File; backupPassphrase: string }} params
70	   * @returns {Promise<{ diff: object[]; snapshot: object; schemaVersion: number }>}
71	   */
72	  async previewImport({ file, backupPassphrase }) {
73	    this._requireRole(ROLES.ADMINISTRATOR);
74	
75	    if (!backupPassphrase?.trim()) throw new Error('Backup passphrase is required.');
76	    if (!file) throw new Error('Import file is required.');
77	
78	    const text = await file.text();
79	    let parsed;
80	    try {
81	      parsed = JSON.parse(text);
82	    } catch {
83	      throw new Error('Import file is not valid JSON.');
84	    }
85	
86	    const { schemaVersion, snapshot } = await this._decryptAndValidate(parsed, backupPassphrase);
87	
88	    const diff = await this._repo.previewDiff(snapshot);
89	
90	    return { diff, snapshot, schemaVersion };
91	  }
92	
93	  /**
94	   * Applies a previously previewed import snapshot, replacing live store data.
95	   * Protected stores (sessions, auditLogs) are never replaced.
96	   * Requires: ADMINISTRATOR role.
97	   *
98	   * @param {{ snapshot: object; actorId: string }} params
99	   * @returns {Promise<void>}
100	   */
101	  async applyImport({ snapshot, actorId }) {
102	    this._requireRole(ROLES.ADMINISTRATOR);
103	
104	    if (!snapshot || typeof snapshot !== 'object') throw new Error('Snapshot must be a non-null object.');
105	
106	    await this._repo.importAll(snapshot);
107	
108	    await auditService.log({
109	      actorId,
110	      action: 'import_backup',
111	      entityType: 'system',
112	      entityId: 'backup',
113	      metadata: { storeCount: Object.keys(snapshot).length },
114	    });
115	  }
116	
117	  /**
118	   * Validates schema version compatibility.
119	   * Throws if the backup schema version does not match the current DB version.
120	   *
121	   * @param {number} backupSchemaVersion
122	   */
123	  validateSchemaVersion(backupSchemaVersion) {
124	    if (backupSchemaVersion !== DB_VERSION) {
125	      throw new Error(
126	        `Schema version mismatch: backup is v${backupSchemaVersion}, app expects v${DB_VERSION}. ` +
127	          'Migration is required before applying this backup.',
128	      );
129	    }
130	  }
131	
132	  // ── Private ──────────────────────────────────────────────────────────────────
133	
134	  async _decryptAndValidate(parsed, backupPassphrase) {
135	    if (!parsed.saltHex || !parsed.iv || !parsed.ciphertext) {
136	      throw new Error('Invalid backup file format: missing required encryption fields (saltHex, iv, ciphertext).');
137	    }
138	
139	    const key = await cryptoService.resolveBackupKey(backupPassphrase, parsed.saltHex);
140	    let json;
141	    try {
142	      json = await cryptoService.decryptBackup(parsed.ciphertext, parsed.iv, key);
143	    } catch {
144	      throw new Error('Failed to decrypt backup. Check that the passphrase is correct.');
145	    }
146	
147	    let envelope;
148	    try {
149	      envelope = JSON.parse(json);
150	    } catch {
151	      throw new Error('Decrypted backup content is not valid JSON.');
152	    }
153	
154	    if (!envelope.data || typeof envelope.schemaVersion !== 'number') {
155	      throw new Error('Invalid backup envelope: missing data or schemaVersion.');
156	    }
157	
158	    this.validateSchemaVersion(envelope.schemaVersion);
159	
160	    return { schemaVersion: envelope.schemaVersion, snapshot: envelope.data };
161	  }
162	
163	  _requireRole(...allowedRoles) {
164	    const user = authService.getCurrentUser();
165	    if (!user) throw new Error('Authentication required.');
166	    if (user.role === ROLES.ADMINISTRATOR) return user;
167	    if (allowedRoles.length > 0 && !allowedRoles.includes(user.role)) {
168	      throw new Error(`Permission denied. Required role(s): ${allowedRoles.join(', ')}`);
169	    }
170	    return user;
171	  }
172	}
173	
