1	/**
2	 * NLPService — offline NLP analysis workspace.
3	 *
4	 * All NLP processing uses bundled, lightweight, deterministic algorithms:
5	 *   - keyword extraction  : TF-IDF frequency analysis
6	 *   - summarization       : extractive (top-scoring sentences)
7	 *   - topic classification: keyword-bag matching against topic dictionaries
8	 *   - sentiment analysis  : lexicon-based polarity scoring
9	 *   - NER                 : dictionary-based entity matching
10	 *
11	 * Quality metrics (precision/recall/F1) are drawn from the active
12	 * ValidationProfile, NOT computed against arbitrary live data.
13	 *
14	 * RBAC:
15	 *   - importText, runBatch, runIncremental → ADMINISTRATOR or ANALYST
16	 *   - getRunHistory, getRunDetail          → ADMINISTRATOR, ANALYST, or REVIEWER
17	 *   - createValidationProfile              → ADMINISTRATOR only
18	 */
19	
20	import {
21	  ImportedTextRepository,
22	  ValidationProfileRepository,
23	  NLPRunRepository,
24	} from '../repositories/implementations/NLPRepository.js';
25	import { auditService } from './AuditService.js';
26	import { authService } from './AuthService.js';
27	import { generateId } from '../utils/idGenerator.js';
28	import { ROLES, NLP } from '../utils/constants.js';
29	
30	export class NLPService {
31	  constructor() {
32	    this._textRepo = new ImportedTextRepository();
33	    this._profileRepo = new ValidationProfileRepository();
34	    this._runRepo = new NLPRunRepository();
35	  }
36	
37	  // ── Text ingestion ────────────────────────────────────────────────────────────
38	
39	  /**
40	   * Imports a text file into the system.
41	   * Requires: ADMINISTRATOR or ANALYST role.
42	   *
43	   * @param {{ sourceType: string; sourceId: string; filename: string; rawText: string; actorId: string }} params
44	   * @returns {Promise<object>}
45	   */
46	  async importText({ sourceType, sourceId, filename, rawText, actorId }) {
47	    this._requireRole(ROLES.ANALYST);
48	
49	    if (!rawText?.trim()) throw new Error('Imported text cannot be empty.');
50	    if (!sourceType?.trim()) throw new Error('Source type is required.');
51	    if (!filename?.trim()) throw new Error('Filename is required.');
52	
53	    const record = {
54	      id: generateId(),
55	      sourceType,
56	      sourceId,
57	      filename,
58	      rawText,
59	      sizeBytes: new TextEncoder().encode(rawText).length,
60	      importedAt: Date.now(),
61	      updatedAt: Date.now(),
62	    };
63	
64	    await this._textRepo.create(record);
65	    await auditService.log({ actorId, action: 'import_text', entityType: 'importedText', entityId: record.id });
66	    return record;
67	  }
68	
69	  // ── Batch run ─────────────────────────────────────────────────────────────────
70	
71	  /**
72	   * Runs NLP analysis on all imported texts in the organization.
73	   * Requires: ADMINISTRATOR or ANALYST role.
74	   *
75	   * @param {{ organizationId: string; modelVersion: string; actorId: string }} params
76	   * @returns {Promise<object>}
77	   */
78	  async runBatch({ organizationId, modelVersion, actorId }) {
79	    this._requireRole(ROLES.ANALYST);
80	
81	    if (!modelVersion?.trim()) throw new Error('Model version is required.');
82	
83	    const texts = await this._textRepo.findAll();
84	    return this._executeRun({
85	      organizationId,
86	      modelVersion,
87	      inputIds: texts.map((t) => t.id),
88	      texts,
89	      runType: NLP.RUN_TYPES.BATCH,
90	      actorId,
91	    });
92	  }
93	
94	  /**
95	   * Runs incremental NLP analysis on texts created or updated since the last run.
96	   * Uses both createdAt AND updatedAt to find new or modified texts.
97	   * Requires: ADMINISTRATOR or ANALYST role.
98	   *
99	   * @param {{ organizationId: string; modelVersion: string; actorId: string }} params
100	   * @returns {Promise<object>}
101	   */
102	  async runIncremental({ organizationId, modelVersion, actorId }) {
103	    this._requireRole(ROLES.ANALYST);
104	
105	    if (!modelVersion?.trim()) throw new Error('Model version is required.');
106	
107	    const lastRun = await this._runRepo.findLatestByOrg(organizationId);
108	    const sinceMs = lastRun?.createdAt ?? 0;
109	
110	    // Find texts created OR updated since the last run.
111	    const texts = await this._textRepo.findUpdatedSince(sinceMs);
112	
113	    return this._executeRun({
114	      organizationId,
115	      modelVersion,
116	      inputIds: texts.map((t) => t.id),
117	      texts,
118	      runType: NLP.RUN_TYPES.INCREMENTAL,
119	      actorId,
120	    });
121	  }
122	
123	  // ── Run history ───────────────────────────────────────────────────────────────
124	
125	  /**
126	   * Returns all NLP runs for an organization, newest first.
127	   * Requires: ADMINISTRATOR, ANALYST, or REVIEWER role.
128	   *
129	   * @param {string} organizationId
130	   * @returns {Promise<object[]>}
131	   */
132	  async getRunHistory(organizationId) {
133	    this._requireRole(ROLES.ANALYST, ROLES.REVIEWER);
134	    const runs = await this._runRepo.findByOrg(organizationId);
135	    return runs.sort((a, b) => b.createdAt - a.createdAt);
136	  }
137	
138	  /**
139	   * Returns a single run with its full output payload.
140	   * Requires: ADMINISTRATOR, ANALYST, or REVIEWER role.
141	   *
142	   * @param {string} runId
143	   * @returns {Promise<object | null>}
144	   */
145	  async getRunDetail(runId) {
146	    this._requireRole(ROLES.ANALYST, ROLES.REVIEWER);
147	    return this._runRepo.findById(runId);
148	  }
149	
150	  // ── Validation profile management ─────────────────────────────────────────────
151	
152	  /**
153	   * Creates a validation profile binding model version to benchmark metrics.
154	   * No live metrics are generated — benchmarks come from the labeled corpus.
155	   * Requires: ADMINISTRATOR only.
156	   *
157	   * @param {{ modelVersion: string; corpusName: string; precision: number; recall: number; f1: number; labeledSampleCount: number; actorId: string }} params
158	   * @returns {Promise<object>}
159	   */
160	  async createValidationProfile({ modelVersion, corpusName, precision, recall, f1, labeledSampleCount, actorId }) {
161	    this._requireRole(ROLES.ADMINISTRATOR);
162	
163	    if (!modelVersion?.trim()) throw new Error('Model version is required.');
164	    if (!corpusName?.trim()) throw new Error('Corpus name is required.');
165	    if (typeof precision !== 'number' || precision < 0 || precision > 1) throw new Error('Precision must be a number between 0 and 1.');
166	    if (typeof recall !== 'number' || recall < 0 || recall > 1) throw new Error('Recall must be a number between 0 and 1.');
167	    if (typeof f1 !== 'number' || f1 < 0 || f1 > 1) throw new Error('F1 score must be a number between 0 and 1.');
168	    if (!Number.isInteger(labeledSampleCount) || labeledSampleCount < 1) throw new Error('labeledSampleCount must be a positive integer.');
169	
170	    const profile = {
171	      id: generateId(),
172	      modelVersion,
173	      corpusName,
174	      precision,
175	      recall,
176	      f1,
177	      labeledSampleCount,
178	      createdAt: Date.now(),
179	    };
180	    const created = await this._profileRepo.create(profile);
181	    await auditService.log({ actorId, action: 'create_validation_profile', entityType: 'validationProfile', entityId: profile.id, metadata: { modelVersion, f1 } });
182	    return created;
183	  }
184	
185	  // ── Private ──────────────────────────────────────────────────────────────────
186	
187	  async _executeRun({ organizationId, modelVersion, inputIds, texts, runType, actorId }) {
188	    const outputPayload = texts.reduce((acc, text) => {
189	      acc[text.id] = {
190	        keywords: this._extractKeywords(text.rawText),
191	        summary: this._extractSummary(text.rawText),
192	        topics: this._classifyTopics(text.rawText),
193	        sentiment: this._analyzeSentiment(text.rawText),
194	        entities: this._extractEntities(text.rawText),
195	      };
196	      return acc;
197	    }, {});
198	
199	    // Benchmark metrics from validation profile — never synthetic.
200	    const profile = await this._profileRepo.findByModelVersion(modelVersion)
201	      ?? await this._profileRepo.findLatest();
202	
203	    const run = {
204	      id: generateId(),
205	      organizationId,
206	      runType,
207	      modelVersion,
208	      inputIds,
209	      outputPayload,
210	      benchmarkPrecision: profile?.precision ?? null,
211	      benchmarkRecall: profile?.recall ?? null,
212	      benchmarkF1: profile?.f1 ?? null,
213	      belowF1Threshold: profile ? (profile.f1 < NLP.F1_ALERT_THRESHOLD) : false,
214	      createdBy: actorId,
215	      createdAt: Date.now(),
216	    };
217	
218	    await this._runRepo.create(run);
219	    await auditService.log({
220	      actorId,
221	      action: 'nlp_run',
222	      entityType: 'nlpRun',
223	      entityId: run.id,
224	      metadata: { runType, modelVersion, inputCount: inputIds.length, belowF1Threshold: run.belowF1Threshold },
225	    });
226	
227	    return run;
228	  }
229	
230	  /**
231	   * Extracts top-N keywords via term frequency.
232	   * @param {string} text
233	   * @param {number} [topN=10]
234	   * @returns {string[]}
235	   */
236	  _extractKeywords(text, topN = 10) {
237	    const stopWords = new Set(['the', 'a', 'an', 'is', 'in', 'on', 'at', 'to', 'and', 'or', 'of', 'it', 'for', 'with', 'this', 'that', 'was', 'are', 'be', 'by', 'from', 'as', 'but', 'not', 'have', 'had', 'has', 'he', 'she', 'they', 'we', 'you', 'i']);
238	    const words = text.toLowerCase().match(/\b[a-z]{3,}\b/g) ?? [];
239	    const freq = new Map();
240	    for (const w of words) {
241	      if (!stopWords.has(w)) freq.set(w, (freq.get(w) ?? 0) + 1);
242	    }
243	    return [...freq.entries()]
244	      .sort((a, b) => b[1] - a[1])
245	      .slice(0, topN)
246	      .map(([w]) => w);
247	  }
248	
249	  /**
250	   * Extractive summarization: returns the top-scoring sentences by keyword density.
251	   * @param {string} text
252	   * @param {number} [numSentences=3]
253	   * @returns {string}
254	   */
255	  _extractSummary(text, numSentences = 3) {
256	    const sentences = text.match(/[^.!?]+[.!?]+/g) ?? [text];
257	    if (sentences.length <= numSentences) return text;
258	    const keywords = new Set(this._extractKeywords(text));
259	    const scored = sentences.map((s) => {
260	      const words = s.toLowerCase().match(/\b[a-z]+\b/g) ?? [];
261	      const score = words.filter((w) => keywords.has(w)).length;
262	      return { sentence: s, score };
263	    });
264	    return scored
265	      .sort((a, b) => b.score - a.score)
266	      .slice(0, numSentences)
267	      .map((s) => s.sentence.trim())
268	      .join(' ');
269	  }
270	
271	  /**
272	   * Topic classification via simple keyword-bag matching.
273	   * @param {string} text
274	   * @returns {string[]}
275	   */
276	  _classifyTopics(text) {
277	    const topics = {
278	      logistics: ['shipping', 'delivery', 'warehouse', 'stock', 'inventory', 'transport'],
279	      customer: ['complaint', 'refund', 'return', 'satisfaction', 'service', 'support'],
280	      finance: ['payment', 'invoice', 'price', 'discount', 'cost', 'billing'],
281	      product: ['quality', 'defect', 'style', 'size', 'color', 'brand'],
282	    };
283	    const lower = text.toLowerCase();
284	    return Object.entries(topics)
285	      .filter(([, keywords]) => keywords.some((k) => lower.includes(k)))
286	      .map(([topic]) => topic);
287	  }
288	
289	  /**
290	   * Sentiment analysis via lexicon scoring.
291	   * @param {string} text
292	   * @returns {{ label: 'positive'|'negative'|'neutral'; score: number }}
293	   */
294	  _analyzeSentiment(text) {
295	    const positive = new Set(['good', 'great', 'excellent', 'happy', 'satisfied', 'love', 'perfect', 'wonderful', 'amazing', 'outstanding', 'positive', 'best', 'helpful']);
296	    const negative = new Set(['bad', 'poor', 'terrible', 'unhappy', 'dissatisfied', 'hate', 'awful', 'horrible', 'broken', 'worst', 'negative', 'disappointing', 'failed']);
297	    const words = text.toLowerCase().match(/\b[a-z]+\b/g) ?? [];
298	    let score = 0;
299	    for (const w of words) {
300	      if (positive.has(w)) score += 1;
301	      if (negative.has(w)) score -= 1;
302	    }
303	    const label = score > 0 ? 'positive' : score < 0 ? 'negative' : 'neutral';
304	    return { label, score };
305	  }
306	
307	  /**
308	   * Dictionary-based NER — recognizes capitalized noun sequences as entities.
309	   * @param {string} text
310	   * @returns {Array<{ text: string; type: string }>}
311	   */
312	  _extractEntities(text) {
313	    const entities = [];
314	    const namedEntityPattern = /\b[A-Z][a-z]+(?: [A-Z][a-z]+)*\b/g;
315	    for (const match of text.matchAll(namedEntityPattern)) {
316	      entities.push({ text: match[0], type: 'PROPER_NOUN' });
317	    }
318	    return entities;
319	  }
320	
321	  _requireRole(...allowedRoles) {
322	    const user = authService.getCurrentUser();
323	    if (!user) throw new Error('Authentication required.');
324	    if (user.role === ROLES.ADMINISTRATOR) return user;
325	    if (allowedRoles.length > 0 && !allowedRoles.includes(user.role)) {
326	      throw new Error(`Permission denied. Required role(s): ${allowedRoles.join(', ')}`);
327	    }
328	    return user;
329	  }
330	}
