1	/**
2	 * ImportExportRepository handles bulk read/write operations for backup/restore.
3	 *
4	 * Unlike domain repositories it operates across multiple stores, so it
5	 * does NOT extend BaseRepository — it holds a reference to the DB directly.
6	 */
7	
8	import { getDB, requestToPromise } from '../../infrastructure/db/db.js';
9	import { ALL_STORE_NAMES, PROTECTED_STORES } from '../../infrastructure/db/schema.js';
10	
11	export class ImportExportRepository {
12	  /**
13	   * Exports all non-protected stores as a plain JS object.
14	   * @returns {Promise<Record<string, object[]>>}
15	   */
16	  async exportAll() {
17	    const db = getDB();
18	    const storeNames = ALL_STORE_NAMES.filter((s) => !PROTECTED_STORES.has(s));
19	    const tx = db.transaction(storeNames, 'readonly');
20	    const result = {};
21	
22	    for (const name of storeNames) {
23	      const store = tx.objectStore(name);
24	      result[name] = await requestToPromise(store.getAll());
25	    }
26	
27	    return result;
28	  }
29	
30	  /**
31	   * Replaces all non-protected stores with the provided data snapshot.
32	   * Runs in a single transaction covering all affected stores.
33	   *
34	   * @param {Record<string, object[]>} snapshot
35	   * @returns {Promise<void>}
36	   */
37	  async importAll(snapshot) {
38	    const db = getDB();
39	    const storeNames = Object.keys(snapshot).filter((s) => !PROTECTED_STORES.has(s));
40	    const tx = db.transaction(storeNames, 'readwrite');
41	
42	    for (const name of storeNames) {
43	      const store = tx.objectStore(name);
44	      await requestToPromise(store.clear());
45	      for (const record of snapshot[name] ?? []) {
46	        await requestToPromise(store.add(record));
47	      }
48	    }
49	
50	    return new Promise((resolve, reject) => {
51	      tx.oncomplete = () => resolve();
52	      tx.onerror = () => reject(tx.error);
53	      tx.onabort = () => reject(new Error('Import transaction aborted'));
54	    });
55	  }
56	
57	  /**
58	   * Returns a preview diff between the current database state and the incoming snapshot.
59	   * Diff entries have the shape: { store, action: 'add'|'update'|'delete', record }
60	   *
61	   * @param {Record<string, object[]>} snapshot
62	   * @returns {Promise<object[]>}
63	   */
64	  async previewDiff(snapshot) {
65	    const db = getDB();
66	    const storeNames = Object.keys(snapshot).filter((s) => !PROTECTED_STORES.has(s));
67	    const diff = [];
68	
69	    for (const name of storeNames) {
70	      const tx = db.transaction(name, 'readonly');
71	      const store = tx.objectStore(name);
72	      const existing = await requestToPromise(store.getAll());
73	      const existingMap = new Map(existing.map((r) => [r.id, r]));
74	      const incomingMap = new Map((snapshot[name] ?? []).map((r) => [r.id, r]));
75	
76	      for (const [id, record] of incomingMap) {
77	        if (!existingMap.has(id)) {
78	          diff.push({ store: name, action: 'add', record });
79	        } else if (JSON.stringify(existingMap.get(id)) !== JSON.stringify(record)) {
80	          diff.push({ store: name, action: 'update', record });
81	        }
82	      }
83	
84	      for (const [id, record] of existingMap) {
85	        if (!incomingMap.has(id)) {
86	          diff.push({ store: name, action: 'delete', record });
87	        }
88	      }
89	    }
90	
91	    return diff;
92	  }
93	}
