1	/**
2	 * Global test setup for RetailOps Console
3	 *
4	 * Configures:
5	 *   - Web Crypto      : explicitly binds globalThis.crypto from node:crypto for Node 18
6	 *   - fake-indexeddb  : shims globalThis.indexedDB for Node 18
7	 *   - BroadcastChannel: jsdom shim (retained for modules that construct BroadcastChannel
8	 *                       directly; production code uses BroadcastService abstractions)
9	 */
10	
11	// ── Web Crypto — explicit binding ─────────────────────────────────────────────
12	// Node 18 ships globalThis.crypto natively, but some jsdom configurations may
13	// shadow it. Explicitly assign webcrypto from node:crypto to guarantee it is
14	// always the real SubtleCrypto implementation.
15	import { webcrypto } from 'node:crypto';
16	
17	if (!globalThis.crypto?.subtle) {
18	  // @ts-ignore — TypeScript does not accept webcrypto as Crypto directly
19	  globalThis.crypto = webcrypto;
20	}
21	
22	// ── IndexedDB shim ────────────────────────────────────────────────────────────
23	import 'fake-indexeddb/auto';
24	import '@testing-library/jest-dom';
25	
26	// ── BroadcastChannel shim ─────────────────────────────────────────────────────
27	// jsdom does not implement BroadcastChannel. This in-process mock is kept so
28	// that BrowserBroadcastService can be instantiated without throwing; tests that
29	// care about messaging should inject MockBroadcastService via setBroadcastService.
30	if (typeof globalThis.BroadcastChannel === 'undefined') {
31	  const registry = new Map(); // name → Set<instance>
32	
33	  class BroadcastChannelMock {
34	    constructor(name) {
35	      this.name = name;
36	      this._closed = false;
37	      this._handlers = [];
38	
39	      if (!registry.has(name)) registry.set(name, new Set());
40	      registry.get(name).add(this);
41	    }
42	
43	    postMessage(data) {
44	      if (this._closed) return;
45	      const peers = registry.get(this.name) ?? new Set();
46	      for (const peer of peers) {
47	        if (peer !== this && !peer._closed) {
48	          const evt = { data, type: 'message' };
49	          peer._handlers.forEach((fn) => fn(evt));
50	          if (typeof peer.onmessage === 'function') peer.onmessage(evt);
51	        }
52	      }
53	    }
54	
55	    addEventListener(_type, fn) {
56	      this._handlers.push(fn);
57	    }
58	
59	    removeEventListener(_type, fn) {
60	      this._handlers = this._handlers.filter((h) => h !== fn);
61	    }
62	
63	    close() {
64	      this._closed = true;
65	      registry.get(this.name)?.delete(this);
66	    }
67	  }
68	
69	  globalThis.BroadcastChannel = BroadcastChannelMock;
70	}
71	
72	// ── Blob polyfills for jsdom ──────────────────────────────────────────────────
73	// jsdom's Blob/File implementation omits .text() and .arrayBuffer().
74	// Polyfill both via FileReader, which jsdom does implement.
75	if (typeof Blob !== 'undefined' && typeof Blob.prototype.text !== 'function') {
76	  Blob.prototype.text = function () {
77	    return new Promise((resolve, reject) => {
78	      const reader = new FileReader();
79	      reader.addEventListener('load', () => resolve(reader.result));
80	      reader.addEventListener('error', reject);
81	      reader.readAsText(this);
82	    });
83	  };
84	}
85	if (typeof Blob !== 'undefined' && typeof Blob.prototype.arrayBuffer !== 'function') {
86	  Blob.prototype.arrayBuffer = function () {
87	    return new Promise((resolve, reject) => {
88	      const reader = new FileReader();
89	      reader.addEventListener('load', () => resolve(reader.result));
90	      reader.addEventListener('error', reject);
91	      reader.readAsArrayBuffer(this);
92	    });
93	  };
94	}
95	
96	// ── Final assertion ───────────────────────────────────────────────────────────
97	if (!globalThis.crypto?.subtle) {
98	  throw new Error(
99	    'globalThis.crypto.subtle is not available. ' +
100	      'Ensure you are running Node 18+ or have a Web Crypto polyfill installed.',
101	  );
102	}
