1	/**
2	 * AuthService — local-only authentication, session, and password management.
3	 *
4	 * Responsibilities:
5	 *   - username/password login and logout
6	 *   - login lockout (5 failed attempts → 15-minute lock)
7	 *   - password validation (min 12 chars, ≥1 digit, ≥1 symbol)
8	 *   - guest trial session (read-only, 30-minute hard expiry)
9	 *   - inactivity auto-lock (10 minutes)
10	 *   - password change with session-key rotation
11	 *   - account deactivation
12	 *   - RBAC role resolution
13	 */
14	
15	import { UserRepository } from '../repositories/implementations/UserRepository.js';
16	import { cryptoService } from './CryptoService.js';
17	import { auditService } from './AuditService.js';
18	import { generateId } from '../utils/idGenerator.js';
19	import { validatePassword, isValidRole } from '../utils/validation.js';
20	import { ROLES, VALIDATION } from '../utils/constants.js';
21	import { cancel, schedule } from '../infrastructure/scheduler/timerManager.js';
22	import {
23	  broadcast,
24	  subscribe,
25	  CHANNEL_NAMES,
26	  EVENT_TYPES,
27	} from '../infrastructure/broadcast/broadcastManager.js';
28	
29	const LOCK_TIMER_KEY = 'auth:auto_lock';
30	const GUEST_TIMER_KEY = 'auth:guest_expiry';
31	const MAX_FAILED_ATTEMPTS = 5;
32	const LOCKOUT_DURATION_MS = 15 * 60_000; // 15 minutes
33	/** Max wrong-password attempts on unlockSession before forcing full logout. */
34	const MAX_UNLOCK_ATTEMPTS = 5;
35	
36	export class AuthService {
37	  constructor() {
38	    this._userRepo = new UserRepository();
39	    /** @type {object | null} Currently active user record. */
40	    this._currentUser = null;
41	    /** @type {boolean} */
42	    this._isLocked = false;
43	    /** @type {boolean} */
44	    this._isGuestSession = false;
45	    /**
46	     * In-memory counter for failed unlockSession attempts.
47	     * Resets on successful unlock or full login.
48	     * Not persisted — physical access resets it (acceptable for local-only app).
49	     * @type {number}
50	     */
51	    this._unlockAttempts = 0;
52	
53	    // Listen for lock events broadcast from other tabs.
54	    subscribe(CHANNEL_NAMES.STATE, (event) => {
55	      if (event.type === EVENT_TYPES.SESSION_LOCKED) {
56	        this._isLocked = true;
57	      } else if (event.type === EVENT_TYPES.SESSION_LOGGED_OUT) {
58	        this._currentUser = null;
59	        this._isLocked = false;
60	        cryptoService.clearSessionKey();
61	      }
62	    });
63	  }
64	
65	  // ── Login / logout ───────────────────────────────────────────────────────────
66	
67	  /**
68	   * Authenticates a user with username and password.
69	   * Derives the session encryption key on success.
70	   * Tracks failed attempts; locks account for 15 minutes after 5 failures.
71	   *
72	   * @param {string} username
73	   * @param {string} password
74	   * @returns {Promise<object>}  The authenticated user record.
75	   * @throws {Error} On invalid credentials, deactivated account, or lockout.
76	   */
77	  async login(username, password) {
78	    const user = await this._userRepo.findByUsername(username);
79	
80	    // Generic error prevents username enumeration.
81	    if (!user) throw new Error('Invalid username or password.');
82	    if (!user.isActive) throw new Error('Account is deactivated.');
83	
84	    // Check lockout before any password work.
85	    const now = Date.now();
86	    if (user.lockoutUntil && now < user.lockoutUntil) {
87	      const remainingMinutes = Math.ceil((user.lockoutUntil - now) / 60_000);
88	      throw new Error(
89	        `Account is temporarily locked due to too many failed attempts. ` +
90	          `Try again in ${remainingMinutes} minute(s).`,
91	      );
92	    }
93	
94	    const valid = await cryptoService.verifyPassword(password, user.passwordSalt, user.passwordHash);
95	
96	    if (!valid) {
97	      const failedAttempts = (user.failedLoginAttempts ?? 0) + 1;
98	      const lockoutUntil = failedAttempts >= MAX_FAILED_ATTEMPTS
99	        ? Date.now() + LOCKOUT_DURATION_MS
100	        : null;
101	
102	      await this._userRepo.update(user.id, {
103	        ...user,
104	        failedLoginAttempts: failedAttempts,
105	        lockoutUntil,
106	        updatedAt: Date.now(),
107	      });
108	
109	      // Generic error — same message regardless of lockout to prevent enumeration.
110	      throw new Error('Invalid username or password.');
111	    }
112	
113	    // Success: clear failure state.
114	    const freshUser = {
115	      ...user,
116	      failedLoginAttempts: 0,
117	      lockoutUntil: null,
118	      updatedAt: Date.now(),
119	    };
120	    await this._userRepo.update(user.id, freshUser);
121	
122	    await cryptoService.deriveSessionKey(password, user.passwordSalt);
123	
124	    this._currentUser = freshUser;
125	    this._isLocked = false;
126	    this._isGuestSession = false;
127	    this._unlockAttempts = 0; // reset on any successful login
128	
129	    this._resetLockTimer();
130	
131	    await auditService.log({
132	      actorId: user.id,
133	      action: 'login',
134	      entityType: 'user',
135	      entityId: user.id,
136	    });
137	
138	    return freshUser;
139	  }
140	
141	  /**
142	   * Logs out the current user and clears all session state.
143	   * @returns {Promise<void>}
144	   */
145	  async logout() {
146	    if (this._currentUser) {
147	      await auditService.log({
148	        actorId: this._currentUser.id,
149	        action: 'logout',
150	        entityType: 'user',
151	        entityId: this._currentUser.id,
152	      });
153	    }
154	
155	    cancel(LOCK_TIMER_KEY);
156	    cancel(GUEST_TIMER_KEY);
157	    cryptoService.clearSessionKey();
158	
159	    this._currentUser = null;
160	    this._isLocked = false;
161	    this._isGuestSession = false;
162	
163	    broadcast(CHANNEL_NAMES.STATE, EVENT_TYPES.SESSION_LOGGED_OUT);
164	  }
165	
166	  // ── Guest session ────────────────────────────────────────────────────────────
167	
168	  /**
169	   * Creates a temporary read-only guest session.
170	   * Hard-expires after 30 minutes and auto-redirects to login.
171	   *
172	   * @param {(reason: string) => void} onExpiry  Called when the guest session expires.
173	   * @returns {{ id: string; role: string; isGuest: true }}
174	   */
175	  createGuestSession(onExpiry) {
176	    const guestUser = {
177	      id: `guest_${Date.now()}`,
178	      username: 'guest',
179	      role: ROLES.GUEST,
180	      organizationNodeId: null,
181	      isActive: true,
182	      isGuest: true,
183	      guestExpiresAt: Date.now() + VALIDATION.GUEST_TRIAL_MINUTES * 60_000,
184	    };
185	
186	    this._currentUser = guestUser;
187	    this._isGuestSession = true;
188	
189	    schedule(
190	      GUEST_TIMER_KEY,
191	      async () => {
192	        await this.logout();
193	        onExpiry('Guest trial expired after 30 minutes.');
194	      },
195	      VALIDATION.GUEST_TRIAL_MINUTES * 60_000,
196	    );
197	
198	    return guestUser;
199	  }
200	
201	  // ── Inactivity lock ──────────────────────────────────────────────────────────
202	
203	  /**
204	   * Resets the inactivity auto-lock timer.
205	   * Must be called on every user interaction.
206	   */
207	  resetInactivityTimer() {
208	    if (!this._currentUser || this._isGuestSession) return;
209	    this._resetLockTimer();
210	  }
211	
212	  /** @private */
213	  _resetLockTimer() {
214	    schedule(
215	      LOCK_TIMER_KEY,
216	      () => {
217	        this.lockSession();
218	        broadcast(CHANNEL_NAMES.STATE, EVENT_TYPES.SESSION_LOCKED);
219	      },
220	      VALIDATION.AUTO_LOCK_MINUTES * 60_000,
221	    );
222	  }
223	
224	  /**
225	   * Locks the session — encrypted data becomes inaccessible until unlock.
226	   */
227	  lockSession() {
228	    cryptoService.clearSessionKey();
229	    this._isLocked = true;
230	  }
231	
232	  /**
233	   * Unlocks the session by re-deriving the encryption key.
234	   *
235	   * @param {string} password
236	   * @returns {Promise<boolean>}
237	   */
238	  async unlockSession(password) {
239	    if (!this._currentUser) throw new Error('No active session to unlock.');
240	
241	    const user = await this._userRepo.findById(this._currentUser.id);
242	    if (!user) throw new Error('User record not found.');
243	
244	    const valid = await cryptoService.verifyPassword(password, user.passwordSalt, user.passwordHash);
245	
246	    if (!valid) {
247	      this._unlockAttempts += 1;
248	      if (this._unlockAttempts >= MAX_UNLOCK_ATTEMPTS) {
249	        // Too many wrong attempts — force full logout to prevent brute-force.
250	        await this.logout();
251	        throw new Error(
252	          `Too many failed unlock attempts (${MAX_UNLOCK_ATTEMPTS}). ` +
253	            'Session has been terminated. Please log in again.',
254	        );
255	      }
256	      return false;
257	    }
258	
259	    // Successful unlock — reset counter, re-derive key, clear lock.
260	    this._unlockAttempts = 0;
261	    await cryptoService.deriveSessionKey(password, user.passwordSalt);
262	    this._isLocked = false;
263	    this._resetLockTimer();
264	    broadcast(CHANNEL_NAMES.STATE, EVENT_TYPES.SESSION_UNLOCKED);
265	    return true;
266	  }
267	
268	  // ── Account management ───────────────────────────────────────────────────────
269	
270	  /**
271	   * Creates a new user account.
272	   * Requires administrator role.
273	   *
274	   * @param {{ username: string; password: string; role: string; organizationNodeId: string }} params
275	   * @returns {Promise<object>}
276	   */
277	  async createUser({ username, password, role, organizationNodeId }) {
278	    this._assertPermission('administrator');
279	
280	    const pwValidation = validatePassword(password);
281	    if (!pwValidation.valid) throw new Error(pwValidation.errors.join(' '));
282	    if (!isValidRole(role)) throw new Error(`Invalid role: ${role}`);
283	
284	    const { hash, salt } = await cryptoService.hashNewPassword(password);
285	
286	    const user = {
287	      id: generateId(),
288	      username,
289	      passwordHash: hash,
290	      passwordSalt: salt,
291	      role,
292	      organizationNodeId,
293	      isActive: true,
294	      isGuest: false,
295	      guestExpiresAt: null,
296	      failedLoginAttempts: 0,
297	      lockoutUntil: null,
298	      createdAt: Date.now(),
299	      updatedAt: Date.now(),
300	    };
301	
302	    await this._userRepo.create(user);
303	    await auditService.log({
304	      actorId: this._currentUser?.id ?? 'system',
305	      action: 'create_user',
306	      entityType: 'user',
307	      entityId: user.id,
308	      metadata: { username, role },
309	    });
310	
311	    return user;
312	  }
313	
314	  /**
315	   * Changes a user's password and re-encrypts all their sensitive data.
316	   *
317	   * @param {string} userId
318	   * @param {string} oldPassword
319	   * @param {string} newPassword
320	   * @param {Array<{ ciphertext: string; iv: string }>} encryptedFields
321	   * @returns {Promise<Array<{ ciphertext: string; iv: string; algorithmVersion: string }>>}
322	   */
323	  async changePassword(userId, oldPassword, newPassword, encryptedFields = []) {
324	    const pwValidation = validatePassword(newPassword);
325	    if (!pwValidation.valid) throw new Error(pwValidation.errors.join(' '));
326	
327	    const user = await this._userRepo.findById(userId);
328	    if (!user) throw new Error('User not found.');
329	
330	    const valid = await cryptoService.verifyPassword(oldPassword, user.passwordSalt, user.passwordHash);
331	    if (!valid) throw new Error('Old password is incorrect.');
332	
333	    const { hash, salt } = await cryptoService.hashNewPassword(newPassword);
334	
335	    // Re-encrypt all sensitive fields before committing the password change.
336	    const reEncrypted = await cryptoService.rotateEncryptedFields(
337	      encryptedFields,
338	      oldPassword,
339	      user.passwordSalt,
340	      newPassword,
341	    );
342	
343	    await this._userRepo.update(userId, {
344	      ...user,
345	      passwordHash: hash,
346	      passwordSalt: salt,
347	      updatedAt: Date.now(),
348	    });
349	
350	    // Re-derive session key with new password.
351	    await cryptoService.deriveSessionKey(newPassword, salt);
352	
353	    await auditService.log({
354	      actorId: userId,
355	      action: 'change_password',
356	      entityType: 'user',
357	      entityId: userId,
358	    });
359	
360	    return reEncrypted;
361	  }
362	
363	  /**
364	   * Deactivates a user account.
365	   * Requires administrator role.
366	   * @param {string} userId
367	   * @returns {Promise<void>}
368	   */
369	  async deactivateAccount(userId) {
370	    this._assertPermission('administrator');
371	
372	    const user = await this._userRepo.findById(userId);
373	    if (!user) throw new Error('User not found.');
374	
375	    await this._userRepo.update(userId, { ...user, isActive: false, updatedAt: Date.now() });
376	
377	    await auditService.log({
378	      actorId: this._currentUser?.id ?? 'system',
379	      action: 'deactivate_account',
380	      entityType: 'user',
381	      entityId: userId,
382	    });
383	  }
384	
385	  // ── State accessors ──────────────────────────────────────────────────────────
386	
387	  /** @returns {object | null} */
388	  getCurrentUser() {
389	    return this._currentUser;
390	  }
391	
392	  /** @returns {boolean} */
393	  isAuthenticated() {
394	    return this._currentUser !== null && !this._isGuestSession;
395	  }
396	
397	  /** @returns {boolean} */
398	  isLocked() {
399	    return this._isLocked;
400	  }
401	
402	  /** @returns {boolean} */
403	  isGuest() {
404	    return this._isGuestSession;
405	  }
406	
407	  /**
408	   * Returns true if the current user has the given role or Administrator access.
409	   * @param {string} requiredRole
410	   * @returns {boolean}
411	   */
412	  hasRole(requiredRole) {
413	    if (!this._currentUser) return false;
414	    if (this._currentUser.role === ROLES.ADMINISTRATOR) return true;
415	    return this._currentUser.role === requiredRole;
416	  }
417	
418	  // ── Private helpers ──────────────────────────────────────────────────────────
419	
420	  /**
421	   * Throws if the current user does not have the required role.
422	   * @param {string} requiredRole
423	   */
424	  _assertPermission(requiredRole) {
425	    if (!this.hasRole(requiredRole)) {
426	      throw new Error(`Permission denied. Required role: ${requiredRole}`);
427	    }
428	  }
429	}
430	
431	export const authService = new AuthService();
432	

