1	<script>
2	  import { onMount, onDestroy } from 'svelte';
3	  import { routes, DEFAULT_ROUTE, PUBLIC_ROUTES, ROLE_ROUTES } from './routes.js';
4	  import { currentPath, navigate } from '../stores/ui.js';
5	  import { isAuthenticated, isGuest, currentRole } from '../stores/auth.js';
6	
7	  let CurrentPage = null;
8	
9	  function resolvePageComponent(path, authenticated, guest, role) {
10	    // Unauthenticated users are redirected to login.
11	    if (!authenticated && !guest && !PUBLIC_ROUTES.has(path)) {
12	      navigate('/login');
13	      return routes['/login'];
14	    }
15	
16	    // Check role-based access.
17	    if (authenticated && role) {
18	      const allowed = ROLE_ROUTES[role] ?? new Set();
19	      if (!PUBLIC_ROUTES.has(path) && !allowed.has(path)) {
20	        // Redirect to a default accessible route for the role.
21	        const defaultForRole = [...allowed][0] ?? '/login';
22	        navigate(defaultForRole);
23	        return routes[defaultForRole] ?? routes[DEFAULT_ROUTE];
24	      }
25	    }
26	
27	    return routes[path] ?? routes[DEFAULT_ROUTE];
28	  }
29	
30	  function onHashChange() {
31	    const path = window.location.hash.slice(1) || DEFAULT_ROUTE;
32	    currentPath.set(path);
33	  }
34	
35	  onMount(() => {
36	    onHashChange();
37	    window.addEventListener('hashchange', onHashChange);
38	  });
39	
40	  onDestroy(() => {
41	    window.removeEventListener('hashchange', onHashChange);
42	  });
43	
44	  $: CurrentPage = resolvePageComponent($currentPath, $isAuthenticated, $isGuest, $currentRole);
45	</script>
46	
47	{#if CurrentPage}
48	  <svelte:component this={CurrentPage} />
49	{:else}
50	  <div style="display:flex;align-items:center;justify-content:center;height:100vh;">
51	    <p>Loading…</p>
52	  </div>
53	{/if}
