  const NAV_LABELS = {
    '/crm': 'CRM',
    '/orders': 'Orders',
    '/master-data': 'Master Data',
    '/messages': 'Messages',
    '/nlp': 'NLP Analysis',
    '/risk-review': 'Risk Review',
    '/org-setup': 'Org Setup',
    '/admin': 'Admin',
