  $: allowedRoutes = (() => {
    const role = $currentRole ?? ($isGuest ? 'guest' : null);
    if (!role) return [];
    return [...(ROLE_ROUTES[role] ?? [])].filter((r) => NAV_LABELS[r]);
  })();

  onMount(async () => {
    try {
      await initDB();
      dbReady = true;

      restoreColumnLayouts();
      restoreSelectedStore();

      // First-run check: if no users exist, redirect to bootstrap setup.
      const bootstrapped = await bootstrapService.isBootstrapped();
      if (!bootstrapped) {
        navigate('/bootstrap');
      }

      // Register domain tasks then start the scheduler.
      schedulerService.registerTask('queue_check', () => notificationService.processDueItems(), 30_000);
      schedulerService.registerTask('overdue_check', () => ticketService.evaluateOverdue(), 5 * 60_000);
      await schedulerService.start();
    } catch (err) {
      dbError = err.message;
      console.error('[App] Startup error:', err);
