2	import { cryptoService } from './CryptoService.js';
3	import { auditService } from './AuditService.js';
4	import { authService } from './AuthService.js';
5	import { generateId } from '../utils/idGenerator.js';
6	import {
7	  validateAllergyField,
8	  validateStoredValue,
9	  validatePoints,
10	  validateRating,
11	  isValidMembershipTier,
12	} from '../utils/validation.js';
13	import { ROLES, MEMBERSHIP_TIERS } from '../utils/constants.js';
