15	export class CustomerService {
16	  constructor() {
17	    this._repo = new CustomerRepository();
18	  }
19	
20	  /**
21	   * Creates a new customer record with encrypted sensitive fields.
22	   * Requires: ADMINISTRATOR or STORE_MANAGER role.
23	   * Scope: actor must have access to the target organizationId.
24	   *
25	   * @param {{ organizationId: string; name: string; membershipTier?: string; points?: number; storedValue?: number; allergies?: string; materialRestrictions?: string; actorId: string }} params
26	   * @returns {Promise<object>}
27	   */
28	  async createCustomer({ organizationId, name, membershipTier = MEMBERSHIP_TIERS.BRONZE, points = 0, storedValue = 0, allergies = '', materialRestrictions = '', actorId }) {
29	    const actor = this._requireRole(ROLES.STORE_MANAGER);
30	    this._assertOrgScope(actor, organizationId);
31	
32	    if (!name?.trim()) throw new Error('Customer name is required.');
33	    if (!isValidMembershipTier(membershipTier)) throw new Error(`Invalid membership tier: ${membershipTier}`);
34	
35	    const allergyCheck = validateAllergyField(allergies);
36	    if (!allergyCheck.valid) throw new Error(`Allergies: ${allergyCheck.error}`);
37	
38	    const mrCheck = validateAllergyField(materialRestrictions);
39	    if (!mrCheck.valid) throw new Error(`Material restrictions: ${mrCheck.error}`);
40	
41	    const svCheck = validateStoredValue(storedValue);
42	    if (!svCheck.valid) throw new Error(svCheck.error);
43	
44	    const ptCheck = validatePoints(points);
45	    if (!ptCheck.valid) throw new Error(ptCheck.error);
46	
47	    if (!cryptoService.isUnlocked()) throw new Error('Session is locked. Please unlock to create customers with encrypted fields.');
48	
49	    const encAllergies = allergies ? await cryptoService.encrypt(allergies) : null;
50	    const encMR = materialRestrictions ? await cryptoService.encrypt(materialRestrictions) : null;
51	    const encSV = await cryptoService.encrypt(String(storedValue.toFixed(2)));
52	
53	    const customer = {
54	      id: generateId(),
55	      organizationId,
56	      name,
57	      membershipTier,
58	      points,
59	      storedValueCiphertext: encSV.ciphertext,
60	      storedValueIv: encSV.iv,
61	      allergiesCiphertext: encAllergies?.ciphertext ?? null,
62	      allergiesIv: encAllergies?.iv ?? null,
63	      materialRestrictionsCiphertext: encMR?.ciphertext ?? null,
64	      materialRestrictionsIv: encMR?.iv ?? null,
65	      ratingAverage: 0,
66	      ratingCount: 0,
67	      createdAt: Date.now(),
68	      updatedAt: Date.now(),
69	    };
70	
71	    await this._repo.create(customer);
72	    await auditService.log({ actorId, action: 'create_customer', entityType: 'customer', entityId: customer.id });
73	    return customer;
74	  }
75	
76	  /**
77	   * Updates non-sensitive customer fields.
78	   * Requires: ADMINISTRATOR or STORE_MANAGER role.
79	   *
80	   * @param {string} customerId
81	   * @param {{ name?: string; membershipTier?: string }} data
82	   * @param {string} actorId
83	   * @returns {Promise<object>}
84	   */
85	  async updateCustomer(customerId, data, actorId) {
86	    const actor = this._requireRole(ROLES.STORE_MANAGER);
87	
88	    const customer = await this._repo.findById(customerId);
89	    if (!customer) throw new Error('Customer not found.');
90	    this._assertOrgScope(actor, customer.organizationId);
91	
92	    if (data.membershipTier && !isValidMembershipTier(data.membershipTier)) {
93	      throw new Error(`Invalid membership tier: ${data.membershipTier}`);
94	    }
95	
96	    const updated = { ...customer, ...data, updatedAt: Date.now() };
97	    await this._repo.update(customerId, updated);
98	    await auditService.log({ actorId, action: 'update_customer', entityType: 'customer', entityId: customerId });
99	    return updated;
100	  }
101	
102	  /**
103	   * Adjusts stored value by delta (positive = credit, negative = debit).
104	   * Blocks negative balance.
105	   * Requires: ADMINISTRATOR or STORE_MANAGER role.
106	   *
107	   * @param {string} customerId
108	   * @param {number} delta
109	   * @param {string} actorId
110	   * @returns {Promise<object>}
111	   */
112	  async adjustStoredValue(customerId, delta, actorId) {
113	    const actor = this._requireRole(ROLES.STORE_MANAGER);
114	
115	    if (!cryptoService.isUnlocked()) throw new Error('Session is locked. Cannot access encrypted stored value.');
116	
117	    const customer = await this._repo.findById(customerId);
118	    if (!customer) throw new Error('Customer not found.');
119	    this._assertOrgScope(actor, customer.organizationId);
120	
121	    const currentStr = await cryptoService.decrypt(customer.storedValueCiphertext, customer.storedValueIv);
122	    const current = parseFloat(currentStr);
123	    const newValue = Math.round((current + delta) * 100) / 100;
124	
125	    const svCheck = validateStoredValue(newValue);
126	    if (!svCheck.valid) throw new Error(svCheck.error);
127	
128	    const encSV = await cryptoService.encrypt(String(newValue.toFixed(2)));
129	    const updated = { ...customer, storedValueCiphertext: encSV.ciphertext, storedValueIv: encSV.iv, updatedAt: Date.now() };
130	    await this._repo.update(customerId, updated);
131	    await auditService.log({ actorId, action: 'adjust_stored_value', entityType: 'customer', entityId: customerId, metadata: { delta } });
132	    return updated;
133	  }
134	
135	  /**
136	   * Adjusts points balance.
137	   * Requires: ADMINISTRATOR or STORE_MANAGER role.
138	   *
139	   * @param {string} customerId
140	   * @param {number} delta  Positive or negative integer.
141	   * @param {string} actorId
142	   * @returns {Promise<object>}
143	   */
144	  async adjustPoints(customerId, delta, actorId) {
145	    const actor = this._requireRole(ROLES.STORE_MANAGER);
146	
147	    const customer = await this._repo.findById(customerId);
148	    if (!customer) throw new Error('Customer not found.');
149	    this._assertOrgScope(actor, customer.organizationId);
150	
151	    if (!Number.isInteger(delta)) throw new Error('Points delta must be an integer.');
152	
153	    const newPoints = customer.points + delta;
154	    const ptCheck = validatePoints(newPoints);
155	    if (!ptCheck.valid) throw new Error(ptCheck.error);
156	
157	    const updated = { ...customer, points: newPoints, updatedAt: Date.now() };
158	    await this._repo.update(customerId, updated);
159	    await auditService.log({ actorId, action: 'adjust_points', entityType: 'customer', entityId: customerId, metadata: { delta } });
160	    return updated;
161	  }
162	
163	  /**
164	   * Adds a service rating for the customer.
