172	   */
173	  async addRating(customerId, rating, actorId) {
174	    this._requireRole(ROLES.STORE_MANAGER);
175	
176	    const ratingCheck = validateRating(rating);
177	    if (!ratingCheck.valid) throw new Error(ratingCheck.error);
178	
179	    const customer = await this._repo.findById(customerId);
180	    if (!customer) throw new Error('Customer not found.');
181	
182	    const newCount = customer.ratingCount + 1;
183	    const newAverage = (customer.ratingAverage * customer.ratingCount + rating) / newCount;
184	    const updated = { ...customer, ratingAverage: Math.round(newAverage * 10) / 10, ratingCount: newCount, updatedAt: Date.now() };
185	    await this._repo.update(customerId, updated);
186	    await auditService.log({ actorId, action: 'add_rating', entityType: 'customer', entityId: customerId, metadata: { rating } });
187	    return updated;
188	  }
189	
190	  /**
191	   * Decrypts and returns sensitive fields for display.
192	   * Requires an unlocked session.
193	   * Requires: ADMINISTRATOR, STORE_MANAGER, or ANALYST role.
194	   *
195	   * @param {string} customerId
