210	    const materialRestrictions = customer.materialRestrictionsCiphertext
211	      ? await cryptoService.decrypt(customer.materialRestrictionsCiphertext, customer.materialRestrictionsIv)
212	      : null;
213	
214	    return { storedValue, allergies, materialRestrictions };
215	  }
216	
217	  /**
218	   * Returns masked placeholders for sensitive fields.
219	   * Requires: any authenticated user.
