119	   * Requires: ADMINISTRATOR or STORE_MANAGER role.
120	   *
121	   * @param {{ organizationId: string; itemId: string; windowMs?: number; frequencyThreshold?: number }} params
122	   * @returns {Promise<{ flagged: boolean; reason: string | null; evidence: object }>}
123	   */
124	  async evaluateBiddingHeuristics({ organizationId, itemId, windowMs = 60 * 60_000, frequencyThreshold = 10 }) {
125	    this._requireRole(ROLES.STORE_MANAGER);
126	
127	    if (!itemId?.trim()) throw new Error('itemId is required.');
128	
129	    const now = Date.now();
130	    const events = await this._bidRepo.findByItemInWindow(itemId, now - windowMs, now);
131	
132	    if (events.length >= frequencyThreshold) {
133	      return {
134	        flagged: true,
135	        reason: `Bid frequency ${events.length} exceeds threshold ${frequencyThreshold} within ${windowMs / 60_000} minutes.`,
136	        evidence: { eventCount: events.length, windowMs, frequencyThreshold },
137	      };
138	    }
139	
140	    // Check for fingerprint clustering (best-effort heuristic).
141	    const fingerprints = new Map();
142	    for (const e of events) {
143	      if (e.deviceFingerprint) {
144	        fingerprints.set(e.deviceFingerprint, (fingerprints.get(e.deviceFingerprint) ?? 0) + 1);
145	      }
146	    }
147	    for (const [fp, count] of fingerprints) {
148	      if (count >= Math.floor(frequencyThreshold * 0.5)) {
149	        return {
150	          flagged: true,
151	          reason: `Device fingerprint '${fp}' appears ${count} times — possible coordinated activity (best-effort signal).`,
152	          evidence: { fingerprint: fp, count, isBestEffort: true },
153	        };
154	      }
155	    }
156	
157	    return { flagged: false, reason: null, evidence: {} };
158	  }
