347	  /**
348	   * Returns all open and in-review risk cases for an organization.
349	   * Requires: ADMINISTRATOR or REVIEWER role.
350	   *
351	   * @param {string} organizationId
352	   * @returns {Promise<object[]>}
353	   */
354	  async getInbox(organizationId) {
