360	  // ── Private ──────────────────────────────────────────────────────────────────
361	
362	  async _getOrThrow(caseId) {
363	    const c = await this._caseRepo.findById(caseId);
364	    if (!c) throw new Error(`Risk case '${caseId}' not found.`);
365	    return c;
366	  }
367	
368	  _assertNotClosed(riskCase) {
369	    if (riskCase.status === RISK_CASE_STATUSES.RESOLVED || riskCase.status === RISK_CASE_STATUSES.DISMISSED) {
370	      throw new Error(`Risk case '${riskCase.id}' is already closed (${riskCase.status}).`);
371	    }
372	  }
373	
374	  _ruleMatches(rule, payload) {
375	    if (rule.ruleType === 'field_contains') {
376	      const { field, value } = rule.parameters;
377	      const fieldValue = String(payload[field] ?? '').toLowerCase();
378	      return fieldValue.includes(String(value).toLowerCase());
379	    }
380	    if (rule.ruleType === 'field_exceeds') {
381	      const { field, threshold } = rule.parameters;
382	      return Number(payload[field] ?? 0) > threshold;
383	    }
384	    return false;
385	  }
386	
387	  _checkSensitiveWords(payload) {
388	    if (this._sensitiveWords.length === 0) return [];
389	    const text = Object.values(payload)
390	      .filter((v) => typeof v === 'string')
391	      .join(' ')
392	      .toLowerCase();
393	    return this._sensitiveWords.filter((word) => text.includes(word));
394	  }
395	
396	  _requireRole(...allowedRoles) {
397	    const user = authService.getCurrentUser();
398	    if (!user) throw new Error('Authentication required.');
399	    if (user.role === ROLES.ADMINISTRATOR) return user;
400	    if (allowedRoles.length > 0 && !allowedRoles.includes(user.role)) {
401	      throw new Error(`Permission denied. Required role(s): ${allowedRoles.join(', ')}`);
402	    }
403	    return user;
404	  }
405	
406	  _assertOrgScope(actor, targetOrgId) {
407	    if (actor.role === ROLES.ADMINISTRATOR) return;
408	    if (!actor.organizationNodeId) throw new Error('Actor has no organization assigned.');
409	    if (targetOrgId !== actor.organizationNodeId) {
410	      throw new Error('Scope violation: you can only access data within your assigned organization.');
411	    }
412	  }
413	}
