1	/**
2	 * NLPService — offline NLP analysis workspace.
3	 *
4	 * All NLP processing uses bundled, lightweight, deterministic algorithms:
5	 *   - keyword extraction  : TF-IDF frequency analysis
6	 *   - summarization       : extractive (top-scoring sentences)
7	 *   - topic classification: keyword-bag matching against topic dictionaries
8	 *   - sentiment analysis  : lexicon-based polarity scoring
9	 *   - NER                 : dictionary-based entity matching
10	 *
11	 * Quality metrics (precision/recall/F1) are drawn from the active
12	 * ValidationProfile, NOT computed against arbitrary live data.
13	 *
14	 * RBAC:
15	 *   - importText, runBatch, runIncremental → ADMINISTRATOR or ANALYST
16	 *   - getRunHistory, getRunDetail          → ADMINISTRATOR, ANALYST, or REVIEWER
17	 *   - createValidationProfile              → ADMINISTRATOR only
18	 */
19	
20	import {
21	  ImportedTextRepository,
22	  ValidationProfileRepository,
23	  NLPRunRepository,
24	} from '../repositories/implementations/NLPRepository.js';
25	import { auditService } from './AuditService.js';
26	import { authService } from './AuthService.js';
27	import { generateId } from '../utils/idGenerator.js';
28	import { ROLES, NLP } from '../utils/constants.js';
29	
30	export class NLPService {
31	  constructor() {
32	    this._textRepo = new ImportedTextRepository();
33	    this._profileRepo = new ValidationProfileRepository();
34	    this._runRepo = new NLPRunRepository();
35	  }
36	
37	  // ── Text ingestion ────────────────────────────────────────────────────────────
38	
39	  /**
40	   * Imports a text file into the system.
41	   * Requires: ADMINISTRATOR or ANALYST role.
42	   *
43	   * @param {{ sourceType: string; sourceId: string; filename: string; rawText: string; actorId: string }} params
44	   * @returns {Promise<object>}
45	   */
46	  async importText({ organizationId, sourceType, sourceId, filename, rawText, actorId }) {
47	    const actor = this._requireRole(ROLES.ANALYST);
48	    this._assertOrgScope(actor, organizationId);
49	
50	    if (!rawText?.trim()) throw new Error('Imported text cannot be empty.');
51	    if (!sourceType?.trim()) throw new Error('Source type is required.');
52	    if (!filename?.trim()) throw new Error('Filename is required.');
53	
54	    const record = {
55	      id: generateId(),
56	      organizationId,
57	      sourceType,
58	      sourceId,
59	      filename,
60	      rawText,
61	      sizeBytes: new TextEncoder().encode(rawText).length,
62	      importedAt: Date.now(),
63	      updatedAt: Date.now(),
64	    };
65	
66	    await this._textRepo.create(record);
67	    await auditService.log({ actorId, action: 'import_text', entityType: 'importedText', entityId: record.id });
68	    return record;
69	  }
70	
71	  // ── Batch run ─────────────────────────────────────────────────────────────────
72	
73	  /**
74	   * Runs NLP analysis on all imported texts in the organization.
75	   * Requires: ADMINISTRATOR or ANALYST role.
76	   *
77	   * @param {{ organizationId: string; modelVersion: string; actorId: string }} params
78	   * @returns {Promise<object>}
79	   */
80	  async runBatch({ organizationId, modelVersion, actorId }) {
81	    this._requireRole(ROLES.ANALYST);
82	
83	    if (!modelVersion?.trim()) throw new Error('Model version is required.');
84	
85	    const texts = await this._textRepo.findByOrg(organizationId);
86	    return this._executeRun({
87	      organizationId,
88	      modelVersion,
89	      inputIds: texts.map((t) => t.id),
90	      texts,
91	      runType: NLP.RUN_TYPES.BATCH,
92	      actorId,
93	    });
94	  }
95	
96	  /**
97	   * Runs incremental NLP analysis on texts created or updated since the last run.
98	   * Uses both createdAt AND updatedAt to find new or modified texts.
99	   * Requires: ADMINISTRATOR or ANALYST role.
100	   *
101	   * @param {{ organizationId: string; modelVersion: string; actorId: string }} params
102	   * @returns {Promise<object>}
103	   */
104	  async runIncremental({ organizationId, modelVersion, actorId }) {
105	    this._requireRole(ROLES.ANALYST);
106	
107	    if (!modelVersion?.trim()) throw new Error('Model version is required.');
108	
109	    const lastRun = await this._runRepo.findLatestByOrg(organizationId);
110	    const sinceMs = lastRun?.createdAt ?? 0;
111	
112	    // Find texts created OR updated since the last run, scoped to this organization.
113	    const texts = await this._textRepo.findByOrgUpdatedSince(organizationId, sinceMs);
114	
115	    return this._executeRun({
116	      organizationId,
117	      modelVersion,
118	      inputIds: texts.map((t) => t.id),
119	      texts,
120	      runType: NLP.RUN_TYPES.INCREMENTAL,
121	      actorId,
122	    });
123	  }
124	
125	  // ── Run history ───────────────────────────────────────────────────────────────
126	
127	  /**
128	   * Returns all NLP runs for an organization, newest first.
129	   * Requires: ADMINISTRATOR, ANALYST, or REVIEWER role.
130	   *
131	   * @param {string} organizationId
132	   * @returns {Promise<object[]>}
133	   */
134	  async getRunHistory(organizationId) {
135	    this._requireRole(ROLES.ANALYST, ROLES.REVIEWER);
136	    const runs = await this._runRepo.findByOrg(organizationId);
137	    return runs.sort((a, b) => b.createdAt - a.createdAt);
138	  }
139	
140	  /**
141	   * Returns a single run with its full output payload.
142	   * Requires: ADMINISTRATOR, ANALYST, or REVIEWER role.
143	   *
144	   * @param {string} runId
145	   * @returns {Promise<object | null>}
146	   */
147	  async getRunDetail(runId) {
148	    const actor = this._requireRole(ROLES.ANALYST, ROLES.REVIEWER);
149	    const run = await this._runRepo.findById(runId);
150	    if (run) this._assertOrgScope(actor, run.organizationId);
151	    return run;
152	  }
153	
154	  // ── Validation profile management ─────────────────────────────────────────────
155	
156	  /**
157	   * Creates a validation profile binding model version to benchmark metrics.
158	   * No live metrics are generated — benchmarks come from the labeled corpus.
159	   * Requires: ADMINISTRATOR only.
160	   *
161	   * @param {{ modelVersion: string; corpusName: string; precision: number; recall: number; f1: number; labeledSampleCount: number; actorId: string }} params
162	   * @returns {Promise<object>}
163	   */
164	  async createValidationProfile({ modelVersion, corpusName, precision, recall, f1, labeledSampleCount, actorId }) {
165	    this._requireRole(ROLES.ADMINISTRATOR);
166	
167	    if (!modelVersion?.trim()) throw new Error('Model version is required.');
168	    if (!corpusName?.trim()) throw new Error('Corpus name is required.');
169	    if (typeof precision !== 'number' || precision < 0 || precision > 1) throw new Error('Precision must be a number between 0 and 1.');
170	    if (typeof recall !== 'number' || recall < 0 || recall > 1) throw new Error('Recall must be a number between 0 and 1.');
171	    if (typeof f1 !== 'number' || f1 < 0 || f1 > 1) throw new Error('F1 score must be a number between 0 and 1.');
172	    if (!Number.isInteger(labeledSampleCount) || labeledSampleCount < 1) throw new Error('labeledSampleCount must be a positive integer.');
173	
174	    const profile = {
175	      id: generateId(),
176	      modelVersion,
177	      corpusName,
178	      precision,
179	      recall,
180	      f1,
181	      labeledSampleCount,
182	      createdAt: Date.now(),
183	    };
184	    const created = await this._profileRepo.create(profile);
185	    await auditService.log({ actorId, action: 'create_validation_profile', entityType: 'validationProfile', entityId: profile.id, metadata: { modelVersion, f1 } });
186	    return created;
187	  }
188	
189	  // ── Private ──────────────────────────────────────────────────────────────────
190	
191	  async _executeRun({ organizationId, modelVersion, inputIds, texts, runType, actorId }) {
192	    const outputPayload = texts.reduce((acc, text) => {
193	      acc[text.id] = {
194	        keywords: this._extractKeywords(text.rawText),
195	        summary: this._extractSummary(text.rawText),
196	        topics: this._classifyTopics(text.rawText),
197	        sentiment: this._analyzeSentiment(text.rawText),
198	        entities: this._extractEntities(text.rawText),
199	      };
200	      return acc;
201	    }, {});
202	
203	    // Benchmark metrics from validation profile — never synthetic.
204	    const profile = await this._profileRepo.findByModelVersion(modelVersion)
205	      ?? await this._profileRepo.findLatest();
206	
207	    const run = {
208	      id: generateId(),
209	      organizationId,
210	      runType,
211	      modelVersion,
212	      inputIds,
213	      outputPayload,
214	      benchmarkPrecision: profile?.precision ?? null,
215	      benchmarkRecall: profile?.recall ?? null,
216	      benchmarkF1: profile?.f1 ?? null,
217	      belowF1Threshold: profile ? (profile.f1 < NLP.F1_ALERT_THRESHOLD) : false,
218	      createdBy: actorId,
219	      createdAt: Date.now(),
220	    };
221	
222	    await this._runRepo.create(run);
223	    await auditService.log({
224	      actorId,
225	      action: 'nlp_run',
226	      entityType: 'nlpRun',
227	      entityId: run.id,
228	      metadata: { runType, modelVersion, inputCount: inputIds.length, belowF1Threshold: run.belowF1Threshold },
229	    });
230	
231	    return run;
232	  }
233	
234	  /**
235	   * Extracts top-N keywords via term frequency.
236	   * @param {string} text
237	   * @param {number} [topN=10]
238	   * @returns {string[]}
239	   */
240	  _extractKeywords(text, topN = 10) {
241	    const stopWords = new Set(['the', 'a', 'an', 'is', 'in', 'on', 'at', 'to', 'and', 'or', 'of', 'it', 'for', 'with', 'this', 'that', 'was', 'are', 'be', 'by', 'from', 'as', 'but', 'not', 'have', 'had', 'has', 'he', 'she', 'they', 'we', 'you', 'i']);
242	    const words = text.toLowerCase().match(/\b[a-z]{3,}\b/g) ?? [];
243	    const freq = new Map();
244	    for (const w of words) {
245	      if (!stopWords.has(w)) freq.set(w, (freq.get(w) ?? 0) + 1);
246	    }
247	    return [...freq.entries()]
248	      .sort((a, b) => b[1] - a[1])
249	      .slice(0, topN)
250	      .map(([w]) => w);
251	  }
252	
253	  /**
254	   * Extractive summarization: returns the top-scoring sentences by keyword density.
255	   * @param {string} text
256	   * @param {number} [numSentences=3]
257	   * @returns {string}
258	   */
259	  _extractSummary(text, numSentences = 3) {
260	    const sentences = text.match(/[^.!?]+[.!?]+/g) ?? [text];
261	    if (sentences.length <= numSentences) return text;
262	    const keywords = new Set(this._extractKeywords(text));
263	    const scored = sentences.map((s) => {
264	      const words = s.toLowerCase().match(/\b[a-z]+\b/g) ?? [];
265	      const score = words.filter((w) => keywords.has(w)).length;
266	      return { sentence: s, score };
267	    });
268	    return scored
269	      .sort((a, b) => b.score - a.score)
270	      .slice(0, numSentences)
271	      .map((s) => s.sentence.trim())
272	      .join(' ');
273	  }
274	
275	  /**
276	   * Topic classification via simple keyword-bag matching.
277	   * @param {string} text
278	   * @returns {string[]}
279	   */
280	  _classifyTopics(text) {
281	    const topics = {
282	      logistics: ['shipping', 'delivery', 'warehouse', 'stock', 'inventory', 'transport'],
283	      customer: ['complaint', 'refund', 'return', 'satisfaction', 'service', 'support'],
284	      finance: ['payment', 'invoice', 'price', 'discount', 'cost', 'billing'],
285	      product: ['quality', 'defect', 'style', 'size', 'color', 'brand'],
286	    };
287	    const lower = text.toLowerCase();
288	    return Object.entries(topics)
289	      .filter(([, keywords]) => keywords.some((k) => lower.includes(k)))
290	      .map(([topic]) => topic);
291	  }
