    const matchesSearch = !searchQuery || c.name.toLowerCase().includes(searchQuery.toLowerCase());
    const matchesTier = !filterTier || c.membershipTier === filterTier;
    return matchesSearch && matchesTier;
  });

  onMount(async () => {
