    } finally {
      revealLoading = false;
    }
  }

  function hideSensitive() {
    sensitiveFields = null;
  }

  async function handleCreate() {
    formError = '';
    formLoading = true;
    try {
      const created = await customerService.createCustomer({
        organizationId: orgId,
        name: newName,
        membershipTier: newTier,
