  });

  async function loadRuns() {
    if (!orgId) return;
    runsLoading = true;
    try {
      runs = await nlpService.getRunHistory(orgId);
    } catch (err) {
      showToast('error', err.message);
    } finally {
      runsLoading = false;
    }
