  import { onMount } from 'svelte';
  import { riskReviewService } from '../services/RiskReviewService.js';
  import { currentUser } from '../app/stores/auth.js';
  import { showToast } from '../app/stores/ui.js';
  import { RISK_CASE_STATUSES, OUTCOME_CODES } from '../utils/constants.js';

  const outcomeCodes = Object.values(OUTCOME_CODES);

  let cases = [];
  let loading = false;
  let filterStatus = '';

  let selectedCase = null;
  let outcomeCode = '';
  let resolutionComment = '';
  let actionLoading = false;

  $: actorId = $currentUser?.id ?? '';
  $: orgId = $currentUser?.organizationNodeId ?? '';

  $: filteredCases = cases.filter((c) =>
    !filterStatus || c.status === filterStatus
  );

  $: canSubmit = outcomeCode && resolutionComment.trim().length > 0;

  onMount(async () => {
    await loadInbox();
  });

  async function loadInbox() {
    if (!orgId) return;
    loading = true;
    try {
      cases = await riskReviewService.getInbox(orgId);
    } catch (err) {
      showToast('error', err.message);
    } finally {
      loading = false;
    }
  }

  function selectCase(c) {
