    await authSvc.unlockSession('Wrong!1111111');
    await authSvc.unlockSession('Wrong!1111111');
    await authSvc.unlockSession(ADMIN_PASS); // correct

    authSvc.lockSession();

    // 3 more wrong — should NOT force logout (counter was reset).
    for (let i = 0; i < 3; i++) {
      await authSvc.unlockSession('Wrong!1111111');
    }
