/**
 * Requires authentication and at least one of the given roles.
 * ADMINISTRATOR always passes. Returns the current user.
 *
 * @param {...string} allowedRoles
 * @returns {object}
 */
_requireRole(...allowedRoles) {
  const user = authService.getCurrentUser();
  if (!user) throw new Error('Authentication required.');
  if (user.role === ROLES.ADMINISTRATOR) return user;
  if (allowedRoles.length > 0 && !allowedRoles.includes(user.role)) {
    throw new Error(`Permission denied. Required role(s): ${allowedRoles.join(', ')}`);
  }
  return user;
}

/** Requires authentication only. Returns the current user. */
_requireAuth() {
  const user = authService.getCurrentUser();
  if (!user) throw new Error('Authentication required.');
  return user;
}

/**
 * For non-admin actors: verifies the target org matches their assigned org node.
 * @param {object} actor
 * @param {string} targetOrgId
 */
_assertOrgScope(actor, targetOrgId) {
  if (actor.role === ROLES.ADMINISTRATOR) return;
  if (!actor.organizationNodeId) throw new Error('Actor has no organization assigned.');
  if (targetOrgId !== actor.organizationNodeId) {
    throw new Error('Scope violation: you can only access data within your assigned organization.');
  }
}

async login(username, password) {
  const user = await this._userRepo.findByUsername(username);

  // Generic error prevents username enumeration.
  if (!user) throw new Error('Invalid username or password.');
  if (!user.isActive) throw new Error('Account is deactivated.');

  // Check lockout before any password work.
  const now = Date.now();
  if (user.lockoutUntil && now < user.lockoutUntil) {
    const remainingMinutes = Math.ceil((user.lockoutUntil - now) / 60_000);
    throw new Error(
      `Account is temporarily locked due to too many failed attempts. ` +
        `Try again in ${remainingMinutes} minute(s).`,
    );
  }

  const valid = await cryptoService.verifyPassword(password, user.passwordSalt, user.passwordHash);

  if (!valid) {
    const failedAttempts = (user.failedLoginAttempts ?? 0) + 1;
    const lockoutUntil = failedAttempts >= MAX_FAILED_ATTEMPTS
      ? Date.now() + LOCKOUT_DURATION_MS
      : null;

    await this._userRepo.update(user.id, {
      ...user,
      failedLoginAttempts: failedAttempts,
      lockoutUntil,
      updatedAt: Date.now(),
    });

    // Generic error — same message regardless of lockout to prevent enumeration.
    throw new Error('Invalid username or password.');
  }

  // Success: clear failure state.
  const freshUser = {
    ...user,
    failedLoginAttempts: 0,
    lockoutUntil: null,
    updatedAt: Date.now(),
  };
  await this._userRepo.update(user.id, freshUser);

  await cryptoService.deriveSessionKey(password, user.passwordSalt);

