  this._isLocked = false;
  this._isGuestSession = false;
  this._unlockAttempts = 0; // reset on any successful login

  this._resetLockTimer();

  await auditService.log({
    actorId: user.id,
    action: 'login',
    entityType: 'user',
    entityId: user.id,
  });

  return freshUser;
}

