2	 * Auth Svelte store.
3	 * Mirrors the AuthService session state into reactive Svelte stores
4	 * so components can subscribe without directly coupling to the service.
5	 */
6	import { writable, derived } from 'svelte/store';
7	
8	/** @type {import('svelte/store').Writable<object | null>} */
9	export const currentUser = writable(null);
10	
11	/** @type {import('svelte/store').Writable<boolean>} */
12	export const isLocked = writable(false);
13	
14	/** @type {import('svelte/store').Writable<boolean>} */
15	export const isAuthenticated = writable(false);
16	
17	/** @type {import('svelte/store').Writable<boolean>} */
18	export const isGuest = writable(false);
19	
20	/** Derived: current user's role string. */
21	export const currentRole = derived(currentUser, ($user) => $user?.role ?? null);
22	
23	/** Derived: true if the user is an admin. */
24	export const isAdmin = derived(currentRole, ($role) => $role === 'administrator');
25	
26	/**
27	 * Syncs all auth stores from the AuthService after a session state change.
28	 * @param {import('../../services/AuthService.js').AuthService} authService
29	 */
30	export function syncAuthStores(authService) {
31	  currentUser.set(authService.getCurrentUser());
32	  isLocked.set(authService.isLocked());
33	  isAuthenticated.set(authService.isAuthenticated());
34	  isGuest.set(authService.isGuest());
35	}
36	
37	/** Resets all auth stores to unauthenticated state. */
38	export function clearAuthStores() {
39	  currentUser.set(null);
40	  isLocked.set(false);
41	  isAuthenticated.set(false);
42	  isGuest.set(false);
43	}
