import { it } from 'vitest';
import { render, screen, waitFor } from '@testing-library/svelte';
import { IDBFactory } from 'fake-indexeddb';
import { initDB, closeDB } from '../src/infrastructure/db/db.js';
import { authService } from '../src/services/AuthService.js';
import { customerService } from '../src/services/CustomerService.js';
import { cryptoService } from '../src/services/CryptoService.js';
import { BootstrapService } from '../src/services/BootstrapService.js';
import { currentUser } from '../src/app/stores/auth.js';
import { setBroadcastService, closeAll } from '../src/infrastructure/broadcast/broadcastManager.js';
import { MockBroadcastService } from '../src/infrastructure/broadcast/MockBroadcastService.js';
import CRMPage from '../src/pages/CRMPage.svelte';

const ADMIN_PASS = 'CrmPage@1234';
const ORG_ID = 'org-crm-test';

it('debug: spy on loadCustomers', async () => {
  setBroadcastService(new MockBroadcastService());
  await initDB(new IDBFactory());

  const bs = new BootstrapService();
  const result = await bs.bootstrap({ adminUsername: 'crm_admin', adminPassword: ADMIN_PASS, orgName: 'CRMTestCo' });
  const adminUser = result.admin;

  await authService.login('crm_admin', ADMIN_PASS);
  authService._currentUser = { ...authService._currentUser, organizationNodeId: ORG_ID };
  currentUser.set(authService._currentUser);

  await customerService.createCustomer({
    organizationId: ORG_ID, name: 'Alice Smith', membershipTier: 'Gold', actorId: adminUser.id,
  });

  // Spy on customerService.getByOrg
  const origGetByOrg = customerService.getByOrg.bind(customerService);
  customerService.getByOrg = async (orgId) => {
    console.log('getByOrg called with:', orgId);
    try {
      const result = await origGetByOrg(orgId);
      console.log('getByOrg returned:', result.length, 'items');
      return result;
    } catch (e) {
      console.log('getByOrg threw:', e.message);
      throw e;
    }
  };

  render(CRMPage);

  // Wait a bit for onMount to fire
  await new Promise(r => setTimeout(r, 1000));

  console.log('After 1s, body text snippet:', document.body.innerText?.slice(0, 100));

  // Restore
  customerService.getByOrg = origGetByOrg;

  cryptoService.clearSessionKey();
  authService._currentUser = null;
  currentUser.set(null);
  closeDB();
  closeAll();
}, 30000);
EOF
