41	  async function loadUsers() {
42	    usersLoading = true;
43	    try {
44	      users = await authService.listUsers();
45	    } catch (err) {
46	      showToast('error', err.message);
47	    } finally {
48	      usersLoading = false;
49	    }
50	  }
51	
52	  async function handleCreateUser() {
53	    userFormError = '';
54	    userFormLoading = true;
55	    try {
56	      await authService.createUser({
57	        username: newUsername,
58	        password: newPassword,
59	        role: newRole,
60	        organizationNodeId: newOrgNodeId || null,
61	      });
62	      await loadUsers();
63	      showCreateUserForm = false;
64	      newUsername = '';
65	      newPassword = '';
66	      newRole = ROLES.STORE_MANAGER;
67	      newOrgNodeId = '';
68	      showToast('success', 'User created.');
69	    } catch (err) {
70	      userFormError = err.message;
71	    } finally {
72	      userFormLoading = false;
73	    }
74	  }
75	
76	  async function handleDeactivate(userId) {
77	    if (!confirm('Deactivate this user? They will no longer be able to log in.')) return;
78	    try {
79	      await authService.deactivateAccount(userId);
80	      await loadUsers();
81	      showToast('success', 'Account deactivated.');
82	    } catch (err) {
83	      showToast('error', err.message);
84	    }
85	  }
86	
87	  async function handleExport() {
88	    if (!exportPassphrase.trim()) {
89	      showToast('error', 'Backup passphrase is required.');
90	      return;
91	    }
92	    exportLoading = true;
93	    try {
94	      const blob = await importExportService.exportBackup({ actorId, backupPassphrase: exportPassphrase });
95	      const url = URL.createObjectURL(blob);
96	      const a = document.createElement('a');
97	      a.href = url;
98	      a.download = `retailops-backup-${Date.now()}.json`;
99	      a.click();
100	      URL.revokeObjectURL(url);
101	      exportPassphrase = '';
102	      showToast('success', 'Backup exported.');
103	    } catch (err) {
104	      showToast('error', err.message);
105	    } finally {
106	      exportLoading = false;
107	    }
108	  }
109	
110	  function handleFileChange(e) {
111	    importFile = e.target.files[0] ?? null;
112	    importPreview = null;
113	    importSchemaVersion = null;
114	  }
115	
116	  async function handlePreviewImport() {
117	    if (!importFile || !importPassphrase.trim()) {
118	      showToast('error', 'File and passphrase are required.');
119	      return;
120	    }
121	    importLoading = true;
122	    try {
123	      const result = await importExportService.previewImport({
124	        file: importFile,
125	        backupPassphrase: importPassphrase,
126	      });
127	      importPreview = result.diff;
128	      importSchemaVersion = result.schemaVersion;
129	    } catch (err) {
130	      showToast('error', err.message);
131	    } finally {
132	      importLoading = false;
133	    }
134	  }
135	
136	  async function handleApplyImport() {
137	    if (!importPreview || importSchemaVersion === null) return;
138	    if (!confirm('Apply this backup? This will overwrite current data. Audit logs are preserved.')) return;
139	    applyLoading = true;
140	    try {
141	      // We need the snapshot — preview stores it; re-run or store snapshot
142	      const result = await importExportService.previewImport({
143	        file: importFile,
144	        backupPassphrase: importPassphrase,
145	      });
146	      await importExportService.applyImport({
147	        snapshot: result.snapshot,
148	        schemaVersion: result.schemaVersion,
149	        actorId,
150	      });
151	      importPreview = null;
152	      importSchemaVersion = null;
153	      importFile = null;
154	      importPassphrase = '';
155	      showToast('success', 'Backup restored successfully.');
156	    } catch (err) {
157	      showToast('error', err.message);
158	    } finally {
159	      applyLoading = false;
160	    }
161	  }
