/**
 * EventDispatcherService — bridges business events to the notification delivery system.
 *
 * Replaces direct notifyUser() calls in OrderService and TicketService.
 * Resolves subscriptions for the event type, then either:
 *   - Enqueues via template (if templateId provided)
 *   - Falls back to notifyUser() for direct/unsubscribed targets
 *
 * Non-fatal: notification failures do not block the business operation.
 */

import { notificationService } from './NotificationService.js';
import { auditService } from './AuditService.js';
import { authService } from './AuthService.js';

export class EventDispatcherService {
  /**
   * Dispatches a business event to all subscribers, optionally targeting specific users.
   *
   * @param {{
   *   organizationId: string;
   *   eventType: string;
   *   sourceId: string;
   *   actorId: string;
   *   vars: { title: string; body: string; [key: string]: string };
   *   templateId?: string | null;
   *   recipientUserIds?: string[] | null;
   * }} params
   */
  async dispatch({ organizationId, eventType, sourceId, actorId, vars, templateId = null, recipientUserIds = null }) {
    try {
      const subscriptions = await notificationService.getSubscriptionsByEventType(eventType);

      // Filter subscriptions to targeted users if recipientUserIds is specified.
      const relevantSubs = recipientUserIds
        ? subscriptions.filter((s) => recipientUserIds.includes(s.userId))
        : subscriptions;

      // Deliver via queue to subscribers.
      const subscriberIds = new Set();
      for (const sub of relevantSubs) {
        subscriberIds.add(sub.userId);
        try {
          if (templateId && sub.channelId) {
            await notificationService.enqueue({
              organizationId,
              recipientUserId: sub.userId,
              templateId,
              channelId: sub.channelId,
              vars,
              eventSourceKey: `${eventType}:${sourceId}:${sub.userId}`,
            });
          } else {
            await notificationService.notifyUser(sub.userId, {
              type: eventType,
              title: vars.title,
              body: vars.body,
            });
          }
        } catch (err) {
          auditService.log({
            actorId,
            action: 'notification_failed',
            entityType: eventType,
            entityId: sourceId,
            metadata: { userId: sub.userId, error: err.message },
          }).catch(() => {});
        }
      }

      // For explicitly targeted users who have no subscription, fall back to direct notifyUser.
      if (recipientUserIds) {
        for (const userId of recipientUserIds) {
          if (!subscriberIds.has(userId)) {
            try {
              await notificationService.notifyUser(userId, {
                type: eventType,
                title: vars.title,
                body: vars.body,
              });
            } catch (err) {
              auditService.log({
                actorId,
                action: 'notification_failed',
                entityType: eventType,
                entityId: sourceId,
                metadata: { userId, error: err.message },
              }).catch(() => {});
            }
          }
        }
      }
    } catch (err) {
      // Event dispatch failure is non-fatal — log and continue.
      auditService.log({
        actorId,
        action: 'dispatch_failed',
        entityType: eventType,
        entityId: sourceId,
        metadata: { error: err.message },
      }).catch(() => {});
    }
  }
}

export const eventDispatcherService = new EventDispatcherService();
```

