21	  // ── Channel configuration ─────────────────────────────────────────────────────
22	
23	  /**
24	   * Creates or updates a notification channel.
25	   * Only 'in_app' channels are supported in the offline runtime.
26	   * Requires: ADMINISTRATOR or STORE_MANAGER role.
27	   *
28	   * @param {{ organizationId: string; name: string; type?: string; isEnabled?: boolean }} params
29	   * @returns {Promise<object>}
30	   */
31	  async upsertChannel({ organizationId, name, type = 'in_app', isEnabled = true }) {
32	    this._requireRole(ROLES.STORE_MANAGER);
33	
34	    if (!name?.trim()) throw new Error('Channel name is required.');
35	
36	    const channel = {
37	      id: generateId(),
38	      organizationId,
39	      name,
40	      type,
41	      isEnabled,
42	      createdAt: Date.now(),
43	      updatedAt: Date.now(),
44	    };
