100	      // Hard constraint violations (compact overflow, etc.) must propagate.
101	      if (!err.message.startsWith('Missing template variables')) throw err;
102	      // Template rendering failure creates a Draft item for manual review.
103	      const draftItem = {
104	        id: generateId(),
105	        organizationId,
106	        recipientUserId,
107	        templateId,
108	        channelId,
109	        payload: vars,
110	        renderedBody: null,
111	        status: QUEUE_STATUSES.DRAFT,
112	        retryCount: 0,
