123	      id: generateId(),
124	      organizationId,
125	      recipientUserId,
126	      templateId,
127	      channelId,
128	      payload: vars,
129	      renderedBody,
130	      status: QUEUE_STATUSES.QUEUED,
131	      retryCount: 0,
132	      nextRetryAt: Date.now(), // process immediately
133	      failureReason: null,
134	      idempotencyKey,
135	      createdAt: Date.now(),
136	      updatedAt: Date.now(),
137	    };
