288	      body: item.renderedBody,
289	      read: false,
290	      createdAt: Date.now(),
291	    };
292	
293	    await this._notifRepo.create(notification);
294	    await auditService.log({
295	      actorId: 'system',
296	      action: 'notification_sent',
297	      entityType: 'messageQueue',
298	      entityId: item.id,
299	    });
300	  }
301	
302	  /**
303	   * Increments retry count and schedules next attempt, or marks as Failed.
304	   * Retry schedule: 1 min, 5 min, 15 min → then Failed.
305	   *
306	   * @param {object} item
