338	    if (allowedRoles.length > 0 && !allowedRoles.includes(user.role)) {
339	      throw new Error(`Permission denied. Required role(s): ${allowedRoles.join(', ')}`);
340	    }
341	    return user;
342	  }
343	
344	  _requireAuth() {
