48	    const now = Date.now();
49	    const ticket = {
50	      id: generateId(),
51	      customerId,
52	      orderId: orderId ?? null,
53	      organizationId,
54	      storeId,
55	      subject,
56	      description,
57	      category,
58	      priority,
59	      status: TICKET_STATUSES.OPEN,
60	      slaDueAt: now + slaHours * 60 * 60 * 1000,
61	      isOverdue: false,
62	      assignedTo: null,
63	      createdAt: now,
64	      updatedAt: now,
65	      resolvedAt: null,
66	      closedBy: null,
