1	/**
2	 * NLPService — offline NLP analysis workspace.
3	 *
4	 * All NLP processing uses bundled, lightweight, deterministic algorithms:
5	 *   - keyword extraction  : TF-IDF frequency analysis
6	 *   - summarization       : extractive (top-scoring sentences)
7	 *   - topic classification: keyword-bag matching against topic dictionaries
8	 *   - sentiment analysis  : lexicon-based polarity scoring
9	 *   - NER                 : dictionary-based entity matching
10	 *
11	 * Quality metrics (precision/recall/F1) are drawn from the active
12	 * ValidationProfile, NOT computed against arbitrary live data.
13	 *
14	 * RBAC:
15	 *   - importText, runBatch, runIncremental → ADMINISTRATOR or ANALYST
16	 *   - getRunHistory, getRunDetail          → ADMINISTRATOR, ANALYST, or REVIEWER
17	 *   - createValidationProfile              → ADMINISTRATOR only
18	 */
19	
20	import {
21	  ImportedTextRepository,
22	  ValidationProfileRepository,
23	  NLPRunRepository,
24	} from '../repositories/implementations/NLPRepository.js';
25	import { auditService } from './AuditService.js';
26	import { authService } from './AuthService.js';
27	import { generateId } from '../utils/idGenerator.js';
28	import { ROLES, NLP } from '../utils/constants.js';
29	import { orgService } from './OrgService.js';
30	
31	export class NLPService {
32	  constructor() {
33	    this._textRepo = new ImportedTextRepository();
34	    this._profileRepo = new ValidationProfileRepository();
35	    this._runRepo = new NLPRunRepository();
36	  }
37	
38	  // ── Text ingestion ────────────────────────────────────────────────────────────
39	
40	  /**
41	   * Imports a text file into the system.
42	   * Requires: ADMINISTRATOR or ANALYST role.
43	   *
44	   * @param {{ sourceType: string; sourceId: string; filename: string; rawText: string; actorId: string }} params
45	   * @returns {Promise<object>}
46	   */
47	  async importText({ organizationId, sourceType, sourceId, filename, rawText, actorId }) {
48	    const actor = this._requireRole(ROLES.ANALYST);
49	    await this._assertOrgScope(actor, organizationId);
50	
51	    if (!rawText?.trim()) throw new Error('Imported text cannot be empty.');
52	    if (!sourceType?.trim()) throw new Error('Source type is required.');
53	    if (!filename?.trim()) throw new Error('Filename is required.');
54	
55	    const record = {
56	      id: generateId(),
57	      organizationId,
58	      sourceType,
59	      sourceId,
60	      filename,
61	      rawText,
62	      sizeBytes: new TextEncoder().encode(rawText).length,
63	      importedAt: Date.now(),
64	      updatedAt: Date.now(),
65	    };
66	
67	    await this._textRepo.create(record);
68	    await auditService.log({ actorId, action: 'import_text', entityType: 'importedText', entityId: record.id });
69	    return record;
70	  }
71	
72	  // ── Batch run ─────────────────────────────────────────────────────────────────
73	
74	  /**
75	   * Runs NLP analysis on all imported texts in the organization.
76	   * Requires: ADMINISTRATOR or ANALYST role.
77	   *
78	   * @param {{ organizationId: string; modelVersion: string; actorId: string }} params
79	   * @returns {Promise<object>}
80	   */
81	  async runBatch({ organizationId, modelVersion, actorId }) {
82	    this._requireRole(ROLES.ANALYST);
83	
84	    if (!modelVersion?.trim()) throw new Error('Model version is required.');
85	
86	    const texts = await this._textRepo.findByOrg(organizationId);
87	    return this._executeRun({
88	      organizationId,
89	      modelVersion,
90	      inputIds: texts.map((t) => t.id),
91	      texts,
92	      runType: NLP.RUN_TYPES.BATCH,
93	      actorId,
94	    });
95	  }
96	
97	  /**
98	   * Runs incremental NLP analysis on texts created or updated since the last run.
99	   * Uses both createdAt AND updatedAt to find new or modified texts.
100	   * Requires: ADMINISTRATOR or ANALYST role.
101	   *
102	   * @param {{ organizationId: string; modelVersion: string; actorId: string }} params
103	   * @returns {Promise<object>}
104	   */
105	  async runIncremental({ organizationId, modelVersion, actorId }) {
106	    this._requireRole(ROLES.ANALYST);
107	
108	    if (!modelVersion?.trim()) throw new Error('Model version is required.');
109	
110	    const lastRun = await this._runRepo.findLatestByOrg(organizationId);
111	    const sinceMs = lastRun?.createdAt ?? 0;
112	
113	    // Find texts created OR updated since the last run, scoped to this organization.
114	    const texts = await this._textRepo.findByOrgUpdatedSince(organizationId, sinceMs);
115	
116	    return this._executeRun({
117	      organizationId,
118	      modelVersion,
119	      inputIds: texts.map((t) => t.id),
120	      texts,
121	      runType: NLP.RUN_TYPES.INCREMENTAL,
122	      actorId,
123	    });
124	  }
125	
126	  // ── Run history ───────────────────────────────────────────────────────────────
127	
128	  /**
129	   * Returns all NLP runs for an organization, newest first.
130	   * Requires: ADMINISTRATOR, ANALYST, or REVIEWER role.
131	   *
132	   * @param {string} organizationId
133	   * @returns {Promise<object[]>}
134	   */
135	  async getRunHistory(organizationId) {
136	    this._requireRole(ROLES.ANALYST, ROLES.REVIEWER);
137	    const runs = await this._runRepo.findByOrg(organizationId);
138	    return runs.sort((a, b) => b.createdAt - a.createdAt);
139	  }
140	
141	  /**
142	   * Returns all imported texts for the organization.
143	   * Requires: ADMINISTRATOR, ANALYST, or REVIEWER role.
144	   *
145	   * @param {string} organizationId
146	   * @returns {Promise<object[]>}
147	   */
148	  async getImportedTexts(organizationId) {
149	    const actor = this._requireRole(ROLES.ANALYST, ROLES.REVIEWER);
150	    await this._assertOrgScope(actor, organizationId);
151	    const texts = await this._textRepo.findByOrg(organizationId);
152	    return texts.sort((a, b) => b.importedAt - a.importedAt);
153	  }
154	
155	  /**
156	   * Returns a single run with its full output payload.
157	   * Requires: ADMINISTRATOR, ANALYST, or REVIEWER role.
158	   *
159	   * @param {string} runId
160	   * @returns {Promise<object | null>}
161	   */
162	  async getRunDetail(runId) {
163	    const actor = this._requireRole(ROLES.ANALYST, ROLES.REVIEWER);
164	    const run = await this._runRepo.findById(runId);
165	    if (run) await this._assertOrgScope(actor, run.organizationId);
166	    return run;
167	  }
168	
169	  // ── Validation profile management ─────────────────────────────────────────────
170	
171	  /**
172	   * Creates a validation profile binding model version to benchmark metrics.
173	   * No live metrics are generated — benchmarks come from the labeled corpus.
174	   * Requires: ADMINISTRATOR only.
175	   *
176	   * @param {{ modelVersion: string; corpusName: string; precision: number; recall: number; f1: number; labeledSampleCount: number; actorId: string }} params
177	   * @returns {Promise<object>}
178	   */
179	  async createValidationProfile({ modelVersion, corpusName, precision, recall, f1, labeledSampleCount, actorId }) {
180	    this._requireRole(ROLES.ADMINISTRATOR);
181	
182	    if (!modelVersion?.trim()) throw new Error('Model version is required.');
183	    if (!corpusName?.trim()) throw new Error('Corpus name is required.');
184	    if (typeof precision !== 'number' || precision < 0 || precision > 1) throw new Error('Precision must be a number between 0 and 1.');
185	    if (typeof recall !== 'number' || recall < 0 || recall > 1) throw new Error('Recall must be a number between 0 and 1.');
186	    if (typeof f1 !== 'number' || f1 < 0 || f1 > 1) throw new Error('F1 score must be a number between 0 and 1.');
187	    if (!Number.isInteger(labeledSampleCount) || labeledSampleCount < 1) throw new Error('labeledSampleCount must be a positive integer.');
188	
189	    const profile = {
190	      id: generateId(),
191	      modelVersion,
192	      corpusName,
193	      precision,
194	      recall,
195	      f1,
196	      labeledSampleCount,
197	      createdAt: Date.now(),
198	    };
199	    const created = await this._profileRepo.create(profile);
200	    await auditService.log({ actorId, action: 'create_validation_profile', entityType: 'validationProfile', entityId: profile.id, metadata: { modelVersion, f1 } });
201	    return created;
202	  }
203	
204	  // ── Private ──────────────────────────────────────────────────────────────────
205	
206	  async _executeRun({ organizationId, modelVersion, inputIds, texts, runType, actorId }) {
207	    const outputPayload = texts.reduce((acc, text) => {
208	      acc[text.id] = {
209	        keywords: this._extractKeywords(text.rawText),
210	        summary: this._extractSummary(text.rawText),
211	        topics: this._classifyTopics(text.rawText),
212	        sentiment: this._analyzeSentiment(text.rawText),
213	        entities: this._extractEntities(text.rawText),
214	      };
215	      return acc;
216	    }, {});
217	
218	    // Benchmark metrics from validation profile — never synthetic.
219	    const profile = await this._profileRepo.findByModelVersion(modelVersion)
220	      ?? await this._profileRepo.findLatest();
221	
222	    const run = {
223	      id: generateId(),
224	      organizationId,
225	      runType,
226	      modelVersion,
227	      inputIds,
228	      outputPayload,
229	      benchmarkPrecision: profile?.precision ?? null,
230	      benchmarkRecall: profile?.recall ?? null,
231	      benchmarkF1: profile?.f1 ?? null,
232	      belowF1Threshold: profile ? (profile.f1 < NLP.F1_ALERT_THRESHOLD) : false,
233	      createdBy: actorId,
234	      createdAt: Date.now(),
235	    };
236	
237	    await this._runRepo.create(run);
238	    await auditService.log({
239	      actorId,
240	      action: 'nlp_run',
241	      entityType: 'nlpRun',
242	      entityId: run.id,
243	      metadata: { runType, modelVersion, inputCount: inputIds.length, belowF1Threshold: run.belowF1Threshold },
244	    });
245	
246	    return run;
247	  }
248	
249	  /**
250	   * Extracts top-N keywords via term frequency.
251	   * @param {string} text
252	   * @param {number} [topN=10]
253	   * @returns {string[]}
254	   */
255	  _extractKeywords(text, topN = 10) {
256	    const stopWords = new Set(['the', 'a', 'an', 'is', 'in', 'on', 'at', 'to', 'and', 'or', 'of', 'it', 'for', 'with', 'this', 'that', 'was', 'are', 'be', 'by', 'from', 'as', 'but', 'not', 'have', 'had', 'has', 'he', 'she', 'they', 'we', 'you', 'i']);
257	    const words = text.toLowerCase().match(/\b[a-z]{3,}\b/g) ?? [];
258	    const freq = new Map();
259	    for (const w of words) {
260	      if (!stopWords.has(w)) freq.set(w, (freq.get(w) ?? 0) + 1);
261	    }
262	    return [...freq.entries()]
263	      .sort((a, b) => b[1] - a[1])
264	      .slice(0, topN)
265	      .map(([w]) => w);
266	  }
267	
268	  /**
269	   * Extractive summarization: returns the top-scoring sentences by keyword density.
270	   * @param {string} text
271	   * @param {number} [numSentences=3]
272	   * @returns {string}
273	   */
274	  _extractSummary(text, numSentences = 3) {
275	    const sentences = text.match(/[^.!?]+[.!?]+/g) ?? [text];
276	    if (sentences.length <= numSentences) return text;
277	    const keywords = new Set(this._extractKeywords(text));
278	    const scored = sentences.map((s) => {
279	      const words = s.toLowerCase().match(/\b[a-z]+\b/g) ?? [];
280	      const score = words.filter((w) => keywords.has(w)).length;
281	      return { sentence: s, score };
282	    });
283	    return scored
284	      .sort((a, b) => b.score - a.score)
285	      .slice(0, numSentences)
286	      .map((s) => s.sentence.trim())
287	      .join(' ');
288	  }
289	
290	  /**
291	   * Topic classification via simple keyword-bag matching.
292	   * @param {string} text
293	   * @returns {string[]}
294	   */
295	  _classifyTopics(text) {
296	    const topics = {
297	      logistics: ['shipping', 'delivery', 'warehouse', 'stock', 'inventory', 'transport'],
298	      customer: ['complaint', 'refund', 'return', 'satisfaction', 'service', 'support'],
299	      finance: ['payment', 'invoice', 'price', 'discount', 'cost', 'billing'],
300	      product: ['quality', 'defect', 'style', 'size', 'color', 'brand'],
301	    };
302	    const lower = text.toLowerCase();
303	    return Object.entries(topics)
304	      .filter(([, keywords]) => keywords.some((k) => lower.includes(k)))
305	      .map(([topic]) => topic);
306	  }
307	
308	  /**
309	   * Sentiment analysis via lexicon scoring.
310	   * @param {string} text
311	   * @returns {{ label: 'positive'|'negative'|'neutral'; score: number }}
312	   */
313	  _analyzeSentiment(text) {
314	    const positive = new Set(['good', 'great', 'excellent', 'happy', 'satisfied', 'love', 'perfect', 'wonderful', 'amazing', 'outstanding', 'positive', 'best', 'helpful']);
315	    const negative = new Set(['bad', 'poor', 'terrible', 'unhappy', 'dissatisfied', 'hate', 'awful', 'horrible', 'broken', 'worst', 'negative', 'disappointing', 'failed']);
316	    const words = text.toLowerCase().match(/\b[a-z]+\b/g) ?? [];
317	    let score = 0;
318	    for (const w of words) {
319	      if (positive.has(w)) score += 1;
320	      if (negative.has(w)) score -= 1;
321	    }
322	    const label = score > 0 ? 'positive' : score < 0 ? 'negative' : 'neutral';
323	    return { label, score };
324	  }
325	
326	  /**
327	   * Dictionary-based NER — recognizes capitalized noun sequences as entities.
328	   * @param {string} text
329	   * @returns {Array<{ text: string; type: string }>}
330	   */
331	  _extractEntities(text) {
332	    const entities = [];
333	    const namedEntityPattern = /\b[A-Z][a-z]+(?: [A-Z][a-z]+)*\b/g;
334	    for (const match of text.matchAll(namedEntityPattern)) {
335	      entities.push({ text: match[0], type: 'PROPER_NOUN' });
336	    }
337	    return entities;
338	  }
