342	    if (!user) throw new Error('Authentication required.');
343	    if (user.role === ROLES.ADMINISTRATOR) return user;
344	    if (allowedRoles.length > 0 && !allowedRoles.includes(user.role)) {
345	      throw new Error(`Permission denied. Required role(s): ${allowedRoles.join(', ')}`);
