9	/**
10	 * MasterDataService — versioned master data lifecycle management.
11	 *
12	 * One active version per (entityType, organizationId) at a time.
13	 * Publish operations use optimistic concurrency: if the active version
14	 * changed since the editor loaded, the publish is rejected.
15	 *
16	 * RBAC:
17	 *   - publishVersion → ADMINISTRATOR or STORE_MANAGER
18	 *   - all reads       → any authenticated user
19	 */
20	export class MasterDataService {
21	  constructor() {
22	    this._repo = new MasterDataRepository();
23	  }
