19	  /**
20	   * Creates a new organization hierarchy node.
21	   * Validates single-parent constraint and valid parent-child type pairing.
22	   * Requires: ADMINISTRATOR role.
23	   *
24	   * @param {{ parentId: string | null; type: string; name: string; organizationId: string; actorId: string }} params
25	   * @returns {Promise<object>}
26	   */
27	  async createNode({ parentId, type, name, organizationId, actorId }) {
28	    this._requireRole(ROLES.ADMINISTRATOR);
29	
30	    if (!name?.trim()) throw new Error('Node name is required.');
31	    if (!Object.values(ORG_NODE_TYPES).includes(type)) {
32	      throw new Error(`Invalid node type: '${type}'. Valid: ${Object.values(ORG_NODE_TYPES).join(', ')}`);
33	    }
34	
35	    if (parentId) {
36	      const parent = await this._repo.findById(parentId);
37	      if (!parent) throw new Error('Parent node not found.');
38	      if (!this.validateParentChildType(parent.type, type)) {
39	        throw new Error(`Invalid parent-child combination: ${parent.type} → ${type}`);
40	      }
41	    } else if (type !== ORG_NODE_TYPES.COMPANY) {
42	      throw new Error('Only company nodes may have no parent.');
43	    }
44	
45	    const node = {
46	      id: generateId(),
47	      parentId: parentId ?? null,
48	      type,
49	      name,
50	      organizationId,
51	      createdAt: Date.now(),
52	      updatedAt: Date.now(),
53	    };
54	
55	    await this._repo.create(node);
56	    await auditService.log({ actorId, action: 'create_org_node', entityType: 'org', entityId: node.id, metadata: { type, name } });
57	    return node;
58	  }
