187	    if (!user) throw new Error('Authentication required.');
188	    if (user.role === ROLES.ADMINISTRATOR) return user;
189	    if (allowedRoles.length > 0 && !allowedRoles.includes(user.role)) {
190	      throw new Error(`Permission denied. Required role(s): ${allowedRoles.join(', ')}`);
191	    }
192	    return user;
193	  }
194	
195	  _requireAuth() {
196	    const user = authService.getCurrentUser();
197	    if (!user) throw new Error('Authentication required.');
198	    return user;
199	  }
200	}
