{"file_path": "/Users/tsiontesfaye/Projects/EaglePoint/retail-ops/repo/tests/integration/eventDispatcher.test.js", "content": "/**
 * Integration tests — EventDispatcherService routing.
 *
 * Covers:
 *   - dispatch with recipientUserIds → direct inbox notification
 *   - dispatch to subscriber → queue item created with template
 *   - dispatch with no subscribers → no queue items added for subscription path
 *   - event type is preserved in notification
 *   - non-fatal: dispatch never throws even if notify fails
 */

import { describe, it, expect, beforeEach, afterEach, vi } from 'vitest';
import { IDBFactory } from 'fake-indexeddb';
import { initDB, closeDB } from '../../src/infrastructure/db/db.js';
import { authService } from '../../src/services/AuthService.js';
import { notificationService } from '../../src/services/NotificationService.js';
import { templateService } from '../../src/services/TemplateService.js';
import { eventDispatcherService } from '../../src/services/EventDispatcherService.js';
import { setBroadcastService, closeAll } from '../../src/infrastructure/broadcast/broadcastManager.js';
import { MockBroadcastService } from '../../src/infrastructure/broadcast/MockBroadcastService.js';
import { ROLES, EVENT_TYPES, QUEUE_STATUSES } from '../../src/utils/constants.js';
import { MessageQueueRepository } from '../../src/repositories/implementations/NotificationRepository.js';

const ADMIN = { id: 'admin-001', role: ROLES.ADMINISTRATOR, organizationNodeId: 'org-001' };
const ORG_ID = 'org-001';

beforeEach(async () => {
  setBroadcastService(new MockBroadcastService());
  await initDB(new IDBFactory());
  authService._currentUser = ADMIN;
});

afterEach(() => {
  authService._currentUser = null;
  closeDB();
  closeAll();
  vi.restoreAllMocks();
});

// ── Direct fallback delivery ──────────────────────────────────────────────────

describe('EventDispatcher — direct recipient delivery', () => {
  it('dispatches notification to explicit recipientUserId', async () => {
    await eventDispatcherService.dispatch({
      organizationId: ORG_ID,
      eventType: EVENT_TYPES.ORDER_STATUS_CHANGED,
      sourceId: 'order-001',
      actorId: 'admin-001',
      title: 'Order ready',
      body: 'Your order is ready for pickup.',
      recipientUserIds: ['admin-001'],
    });

    const inbox = await notificationService.getInbox('admin-001');
    expect(inbox.length).toBeGreaterThan(0);
    expect(inbox.some((n) => n.title === 'Order ready')).toBe(true);
  });

  it('notification type matches eventType', async () => {
    await eventDispatcherService.dispatch({
      organizationId: ORG_ID,
      eventType: EVENT_TYPES.TICKET_ASSIGNED,
      sourceId: 'ticket-001',
      actorId: 'admin-001',
      title: 'Ticket assigned',
      body: 'A ticket was assigned to you.',
      recipientUserIds: ['admin-001'],
    });

    const inbox = await notificationService.getInbox('admin-001');
    const notif = inbox.find((n) => n.title === 'Ticket assigned');
    expect(notif).toBeTruthy();
    expect(notif.type).toBe(EVENT_TYPES.TICKET_ASSIGNED);
  });

  it('dispatches to multiple recipients', async () => {
    // Set up second user in inbox (ADMIN can view their own)
    await eventDispatcherService.dispatch({
      organizationId: ORG_ID,
      eventType: EVENT_TYPES.ORDER_STATUS_CHANGED,
      sourceId: 'order-multi',
      actorId: 'admin-001',
      title: 'Multi Dispatch',
      body: 'Sent to two users.',
      recipientUserIds: ['admin-001', 'user-002'],
    });

    // Verify admin received it
    const adminInbox = await notificationService.getInbox('admin-001');
    expect(adminInbox.some((n) => n.title === 'Multi Dispatch')).toBe(true);

    // Switch user to check user-002's inbox
    authService._currentUser = { id: 'user-002', role: ROLES.STORE_MANAGER, organizationNodeId: ORG_ID };
    const userInbox = await notificationService.getInbox('user-002');
    expect(userInbox.some((n) => n.title === 'Multi Dispatch')).toBe(true);
  });

  it('dispatch is non-fatal even if notifyUser throws', async () => {
    vi.spyOn(notificationService, 'notifyUser').mockRejectedValue(new Error('DB error'));

    // Should not throw
    await expect(
      eventDispatcherService.dispatch({
        organizationId: ORG_ID,
        eventType: EVENT_TYPES.ORDER_STATUS_CHANGED,
        sourceId: 'order-002',
        actorId: 'admin-001',
        title: 'Test',
        body: 'Test body.',
        recipientUserIds: ['admin-001'],
      }),
    ).resolves.toBeUndefined();
  });
});

// ── Subscription-based delivery ───────────────────────────────────────────────

describe('EventDispatcher — subscription → queue delivery', () => {
  it('enqueues a templated message for a subscriber', async () => {
    const template = await templateService.createTemplate({
      organizationId: ORG_ID,
      name: 'Order Status',
      body: 'Order {orderId} is now {status}.',
      isCompact: false,
      actorId: 'admin-001',
    });

    const channel = await notificationService.upsertChannel({
      organizationId: ORG_ID,
      name: 'In-App',
    });

    await notificationService.subscribe({
      userId: 'admin-001',
      channelId: channel.id,
      eventType: EVENT_TYPES.ORDER_STATUS_CHANGED,
    });

    await eventDispatcherService.dispatch({
      organizationId: ORG_ID,
      eventType: EVENT_TYPES.ORDER_STATUS_CHANGED,
      sourceId: 'order-sub-001',
      actorId: 'admin-001',
      templateId: template.id,
      vars: { orderId: 'order-sub-001', status: 'ready' },
    });

    const queueRepo = new MessageQueueRepository();
    const allItems = await queueRepo.findAll();
    const queued = allItems.filter((i) => i.recipientUserId === 'admin-001');
    expect(queued.length).toBeGreaterThan(0);
    expect(queued[0].renderedBody).toContain('order-sub-001');
    expect(queued[0].renderedBody).toContain('ready');
  });

  it('no queue items created when no subscribers exist', async () => {
    const template = await templateService.createTemplate({
      organizationId: ORG_ID,
      name: 'Risk Alert',
      body: 'Risk case {caseId} flagged.',
      isCompact: false,
      actorId: 'admin-001',
    });

    await eventDispatcherService.dispatch({
      organizationId: ORG_ID,
      eventType: EVENT_TYPES.RISK_CASE_FLAGGED,
      sourceId: 'case-001',
      actorId: 'admin-001',
      templateId: template.id,
      vars: { caseId: 'case-001' },
    });

    const queueRepo = new MessageQueueRepository();
    const allItems = await queueRepo.findAll();
    expect(allItems.length).toBe(0);
  });
});

// ── Subscription management ───────────────────────────────────────────────────

describe('NotificationService — subscription management', () => {
  it('getSubscriptionsByEventType returns matching subscriptions', async () => {
    const channel = await notificationService.upsertChannel({ organizationId: ORG_ID, name: 'Ch1' });
    await notificationService.subscribe({ userId: 'admin-001', channelId: channel.id, eventType: EVENT_TYPES.TICKET_ASSIGNED });
    await notificationService.subscribe({ userId: 'admin-001', channelId: channel.id, eventType: EVENT_TYPES.ORDER_STATUS_CHANGED });

    const subs = await notificationService.getSubscriptionsByEventType(EVENT_TYPES.TICKET_ASSIGNED);
    expect(subs.length).toBe(1);
    expect(subs[0].eventType).toBe(EVENT_TYPES.TICKET_ASSIGNED);
  });

  it('getSubscriptions returns all subscriptions for a user', async () => {
    const channel = await notificationService.upsertChannel({ organizationId: ORG_ID, name: 'Ch2' });
    await notificationService.subscribe({ userId: 'admin-001', channelId: channel.id, eventType: EVENT_TYPES.TICKET_ASSIGNED });
    await notificationService.subscribe({ userId: 'admin-001', channelId: channel.id, eventType: EVENT_TYPES.ORDER_STATUS_CHANGED });

    const subs = await notificationService.getSubscriptions('admin-001');
    expect(subs.length).toBe(2);
  });

  it('deleteSubscription removes subscription', async () => {
    const channel = await notificationService.upsertChannel({ organizationId: ORG_ID, name: 'Ch3' });
    const sub = await notificationService.subscribe({ userId: 'admin-001', channelId: channel.id, eventType: EVENT_TYPES.TICKET_ASSIGNED });

    await notificationService.deleteSubscription(sub.id, 'admin-001');

    const remaining = await notificationService.getSubscriptions('admin-001');
    expect(remaining.find((s) => s.id === sub.id)).toBeUndefined();
  });

  it('deleteSubscription throws for unknown subscription', async () => {
    await expect(
      notificationService.deleteSubscription('nonexistent-id', 'admin-001'),
    ).rejects.toThrow('not found');
  });
});
"}

