      target: { value: 'My Template' },
    });
    await fireEvent.input(screen.getAllByRole('textbox')[1], {
      target: { value: 'Hello {name}, your order is ready.' },
    });

    await waitFor(() => {
      const btns = screen.getAllByRole('button', { name: /^create$/i });
      expect(btns.some((b) => !b.disabled)).toBe(true);
    }, { timeout: 1000 });
  });

  it('Cancel button closes the template modal', async () => {
    render(MessagesPage);
    await waitFor(() => screen.getByRole('button', { name: /templates/i }));
    fireEvent.click(screen.getByRole('button', { name: /templates/i }));
    await waitFor(() => screen.getByText('+ New Template'), { timeout: 2000 });
    fireEvent.click(screen.getByText('+ New Template'));
    await waitFor(() => screen.getByText('New Template'), { timeout: 2000 });

    fireEvent.click(screen.getByRole('button', { name: /^cancel$/i }));

    await waitFor(() => {
      expect(screen.queryByText('New Template')).toBeNull();
    }, { timeout: 1000 });
  });

  it('clicking "+ Add Node" opens the create node modal in OrgSetupPage', async () => {
    render(OrgSetupPage);
    await waitFor(() => screen.getByText('+ Add Node'), { timeout: 3000 });
    fireEvent.click(screen.getByText('+ Add Node'));

    await waitFor(() => {
      expect(screen.getByText(/add org node/i)).toBeTruthy();
    }, { timeout: 2000 });
  });
});

// ── File upload ───────────────────────────────────────────────────────────────

describe('Interactions — file upload', () => {
  it('Import Text modal contains a file upload input', async () => {
    render(NLPPage);
    await waitFor(() => screen.getByText('Import Text'), { timeout: 3000 });
    fireEvent.click(screen.getByText('Import Text'));

    await waitFor(() => {
      const fileInput = document.querySelector('input[type="file"]');
      expect(fileInput).toBeTruthy();
    }, { timeout: 2000 });
  });

  it('file input accepts text file types', async () => {
    render(NLPPage);
    await waitFor(() => screen.getByText('Import Text'), { timeout: 3000 });
    fireEvent.click(screen.getByText('Import Text'));

    await waitFor(() => {
      const fileInput = document.querySelector('input[type="file"]');
      expect(fileInput).toBeTruthy();
      // Accept attribute should include text file types
      const accept = fileInput?.getAttribute('accept') ?? '';
      expect(accept.length).toBeGreaterThan(0);
    }, { timeout: 2000 });
  });

  it('Import button disabled when no text is provided', async () => {
    render(NLPPage);
    await waitFor(() => screen.getByText('Import Text'), { timeout: 3000 });
    fireEvent.click(screen.getByText('Import Text'));

    await waitFor(() => {
      const importBtn = screen.getByRole('button', { name: /^import$/i });
      expect(importBtn).toBeDisabled();
    }, { timeout: 2000 });
  });

  it('Import button enables after pasting text', async () => {
    render(NLPPage);
    await waitFor(() => screen.getByText('Import Text'), { timeout: 3000 });
    fireEvent.click(screen.getByText('Import Text'));
    await waitFor(() => screen.getByRole('button', { name: /^import$/i }), { timeout: 2000 });

    const textarea = document.querySelector('textarea');
    if (textarea) {
      await fireEvent.input(textarea, { target: { value: 'Some text content to analyze for NLP processing.' } });
      await waitFor(() => {
        const importBtn = screen.getByRole('button', { name: /^import$/i });
        expect(importBtn).not.toBeDisabled();
      }, { timeout: 1000 });
    }
  });
});

// ── Lock / unlock flow ────────────────────────────────────────────────────────

describe('Interactions — lock/unlock flow', () => {
  it('Sidebar renders Lock button for authenticated user', () => {
    render(Sidebar, { props: { currentPath: '/crm' } });
    expect(screen.getByRole('button', { name: /lock/i })).toBeTruthy();
  });

  it('clicking Lock button calls authService.lockSession', async () => {
    render(Sidebar, { props: { currentPath: '/crm' } });
    const lockBtn = screen.getByRole('button', { name: /lock/i });

    await fireEvent.click(lockBtn);

    // After locking, session key should be cleared
    expect(cryptoService.hasSessionKey()).toBe(false);
  });

  it('Sidebar renders Log out button for authenticated user', () => {
    render(Sidebar, { props: { currentPath: '/crm' } });
    expect(screen.getByRole('button', { name: /log out/i })).toBeTruthy();
  });

  it('clicking Log out clears current user', async () => {
    render(Sidebar, { props: { currentPath: '/crm' } });
    const logoutBtn = screen.getByRole('button', { name: /log out/i });

    await fireEvent.click(logoutBtn);

    await waitFor(() => {
      expect(authService.getCurrentUser()).toBeNull();
    }, { timeout: 1000 });
  });
});
"}

