1	/**
2	 * LookupDataService — CRUD for master data reference tables.
3	 *
4	 * Manages the individual entity stores: colors, sizes, seasons, brands, suppliers.
5	 * These are the building blocks that styles reference.
6	 *
7	 * RBAC:
8	 *   - createEntry, deactivateEntry, reactivateEntry → ADMINISTRATOR or STORE_MANAGER
9	 *   - listEntries → any authenticated user
10	 */
11	
12	import { BaseRepository } from '../repositories/base/BaseRepository.js';
13	import { auditService } from './AuditService.js';
14	import { authService } from './AuthService.js';
15	import { generateId } from '../utils/idGenerator.js';
16	import { ROLES } from '../utils/constants.js';
17	
18	const SUPPORTED_STORES = ['colors', 'sizes', 'seasons', 'brands', 'suppliers'];
19	
20	const STYLE_FIELD_MAP = {
21	  colors: 'colorId',
22	  sizes: 'sizeId',
23	  seasons: 'seasonId',
24	  brands: 'brandId',
25	  suppliers: 'supplierId',
26	};
27	
28	export class LookupDataService {
29	  _repo(store) {
30	    if (!SUPPORTED_STORES.includes(store)) throw new Error(`Unknown lookup store: ${store}`);
31	    return new BaseRepository(store);
32	  }
33	
34	  /**
35	   * Creates a new lookup entry (color, size, season, brand, or supplier).
36	   * Requires: ADMINISTRATOR or STORE_MANAGER role.
37	   */
38	  async createEntry({ store, organizationId, name, actorId }) {
39	    this._requireRole(ROLES.STORE_MANAGER);
40	    if (!name?.trim()) throw new Error(`${store} name is required.`);
41	
42	    const record = {
43	      id: generateId(),
44	      organizationId,
45	      name: name.trim(),
46	      isActive: true,
47	      createdAt: Date.now(),
48	      updatedAt: Date.now(),
49	    };
50	
51	    const saved = await this._repo(store).create(record);
52	    await auditService.log({ actorId, action: 'create_lookup_entry', entityType: store, entityId: record.id, metadata: { name } });
53	    return saved;
54	  }
55	
56	  /**
57	   * Lists all lookup entries for an organization.
58	   * Requires: any authenticated user.
59	   */
60	  async listEntries(store, organizationId) {
61	    this._requireAuth();
62	    const all = await this._repo(store).findByIndex('by_orgId', organizationId);
63	    return all.sort((a, b) => a.name.localeCompare(b.name));
64	  }
65	
66	  /**
67	   * Deactivates a lookup entry if no active styles reference it.
68	   * Requires: ADMINISTRATOR or STORE_MANAGER role.
69	   */
70	  async deactivateEntry({ store, entryId, actorId }) {
71	    this._requireRole(ROLES.STORE_MANAGER);
72	    const record = await this._repo(store).findById(entryId);
73	    if (!record) throw new Error(`${store} entry '${entryId}' not found.`);
74	
75	    // Check for active style references.
76	    const styleRepo = new BaseRepository('styles');
77	    const allStyles = await styleRepo.findByIndex('by_orgId', record.organizationId);
78	    const fieldName = STYLE_FIELD_MAP[store];
79	    const activeRefs = allStyles.filter((s) => s.isActive && s[fieldName] === entryId);
80	    if (activeRefs.length > 0) {
81	      throw new Error(`Cannot deactivate — ${activeRefs.length} active style(s) reference this entry.`);
82	    }
83	
84	    const updated = { ...record, isActive: false, updatedAt: Date.now() };
85	    await this._repo(store).update(entryId, updated);
86	    await auditService.log({ actorId, action: 'deactivate_lookup_entry', entityType: store, entityId: entryId });
87	  }
88	
89	  /**
90	   * Reactivates a lookup entry.
91	   * Requires: ADMINISTRATOR or STORE_MANAGER role.
92	   */
93	  async reactivateEntry({ store, entryId, actorId }) {
94	    this._requireRole(ROLES.STORE_MANAGER);
95	    const record = await this._repo(store).findById(entryId);
96	    if (!record) throw new Error(`${store} entry '${entryId}' not found.`);
97	
98	    const updated = { ...record, isActive: true, updatedAt: Date.now() };
99	    await this._repo(store).update(entryId, updated);
100	    await auditService.log({ actorId, action: 'reactivate_lookup_entry', entityType: store, entityId: entryId });
101	  }
102	
103	  // ── Private ──────────────────────────────────────────────────────────────────
104	
105	  _requireRole(...allowedRoles) {
106	    const user = authService.getCurrentUser();
107	    if (!user) throw new Error('Authentication required.');
108	    if (user.role === ROLES.ADMINISTRATOR) return user;
109	    if (allowedRoles.length > 0 && !allowedRoles.includes(user.role)) {
110	      throw new Error(`Permission denied. Required role(s): ${allowedRoles.join(', ')}`);
111	    }
112	    return user;
113	  }
114	
115	  _requireAuth() {
116	    const user = authService.getCurrentUser();
117	    if (!user) throw new Error('Authentication required.');
118	    return user;
119	  }
120	}
121	
122	export const lookupDataService = new LookupDataService();
123	

