1	import { CustomerRepository } from '../repositories/implementations/CustomerRepository.js';
2	import { cryptoService } from './CryptoService.js';
3	import { auditService } from './AuditService.js';
4	import { authService } from './AuthService.js';
5	import { generateId } from '../utils/idGenerator.js';
6	import {
7	  validateAllergyField,
8	  validateStoredValue,
9	  validatePoints,
10	  validateRating,
11	  isValidMembershipTier,
12	} from '../utils/validation.js';
13	import { ROLES, MEMBERSHIP_TIERS } from '../utils/constants.js';
14	import { orgService } from './OrgService.js';
15	
16	export class CustomerService {
17	  constructor() {
18	    this._repo = new CustomerRepository();
19	  }
20	
21	  /**
22	   * Creates a new customer record with encrypted sensitive fields.
23	   * Requires: ADMINISTRATOR or STORE_MANAGER role.
24	   * Scope: actor must have access to the target organizationId.
25	   *
26	   * @param {{ organizationId: string; name: string; membershipTier?: string; points?: number; storedValue?: number; allergies?: string; materialRestrictions?: string; actorId: string }} params
27	   * @returns {Promise<object>}
28	   */
29	  async createCustomer({ organizationId, name, membershipTier = MEMBERSHIP_TIERS.BRONZE, points = 0, storedValue = 0, allergies = '', materialRestrictions = '', actorId }) {
30	    const actor = this._requireRole(ROLES.STORE_MANAGER);
31	    await this._assertOrgScope(actor, organizationId);
32	
33	    if (!name?.trim()) throw new Error('Customer name is required.');
34	    if (!isValidMembershipTier(membershipTier)) throw new Error(`Invalid membership tier: ${membershipTier}`);
35	
36	    const allergyCheck = validateAllergyField(allergies);
37	    if (!allergyCheck.valid) throw new Error(`Allergies: ${allergyCheck.error}`);
38	
39	    const mrCheck = validateAllergyField(materialRestrictions);
40	    if (!mrCheck.valid) throw new Error(`Material restrictions: ${mrCheck.error}`);
41	
42	    const svCheck = validateStoredValue(storedValue);
43	    if (!svCheck.valid) throw new Error(svCheck.error);
44	
45	    const ptCheck = validatePoints(points);
46	    if (!ptCheck.valid) throw new Error(ptCheck.error);
47	
48	    if (!cryptoService.isUnlocked()) throw new Error('Session is locked. Please unlock to create customers with encrypted fields.');
49	
50	    const encAllergies = allergies ? await cryptoService.encrypt(allergies) : null;
51	    const encMR = materialRestrictions ? await cryptoService.encrypt(materialRestrictions) : null;
52	    const encSV = await cryptoService.encrypt(String(storedValue.toFixed(2)));
53	
54	    const customer = {
55	      id: generateId(),
56	      organizationId,
57	      name,
58	      membershipTier,
59	      points,
60	      storedValueCiphertext: encSV.ciphertext,
61	      storedValueIv: encSV.iv,
62	      allergiesCiphertext: encAllergies?.ciphertext ?? null,
63	      allergiesIv: encAllergies?.iv ?? null,
64	      materialRestrictionsCiphertext: encMR?.ciphertext ?? null,
65	      materialRestrictionsIv: encMR?.iv ?? null,
66	      ratingAverage: 0,
67	      ratingCount: 0,
68	      createdAt: Date.now(),
69	      updatedAt: Date.now(),
70	    };
71	
72	    await this._repo.create(customer);
73	    await auditService.log({ actorId, action: 'create_customer', entityType: 'customer', entityId: customer.id });
74	    return customer;
75	  }
76	
77	  /**
78	   * Updates non-sensitive customer fields.
79	   * Requires: ADMINISTRATOR or STORE_MANAGER role.
80	   *
81	   * @param {string} customerId
82	   * @param {{ name?: string; membershipTier?: string }} data
83	   * @param {string} actorId
84	   * @returns {Promise<object>}
85	   */
86	  async updateCustomer(customerId, data, actorId) {
87	    const actor = this._requireRole(ROLES.STORE_MANAGER);
88	
89	    const customer = await this._repo.findById(customerId);
90	    if (!customer) throw new Error('Customer not found.');
91	    await this._assertOrgScope(actor, customer.organizationId);
92	
93	    if (data.membershipTier && !isValidMembershipTier(data.membershipTier)) {
94	      throw new Error(`Invalid membership tier: ${data.membershipTier}`);
95	    }
96	
97	    const updated = { ...customer, ...data, updatedAt: Date.now() };
98	    await this._repo.update(customerId, updated);
99	    await auditService.log({ actorId, action: 'update_customer', entityType: 'customer', entityId: customerId });
100	    return updated;
101	  }
102	
103	  /**
104	   * Adjusts stored value by delta (positive = credit, negative = debit).
105	   * Blocks negative balance.
106	   * Requires: ADMINISTRATOR or STORE_MANAGER role.
107	   *
108	   * @param {string} customerId
109	   * @param {number} delta
110	   * @param {string} actorId
111	   * @returns {Promise<object>}
112	   */
113	  async adjustStoredValue(customerId, delta, actorId) {
114	    const actor = this._requireRole(ROLES.STORE_MANAGER);
115	
116	    if (!cryptoService.isUnlocked()) throw new Error('Session is locked. Cannot access encrypted stored value.');
117	
118	    const customer = await this._repo.findById(customerId);
119	    if (!customer) throw new Error('Customer not found.');
120	    await this._assertOrgScope(actor, customer.organizationId);
121	
122	    const currentStr = await cryptoService.decrypt(customer.storedValueCiphertext, customer.storedValueIv);
123	    const current = parseFloat(currentStr);
124	    const newValue = Math.round((current + delta) * 100) / 100;
125	
126	    const svCheck = validateStoredValue(newValue);
127	    if (!svCheck.valid) throw new Error(svCheck.error);
128	
129	    const encSV = await cryptoService.encrypt(String(newValue.toFixed(2)));
130	    const updated = { ...customer, storedValueCiphertext: encSV.ciphertext, storedValueIv: encSV.iv, updatedAt: Date.now() };
131	    await this._repo.update(customerId, updated);
132	    await auditService.log({ actorId, action: 'adjust_stored_value', entityType: 'customer', entityId: customerId, metadata: { delta } });
133	    return updated;
134	  }
135	
136	  /**
137	   * Adjusts points balance.
138	   * Requires: ADMINISTRATOR or STORE_MANAGER role.
139	   *
140	   * @param {string} customerId
141	   * @param {number} delta  Positive or negative integer.
142	   * @param {string} actorId
143	   * @returns {Promise<object>}
144	   */
145	  async adjustPoints(customerId, delta, actorId) {
146	    const actor = this._requireRole(ROLES.STORE_MANAGER);
147	
148	    const customer = await this._repo.findById(customerId);
149	    if (!customer) throw new Error('Customer not found.');
150	    await this._assertOrgScope(actor, customer.organizationId);
151	
152	    if (!Number.isInteger(delta)) throw new Error('Points delta must be an integer.');
153	
154	    const newPoints = customer.points + delta;
155	    const ptCheck = validatePoints(newPoints);
156	    if (!ptCheck.valid) throw new Error(ptCheck.error);
157	
158	    const updated = { ...customer, points: newPoints, updatedAt: Date.now() };
159	    await this._repo.update(customerId, updated);
160	    await auditService.log({ actorId, action: 'adjust_points', entityType: 'customer', entityId: customerId, metadata: { delta } });
161	    return updated;
162	  }
163	
164	  /**
165	   * Adds a service rating for the customer.
166	   * Updates running average and count.
167	   * Requires: ADMINISTRATOR or STORE_MANAGER role.
168	   *
169	   * @param {string} customerId
170	   * @param {number} rating  Integer 1–5.
171	   * @param {string} actorId
172	   * @returns {Promise<object>}
173	   */
174	  async addRating(customerId, rating, actorId) {
175	    this._requireRole(ROLES.STORE_MANAGER);
176	
177	    const ratingCheck = validateRating(rating);
178	    if (!ratingCheck.valid) throw new Error(ratingCheck.error);
179	
180	    const customer = await this._repo.findById(customerId);
181	    if (!customer) throw new Error('Customer not found.');
182	
183	    const newCount = customer.ratingCount + 1;
184	    const newAverage = (customer.ratingAverage * customer.ratingCount + rating) / newCount;
185	    const updated = { ...customer, ratingAverage: Math.round(newAverage * 10) / 10, ratingCount: newCount, updatedAt: Date.now() };
186	    await this._repo.update(customerId, updated);
187	    await auditService.log({ actorId, action: 'add_rating', entityType: 'customer', entityId: customerId, metadata: { rating } });
188	    return updated;
189	  }
190	
191	  /**
192	   * Decrypts and returns sensitive fields for display.
193	   * Requires an unlocked session.
194	   * Requires: ADMINISTRATOR, STORE_MANAGER, or ANALYST role.
195	   *
196	   * @param {string} customerId
197	   * @returns {Promise<{ storedValue: string; allergies: string | null; materialRestrictions: string | null }>}
198	   */
199	  async revealSensitiveFields(customerId) {
200	    this._requireRole(ROLES.ANALYST);
201	
202	    if (!cryptoService.isUnlocked()) throw new Error('Session is locked. Please unlock to access sensitive data.');
203	
204	    const customer = await this._repo.findById(customerId);
205	    if (!customer) throw new Error('Customer not found.');
206	
207	    const storedValue = await cryptoService.decrypt(customer.storedValueCiphertext, customer.storedValueIv);
208	    const allergies = customer.allergiesCiphertext
209	      ? await cryptoService.decrypt(customer.allergiesCiphertext, customer.allergiesIv)
210	      : null;
211	    const materialRestrictions = customer.materialRestrictionsCiphertext
212	      ? await cryptoService.decrypt(customer.materialRestrictionsCiphertext, customer.materialRestrictionsIv)
213	      : null;
214	
215	    return { storedValue, allergies, materialRestrictions };
216	  }
217	
218	  /**
219	   * Returns masked placeholders for sensitive fields.
220	   * Requires: any authenticated user.
221	   *
222	   * @param {string} customerId
223	   * @returns {Promise<{ storedValue: string; allergies: string; materialRestrictions: string }>}
224	   */
225	  async getMaskedFields(customerId) {
226	    const actor = this._requireAuth();
227	
228	    const customer = await this._repo.findById(customerId);
229	    if (!customer) throw new Error('Customer not found.');
230	    await this._assertOrgScope(actor, customer.organizationId);
231	
232	    return {
233	      storedValue: cryptoService.maskValue(''),
234	      allergies: customer.allergiesCiphertext ? cryptoService.maskValue('') : null,
235	      materialRestrictions: customer.materialRestrictionsCiphertext ? cryptoService.maskValue('') : null,
236	    };
237	  }
238	
239	  /**
240	   * Returns all customers for an organization.
241	   * Scope-enforced for non-admin users.
242	   *
243	   * @param {string} organizationId
244	   * @returns {Promise<object[]>}
245	   */
246	  async getByOrg(organizationId) {
247	    const actor = this._requireAuth();
248	    await this._assertOrgScope(actor, organizationId);
249	    return this._repo.findByOrg(organizationId);
250	  }
251	
252	  /**
253	   * Returns a single customer by ID.
254	   * @param {string} customerId
255	   * @returns {Promise<object | null>}
256	   */
257	  async getById(customerId) {
258	    const actor = this._requireAuth();
259	    const customer = await this._repo.findById(customerId);
260	    if (customer) await this._assertOrgScope(actor, customer.organizationId);
261	    return customer;
262	  }
263	
264	  // ── Private helpers ──────────────────────────────────────────────────────────
265	
266	  /**
267	   * Requires authentication and at least one of the given roles.
268	   * ADMINISTRATOR always passes. Returns the current user.
269	   *
270	   * @param {...string} allowedRoles
271	   * @returns {object}
272	   */
273	  _requireRole(...allowedRoles) {
274	    const user = authService.getCurrentUser();
275	    if (!user) throw new Error('Authentication required.');
276	    if (user.role === ROLES.ADMINISTRATOR) return user;
277	    if (allowedRoles.length > 0 && !allowedRoles.includes(user.role)) {
278	      throw new Error(`Permission denied. Required role(s): ${allowedRoles.join(', ')}`);
279	    }
280	    return user;
281	  }
282	
283	  /** Requires authentication only. Returns the current user. */
284	  _requireAuth() {
285	    const user = authService.getCurrentUser();
286	    if (!user) throw new Error('Authentication required.');
287	    return user;
288	  }
289	
290	  /**
291	   * For non-admin actors: verifies the target org is within their accessible subtree.
292	   * @param {object} actor
293	   * @param {string} targetOrgId
294	   */
295	  async _assertOrgScope(actor, targetOrgId) {
296	    if (actor.role === ROLES.ADMINISTRATOR) return;
297	    if (!actor.organizationNodeId) throw new Error('Actor has no organization assigned.');
298	    const inScope = await orgService.isInScope(actor, targetOrgId);
299	    if (!inScope) throw new Error('Scope violation: you can only access data within your assigned organization.');
300	  }
301	}
