17	 * RBAC:
18	 *   - create/update/delete → ADMINISTRATOR or STORE_MANAGER
19	 *   - reads / render       → any authenticated user
20	 */
21	export class TemplateService {
22	  constructor() {
23	    this._repo = new TemplateRepository();
24	  }
25	
26	  /**
27	   * Creates a new message template.
28	   * Validates declared placeholders match those found in the body.
29	   * Requires: ADMINISTRATOR or STORE_MANAGER role.
30	   *
31	   * @param {{ organizationId: string; name: string; body: string; isCompact?: boolean; actorId: string }} params
32	   * @returns {Promise<object>}
33	   */
34	  async createTemplate({ organizationId, name, body, isCompact = false, actorId }) {
35	    this._requireRole(ROLES.STORE_MANAGER);
36	
37	    if (!name?.trim()) throw new Error('Template name is required.');
38	    if (!body?.trim()) throw new Error('Template body is required.');
39	
40	    const detectedPlaceholders = extractPlaceholders(body);
41	
42	    const template = {
43	      id: generateId(),
44	      organizationId,
45	      name,
46	      body,
47	      placeholders: detectedPlaceholders,
48	      isCompact,
49	      createdAt: Date.now(),
50	      updatedAt: Date.now(),
51	    };
52	
53	    await this._repo.create(template);
54	    await auditService.log({ actorId, action: 'create_template', entityType: 'template', entityId: template.id });
55	    return template;
56	  }
57	
58	  /**
59	   * Updates a template.
60	   * Requires: ADMINISTRATOR or STORE_MANAGER role.
61	   *
62	   * @param {string} templateId
63	   * @param {{ name?: string; body?: string; isCompact?: boolean }} data
64	   * @param {string} actorId
65	   * @returns {Promise<object>}
66	   */
67	  async updateTemplate(templateId, data, actorId) {
68	    this._requireRole(ROLES.STORE_MANAGER);
69	
70	    const existing = await this._repo.findById(templateId);
71	    if (!existing) throw new Error('Template not found.');
72	
73	    const newBody = data.body ?? existing.body;
74	    const detectedPlaceholders = extractPlaceholders(newBody);
75	
76	    const updated = {
