2	import { getDB, requestToPromise } from '../../infrastructure/db/db.js';
3	
4	export class MasterDataRepository extends BaseRepository {
5	  constructor() {
6	    super('masterDataVersions');
7	  }
8	
9	  /**
10	   * Returns the single active version for an entity type in an org.
11	   * @param {string} entityType
12	   * @param {string} organizationId
13	   * @returns {Promise<object | null>}
14	   */
15	  async findActiveVersion(entityType, organizationId) {
16	    const all = await this.findAll();
17	    return (
18	      all.find(
19	        (v) => v.entityType === entityType && v.organizationId === organizationId && v.isActive,
20	      ) ?? null
21	    );
22	  }
23	
24	  /**
25	   * Returns all versions for a specific entity, ordered by versionNumber descending.
26	   * @param {string} entityId
27	   * @returns {Promise<object[]>}
28	   */
29	  async findVersionHistory(entityId) {
30	    const versions = await this.findByIndex('by_entityId', entityId);
31	    return versions.sort((a, b) => b.versionNumber - a.versionNumber);
32	  }
33	
34	  /**
35	   * Returns all active versions for an organization.
36	   * @param {string} organizationId
37	   * @returns {Promise<object[]>}
38	   */
39	  async findActiveVersionsByOrg(organizationId) {
40	    const all = await this.findByIndex('by_orgId', organizationId);
41	    return all.filter((v) => v.isActive);
42	  }
43	
44	  /**
45	   * Atomically checks the optimistic concurrency guard, deactivates the
46	   * current active version, and creates the new one — all within a single
47	   * IndexedDB transaction.  This eliminates the TOCTOU race that would occur
48	   * if the concurrency check happened outside the transaction.
49	   *
50	   * @param {string | null} expectedActiveVersionId  The version the caller loaded.
51	   * @param {object} newVersionData  Must include entityType and organizationId.
52	   * @returns {Promise<object>}
53	   */
54	  async atomicVersionSwitch(expectedActiveVersionId, newVersionData) {
55	    const db = getDB();
56	    const tx = db.transaction('masterDataVersions', 'readwrite');
57	    const store = tx.objectStore('masterDataVersions');
58	
59	    // Re-read the current active version INSIDE the transaction so the check
60	    // and the write are serialized by IDB's transaction locking.
61	    const all = await requestToPromise(store.getAll());
62	    const currentActive = all.find(
63	      (v) =>
64	        v.entityType === newVersionData.entityType &&
65	        v.organizationId === newVersionData.organizationId &&
66	        v.isActive,
67	    ) ?? null;
68	
69	    const currentActiveId = currentActive?.id ?? null;
70	    if (currentActiveId !== (expectedActiveVersionId ?? null)) {
71	      tx.abort();
72	      throw new Error(
73	        'Concurrency conflict: the active version changed since you loaded this form. Please reload.',
74	      );
75	    }
76	
77	    if (currentActive) {
78	      await requestToPromise(store.put({ ...currentActive, isActive: false }));
79	    }
80	
81	    await requestToPromise(store.add(newVersionData));
82	
83	    return new Promise((resolve, reject) => {
84	      tx.oncomplete = () => resolve(newVersionData);
85	      tx.onerror = () => reject(tx.error);
86	      tx.onabort = () => reject(new Error('atomicVersionSwitch transaction aborted'));
87	    });
88	  }
89	}
