1	import {
2	  RiskRuleRepository,
3	  RiskCaseRepository,
4	  BidEventRepository,
5	  LinkedAccountRepository,
6	} from '../repositories/implementations/RiskRepository.js';
7	import { auditService } from './AuditService.js';
8	import { authService } from './AuthService.js';
9	import { generateId } from '../utils/idGenerator.js';
10	import { ROLES, RISK_CASE_STATUSES, OUTCOME_CODES } from '../utils/constants.js';
11	import { orgService } from './OrgService.js';
12	import { isValidOutcomeCode, validateImageFile } from '../utils/validation.js';
13	
14	/**
15	 * RiskReviewService — risk case evaluation, bid signal analysis, and resolution.
16	 *
17	 * RBAC:
18	 *   - evaluateRules, validateImage, evaluateBiddingHeuristics → ADMINISTRATOR or STORE_MANAGER
19	 *   - ingestBidEvent, ingestLinkedAccount                     → ADMINISTRATOR or STORE_MANAGER
20	 *   - assignCase, resolveCase, dismissCase                    → ADMINISTRATOR or REVIEWER
21	 *   - getInbox                                                → ADMINISTRATOR or REVIEWER
22	 */
23	export class RiskReviewService {
24	  constructor() {
25	    this._ruleRepo = new RiskRuleRepository();
26	    this._caseRepo = new RiskCaseRepository();
27	    this._bidRepo = new BidEventRepository();
28	    this._linkedRepo = new LinkedAccountRepository();
29	
30	    /** @type {string[]} Sensitive word dictionary (loaded from app config). */
31	    this._sensitiveWords = [];
32	  }
33	
34	  /**
35	   * Loads the sensitive word dictionary from a plain array.
36	   * Words are lowercased for matching.
37	   * @param {string[]} words
38	   */
39	  loadSensitiveWordDictionary(words) {
40	    if (!Array.isArray(words)) throw new Error('Sensitive word dictionary must be an array.');
41	    this._sensitiveWords = words.map((w) => w.toLowerCase());
42	  }
43	
44	  // ── Machine rule evaluation ───────────────────────────────────────────────────
45	
46	  /**
47	   * Evaluates all active rules against a submitted entity and generates risk cases.
48	   * Requires: ADMINISTRATOR or STORE_MANAGER role.
49	   *
50	   * @param {{ organizationId: string; entityType: string; entityId: string; payload: object; actorId: string }} params
51	   * @returns {Promise<object[]>}  Generated risk cases.
52	   */
53	  async evaluateRules({ organizationId, entityType, entityId, payload, actorId }) {
54	    this._requireRole(ROLES.STORE_MANAGER);
55	
56	    if (!entityType?.trim()) throw new Error('entityType is required.');
57	    if (!entityId?.trim()) throw new Error('entityId is required.');
58	    if (!payload || typeof payload !== 'object') throw new Error('payload must be a non-null object.');
59	
60	    const rules = await this._ruleRepo.findActiveByOrg(organizationId);
61	    const applicableRules = rules.filter((r) => r.targetEntityType === entityType || r.targetEntityType === '*');
62	
63	    const matches = [];
64	    for (const rule of applicableRules) {
65	      if (this._ruleMatches(rule, payload)) {
66	        matches.push({ ruleId: rule.id, ruleName: rule.name, ruleType: rule.ruleType });
67	      }
68	    }
69	
70	    // Check sensitive words in any string field of the payload.
71	    const swMatches = this._checkSensitiveWords(payload);
72	    if (swMatches.length > 0) {
73	      matches.push({ ruleId: 'sensitive_word', ruleName: 'Sensitive Word Match', matches: swMatches });
74	    }
75	
76	    if (matches.length === 0) return [];
77	
78	    const riskCase = {
79	      id: generateId(),
80	      organizationId,
81	      sourceType: entityType,
82	      sourceId: entityId,
83	      ruleMatches: matches,
84	      status: RISK_CASE_STATUSES.OPEN,
85	      outcomeCode: null,
86	      resolutionComment: null,
87	      assignedReviewerId: null,
88	      createdAt: Date.now(),
89	      resolvedAt: null,
90	    };
91	
92	    await this._caseRepo.create(riskCase);
93	    await auditService.log({
94	      actorId,
95	      action: 'risk_case_created',
96	      entityType: 'riskCase',
97	      entityId: riskCase.id,
98	      metadata: { sourceType: entityType, ruleMatchCount: matches.length },
99	    });
100	
101	    return [riskCase];
102	  }
103	
104	  /**
105	   * Validates an image file before ingestion.
106	   * Checks MIME type, magic bytes, and size.
107	   * Requires: ADMINISTRATOR or STORE_MANAGER role.
108	   *
109	   * @param {File} file
110	   * @returns {Promise<{ valid: boolean; error: string | null }>}
111	   */
112	  async validateImage(file) {
113	    this._requireRole(ROLES.STORE_MANAGER);
114	    return validateImageFile(file);
115	  }
116	
117	  /**
118	   * Evaluates shill/abnormal bidding heuristics for a given item.
119	   * Device fingerprint clustering is best-effort only.
120	   * Requires: ADMINISTRATOR or STORE_MANAGER role.
121	   *
122	   * @param {{ organizationId: string; itemId: string; windowMs?: number; frequencyThreshold?: number }} params
123	   * @returns {Promise<{ flagged: boolean; reason: string | null; evidence: object }>}
124	   */
125	  async evaluateBiddingHeuristics({ organizationId, itemId, windowMs = 60 * 60_000, frequencyThreshold = 10 }) {
126	    this._requireRole(ROLES.STORE_MANAGER);
127	
128	    if (!itemId?.trim()) throw new Error('itemId is required.');
129	
130	    const now = Date.now();
131	    const events = await this._bidRepo.findByItemInWindow(itemId, now - windowMs, now);
132	
133	    if (events.length >= frequencyThreshold) {
134	      return {
135	        flagged: true,
136	        reason: `Bid frequency ${events.length} exceeds threshold ${frequencyThreshold} within ${windowMs / 60_000} minutes.`,
137	        evidence: { eventCount: events.length, windowMs, frequencyThreshold },
138	      };
139	    }
140	
141	    // Check for fingerprint clustering (best-effort heuristic).
142	    const fingerprints = new Map();
143	    for (const e of events) {
144	      if (e.deviceFingerprint) {
145	        fingerprints.set(e.deviceFingerprint, (fingerprints.get(e.deviceFingerprint) ?? 0) + 1);
146	      }
147	    }
148	    for (const [fp, count] of fingerprints) {
149	      if (count >= Math.floor(frequencyThreshold * 0.5)) {
150	        return {
151	          flagged: true,
152	          reason: `Device fingerprint '${fp}' appears ${count} times — possible coordinated activity (best-effort signal).`,
153	          evidence: { fingerprint: fp, count, isBestEffort: true },
154	        };
155	      }
156	    }
157	
158	    return { flagged: false, reason: null, evidence: {} };
159	  }
160	
161	  // ── Bid / linked account ingestion ───────────────────────────────────────────
162	
163	  /**
164	   * Ingests a bid event for analysis.
165	   * Requires: ADMINISTRATOR or STORE_MANAGER role.
166	   *
167	   * @param {{ organizationId: string; userId: string; itemId: string; deviceFingerprint?: string; bidAmount: number; actorId: string }} params
168	   * @returns {Promise<object>}
169	   */
170	  async ingestBidEvent({ organizationId, userId, itemId, deviceFingerprint = null, bidAmount, actorId }) {
171	    const actor = this._requireRole(ROLES.STORE_MANAGER);
172	    await this._assertOrgScope(actor, organizationId);
173	
174	    if (!userId?.trim()) throw new Error('userId is required.');
175	    if (!itemId?.trim()) throw new Error('itemId is required.');
176	    if (typeof bidAmount !== 'number' || bidAmount <= 0) throw new Error('bidAmount must be a positive number.');
177	
178	    const event = {
179	      id: generateId(),
180	      organizationId,
181	      userId,
182	      itemId,
183	      deviceFingerprint,
184	      bidAmount,
185	      createdAt: Date.now(),
186	    };
187	
188	    await this._bidRepo.create(event);
189	    await auditService.log({
190	      actorId,
191	      action: 'ingest_bid_event',
192	      entityType: 'bidEvent',
193	      entityId: event.id,
194	      metadata: { userId, itemId, bidAmount },
195	    });
196	
197	    return event;
198	  }
199	
200	  /**
201	   * Records a linked account relationship as evidence.
202	   * Requires: ADMINISTRATOR or STORE_MANAGER role.
203	   *
204	   * @param {{ organizationId: string; primaryUserId: string; linkedUserId: string; evidenceType: string; evidenceDetails: string; actorId: string }} params
205	   * @returns {Promise<object>}
206	   */
207	  async ingestLinkedAccount({ organizationId, primaryUserId, linkedUserId, evidenceType, evidenceDetails, actorId }) {
208	    const actor = this._requireRole(ROLES.STORE_MANAGER);
209	    await this._assertOrgScope(actor, organizationId);
210	
211	    if (!primaryUserId?.trim()) throw new Error('primaryUserId is required.');
212	    if (!linkedUserId?.trim()) throw new Error('linkedUserId is required.');
213	    if (primaryUserId === linkedUserId) throw new Error('primaryUserId and linkedUserId must differ.');
214	    if (!evidenceType?.trim()) throw new Error('evidenceType is required.');
215	    if (!evidenceDetails?.trim()) throw new Error('evidenceDetails is required.');
216	
217	    const link = {
218	      id: generateId(),
219	      organizationId,
220	      primaryUserId,
221	      linkedUserId,
222	      evidenceType,
223	      evidenceDetails,
224	      createdAt: Date.now(),
225	    };
226	
227	    await this._linkedRepo.create(link);
228	    await auditService.log({
229	      actorId,
230	      action: 'ingest_linked_account',
231	      entityType: 'linkedAccount',
232	      entityId: link.id,
233	      metadata: { primaryUserId, linkedUserId, evidenceType },
234	    });
235	
236	    return link;
237	  }
238	
239	  // ── Case management ───────────────────────────────────────────────────────────
240	
241	  /**
242	   * Assigns a risk case to a reviewer.
243	   * Requires: ADMINISTRATOR or REVIEWER role.
244	   *
245	   * @param {string} caseId
246	   * @param {string} reviewerId
247	   * @param {string} actorId
248	   * @returns {Promise<object>}
249	   */
250	  async assignCase(caseId, reviewerId, actorId) {
251	    const actor = this._requireRole(ROLES.REVIEWER);
252	
253	    const riskCase = await this._getOrThrow(caseId);
254	    await this._assertOrgScope(actor, riskCase.organizationId);
255	    this._assertNotClosed(riskCase);
256	
257	    const updated = { ...riskCase, status: RISK_CASE_STATUSES.IN_REVIEW, assignedReviewerId: reviewerId };
258	    await this._caseRepo.update(caseId, updated);
259	    await auditService.log({
260	      actorId,
261	      action: 'assign_risk_case',
262	      entityType: 'riskCase',
263	      entityId: caseId,
264	      metadata: { reviewerId },
265	    });
266	    return updated;
267	  }
268	
269	  /**
270	   * Resolves a risk case with an outcome code and comment.
271	   * Both outcome code and comment are REQUIRED — no case may close without them.
272	   * Requires: ADMINISTRATOR or REVIEWER role.
273	   *
274	   * @param {{ caseId: string; outcomeCode: string; resolutionComment: string; reviewerId: string }} params
275	   * @returns {Promise<object>}
276	   */
277	  async resolveCase({ caseId, outcomeCode, resolutionComment, reviewerId }) {
278	    const actor = this._requireRole(ROLES.REVIEWER);
279	
280	    if (!isValidOutcomeCode(outcomeCode)) {
281	      throw new Error(`Invalid outcome code: '${outcomeCode}'. Valid: ${Object.values(OUTCOME_CODES).join(', ')}`);
282	    }
283	    if (!resolutionComment?.trim()) {
284	      throw new Error('Resolution comment is required to close a risk case.');
285	    }
286	
287	    const riskCase = await this._getOrThrow(caseId);
288	    await this._assertOrgScope(actor, riskCase.organizationId);
289	    this._assertNotClosed(riskCase);
290	
291	    const updated = {
292	      ...riskCase,
293	      status: RISK_CASE_STATUSES.RESOLVED,
294	      outcomeCode,
295	      resolutionComment,
296	      assignedReviewerId: reviewerId,
297	      resolvedAt: Date.now(),
298	    };
299	
300	    await this._caseRepo.update(caseId, updated);
301	    await auditService.log({
302	      actorId: reviewerId,
303	      action: 'resolve_risk_case',
