507	  _assertNotClosed(riskCase) {
508	    if (riskCase.status === RISK_CASE_STATUSES.RESOLVED || riskCase.status === RISK_CASE_STATUSES.DISMISSED) {
509	      throw new Error(`Risk case '${riskCase.id}' is already closed (${riskCase.status}).`);
510	    }
511	  }
512	
513	  _ruleMatches(rule, payload) {
514	    if (rule.ruleType === 'field_contains') {
515	      const { field, value } = rule.parameters;
516	      const fieldValue = String(payload[field] ?? '').toLowerCase();
517	      return fieldValue.includes(String(value).toLowerCase());
518	    }
519	    if (rule.ruleType === 'field_exceeds') {
520	      const { field, threshold } = rule.parameters;
521	      return Number(payload[field] ?? 0) > threshold;
522	    }
523	    return false;
524	  }
525	
526	  _checkSensitiveWords(payload) {
527	    if (this._sensitiveWords.length === 0) return [];
528	    const text = Object.values(payload)
529	      .filter((v) => typeof v === 'string')
530	      .join(' ')
531	      .toLowerCase();
532	    return this._sensitiveWords.filter((word) => text.includes(word));
533	  }
534	
535	  _requireRole(...allowedRoles) {
536	    const user = authService.getCurrentUser();
537	    if (!user) throw new Error('Authentication required.');
538	    if (user.role === ROLES.ADMINISTRATOR) return user;
539	    if (allowedRoles.length > 0 && !allowedRoles.includes(user.role)) {
540	      throw new Error(`Permission denied. Required role(s): ${allowedRoles.join(', ')}`);
541	    }
542	    return user;
543	  }
544	
545	  async _assertOrgScope(actor, targetOrgId) {
546	    if (actor.role === ROLES.ADMINISTRATOR) return;
547	    if (!actor.organizationNodeId) throw new Error('Actor has no organization assigned.');
548	    const inScope = await orgService.isInScope(actor, targetOrgId);
549	    if (!inScope) throw new Error('Scope violation: you can only access data within your assigned organization.');
550	  }
551	}
