168	
169	  // ── Topic clustering ─────────────────────────────────────────────────────────
170	
171	  /**
172	   * Clusters imported texts by their dominant topic using the latest run.
173	   * Returns a map of { topicName: [textId, ...] }.
174	   * If no runs exist, returns an empty object.
175	   * Requires: ADMINISTRATOR, ANALYST, or REVIEWER role.
176	   *
177	   * @param {string} organizationId
178	   * @returns {Promise<Record<string, string[]>>}
179	   */
180	  async clusterTopics(organizationId) {
181	    this._requireRole(ROLES.ANALYST, ROLES.REVIEWER);
182	
183	    const runs = await this._runRepo.findByOrg(organizationId);
184	    if (runs.length === 0) return {};
185	
186	    const latestRun = runs.sort((a, b) => b.createdAt - a.createdAt)[0];
187	    const clusters = {};
188	
189	    for (const [textId, output] of Object.entries(latestRun.outputPayload)) {
190	      const topics = output.topics ?? [];
191	      const dominant = topics[0] ?? 'uncategorized';
192	      if (!clusters[dominant]) clusters[dominant] = [];
193	      clusters[dominant].push(textId);
194	    }
195	
196	    return clusters;
197	  }
