199	  // ── Entity disambiguation ─────────────────────────────────────────────────────
200	
201	  /**
202	   * Extracts and disambiguates named entities from text using context cues.
203	   * Returns entities with types: PERSON, ORG, LOCATION, PRODUCT, or PROPER_NOUN.
204	   *
205	   * @param {string} text
206	   * @returns {Array<{ text: string; type: string }>}
207	   */
208	  disambiguateEntities(text) {
209	    const rawEntities = this._extractEntities(text);
210	    const lower = text.toLowerCase();
211	
212	    const orgSuffixes = ['inc', 'corp', 'ltd', 'llc', 'co', 'group', 'enterprises', 'company', 'solutions', 'technologies'];
213	    const locationIndicators = ['street', 'avenue', 'blvd', 'road', 'city', 'town', 'county', 'district', 'park', 'plaza', 'located in', 'based in', 'store in'];
214	    const productIndicators = ['model', 'version', 'edition', 'series', 'collection', 'range', 'line', 'sku', 'product', 'item'];
215	
216	    return rawEntities.map((entity) => {
217	      const entityLower = entity.text.toLowerCase();
218	      const entityIdx = lower.indexOf(entityLower);
219	      const context = entityIdx !== -1
220	        ? lower.slice(Math.max(0, entityIdx - 30), entityIdx + entityLower.length + 30)
221	        : '';
222	
223	      if (orgSuffixes.some((s) => entityLower.endsWith(s) || context.includes(entityLower + ' ' + s))) {
224	        return { text: entity.text, type: 'ORG' };
225	      }
226	
227	      if (locationIndicators.some((indicator) => context.includes(indicator))) {
228	        return { text: entity.text, type: 'LOCATION' };
229	      }
230	
231	      if (productIndicators.some((indicator) => context.includes(indicator))) {
232	        return { text: entity.text, type: 'PRODUCT' };
233	      }
234	
235	      return { text: entity.text, type: 'PERSON' };
236	    });
237	  }
