249	  async createValidationProfile({ modelVersion, corpusName, precision, recall, f1, labeledSampleCount, actorId }) {
250	    this._requireRole(ROLES.ADMINISTRATOR);
251	
252	    if (!modelVersion?.trim()) throw new Error('Model version is required.');
253	    if (!corpusName?.trim()) throw new Error('Corpus name is required.');
254	    if (typeof precision !== 'number' || precision < 0 || precision > 1) throw new Error('Precision must be a number between 0 and 1.');
255	    if (typeof recall !== 'number' || recall < 0 || recall > 1) throw new Error('Recall must be a number between 0 and 1.');
256	    if (typeof f1 !== 'number' || f1 < 0 || f1 > 1) throw new Error('F1 score must be a number between 0 and 1.');
257	    if (!Number.isInteger(labeledSampleCount) || labeledSampleCount < 1) throw new Error('labeledSampleCount must be a positive integer.');
258	
259	    const profile = {
260	      id: generateId(),
261	      modelVersion,
262	      corpusName,
263	      precision,
264	      recall,
265	      f1,
266	      labeledSampleCount,
267	      createdAt: Date.now(),
268	    };
269	    const created = await this._profileRepo.create(profile);
270	    await auditService.log({ actorId, action: 'create_validation_profile', entityType: 'validationProfile', entityId: profile.id, metadata: { modelVersion, f1 } });
271	    return created;
272	  }
