276	  async _executeRun({ organizationId, modelVersion, inputIds, texts, runType, actorId }) {
277	    const outputPayload = texts.reduce((acc, text) => {
278	      acc[text.id] = {
279	        keywords: this._extractKeywords(text.rawText),
280	        summary: this._extractSummary(text.rawText),
281	        topics: this._classifyTopics(text.rawText),
282	        sentiment: this._analyzeSentiment(text.rawText),
283	        entities: this._extractEntities(text.rawText),
284	      };
285	      return acc;
286	    }, {});
287	
288	    // Benchmark metrics from validation profile — never synthetic.
289	    const profile = await this._profileRepo.findByModelVersion(modelVersion)
290	      ?? await this._profileRepo.findLatest();
291	
292	    const run = {
293	      id: generateId(),
294	      organizationId,
295	      runType,
296	      modelVersion,
297	      inputIds,
298	      outputPayload,
299	      benchmarkPrecision: profile?.precision ?? null,
300	      benchmarkRecall: profile?.recall ?? null,
301	      benchmarkF1: profile?.f1 ?? null,
302	      belowF1Threshold: profile ? (profile.f1 < NLP.F1_ALERT_THRESHOLD) : false,
303	      createdBy: actorId,
304	      createdAt: Date.now(),
305	    };
306	
307	    await this._runRepo.create(run);
308	    await auditService.log({
309	      actorId,
310	      action: 'nlp_run',
311	      entityType: 'nlpRun',
312	      entityId: run.id,
313	      metadata: { runType, modelVersion, inputCount: inputIds.length, belowF1Threshold: run.belowF1Threshold },
314	    });
