325	  _extractKeywords(text, topN = 10) {
326	    const stopWords = new Set(['the', 'a', 'an', 'is', 'in', 'on', 'at', 'to', 'and', 'or', 'of', 'it', 'for', 'with', 'this', 'that', 'was', 'are', 'be', 'by', 'from', 'as', 'but', 'not', 'have', 'had', 'has', 'he', 'she', 'they', 'we', 'you', 'i']);
327	    const words = text.toLowerCase().match(/\b[a-z]{3,}\b/g) ?? [];
328	    const freq = new Map();
329	    for (const w of words) {
330	      if (!stopWords.has(w)) freq.set(w, (freq.get(w) ?? 0) + 1);
331	    }
332	    return [...freq.entries()]
333	      .sort((a, b) => b[1] - a[1])
334	      .slice(0, topN)
335	      .map(([w]) => w);
336	  }
337	
338	  /**
339	   * Extractive summarization: returns the top-scoring sentences by keyword density.
340	   * @param {string} text
341	   * @param {number} [numSentences=3]
342	   * @returns {string}
343	   */
344	  _extractSummary(text, numSentences = 3) {
345	    const sentences = text.match(/[^.!?]+[.!?]+/g) ?? [text];
346	    if (sentences.length <= numSentences) return text;
347	    const keywords = new Set(this._extractKeywords(text));
348	    const scored = sentences.map((s) => {
349	      const words = s.toLowerCase().match(/\b[a-z]+\b/g) ?? [];
350	      const score = words.filter((w) => keywords.has(w)).length;
351	      return { sentence: s, score };
352	    });
353	    return scored
354	      .sort((a, b) => b.score - a.score)
355	      .slice(0, numSentences)
356	      .map((s) => s.sentence.trim())
357	      .join(' ');
358	  }
359	
360	  /**
361	   * Topic classification via simple keyword-bag matching.
362	   * @param {string} text
363	   * @returns {string[]}
364	   */
365	  _classifyTopics(text) {
366	    const topics = {
367	      logistics: ['shipping', 'delivery', 'warehouse', 'stock', 'inventory', 'transport'],
368	      customer: ['complaint', 'refund', 'return', 'satisfaction', 'service', 'support'],
369	      finance: ['payment', 'invoice', 'price', 'discount', 'cost', 'billing'],
370	      product: ['quality', 'defect', 'style', 'size', 'color', 'brand'],
371	    };
372	    const lower = text.toLowerCase();
373	    return Object.entries(topics)
374	      .filter(([, keywords]) => keywords.some((k) => lower.includes(k)))
375	      .map(([topic]) => topic);
376	  }
377	
378	  /**
379	   * Sentiment analysis via lexicon scoring.
380	   * @param {string} text
381	   * @returns {{ label: 'positive'|'negative'|'neutral'; score: number }}
382	   */
383	  _analyzeSentiment(text) {
384	    const positive = new Set(['good', 'great', 'excellent', 'happy', 'satisfied', 'love', 'perfect', 'wonderful', 'amazing', 'outstanding', 'positive', 'best', 'helpful']);
385	    const negative = new Set(['bad', 'poor', 'terrible', 'unhappy', 'dissatisfied', 'hate', 'awful', 'horrible', 'broken', 'worst', 'negative', 'disappointing', 'failed']);
386	    const words = text.toLowerCase().match(/\b[a-z]+\b/g) ?? [];
387	    let score = 0;
388	    for (const w of words) {
389	      if (positive.has(w)) score += 1;
390	      if (negative.has(w)) score -= 1;
391	    }
392	    const label = score > 0 ? 'positive' : score < 0 ? 'negative' : 'neutral';
393	    return { label, score };
394	  }
395	
396	  /**
397	   * Dictionary-based NER — recognizes capitalized noun sequences as entities.
398	   * @param {string} text
399	   * @returns {Array<{ text: string; type: string }>}
400	   */
401	  _extractEntities(text) {
402	    const entities = [];
403	    const namedEntityPattern = /\b[A-Z][a-z]+(?: [A-Z][a-z]+)*\b/g;
404	    for (const match of text.matchAll(namedEntityPattern)) {
405	      entities.push({ text: match[0], type: 'PROPER_NOUN' });
406	    }
407	    return entities;
408	  }
409	
410	  _requireRole(...allowedRoles) {
411	    const user = authService.getCurrentUser();
412	    if (!user) throw new Error('Authentication required.');
413	    if (user.role === ROLES.ADMINISTRATOR) return user;
414	    if (allowedRoles.length > 0 && !allowedRoles.includes(user.role)) {
415	      throw new Error(`Permission denied. Required role(s): ${allowedRoles.join(', ')}`);
416	    }
417	    return user;
418	  }
419	
420	  async _assertOrgScope(actor, targetOrgId) {
421	    if (actor.role === ROLES.ADMINISTRATOR) return;
422	    if (!actor.organizationNodeId) throw new Error('Actor has no organization assigned.');
423	    const inScope = await orgService.isInScope(actor, targetOrgId);
424	    if (!inScope) throw new Error('Scope violation: you can only access data within your assigned organization.');
425	  }
426	}
