1	<script>
2	  import { riskReviewService } from '../services/RiskReviewService.js';
3	  import { currentUser } from '../app/stores/auth.js';
4	  import { showToast } from '../app/stores/ui.js';
5	  import { RISK_CASE_STATUSES, OUTCOME_CODES } from '../utils/constants.js';
6	
7	  const outcomeCodes = Object.values(OUTCOME_CODES);
8	  const tabs = ['inbox', 'rules'];
9	
10	  let activeTab = 'inbox';
11	
12	  // Inbox tab
13	  let cases = [];
14	  let loading = false;
15	  let filterStatus = '';
16	
17	  let selectedCase = null;
18	  let outcomeCode = '';
19	  let resolutionComment = '';
20	  let actionLoading = false;
21	
22	  // Rules tab
23	  let rules = [];
24	  let rulesLoading = false;
25	  let showRuleForm = false;
26	  let ruleFormName = '';
27	  let ruleFormType = 'field_contains';
28	  let ruleFormEntityType = '*';
29	  let ruleFormField = '';
30	  let ruleFormValue = '';
31	  let ruleFormThreshold = '';
32	  let ruleFormError = '';
33	  let ruleFormLoading = false;
34	
35	  // Sensitive words
36	  let sensitiveWordsText = '';
37	  let sensitiveWordsLoading = false;
38	
39	  // Evaluate entity
40	  let evalEntityType = '';
41	  let evalEntityId = '';
42	  let evalPayloadJson = '{}';
43	  let evalResult = null;
44	  let evalLoading = false;
45	  let evalError = '';
46	
47	  $: actorId = $currentUser?.id ?? '';
48	  $: orgId = $currentUser?.organizationNodeId ?? '';
49	
50	  $: filteredCases = cases.filter((c) =>
51	    !filterStatus || c.status === filterStatus
52	  );
53	
54	  $: canSubmit = outcomeCode && resolutionComment.trim().length > 0;
55	
56	  $: if (orgId) loadInbox();
57	
58	  async function switchTab(tab) {
59	    activeTab = tab;
60	    if (tab === 'rules') await loadRules();
61	  }
62	
63	  async function loadInbox() {
64	    if (!orgId) return;
65	    loading = true;
66	    try {
67	      cases = await riskReviewService.getInbox(orgId);
68	    } catch (err) {
69	      showToast('error', err.message);
70	    } finally {
71	      loading = false;
72	    }
73	  }
74	
75	  async function loadRules() {
76	    rulesLoading = true;
77	    try {
78	      rules = await riskReviewService.listRules(orgId);
79	      sensitiveWordsText = riskReviewService.getSensitiveWords().join(', ');
80	    } catch (err) {
81	      showToast('error', err.message);
82	    } finally {
83	      rulesLoading = false;
84	    }
85	  }
86	
87	  function selectCase(c) {
88	    selectedCase = c;
89	    outcomeCode = c.outcomeCode ?? '';
90	    resolutionComment = c.resolutionComment ?? '';
91	  }
92	
93	  async function handleAssign() {
94	    if (!selectedCase) return;
95	    actionLoading = true;
96	    try {
97	      const updated = await riskReviewService.assignCase(selectedCase.id, actorId, actorId);
98	      cases = cases.map((c) => (c.id === updated.id ? updated : c));
99	      selectedCase = updated;
100	      showToast('success', 'Case assigned to you.');
101	    } catch (err) {
102	      showToast('error', err.message);
103	    } finally {
104	      actionLoading = false;
105	    }
106	  }
107	
108	  async function handleResolve() {
109	    if (!selectedCase || !canSubmit) return;
110	    actionLoading = true;
111	    try {
112	      const updated = await riskReviewService.resolveCase({
113	        caseId: selectedCase.id,
114	        outcomeCode,
115	        resolutionComment,
116	        reviewerId: actorId,
117	      });
118	      cases = cases.filter((c) => c.id !== updated.id); // Remove from inbox (terminal)
119	      selectedCase = null;
120	      outcomeCode = '';
121	      resolutionComment = '';
122	      showToast('success', 'Case resolved.');
123	    } catch (err) {
124	      showToast('error', err.message);
125	    } finally {
126	      actionLoading = false;
127	    }
128	  }
129	
130	  async function handleDismiss() {
131	    if (!selectedCase || !resolutionComment.trim()) return;
132	    actionLoading = true;
133	    try {
134	      const updated = await riskReviewService.dismissCase(
135	        selectedCase.id,
136	        resolutionComment,
137	        actorId,
138	      );
139	      cases = cases.filter((c) => c.id !== updated.id);
140	      selectedCase = null;
141	      outcomeCode = '';
142	      resolutionComment = '';
143	      showToast('success', 'Case dismissed as false positive.');
144	    } catch (err) {
145	      showToast('error', err.message);
146	    } finally {
147	      actionLoading = false;
148	    }
149	  }
150	
151	  async function handleCreateRule() {
152	    ruleFormError = '';
153	    ruleFormLoading = true;
154	    try {
155	      const parameters = ruleFormType === 'field_contains'
156	        ? { field: ruleFormField.trim(), value: ruleFormValue.trim() }
157	        : { field: ruleFormField.trim(), threshold: parseFloat(ruleFormThreshold) };
158	      await riskReviewService.createRule({
159	        organizationId: orgId,
160	        name: ruleFormName,
161	        ruleType: ruleFormType,
162	        targetEntityType: ruleFormEntityType,
163	        parameters,
164	        actorId,
165	      });
166	      await loadRules();
167	      showRuleForm = false;
168	      ruleFormName = '';
169	      ruleFormField = '';
170	      ruleFormValue = '';
171	      ruleFormThreshold = '';
172	      showToast('success', 'Rule created.');
173	    } catch (err) {
174	      ruleFormError = err.message;
175	    } finally {
176	      ruleFormLoading = false;
177	    }
178	  }
179	
180	  async function handleDeleteRule(ruleId) {
181	    try {
182	      await riskReviewService.deleteRule(ruleId, actorId);
183	      rules = rules.filter((r) => r.id !== ruleId);
184	      showToast('success', 'Rule deleted.');
185	    } catch (err) {
186	      showToast('error', err.message);
187	    }
188	  }
189	
190	  function handleUpdateSensitiveWords() {
191	    try {
192	      const words = sensitiveWordsText.split(',').map((w) => w.trim()).filter(Boolean);
193	      riskReviewService.updateSensitiveWords(words, actorId);
194	      showToast('success', 'Sensitive word dictionary updated.');
195	    } catch (err) {
196	      showToast('error', err.message);
197	    }
198	  }
199	
200	  async function handleEvaluate() {
201	    evalError = '';
202	    evalResult = null;
203	    let payload;
204	    try {
205	      payload = JSON.parse(evalPayloadJson);
206	    } catch {
207	      evalError = 'Payload must be valid JSON.';
208	      return;
209	    }
210	    evalLoading = true;
211	    try {
212	      const newCases = await riskReviewService.evaluateRules({
213	        organizationId: orgId,
214	        entityType: evalEntityType.trim(),
215	        entityId: evalEntityId.trim(),
216	        payload,
217	        actorId,
218	      });
219	      evalResult = newCases.length;
220	      if (newCases.length > 0) {
221	        await loadInbox(); // Refresh inbox so new cases appear
222	        showToast('success', `${newCases.length} case(s) created.`);
223	      } else {
224	        showToast('info', 'No rules matched — 0 cases created.');
225	      }
226	    } catch (err) {
227	      evalError = err.message;
228	    } finally {
229	      evalLoading = false;
230	    }
231	  }
232	
233	  function statusBadgeClass(status) {
234	    if (status === RISK_CASE_STATUSES.OPEN) return 'badge--open';
235	    if (status === RISK_CASE_STATUSES.IN_REVIEW) return 'badge--in-review';
236	    if (status === RISK_CASE_STATUSES.RESOLVED) return 'badge--resolved';
237	    return 'badge--dismissed';
238	  }
239	
240	  function formatDate(ms) {
241	    return ms ? new Date(ms).toLocaleString() : '—';
242	  }
