94	    if (!selectedCase) return;
95	    actionLoading = true;
96	    try {
97	      const updated = await riskReviewService.assignCase(selectedCase.id, actorId, actorId);
98	      cases = cases.map((c) => (c.id === updated.id ? updated : c));
99	      selectedCase = updated;
