111	    try {
112	      const updated = await riskReviewService.resolveCase({
113	        caseId: selectedCase.id,
114	        outcomeCode,
115	        resolutionComment,
116	        reviewerId: actorId,
117	      });
118	      cases = cases.filter((c) => c.id !== updated.id); // Remove from inbox (terminal)
119	      selectedCase = null;
