131	    if (!selectedCase || !resolutionComment.trim()) return;
132	    actionLoading = true;
133	    try {
134	      const updated = await riskReviewService.dismissCase(
135	        selectedCase.id,
136	        resolutionComment,
137	        actorId,
138	      );
139	      cases = cases.filter((c) => c.id !== updated.id);
140	      selectedCase = null;
141	      outcomeCode = '';
142	      resolutionComment = '';
143	      showToast('success', 'Case dismissed as false positive.');
