1	/**
2	 * EventDispatcherService
3	 *
4	 * Routes business events to notification recipients.
5	 * For each subscribed user it enqueues a templated message via NotificationService.enqueue().
6	 * For explicit recipientUserIds with no matching subscription it falls back to notifyUser().
7	 * All delivery failures are non-fatal and recorded in the audit log.
8	 */
9	
10	import { notificationService } from './NotificationService.js';
11	import { auditService } from './AuditService.js';
12	import { authService } from './AuthService.js';
13	import { generateId } from '../utils/idGenerator.js';
14	
15	export class EventDispatcherService {
16	  /**
17	   * Dispatches a business event.
18	   *
19	   * - Fetches subscriptions for eventType and enqueues a templated message for each subscriber.
20	   * - If recipientUserIds is provided, also notifies those users directly (fallback path for
21	   *   services that know their audience but subscribers may not exist yet).
22	   * - All delivery failures are caught and logged; they never propagate to callers.
23	   *
24	   * @param {{
25	   *   organizationId: string;
26	   *   eventType: string;
27	   *   sourceId: string;
28	   *   actorId: string;
29	   *   vars?: Record<string, string>;
30	   *   templateId?: string | null;
31	   *   recipientUserIds?: string[] | null;
32	   *   title?: string;
33	   *   body?: string;
34	   * }} params
35	   * @returns {Promise<void>}
36	   */
37	  async dispatch({
38	    organizationId,
39	    eventType,
40	    sourceId,
41	    actorId,
42	    vars = {},
43	    templateId = null,
44	    recipientUserIds = null,
45	    title,
46	    body,
47	  }) {
48	    const eventSourceKey = `${eventType}:${sourceId}:${actorId}:${Date.now()}`;
49	
50	    // ── Subscription-based delivery ──────────────────────────────────────────
51	    if (templateId) {
52	      try {
53	        const subscriptions = await notificationService.getSubscriptionsByEventType(eventType);
54	        for (const sub of subscriptions) {
55	          try {
56	            await notificationService.enqueue({
57	              organizationId,
58	              recipientUserId: sub.userId,
59	              templateId,
60	              channelId: sub.channelId,
61	              vars,
62	              eventSourceKey: `${eventSourceKey}:${sub.userId}`,
63	            });
64	          } catch (err) {
65	            await auditService.log({
66	              actorId,
67	              action: 'dispatch_enqueue_failed',
68	              entityType: 'event',
69	              entityId: sourceId,
70	              metadata: { eventType, userId: sub.userId, error: err.message },
71	            }).catch(() => {});
72	          }
73	        }
74	      } catch (err) {
75	        await auditService.log({
76	          actorId,
77	          action: 'dispatch_subscription_lookup_failed',
78	          entityType: 'event',
79	          entityId: sourceId,
80	          metadata: { eventType, error: err.message },
81	        }).catch(() => {});
82	      }
83	    }
84	
85	    // ── Direct fallback delivery ──────────────────────────────────────────────
86	    if (recipientUserIds?.length && title && body) {
87	      for (const userId of recipientUserIds) {
88	        try {
89	          await notificationService.notifyUser(userId, { type: eventType, title, body });
90	        } catch (err) {
91	          await auditService.log({
92	            actorId,
93	            action: 'dispatch_notify_failed',
94	            entityType: 'event',
95	            entityId: sourceId,
96	            metadata: { eventType, userId, error: err.message },
97	          }).catch(() => {});
98	        }
99	      }
100	    }
101	  }
102	
103	  _requireAuth() {
104	    const user = authService.getCurrentUser();
105	    if (!user) throw new Error('Authentication required.');
106	    return user;
107	  }
108	}
109	
110	export const eventDispatcherService = new EventDispatcherService();
111	

