1	import { CustomerRepository } from '../repositories/implementations/CustomerRepository.js';
2	import { MasterDataRepository } from '../repositories/implementations/MasterDataRepository.js';
3	import { cryptoService } from './CryptoService.js';
4	import { auditService } from './AuditService.js';
5	import { authService } from './AuthService.js';
6	import { generateId } from '../utils/idGenerator.js';
7	import {
8	  validateAllergyField,
9	  validateStoredValue,
10	  validatePoints,
11	  validateRating,
12	  validateReasonNote,
13	  isValidMembershipTier,
14	} from '../utils/validation.js';
15	import { ROLES, MEMBERSHIP_TIERS } from '../utils/constants.js';
16	import { orgService } from './OrgService.js';
17	
18	export class CustomerService {
19	  constructor() {
20	    this._repo = new CustomerRepository();
21	  }
22	
23	  /**
24	   * Creates a new customer record with encrypted sensitive fields.
25	   * Requires: ADMINISTRATOR or STORE_MANAGER role.
26	   * Scope: actor must have access to the target organizationId.
27	   *
28	   * @param {{ organizationId: string; name: string; membershipTier?: string; points?: number; storedValue?: number; allergies?: string; materialRestrictions?: string; actorId: string }} params
29	   * @returns {Promise<object>}
30	   */
31	  async createCustomer({ organizationId, name, membershipTier = MEMBERSHIP_TIERS.BRONZE, points = 0, storedValue = 0, allergies = '', materialRestrictions = '', actorId }) {
32	    const actor = this._requireRole(ROLES.STORE_MANAGER);
33	    await this._assertOrgScope(actor, organizationId);
34	
35	    if (!name?.trim()) throw new Error('Customer name is required.');
36	    if (!isValidMembershipTier(membershipTier)) throw new Error(`Invalid membership tier: ${membershipTier}`);
37	
38	    const allergyCheck = validateAllergyField(allergies);
39	    if (!allergyCheck.valid) throw new Error(`Allergies: ${allergyCheck.error}`);
40	
41	    const mrCheck = validateAllergyField(materialRestrictions);
42	    if (!mrCheck.valid) throw new Error(`Material restrictions: ${mrCheck.error}`);
43	
44	    const svCheck = validateStoredValue(storedValue);
45	    if (!svCheck.valid) throw new Error(svCheck.error);
46	
47	    const ptCheck = validatePoints(points);
48	    if (!ptCheck.valid) throw new Error(ptCheck.error);
49	
50	    if (!cryptoService.isUnlocked()) throw new Error('Session is locked. Please unlock to create customers with encrypted fields.');
51	
52	    const encAllergies = allergies ? await cryptoService.encrypt(allergies) : null;
53	    const encMR = materialRestrictions ? await cryptoService.encrypt(materialRestrictions) : null;
54	    const encSV = await cryptoService.encrypt(String(storedValue.toFixed(2)));
55	
56	    const customer = {
57	      id: generateId(),
58	      organizationId,
59	      name,
60	      membershipTier,
61	      points,
62	      storedValueCiphertext: encSV.ciphertext,
63	      storedValueIv: encSV.iv,
64	      allergiesCiphertext: encAllergies?.ciphertext ?? null,
65	      allergiesIv: encAllergies?.iv ?? null,
66	      materialRestrictionsCiphertext: encMR?.ciphertext ?? null,
67	      materialRestrictionsIv: encMR?.iv ?? null,
68	      ratingAverage: 0,
69	      ratingCount: 0,
70	      createdAt: Date.now(),
71	      updatedAt: Date.now(),
72	    };
73	
74	    await this._repo.create(customer);
75	    await auditService.log({ actorId, action: 'create_customer', entityType: 'customer', entityId: customer.id });
76	    return customer;
77	  }
78	
79	  /**
80	   * Updates non-sensitive customer fields.
81	   * Requires: ADMINISTRATOR or STORE_MANAGER role.
82	   *
83	   * @param {string} customerId
84	   * @param {{ name?: string; membershipTier?: string }} data
85	   * @param {string} actorId
86	   * @returns {Promise<object>}
87	   */
88	  async updateCustomer(customerId, data, actorId) {
89	    const actor = this._requireRole(ROLES.STORE_MANAGER);
90	
91	    const customer = await this._repo.findById(customerId);
92	    if (!customer) throw new Error('Customer not found.');
93	    await this._assertOrgScope(actor, customer.organizationId);
94	
95	    if (data.membershipTier && !isValidMembershipTier(data.membershipTier)) {
96	      throw new Error(`Invalid membership tier: ${data.membershipTier}`);
97	    }
98	
99	    const updated = { ...customer, ...data, updatedAt: Date.now() };
100	    await this._repo.update(customerId, updated);
101	    await auditService.log({ actorId, action: 'update_customer', entityType: 'customer', entityId: customerId });
102	    return updated;
103	  }
104	
105	  /**
106	   * Adjusts stored value by delta (positive = credit, negative = debit).
107	   * Blocks negative balance.
108	   * Requires: ADMINISTRATOR or STORE_MANAGER role.
109	   *
110	   * @param {string} customerId
111	   * @param {number} delta
112	   * @param {string} actorId
113	   * @returns {Promise<object>}
114	   */
115	  async adjustStoredValue(customerId, delta, actorId) {
116	    const actor = this._requireRole(ROLES.STORE_MANAGER);
117	
118	    if (!cryptoService.isUnlocked()) throw new Error('Session is locked. Cannot access encrypted stored value.');
119	
120	    const customer = await this._repo.findById(customerId);
121	    if (!customer) throw new Error('Customer not found.');
122	    await this._assertOrgScope(actor, customer.organizationId);
123	
124	    const currentStr = await cryptoService.decrypt(customer.storedValueCiphertext, customer.storedValueIv);
125	    const current = parseFloat(currentStr);
126	    const newValue = Math.round((current + delta) * 100) / 100;
127	
128	    const svCheck = validateStoredValue(newValue);
129	    if (!svCheck.valid) throw new Error(svCheck.error);
130	
131	    const encSV = await cryptoService.encrypt(String(newValue.toFixed(2)));
132	    const updated = { ...customer, storedValueCiphertext: encSV.ciphertext, storedValueIv: encSV.iv, updatedAt: Date.now() };
133	    await this._repo.update(customerId, updated);
134	    await auditService.log({ actorId, action: 'adjust_stored_value', entityType: 'customer', entityId: customerId, metadata: { delta } });
135	    return updated;
136	  }
137	
138	  /**
139	   * Adjusts points balance.
140	   * Requires: ADMINISTRATOR or STORE_MANAGER role.
141	   *
142	   * @param {string} customerId
143	   * @param {number} delta  Positive or negative integer.
144	   * @param {string} actorId
145	   * @returns {Promise<object>}
146	   */
147	  async adjustPoints(customerId, delta, actorId) {
148	    const actor = this._requireRole(ROLES.STORE_MANAGER);
149	
150	    const customer = await this._repo.findById(customerId);
151	    if (!customer) throw new Error('Customer not found.');
152	    await this._assertOrgScope(actor, customer.organizationId);
153	
154	    if (!Number.isInteger(delta)) throw new Error('Points delta must be an integer.');
155	
156	    const newPoints = customer.points + delta;
157	    const ptCheck = validatePoints(newPoints);
158	    if (!ptCheck.valid) throw new Error(ptCheck.error);
159	
160	    const updated = { ...customer, points: newPoints, updatedAt: Date.now() };
161	    await this._repo.update(customerId, updated);
162	    await auditService.log({ actorId, action: 'adjust_points', entityType: 'customer', entityId: customerId, metadata: { delta } });
163	    return updated;
164	  }
165	
166	  /**
167	   * Adds a service rating for the customer.
168	   * Updates running average and count.
169	   * Requires: ADMINISTRATOR or STORE_MANAGER role.
170	   *
171	   * @param {string} customerId
172	   * @param {number} rating  Integer 1–5.
173	   * @param {string} actorId
174	   * @returns {Promise<object>}
175	   */
176	  async addRating(customerId, rating, actorId) {
177	    const actor = this._requireRole(ROLES.STORE_MANAGER);
178	
179	    const ratingCheck = validateRating(rating);
180	    if (!ratingCheck.valid) throw new Error(ratingCheck.error);
181	
182	    const customer = await this._repo.findById(customerId);
183	    if (!customer) throw new Error('Customer not found.');
184	    await this._assertOrgScope(actor, customer.organizationId);
185	
186	    const newCount = customer.ratingCount + 1;
187	    const newAverage = (customer.ratingAverage * customer.ratingCount + rating) / newCount;
188	    const updated = { ...customer, ratingAverage: Math.round(newAverage * 10) / 10, ratingCount: newCount, updatedAt: Date.now() };
189	    await this._repo.update(customerId, updated);
190	    await auditService.log({ actorId, action: 'add_rating', entityType: 'customer', entityId: customerId, metadata: { rating } });
191	    return updated;
192	  }
193	
194	  /**
195	   * Decrypts and returns sensitive fields for display.
196	   * Requires an unlocked session.
197	   * Requires: ADMINISTRATOR, STORE_MANAGER, or ANALYST role.
198	   *
199	   * @param {string} customerId
200	   * @returns {Promise<{ storedValue: string; allergies: string | null; materialRestrictions: string | null }>}
201	   */
202	  async revealSensitiveFields(customerId) {
203	    const actor = this._requireRole(ROLES.ANALYST);
204	
205	    if (!cryptoService.isUnlocked()) throw new Error('Session is locked. Please unlock to access sensitive data.');
206	
207	    const customer = await this._repo.findById(customerId);
208	    if (!customer) throw new Error('Customer not found.');
209	    await this._assertOrgScope(actor, customer.organizationId);
210	
211	    const storedValue = await cryptoService.decrypt(customer.storedValueCiphertext, customer.storedValueIv);
212	    const allergies = customer.allergiesCiphertext
213	      ? await cryptoService.decrypt(customer.allergiesCiphertext, customer.allergiesIv)
214	      : null;
215	    const materialRestrictions = customer.materialRestrictionsCiphertext
216	      ? await cryptoService.decrypt(customer.materialRestrictionsCiphertext, customer.materialRestrictionsIv)
217	      : null;
218	
219	    return { storedValue, allergies, materialRestrictions };
220	  }
221	
222	  /**
223	   * Returns masked placeholders for sensitive fields.
224	   * Requires: any authenticated user.
225	   *
226	   * @param {string} customerId
227	   * @returns {Promise<{ storedValue: string; allergies: string; materialRestrictions: string }>}
228	   */
229	  async getMaskedFields(customerId) {
230	    const actor = this._requireAuth();
231	
232	    const customer = await this._repo.findById(customerId);
233	    if (!customer) throw new Error('Customer not found.');
234	    await this._assertOrgScope(actor, customer.organizationId);
235	
236	    return {
237	      storedValue: cryptoService.maskValue(''),
238	      allergies: customer.allergiesCiphertext ? cryptoService.maskValue('') : null,
239	      materialRestrictions: customer.materialRestrictionsCiphertext ? cryptoService.maskValue('') : null,
240	    };
241	  }
242	
243	  /**
244	   * Returns all customers for an organization.
245	   * Scope-enforced for non-admin users.
246	   *
247	   * @param {string} organizationId
248	   * @returns {Promise<object[]>}
249	   */
250	  async getByOrg(organizationId) {
251	    const actor = this._requireAuth();
252	    await this._assertOrgScope(actor, organizationId);
253	    return this._repo.findByOrg(organizationId);
254	  }
255	
256	  /**
257	   * Returns a single customer by ID.
258	   * @param {string} customerId
259	   * @returns {Promise<object | null>}
260	   */
261	  async getById(customerId) {
262	    const actor = this._requireAuth();
263	    const customer = await this._repo.findById(customerId);
264	    if (customer) await this._assertOrgScope(actor, customer.organizationId);
265	    return customer;
266	  }
267	
268	  // ── Version history ──────────────────────────────────────────────────────────
269	
270	  /**
271	   * Snapshots the current customer state as a new published version.
272	   * Deactivates any previous active version for this customer.
273	   * Requires: ADMINISTRATOR or STORE_MANAGER role.
274	   *
275	   * @param {{ customerId: string; organizationId: string; reasonNote: string; actorId: string }} params
276	   * @returns {Promise<object>}
277	   */
278	  async publishCustomerVersion({ customerId, organizationId, reasonNote, actorId }) {
279	    const actor = this._requireRole(ROLES.STORE_MANAGER);
280	    await this._assertOrgScope(actor, organizationId);
281	
282	    const noteCheck = validateReasonNote(reasonNote);
283	    if (!noteCheck.valid) throw new Error(noteCheck.error);
284	
285	    const customer = await this._repo.findById(customerId);
286	    if (!customer) throw new Error('Customer not found.');
287	
288	    const mdRepo = new MasterDataRepository();
289	    const history = await mdRepo.findVersionHistory(customerId);
290	    const nextVersion = history.length > 0 ? history[0].versionNumber + 1 : 1;
291	
292	    // Deactivate current active version for this customer.
293	    const currentActive = history.find((v) => v.isActive);
294	    if (currentActive) {
295	      await mdRepo.update(currentActive.id, { ...currentActive, isActive: false });
296	    }
297	
298	    const newVersion = {
299	      id: generateId(),
300	      organizationId,
301	      entityType: 'customer',
302	      entityId: customerId,
303	      versionNumber: nextVersion,
304	      payload: {
305	        name: customer.name,
306	        membershipTier: customer.membershipTier,
307	        points: customer.points,
308	      },
309	      reasonNote,
310	      isActive: true,
311	      createdBy: actorId,
312	      createdAt: Date.now(),
313	    };
314	
315	    await mdRepo.create(newVersion);
316	
317	    await auditService.log({
318	      actorId,
319	      action: 'publish_customer_version',
320	      entityType: 'customer',
321	      entityId: customerId,
322	      metadata: { versionNumber: nextVersion, organizationId },
323	    });
324	
325	    return newVersion;
326	  }
327	
328	  /**
329	   * Returns the full version history for a customer, newest first.
330	   * Requires: any authenticated user.
331	   *
332	   * @param {string} customerId
333	   * @returns {Promise<object[]>}
334	   */
335	  async getCustomerVersionHistory(customerId) {
336	    this._requireAuth();
337	    const mdRepo = new MasterDataRepository();
338	    return mdRepo.findVersionHistory(customerId);
339	  }
340	
341	  /**
342	   * Returns the currently active version snapshot for a customer, or null.
343	   * Requires: any authenticated user.
344	   *
345	   * @param {string} customerId
346	   * @returns {Promise<object | null>}
347	   */
348	  async getActiveCustomerVersion(customerId) {
349	    this._requireAuth();
350	    const mdRepo = new MasterDataRepository();
351	    const history = await mdRepo.findVersionHistory(customerId);
352	    return history.find((v) => v.isActive) ?? null;
353	  }
