355	  // ── Private helpers ──────────────────────────────────────────────────────────
356	
357	  /**
358	   * Requires authentication and at least one of the given roles.
359	   * ADMINISTRATOR always passes. Returns the current user.
360	   *
361	   * @param {...string} allowedRoles
362	   * @returns {object}
363	   */
364	  _requireRole(...allowedRoles) {
365	    const user = authService.getCurrentUser();
366	    if (!user) throw new Error('Authentication required.');
367	    if (user.role === ROLES.ADMINISTRATOR) return user;
368	    if (allowedRoles.length > 0 && !allowedRoles.includes(user.role)) {
369	      throw new Error(`Permission denied. Required role(s): ${allowedRoles.join(', ')}`);
370	    }
371	    return user;
372	  }
373	
374	  /** Requires authentication only. Returns the current user. */
375	  _requireAuth() {
376	    const user = authService.getCurrentUser();
377	    if (!user) throw new Error('Authentication required.');
378	    return user;
379	  }
380	
381	  /**
382	   * For non-admin actors: verifies the target org is within their accessible subtree.
383	   * @param {object} actor
384	   * @param {string} targetOrgId
385	   */
386	  async _assertOrgScope(actor, targetOrgId) {
387	    if (actor.role === ROLES.ADMINISTRATOR) return;
388	    if (!actor.organizationNodeId) throw new Error('Actor has no organization assigned.');
389	    const inScope = await orgService.isInScope(actor, targetOrgId);
390	    if (!inScope) throw new Error('Scope violation: you can only access data within your assigned organization.');
391	  }
