 * E2E Simulation — Ticket management lifecycle.
 *
 * Covers:
 *   - createTicket → open status with SLA
 *   - assignTicket → in_progress status, dispatches TICKET_ASSIGNED event
 *   - transitionTicket → resolved → closed
 *   - invalid transition rejected
 *   - closed ticket cannot be modified
 *   - evaluateOverdue marks overdue tickets and dispatches DEADLINE_APPROACHING
 *   - SLA timer: default 48h
 *   - role enforcement: reviewer cannot create/assign/transition
 */

import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import { IDBFactory } from 'fake-indexeddb';
import { initDB, closeDB } from '../../src/infrastructure/db/db.js';
import { authService } from '../../src/services/AuthService.js';
import { cryptoService } from '../../src/services/CryptoService.js';
import { ticketService } from '../../src/services/TicketService.js';
import { notificationService } from '../../src/services/NotificationService.js';
import { BootstrapService } from '../../src/services/BootstrapService.js';
import { setBroadcastService, closeAll } from '../../src/infrastructure/broadcast/broadcastManager.js';
import { MockBroadcastService } from '../../src/infrastructure/broadcast/MockBroadcastService.js';
import { MessageQueueRepository } from '../../src/repositories/implementations/NotificationRepository.js';
import { ROLES, TICKET_STATUSES, QUEUE_STATUSES } from '../../src/utils/constants.js';

const ADMIN_PASS = 'TicketFlow@123';
let orgId;
let adminUser;

beforeEach(async () => {
  setBroadcastService(new MockBroadcastService());
  await initDB(new IDBFactory());

  const bs = new BootstrapService();
  const { admin, org } = await bs.bootstrap({
    adminUsername: 'ticket_flow_admin',
