88	   * Deduplicates using an idempotency key derived from the source event.
89	   * Requires: any authenticated user.
90	   *
91	   * @param {{ organizationId: string; recipientUserId: string; templateId?: string | null; channelId: string | null; vars?: Record<string, string>; eventSourceKey: string; body?: string | null }} params
92	   * @returns {Promise<object>}
93	   */
94	  async enqueue({ organizationId, recipientUserId, templateId = null, channelId, vars = {}, eventSourceKey, body = null }) {
95	    this._requireAuth();
96	
97	    if (!eventSourceKey?.trim()) throw new Error('eventSourceKey is required for deduplication.');
98	    if (!templateId && !body) throw new Error('Either templateId or body is required.');
99	
100	    const idempotencyKey = generateIdempotencyKey(eventSourceKey);
101	
102	    // Deduplication: skip if an identical key already exists in non-failed state.
103	    const existing = await this._queueRepo.findAll();
104	    const duplicate = existing.find(
105	      (item) => item.idempotencyKey === idempotencyKey && item.status !== QUEUE_STATUSES.FAILED,
106	    );
107	    if (duplicate) return duplicate;
108	
109	    let renderedBody;
110	
111	    if (templateId) {
112	      // Template-based rendering with placeholder validation.
113	      try {
114	        renderedBody = await templateService.renderTemplate(templateId, vars);
115	      } catch (err) {
116	        // Only missing-placeholder errors produce a Draft (they may be resolved later).
117	        // Hard constraint violations (compact overflow, etc.) must propagate.
118	        if (!err.message.startsWith('Missing template variables')) throw err;
119	        // Template rendering failure creates a Draft item for manual review.
120	        const draftItem = {
121	          id: generateId(),
122	          organizationId,
123	          recipientUserId,
124	          templateId,
125	          channelId,
126	          payload: vars,
127	          renderedBody: null,
128	          status: QUEUE_STATUSES.DRAFT,
129	          retryCount: 0,
130	          nextRetryAt: null,
131	          failureReason: err.message,
132	          idempotencyKey,
133	          createdAt: Date.now(),
134	          updatedAt: Date.now(),
135	        };
136	        return this._queueRepo.create(draftItem);
137	      }
138	    } else {
139	      // Body passed directly — no template rendering needed.
140	      renderedBody = body;
141	    }
142	
143	    const item = {
144	      id: generateId(),
145	      organizationId,
146	      recipientUserId,
147	      templateId,
148	      channelId,
149	      payload: vars,
150	      renderedBody,
151	      status: QUEUE_STATUSES.QUEUED,
152	      retryCount: 0,
153	      nextRetryAt: Date.now(), // process immediately
154	      failureReason: null,
155	      idempotencyKey,
156	      createdAt: Date.now(),
157	      updatedAt: Date.now(),
158	    };
159	
160	    return this._queueRepo.create(item);
161	  }
162	
163	  // ── Direct in-app notification ────────────────────────────────────────────────
164	
165	  /**
166	   * Creates an in-app notification directly for a user — no template required.
167	   * Used by other services (OrderService, TicketService) to notify on state changes.

1	/**
2	 * EventDispatcherService
3	 *
4	 * Routes business events to notification recipients via the message queue.
5	 *
6	 * Delivery paths (both go through the queue):
7	 *   1. Subscription path — fetches subscribers for the event type (scoped by org) and enqueues
8	 *      a templated message (templateId) or a raw body message (title+body fallback).
9	 *   2. Direct path — explicit recipientUserIds get a queue item using body text; the queue
10	 *      processes and delivers it to their inbox. No notification bypasses the queue.
11	 *
12	 * All delivery failures are non-fatal and recorded in the audit log.
13	 */
14	
15	import { notificationService } from './NotificationService.js';
16	import { auditService } from './AuditService.js';
17	import { authService } from './AuthService.js';
18	import { generateId } from '../utils/idGenerator.js';
19	import { EVENT_TYPES } from '../utils/constants.js';
20	
21	export class EventDispatcherService {
22	  /**
23	   * Dispatches a business event.
24	   *
25	   * - Fetches subscriptions for eventType and enqueues a templated message for each subscriber.
26	   * - If recipientUserIds is provided, also notifies those users directly (fallback path for
27	   *   services that know their audience but subscribers may not exist yet).
28	   * - All delivery failures are caught and logged; they never propagate to callers.
29	   *
30	   * @param {{
31	   *   organizationId: string;
32	   *   eventType: string;
33	   *   sourceId: string;
34	   *   actorId: string;
35	   *   vars?: Record<string, string>;
36	   *   templateId?: string | null;
37	   *   recipientUserIds?: string[] | null;
38	   *   title?: string;
39	   *   body?: string;
40	   * }} params
41	   * @returns {Promise<void>}
42	   */
43	  async dispatch({
44	    organizationId,
45	    eventType,
46	    sourceId,
47	    actorId,
48	    vars = {},
49	    templateId = null,
50	    recipientUserIds = null,
51	    title,
52	    body,
53	  }) {
54	    const eventSourceKey = `${eventType}:${sourceId}:${actorId}:${Date.now()}`;
55	
56	    // ── Subscription-based delivery (queue path) ─────────────────────────────
57	    // Triggered when either a templateId is provided OR direct title+body are present.
58	    // Org-scoped: only subscribers within the same organization receive the event.
59	    const canDeliverToSubscribers = templateId || (title && body);
60	    if (canDeliverToSubscribers) {
61	      try {
62	        const subscriptions = await notificationService.getSubscriptionsByEventType(eventType, organizationId);
63	        for (const sub of subscriptions) {
64	          try {
65	            if (templateId) {
66	              await notificationService.enqueue({
67	                organizationId,
68	                recipientUserId: sub.userId,
69	                templateId,
70	                channelId: sub.channelId,
71	                vars,
72	                eventSourceKey: `${eventSourceKey}:sub:${sub.userId}`,
73	              });
74	            } else {
75	              // No template available — enqueue with pre-rendered body so subscribers
76	              // still receive the notification via the queue lifecycle.
77	              await notificationService.enqueue({
78	                organizationId,
79	                recipientUserId: sub.userId,
80	                channelId: sub.channelId,
81	                vars: {},
82	                body: `${title}\n${body}`,
83	                eventSourceKey: `${eventSourceKey}:sub:${sub.userId}`,
84	              });
85	            }
86	          } catch (err) {
87	            await auditService.log({
88	              actorId,
89	              action: 'dispatch_enqueue_failed',
90	              entityType: 'event',
91	              entityId: sourceId,
92	              metadata: { eventType, userId: sub.userId, error: err.message },
93	            }).catch(() => {});
94	          }
95	        }
96	      } catch (err) {
97	        await auditService.log({
98	          actorId,
99	          action: 'dispatch_subscription_lookup_failed',
100	          entityType: 'event',
101	          entityId: sourceId,
102	          metadata: { eventType, error: err.message },
103	        }).catch(() => {});
104	      }
105	    }
106	
107	    // ── Direct delivery (explicit recipients, queue path) ────────────────────
108	    // For services that know their target audience (e.g. "notify the assignee").
109	    // Uses queue-based delivery so the full retry/lifecycle still applies.
110	    if (recipientUserIds?.length && title && body) {
111	      for (const userId of recipientUserIds) {
112	        try {
113	          await notificationService.enqueue({
114	            organizationId,
115	            recipientUserId: userId,
116	            channelId: null,
117	            vars: {},
118	            body: `${title}\n${body}`,
119	            eventSourceKey: `${eventSourceKey}:direct:${userId}`,
120	          });
121	        } catch (err) {
122	          await auditService.log({
123	            actorId,
124	            action: 'dispatch_enqueue_direct_failed',
125	            entityType: 'event',
126	            entityId: sourceId,
127	            metadata: { eventType, userId, error: err.message },
128	          }).catch(() => {});
129	        }
130	      }
131	    }
132	  }
133	
134	  /**
135	   * Broadcasts an organization-wide announcement to all subscribers of ANNOUNCEMENT events.
136	   * Also delivers to explicit recipientUserIds if provided.
137	   *
138	   * @param {{ organizationId: string; title: string; body: string; actorId: string; recipientUserIds?: string[] }} params
139	   * @returns {Promise<void>}
140	   */
141	  async announce({ organizationId, title, body, actorId, recipientUserIds = [] }) {
142	    return this.dispatch({
143	      organizationId,
144	      eventType: EVENT_TYPES.ANNOUNCEMENT,
145	      sourceId: `announcement:${Date.now()}`,
146	      actorId,
