2	 * BootstrapService — first-run system initialization.
3	 *
4	 * Responsibilities:
5	 *   - detect whether the system has been initialized (any users exist)
6	 *   - create the first Administrator account and root organization node
7	 *   - record a bootstrap completion marker in appConfig
8	 *   - refuse re-initialization once any user exists
9	 *
10	 * IMPORTANT: This service is deliberately exempt from the standard RBAC
11	 * pattern because it executes before any user exists. It MUST NOT be
12	 * reachable once isBootstrapped() returns true.
13	 */
14	
15	import { UserRepository } from '../repositories/implementations/UserRepository.js';
16	import { OrgRepository } from '../repositories/implementations/OrgRepository.js';
17	import { AppConfigRepository } from '../repositories/implementations/AppConfigRepository.js';
18	import { cryptoService } from './CryptoService.js';
19	import { auditService } from './AuditService.js';
20	import { generateId } from '../utils/idGenerator.js';
21	import { validatePassword } from '../utils/validation.js';
22	import { ROLES, ORG_NODE_TYPES } from '../utils/constants.js';
23	
24	export class BootstrapService {
25	  constructor() {
26	    this._userRepo = new UserRepository();
27	    this._orgRepo = new OrgRepository();
28	    this._configRepo = new AppConfigRepository();
29	  }
30	
31	  /**
32	   * Returns true if at least one user account exists.
33	   * When false the system is in bootstrap mode.
34	   *
35	   * @returns {Promise<boolean>}
36	   */
37	  async isBootstrapped() {
38	    const count = await this._userRepo.count();
39	    return count > 0;
40	  }
41	
42	  /**
43	   * Performs the one-time first-run setup:
44	   *   1. Validates all inputs.
45	   *   2. Creates the root company organization node.
46	   *   3. Creates the first Administrator user with a properly derived key.
47	   *   4. Stores the bootstrap completion record in appConfig.
48	   *
49	   * Throws if the system is already bootstrapped.
50	   *
51	   * @param {{ adminUsername: string; adminPassword: string; orgName: string }} params
52	   * @returns {Promise<{ admin: object; org: object }>}
53	   */
54	  async bootstrap({ adminUsername, adminPassword, orgName }) {
55	    if (await this.isBootstrapped()) {
56	      throw new Error('System is already initialized. Bootstrap cannot be re-triggered.');
57	    }
58	
59	    // Validate inputs before any writes.
60	    if (!adminUsername?.trim()) throw new Error('Administrator username is required.');
61	    if (!orgName?.trim()) throw new Error('Organization name is required.');
62	
63	    const pwCheck = validatePassword(adminPassword);
64	    if (!pwCheck.valid) throw new Error(pwCheck.errors.join(' '));
65	
66	    // 1. Create root organization node.
67	    const orgId = generateId();
68	    const org = {
69	      id: orgId,
70	      name: orgName.trim(),
71	      type: ORG_NODE_TYPES.COMPANY,
72	      parentId: null,
73	      organizationId: orgId,
74	      createdAt: Date.now(),
75	    };
76	    await this._orgRepo.create(org);
77	
78	    // 2. Create first Administrator.
79	    const { hash, salt } = await cryptoService.hashNewPassword(adminPassword);
80	    const adminId = generateId();
81	    const adminUser = {
82	      id: adminId,
83	      username: adminUsername.trim(),
84	      passwordHash: hash,
85	      passwordSalt: salt,
86	      role: ROLES.ADMINISTRATOR,
87	      organizationNodeId: orgId,
88	      isActive: true,
89	      isGuest: false,
90	      guestExpiresAt: null,
91	      failedLoginAttempts: 0,
92	      lockoutUntil: null,
93	      unlockAttempts: 0,
94	      createdAt: Date.now(),
95	      updatedAt: Date.now(),
96	    };
97	    await this._userRepo.create(adminUser);
98	
99	    // 3. Mark bootstrap as completed.
100	    await this._configRepo.create({
101	      id: generateId(),
102	      organizationId: orgId,
103	      bootstrappedAt: Date.now(),
104	      bootstrappedBy: adminId,
105	    });
106	
107	    // 4. Audit trail (does not require auth).
108	    await auditService.log({
109	      actorId: adminId,
110	      action: 'system_bootstrap',
111	      entityType: 'system',
112	      entityId: 'bootstrap',
113	      metadata: { orgId, adminId },
114	    });
115	
116	    return { admin: adminUser, org };
117	  }
118	}
