 * EventDispatcherService
 *
 * Routes business events to notification recipients via the message queue.
 *
 * Delivery paths (both go through the queue):
 *   1. Subscription path — fetches subscribers for the event type (scoped by org) and enqueues
 *      a templated message (templateId) or a raw body message (title+body fallback).
 *   2. Direct path — explicit recipientUserIds get a queue item using body text; the queue
 *      processes and delivers it to their inbox. No notification bypasses the queue.
 *
 * All delivery failures are non-fatal and recorded in the audit log.
 */

import { notificationService } from './NotificationService.js';
import { auditService } from './AuditService.js';
import { authService } from './AuthService.js';
import { generateId } from '../utils/idGenerator.js';
import { EVENT_TYPES } from '../utils/constants.js';

export class EventDispatcherService {
  /**
   * Dispatches a business event.
   *
   * - Fetches subscriptions for eventType and enqueues a templated message for each subscriber.
   * - If recipientUserIds is provided, also notifies those users directly (fallback path for
   *   services that know their audience but subscribers may not exist yet).
   * - All delivery failures are caught and logged; they never propagate to callers.
   *
   * @param {{
   *   organizationId: string;
   *   eventType: string;
   *   sourceId: string;
   *   actorId: string;
   *   vars?: Record<string, string>;
   *   templateId?: string | null;
   *   recipientUserIds?: string[] | null;
   *   title?: string;
   *   body?: string;
   * }} params
   * @returns {Promise<void>}
   */
  async dispatch({
    organizationId,
    eventType,
    sourceId,
    actorId,
    vars = {},
    templateId = null,
    recipientUserIds = null,
    title,
    body,
  }) {
    const eventSourceKey = `${eventType}:${sourceId}:${actorId}:${Date.now()}`;

    // ── Subscription-based delivery (queue path) ─────────────────────────────
    // Triggered when either a templateId is provided OR direct title+body are present.
    // Org-scoped: only subscribers within the same organization receive the event.
    const canDeliverToSubscribers = templateId || (title && body);
    if (canDeliverToSubscribers) {
      try {
        const subscriptions = await notificationService.getSubscriptionsByEventType(eventType, organizationId);
        for (const sub of subscriptions) {
          try {
            if (templateId) {
              await notificationService.enqueue({
                organizationId,
                recipientUserId: sub.userId,
                templateId,
                channelId: sub.channelId,
                vars,
                eventSourceKey: `${eventSourceKey}:sub:${sub.userId}`,
              });
            } else {
              // No template available — enqueue with pre-rendered body so subscribers
              // still receive the notification via the queue lifecycle.
              await notificationService.enqueue({
                organizationId,
                recipientUserId: sub.userId,
                channelId: sub.channelId,
                vars: {},
                body: `${title}\n${body}`,
                eventSourceKey: `${eventSourceKey}:sub:${sub.userId}`,
              });
            }
          } catch (err) {
            await auditService.log({
              actorId,
              action: 'dispatch_enqueue_failed',
              entityType: 'event',
              entityId: sourceId,
              metadata: { eventType, userId: sub.userId, error: err.message },
            }).catch(() => {});
          }
        }
      } catch (err) {
        await auditService.log({
          actorId,
          action: 'dispatch_subscription_lookup_failed',
          entityType: 'event',
          entityId: sourceId,
          metadata: { eventType, error: err.message },
        }).catch(() => {});
      }
    }

    // ── Direct delivery (explicit recipients, queue path) ────────────────────
    // For services that know their target audience (e.g. "notify the assignee").
    // Uses queue-based delivery so the full retry/lifecycle still applies.
    if (recipientUserIds?.length && title && body) {
      for (const userId of recipientUserIds) {
        try {
          await notificationService.enqueue({
            organizationId,
            recipientUserId: userId,
            channelId: null,
            vars: {},
            body: `${title}\n${body}`,
            eventSourceKey: `${eventSourceKey}:direct:${userId}`,
          });
        } catch (err) {
          await auditService.log({
            actorId,
            action: 'dispatch_enqueue_direct_failed',
            entityType: 'event',
            entityId: sourceId,
            metadata: { eventType, userId, error: err.message },
          }).catch(() => {});
        }
      }
    }
  }

  /**
   * Broadcasts an organization-wide announcement to all subscribers of ANNOUNCEMENT events.
   * Also delivers to explicit recipientUserIds if provided.
   *
   * @param {{ organizationId: string; title: string; body: string; actorId: string; recipientUserIds?: string[] }} params
   * @returns {Promise<void>}
   */
  async announce({ organizationId, title, body, actorId, recipientUserIds = [] }) {
    return this.dispatch({
      organizationId,
      eventType: EVENT_TYPES.ANNOUNCEMENT,
      sourceId: `announcement:${Date.now()}`,
      actorId,
      vars: { title, body },
      recipientUserIds: recipientUserIds.length > 0 ? recipientUserIds : null,
      title,
      body,
    });
  }

  _requireAuth() {
    const user = authService.getCurrentUser();
    if (!user) throw new Error('Authentication required.');
    return user;
  }
}

