{"replace_all": false, "file_path": "/Users/tsiontesfaye/Projects/EaglePoint/retail-ops/repo/tests/API_tests/eventDispatcher.test.js", "old_string": "describe('NotificationService — subscription management', () => {
  it('getSubscriptionsByEventType returns matching subscriptions', async () => {
    const channel = await notificationService.upsertChannel({ organizationId: ORG_ID, name: 'Ch1' });
    await notificationService.subscribe({ userId: 'admin-001', channelId: channel.id, eventType: EVENT_TYPES.TICKET_ASSIGNED, organizationId: ORG_ID });
    await notificationService.subscribe({ userId: 'admin-001', channelId: channel.id, eventType: EVENT_TYPES.ORDER_STATUS_CHANGED, organizationId: ORG_ID });

    const subs = await notificationService.getSubscriptionsByEventType(EVENT_TYPES.TICKET_ASSIGNED);
    expect(subs.length).toBe(1);
    expect(subs[0].eventType).toBe(EVENT_TYPES.TICKET_ASSIGNED);
  });

  it('getSubscriptions returns all subscriptions for a user', async () => {
    const channel = await notificationService.upsertChannel({ organizationId: ORG_ID, name: 'Ch2' });
    await notificationService.subscribe({ userId: 'admin-001', channelId: channel.id, eventType: EVENT_TYPES.TICKET_ASSIGNED, organizationId: ORG_ID });
    await notificationService.subscribe({ userId: 'admin-001', channelId: channel.id, eventType: EVENT_TYPES.ORDER_STATUS_CHANGED, organizationId: ORG_ID });

    const subs = await notificationService.getSubscriptions('admin-001');
    expect(subs.length).toBe(2);
  });

  it('deleteSubscription removes subscription', async () => {
    const channel = await notificationService.upsertChannel({ organizationId: ORG_ID, name: 'Ch3' });
    const sub = await notificationService.subscribe({ userId: 'admin-001', channelId: channel.id, eventType: EVENT_TYPES.TICKET_ASSIGNED, organizationId: ORG_ID });

    await notificationService.deleteSubscription(sub.id, 'admin-001');

    const remaining = await notificationService.getSubscriptions('admin-001');
    expect(remaining.find((s) => s.id === sub.id)).toBeUndefined();
  });

  it('deleteSubscription throws for unknown subscription', async () => {
    await expect(
      notificationService.deleteSubscription('nonexistent-id', 'admin-001'),
    ).rejects.toThrow('not found');
  });

  it('non-admin cannot subscribe for another user', async () => {
    authService._currentUser = { id: 'staff-001', role: ROLES.STORE_MANAGER, organizationNodeId: ORG_ID };
    await expect(
      notificationService.subscribe({
        userId: 'other-user',   // different from actor
        channelId: null,
        eventType: EVENT_TYPES.TICKET_ASSIGNED,
        organizationId: ORG_ID,
      }),
    ).rejects.toThrow(/permission denied/i);
  });

  it('non-admin cannot view another user\'s subscriptions', async () => {
    authService._currentUser = { id: 'staff-001', role: ROLES.STORE_MANAGER, organizationNodeId: ORG_ID };
    await expect(
      notificationService.getSubscriptions('other-user'),
    ).rejects.toThrow(/permission denied/i);
  });
});", "new_string": "describe('NotificationService — subscription management', () => {
