10	   * Returns the single active version for an entity type in an org.
11	   * @param {string} entityType
12	   * @param {string} organizationId
13	   * @returns {Promise<object | null>}
14	   */
15	  async findActiveVersion(entityType, organizationId) {
16	    const all = await this.findAll();
17	    return (
18	      all.find(
19	        (v) => v.entityType === entityType && v.organizationId === organizationId && v.isActive,
20	      ) ?? null
21	    );
22	  }
