91	    const countMap = new Map();
92	    for (const { store, action } of rawDiff) {
93	      const key = `${store}::${action}`;
94	      countMap.set(key, { store, action, count: (countMap.get(key)?.count ?? 0) + 1 });
95	    }
96	    const diff = [...countMap.values()];
97	
98	    return { diff, snapshot, schemaVersion };
99	  }
