101	  /**
102	   * Applies a previously previewed import snapshot, replacing live store data.
103	   * Protected stores (sessions, auditLogs) are never replaced.
104	   * Requires: ADMINISTRATOR role.
105	   *
106	   * @param {{ snapshot: object; actorId: string }} params
107	   * @returns {Promise<void>}
