109	  async applyImport({ snapshot, schemaVersion, actorId }) {
110	    this._requireRole(ROLES.ADMINISTRATOR);
111	
112	    if (!snapshot || typeof snapshot !== 'object') throw new Error('Snapshot must be a non-null object.');
113	    if (typeof schemaVersion !== 'number') throw new Error('Schema version is required for import validation.');
114	    this.validateSchemaVersion(schemaVersion);
