153	    } catch {
154	      throw new Error('Failed to decrypt backup. Check that the passphrase is correct.');
155	    }
156	
157	    let envelope;
158	    try {
159	      envelope = JSON.parse(json);
160	    } catch {
161	      throw new Error('Decrypted backup content is not valid JSON.');
162	    }
163	
164	    if (!envelope.data || typeof envelope.schemaVersion !== 'number') {
165	      throw new Error('Invalid backup envelope: missing data or schemaVersion.');
166	    }
167	
168	    this.validateSchemaVersion(envelope.schemaVersion);
169	
170	    return { schemaVersion: envelope.schemaVersion, snapshot: envelope.data };
171	  }
