173	  _requireRole(...allowedRoles) {
174	    const user = authService.getCurrentUser();
175	    if (!user) throw new Error('Authentication required.');
176	    if (user.role === ROLES.ADMINISTRATOR) return user;
177	    if (allowedRoles.length > 0 && !allowedRoles.includes(user.role)) {
178	      throw new Error(`Permission denied. Required role(s): ${allowedRoles.join(', ')}`);
179	    }
180	    return user;
181	  }
