128	  async evaluateBiddingHeuristics({ organizationId, itemId, windowMs = 60 * 60_000, frequencyThreshold = 10 }) {
129	    const actor = this._requireRole(ROLES.STORE_MANAGER);
130	    await this._assertOrgScope(actor, organizationId);
131	
132	    if (!itemId?.trim()) throw new Error('itemId is required.');
133	
134	    const now = Date.now();
135	    const events = await this._bidRepo.findByItemInWindow(itemId, now - windowMs, now);
136	
137	    if (events.length >= frequencyThreshold) {
138	      return {
139	        flagged: true,
140	        reason: `Bid frequency ${events.length} exceeds threshold ${frequencyThreshold} within ${windowMs / 60_000} minutes.`,
141	        evidence: { eventCount: events.length, windowMs, frequencyThreshold },
142	      };
143	    }
144	
145	    // Check for fingerprint clustering (best-effort heuristic).
146	    const fingerprints = new Map();
147	    for (const e of events) {
148	      if (e.deviceFingerprint) {
149	        fingerprints.set(e.deviceFingerprint, (fingerprints.get(e.deviceFingerprint) ?? 0) + 1);
150	      }
151	    }
152	    for (const [fp, count] of fingerprints) {
153	      if (count >= Math.floor(frequencyThreshold * 0.5)) {
154	        return {
155	          flagged: true,
156	          reason: `Device fingerprint '${fp}' appears ${count} times — possible coordinated activity (best-effort signal).`,
157	          evidence: { fingerprint: fp, count, isBestEffort: true },
158	        };
159	      }
160	    }
161	
162	    // Check linked-account relationships among bidders on this item.
163	    const bidderIds = [...new Set(events.map((e) => e.userId).filter(Boolean))];
164	    if (bidderIds.length > 1) {
165	      const linksByBidder = await Promise.all(
166	        bidderIds.map((id) => this._linkedRepo.findAllLinksForUser(id)),
167	      );
168	      const allLinks = linksByBidder.flat();
169	      // Deduplicate: findAllLinksForUser queries both directions, so the same
170	      // link may appear twice when both its ends are in the bidder set.
171	      const uniqueLinks = [...new Map(allLinks.map((l) => [l.id, l])).values()];
172	      // Keep only links where both ends are active bidders on this item.
173	      const crossBidderLinks = uniqueLinks.filter(
174	        (link) => bidderIds.includes(link.primaryUserId) && bidderIds.includes(link.linkedUserId),
175	      );
176	      if (crossBidderLinks.length > 0) {
177	        const linkedUserIds = [...new Set(crossBidderLinks.flatMap((l) => [l.primaryUserId, l.linkedUserId]))];
178	        return {
179	          flagged: true,
180	          reason: `${crossBidderLinks.length} linked-account relationship(s) detected among ${linkedUserIds.length} bidder(s) on item '${itemId}'. Possible coordinated bidding.`,
181	          evidence: {
182	            linkedAccountCount: crossBidderLinks.length,
183	            linkedUserIds,
184	            evidenceTypes: [...new Set(crossBidderLinks.map((l) => l.evidenceType))],
185	            links: crossBidderLinks.map((l) => ({
186	              primaryUserId: l.primaryUserId,
187	              linkedUserId: l.linkedUserId,
188	              evidenceType: l.evidenceType,
189	              evidenceDetails: l.evidenceDetails,
190	            })),
191	          },
192	        };
193	      }
194	    }
195	
196	    return { flagged: false, reason: null, evidence: {} };
197	  }
