1	/**
2	 * LookupDataService — CRUD for master data reference tables.
3	 *
4	 * Manages the individual entity stores: colors, sizes, seasons, brands, suppliers.
5	 * These are the building blocks that styles reference.
6	 *
7	 * RBAC:
8	 *   - createEntry, deactivateEntry, reactivateEntry → ADMINISTRATOR or STORE_MANAGER
9	 *   - listEntries → any authenticated user
10	 */
11	
12	import { BaseRepository } from '../repositories/base/BaseRepository.js';
13	import { auditService } from './AuditService.js';
14	import { authService } from './AuthService.js';
15	import { generateId } from '../utils/idGenerator.js';
16	import { ROLES } from '../utils/constants.js';
17	import { orgService } from './OrgService.js';
18	
19	const SUPPORTED_STORES = ['colors', 'sizes', 'seasons', 'brands', 'suppliers'];
20	
21	const STYLE_FIELD_MAP = {
22	  colors: 'colorId',
23	  sizes: 'sizeId',
24	  seasons: 'seasonId',
25	  brands: 'brandId',
26	  suppliers: 'supplierId',
27	};
28	
29	export class LookupDataService {
30	  _repo(store) {
31	    if (!SUPPORTED_STORES.includes(store)) throw new Error(`Unknown lookup store: ${store}`);
32	    return new BaseRepository(store);
33	  }
34	
35	  /**
36	   * Creates a new lookup entry (color, size, season, brand, or supplier).
37	   * Requires: ADMINISTRATOR or STORE_MANAGER role.
38	   */
39	  async createEntry({ store, organizationId, name, actorId }) {
40	    const actor = this._requireRole(ROLES.STORE_MANAGER);
41	    if (!name?.trim()) throw new Error(`${store} name is required.`);
42	    await this._assertOrgScope(actor, organizationId);
43	
44	    const record = {
45	      id: generateId(),
46	      organizationId,
47	      name: name.trim(),
48	      isActive: true,
49	      createdAt: Date.now(),
50	      updatedAt: Date.now(),
51	    };
52	
53	    const saved = await this._repo(store).create(record);
54	    await auditService.log({ actorId, action: 'create_lookup_entry', entityType: store, entityId: record.id, metadata: { name } });
55	    return saved;
56	  }
57	
58	  /**
59	   * Lists all lookup entries for an organization.
60	   * Requires: any authenticated user.
61	   */
62	  async listEntries(store, organizationId) {
63	    const actor = this._requireAuth();
64	    await this._assertOrgScope(actor, organizationId);
65	    const all = await this._repo(store).findByIndex('by_orgId', organizationId);
66	    return all.sort((a, b) => a.name.localeCompare(b.name));
67	  }
68	
69	  /**
70	   * Deactivates a lookup entry if no active styles reference it.
71	   * Requires: ADMINISTRATOR or STORE_MANAGER role.
72	   */
73	  async deactivateEntry({ store, entryId, actorId }) {
74	    const actor = this._requireRole(ROLES.STORE_MANAGER);
75	    const record = await this._repo(store).findById(entryId);
76	    if (!record) throw new Error(`${store} entry '${entryId}' not found.`);
77	    await this._assertOrgScope(actor, record.organizationId);
78	
79	    // Check for active style references.
80	    const styleRepo = new BaseRepository('styles');
81	    const allStyles = await styleRepo.findByIndex('by_orgId', record.organizationId);
82	    const fieldName = STYLE_FIELD_MAP[store];
83	    const activeRefs = allStyles.filter((s) => s.isActive && s[fieldName] === entryId);
84	    if (activeRefs.length > 0) {
85	      throw new Error(`Cannot deactivate — ${activeRefs.length} active style(s) reference this entry.`);
86	    }
87	
88	    const updated = { ...record, isActive: false, updatedAt: Date.now() };
89	    await this._repo(store).update(entryId, updated);
90	    await auditService.log({ actorId, action: 'deactivate_lookup_entry', entityType: store, entityId: entryId });
91	  }
92	
93	  /**
94	   * Reactivates a lookup entry.
95	   * Requires: ADMINISTRATOR or STORE_MANAGER role.
96	   */
97	  async reactivateEntry({ store, entryId, actorId }) {
98	    const actor = this._requireRole(ROLES.STORE_MANAGER);
99	    const record = await this._repo(store).findById(entryId);
100	    if (!record) throw new Error(`${store} entry '${entryId}' not found.`);
101	    await this._assertOrgScope(actor, record.organizationId);
102	
103	    const updated = { ...record, isActive: true, updatedAt: Date.now() };
104	    await this._repo(store).update(entryId, updated);
105	    await auditService.log({ actorId, action: 'reactivate_lookup_entry', entityType: store, entityId: entryId });
106	  }
107	
108	  // ── Private ──────────────────────────────────────────────────────────────────
109	
110	  _requireRole(...allowedRoles) {
111	    const user = authService.getCurrentUser();
112	    if (!user) throw new Error('Authentication required.');
113	    if (user.role === ROLES.ADMINISTRATOR) return user;
114	    if (allowedRoles.length > 0 && !allowedRoles.includes(user.role)) {
115	      throw new Error(`Permission denied. Required role(s): ${allowedRoles.join(', ')}`);
116	    }
117	    return user;
118	  }
119	
120	  _requireAuth() {
121	    const user = authService.getCurrentUser();
122	    if (!user) throw new Error('Authentication required.');
123	    return user;
124	  }
125	
126	  async _assertOrgScope(actor, targetOrgId) {
127	    if (actor.role === ROLES.ADMINISTRATOR) return;
128	    if (!actor.organizationNodeId) throw new Error('Actor has no organization assigned.');
129	    const inScope = await orgService.isInScope(actor, targetOrgId);
130	    if (!inScope) throw new Error('Scope violation: you can only access data within your assigned organization.');
131	  }
132	}
133	
134	export const lookupDataService = new LookupDataService();
135

1	import { MasterDataRepository } from '../repositories/implementations/MasterDataRepository.js';
2	import { auditService } from './AuditService.js';
3	import { authService } from './AuthService.js';
4	import { eventDispatcherService } from './EventDispatcherService.js';
5	import { generateId } from '../utils/idGenerator.js';
6	import { validateReasonNote } from '../utils/validation.js';
7	import { ROLES, MASTER_DATA_ENTITY_TYPES, EVENT_TYPES } from '../utils/constants.js';
8	import { orgService } from './OrgService.js';
9	
10	/**
11	 * MasterDataService — versioned master data lifecycle management.
12	 *
13	 * One active version per (entityType, organizationId) at a time.
14	 * Publish operations use optimistic concurrency: if the active version
15	 * changed since the editor loaded, the publish is rejected.
16	 *
17	 * RBAC:
18	 *   - publishVersion → ADMINISTRATOR or STORE_MANAGER
19	 *   - all reads       → any authenticated user
20	 */
21	export class MasterDataService {
22	  constructor() {
23	    this._repo = new MasterDataRepository();
24	  }
25	
26	  /**
27	   * Creates and immediately publishes a new version of a master data entity.
28	   * Atomically deactivates the previous active version.
29	   * Requires: ADMINISTRATOR or STORE_MANAGER role.
30	   *
31	   * @param {{ entityType: string; entityId: string; organizationId: string; payload: object; reasonNote: string; createdBy: string; expectedActiveVersionId: string | null }} params
32	   * @returns {Promise<object>}
33	   */
34	  async publishVersion({ entityType, entityId, organizationId, payload, reasonNote, createdBy, expectedActiveVersionId }) {
35	    const actor = this._requireRole(ROLES.STORE_MANAGER);
36	    await this._assertOrgScope(actor, organizationId);
37	    this._assertValidEntityType(entityType);
38	
39	    const noteCheck = validateReasonNote(reasonNote);
40	    if (!noteCheck.valid) throw new Error(noteCheck.error);
41	
42	    if (!payload || typeof payload !== 'object') throw new Error('Payload must be a non-null object.');
43	
44	    const history = await this._repo.findVersionHistory(entityId);
45	    const nextVersion = history.length > 0 ? history[0].versionNumber + 1 : 1;
46	
47	    const newVersion = {
48	      id: generateId(),
49	      organizationId,
50	      entityType,
51	      entityId,
52	      versionNumber: nextVersion,
53	      payload,
54	      reasonNote,
55	      isActive: true,
56	      createdBy,
57	      createdAt: Date.now(),
58	    };
59	
60	    // The concurrency check (expectedActiveVersionId vs current active) happens
61	    // atomically inside the transaction in the repository layer.
62	    await this._repo.atomicVersionSwitch(expectedActiveVersionId, newVersion);
63	
64	    await auditService.log({
65	      actorId: createdBy,
66	      action: 'publish_version',
67	      entityType,
68	      entityId,
69	      metadata: { versionNumber: nextVersion, previousActiveId: expectedActiveVersionId ?? null, organizationId },
70	    });
71	
72	    // Dispatch publish event (non-fatal).
73	    await eventDispatcherService.dispatch({
74	      organizationId,
75	      eventType: EVENT_TYPES.MASTER_DATA_PUBLISHED,
76	      sourceId: newVersion.id,
77	      actorId: createdBy,
78	      vars: { entityType, entityId, versionNumber: String(nextVersion) },
79	      title: `Master data published: ${entityType}`,
80	      body: `Version ${nextVersion} of ${entityType} has been published.`,
81	    }).catch(() => {});
82	
83	    return newVersion;
84	  }
85	
86	  /**
87	   * Returns the currently active version for an entity type in an org.
88	   * Requires: any authenticated user.
89	   *
90	   * @param {string} entityType
91	   * @param {string} organizationId
92	   * @returns {Promise<object | null>}
93	   */
94	  async getActiveVersion(entityType, organizationId) {
95	    const actor = this._requireAuth();
96	    await this._assertOrgScope(actor, organizationId);
97	    this._assertValidEntityType(entityType);
98	    return this._repo.findActiveVersion(entityType, organizationId);
99	  }
100	
101	  /**
102	   * Returns all historical versions for an entity, newest first.
103	   * Results are filtered to the actor's org scope — cross-org versions are excluded.
104	   * Requires: any authenticated user.
105	   *
106	   * @param {string} entityId
107	   * @param {string} [organizationId]  When provided, only versions from this org are returned.
108	   * @returns {Promise<object[]>}
109	   */
110	  async getVersionHistory(entityId, organizationId) {
111	    const actor = this._requireAuth();
112	    const versions = await this._repo.findVersionHistory(entityId);
113	    if (actor.role === ROLES.ADMINISTRATOR && !organizationId) return versions;
114	    // Filter versions to the actor's org scope.
