_scheduleTask(name, fn, intervalMs) {
  schedule(`scheduler:task:${name}`, async () => {
    if (!this._isLeader) return;
    try {
      await fn();
    } catch (err) {
      console.error(`[SchedulerService] Task "${name}" error:`, err);
    }
    this._scheduleTask(name, fn, intervalMs);
  }, intervalMs);
}
