1	/**
2	 * LookupDataService — CRUD for master data reference tables.
3	 *
4	 * Manages the individual entity stores: colors, sizes, seasons, brands, suppliers.
5	 * These are the building blocks that styles reference.
6	 *
7	 * RBAC:
8	 *   - createEntry, deactivateEntry, reactivateEntry → ADMINISTRATOR or STORE_MANAGER
9	 *   - listEntries → any authenticated user
10	 */
11	
12	import { BaseRepository } from '../repositories/base/BaseRepository.js';
13	import { MasterDataRepository } from '../repositories/implementations/MasterDataRepository.js';
14	import { auditService } from './AuditService.js';
15	import { authService } from './AuthService.js';
16	import { generateId } from '../utils/idGenerator.js';
17	import { validateReasonNote } from '../utils/validation.js';
18	import { ROLES } from '../utils/constants.js';
19	import { orgService } from './OrgService.js';
20	
21	const SUPPORTED_STORES = ['colors', 'sizes', 'seasons', 'brands', 'suppliers'];
22	
23	const STYLE_FIELD_MAP = {
24	  colors: 'colorId',
25	  sizes: 'sizeId',
26	  seasons: 'seasonId',
27	  brands: 'brandId',
28	  suppliers: 'supplierId',
29	};
30	
31	export class LookupDataService {
32	  _repo(store) {
33	    if (!SUPPORTED_STORES.includes(store)) throw new Error(`Unknown lookup store: ${store}`);
34	    return new BaseRepository(store);
35	  }
36	
37	  /**
38	   * Creates a new lookup entry (color, size, season, brand, or supplier).
39	   * A version record is created alongside the entity for audit traceability.
40	   * Requires: ADMINISTRATOR or STORE_MANAGER role.
41	   *
42	   * @param {{ store: string; organizationId: string; name: string; actorId: string; reasonNote?: string }} params
43	   */
44	  async createEntry({ store, organizationId, name, actorId, reasonNote = '' }) {
45	    const actor = this._requireRole(ROLES.STORE_MANAGER);
46	    if (!name?.trim()) throw new Error(`${store} name is required.`);
47	    await this._assertOrgScope(actor, organizationId);
48	
49	    // Reason note required for all mutations.
50	    const noteCheck = validateReasonNote(reasonNote);
51	    if (!noteCheck.valid) throw new Error(noteCheck.error);
52	
53	    const record = {
54	      id: generateId(),
55	      organizationId,
56	      name: name.trim(),
57	      isActive: true,
58	      createdAt: Date.now(),
59	      updatedAt: Date.now(),
60	    };
61	
62	    const saved = await this._repo(store).create(record);
63	
64	    // Create a version record — single-active invariant enforced.
65	    await this._createVersion({
66	      organizationId, entityType: store, entityId: record.id,
67	      payload: { name: record.name, isActive: true }, reasonNote, actorId,
68	    });
69	
70	    await auditService.log({ actorId, action: 'create_lookup_entry', entityType: store, entityId: record.id, metadata: { name, reasonNote } });
71	    return saved;
72	  }
73	
74	  /**
75	   * Lists all lookup entries for an organization.
76	   * Requires: any authenticated user.
77	   */
78	  async listEntries(store, organizationId) {
79	    const actor = this._requireAuth();
80	    await this._assertOrgScope(actor, organizationId);
81	    const all = await this._repo(store).findByIndex('by_orgId', organizationId);
82	    return all.sort((a, b) => a.name.localeCompare(b.name));
83	  }
84	
85	  /**
86	   * Deactivates a lookup entry if no active styles reference it.
87	   * Creates a version record for the state change.
88	   * Requires: ADMINISTRATOR or STORE_MANAGER role.
89	   *
90	   * @param {{ store: string; entryId: string; actorId: string; reasonNote?: string }} params
91	   */
92	  async deactivateEntry({ store, entryId, actorId, reasonNote = '' }) {
93	    const actor = this._requireRole(ROLES.STORE_MANAGER);
94	    const record = await this._repo(store).findById(entryId);
95	    if (!record) throw new Error(`${store} entry '${entryId}' not found.`);
96	    await this._assertOrgScope(actor, record.organizationId);
97	
98	    const noteCheck = validateReasonNote(reasonNote);
99	    if (!noteCheck.valid) throw new Error(noteCheck.error);
100	
101	    // Check for active style references.
102	    const styleRepo = new BaseRepository('styles');
103	    const allStyles = await styleRepo.findByIndex('by_orgId', record.organizationId);
104	    const fieldName = STYLE_FIELD_MAP[store];
105	    const activeRefs = allStyles.filter((s) => s.isActive && s[fieldName] === entryId);
106	    if (activeRefs.length > 0) {
107	      throw new Error(`Cannot deactivate — ${activeRefs.length} active style(s) reference this entry.`);
108	    }
109	
110	    const updated = { ...record, isActive: false, updatedAt: Date.now() };
111	    await this._repo(store).update(entryId, updated);
112	
113	    await this._createVersion({
114	      organizationId: record.organizationId, entityType: store, entityId: entryId,
115	      payload: { name: record.name, isActive: false }, reasonNote, actorId,
116	    });
117	
118	    await auditService.log({ actorId, action: 'deactivate_lookup_entry', entityType: store, entityId: entryId, metadata: { reasonNote } });
119	  }
120	
121	  /**
122	   * Reactivates a lookup entry.
123	   * Creates a version record for the state change.
124	   * Requires: ADMINISTRATOR or STORE_MANAGER role.
125	   *
126	   * @param {{ store: string; entryId: string; actorId: string; reasonNote?: string }} params
127	   */
128	  async reactivateEntry({ store, entryId, actorId, reasonNote = '' }) {
129	    const actor = this._requireRole(ROLES.STORE_MANAGER);
130	    const record = await this._repo(store).findById(entryId);
131	    if (!record) throw new Error(`${store} entry '${entryId}' not found.`);
132	    await this._assertOrgScope(actor, record.organizationId);
133	
134	    const noteCheck = validateReasonNote(reasonNote);
135	    if (!noteCheck.valid) throw new Error(noteCheck.error);
136	
137	    const updated = { ...record, isActive: true, updatedAt: Date.now() };
138	    await this._repo(store).update(entryId, updated);
139	
140	    await this._createVersion({
141	      organizationId: record.organizationId, entityType: store, entityId: entryId,
142	      payload: { name: record.name, isActive: true }, reasonNote, actorId,
143	    });
144	
145	    await auditService.log({ actorId, action: 'reactivate_lookup_entry', entityType: store, entityId: entryId, metadata: { reasonNote } });
146	  }
147	
148	  // ── Private ──────────────────────────────────────────────────────────────────
149	
150	  /**
151	   * Creates a version record, enforcing the single-active-version invariant:
152	   * deactivates all prior active versions for this entity before creating the new one.
153	   */
154	  async _createVersion({ organizationId, entityType, entityId, payload, reasonNote, actorId }) {
155	    const mdRepo = new MasterDataRepository();
