      id: generateId(), organizationId: orgId, entityType: 'size', entityId: sizeId,
      versionNumber: 1, payload: { name: 'S' }, reasonNote: 'v1', isActive: true,
      createdBy: adminUser.id, createdAt: Date.now(),
    });
    await mdRepo.create({
