1	/**
2	 * accessControl.js — pure RBAC access-control helper.
3	 *
4	 * Extracted from Router.svelte so the routing logic can be unit-tested
5	 * without a running Svelte component tree or browser environment.
6	 *
7	 * All parameters are plain values; no Svelte stores or DOM access.
8	 */
9	
10	import { ROLE_ROUTES, PUBLIC_ROUTES } from './routes.js';
11	
12	/**
13	 * Determines whether a session may access a path and, if not, where to redirect.
14	 *
15	 * @param {string}       path           Hash path being requested (e.g. '/crm')
16	 * @param {boolean}      authenticated  True when a non-guest user is logged in
17	 * @param {boolean}      guest          True when a guest session is active
18	 * @param {string|null}  role           Current user's role, or null for guests
19	 * @returns {{ allowed: boolean; redirectTo: string | null }}
20	 */
21	export function resolveAccess(path, authenticated, guest, role) {
22	  // Unauthenticated, non-guest → any protected route redirects to login.
23	  if (!authenticated && !guest && !PUBLIC_ROUTES.has(path)) {
24	    return { allowed: false, redirectTo: '/login' };
25	  }
26	
27	  // Compute effective role (authenticated users use their role; guests use 'guest').
28	  const effectiveRole = role ?? (guest ? 'guest' : null);
29	
30	  if (effectiveRole && !PUBLIC_ROUTES.has(path)) {
31	    const allowed = ROLE_ROUTES[effectiveRole] ?? new Set();
32	    if (!allowed.has(path)) {
33	      // Redirect to the first accessible route for this role, or login.
34	      const defaultForRole = [...allowed][0] ?? '/login';
35	      return { allowed: false, redirectTo: defaultForRole };
36	    }
37	  }
38	
39	  return { allowed: true, redirectTo: null };
40	}
41	
42	/**
43	 * Returns true if `path` is accessible by any session with the given
44	 * authenticated / guest / role combination.
45	 *
46	 * Convenience wrapper used by nav-rendering code.
47	 *
48	 * @param {string}      path
49	 * @param {string|null} role
50	 * @param {boolean}     guest
51	 * @returns {boolean}
52	 */
53	export function canAccess(path, role, guest = false) {
54	  const authenticated = !guest && role !== null;
55	  const { allowed } = resolveAccess(path, authenticated, guest, role);
56	  return allowed;
57	}
