2	 * Simple device fingerprint generator.
3	 * Combines user agent, screen dimensions, and a user-specific seed
4	 * to produce a deterministic hash string for bid event correlation.
5	 *
6	 * NOT cryptographically secure — sufficient for heuristic grouping.
7	 *
8	 * @param {string} userId
9	 * @returns {string}
10	 */
11	export function generateFingerprint(userId) {
12	  const ua = typeof navigator !== 'undefined' ? navigator.userAgent : 'node';
13	  const sw = typeof screen !== 'undefined' ? screen.width : 0;
14	  const sh = typeof screen !== 'undefined' ? screen.height : 0;
15	  const raw = `${ua}|${sw}x${sh}|${userId}`;
16	
17	  // Simple DJB2 hash — deterministic, fast, no dependencies.
18	  let hash = 5381;
19	  for (let i = 0; i < raw.length; i++) {
20	    hash = ((hash << 5) + hash + raw.charCodeAt(i)) >>> 0;
21	  }
22	  return `fp_${hash.toString(16)}`;
