1	/**
2	 * CryptoService — application-level encryption facade.
3	 *
4	 * Wraps the low-level webCrypto module to provide domain-oriented methods.
5	 * Holds the in-session derived CryptoKey; cleared on lock/logout.
6	 */
7	
8	import {
9	  hashPassword,
10	  verifyPassword,
11	  deriveKey,
12	  encryptField,
13	  decryptField,
14	  generateSalt,
15	  generateIv,
16	  toHex,
17	  fromHex,
18	} from '../infrastructure/crypto/webCrypto.js';
19	
20	export class CryptoService {
21	  constructor() {
22	    /** @type {CryptoKey | null} Active session data key. */
23	    this._sessionKey = null;
24	  }
25	
26	  // ── Password ────────────────────────────────────────────────────────────────
27	
28	  /**
29	   * Hashes a new password with a fresh random salt.
30	   * @param {string} password
31	   * @returns {Promise<{ hash: string; salt: string }>}  Both hex-encoded.
32	   */
33	  async hashNewPassword(password) {
34	    const salt = generateSalt();
35	    const hash = await hashPassword(password, salt);
36	    return { hash, salt: toHex(salt) };
37	  }
38	
39	  /**
40	   * Verifies a password against stored hex hash + salt.
41	   * @param {string} password
42	   * @param {string} saltHex
43	   * @param {string} hashHex
44	   * @returns {Promise<boolean>}
45	   */
46	  async verifyPassword(password, saltHex, hashHex) {
47	    return verifyPassword(password, saltHex, hashHex);
48	  }
49	
50	  // ── Session key ─────────────────────────────────────────────────────────────
51	
52	  /**
53	   * Derives and caches the session data key from the user's password and salt.
54	   * Must be called after successful login.
55	   *
56	   * @param {string} password
57	   * @param {string} saltHex
58	   * @returns {Promise<void>}
59	   */
60	  async deriveSessionKey(password, saltHex) {
61	    const salt = fromHex(saltHex);
62	    this._sessionKey = await deriveKey(password, salt);
63	  }
64	
65	  /**
66	   * Sets the session key directly from an imported/shared CryptoKey.
67	   * Used for org-level shared encryption where all authorized users
68	   * in the same org share the same data encryption key.
69	   *
70	   * @param {CryptoKey} key
71	   */
72	  setSessionKey(key) {
73	    this._sessionKey = key;
74	  }
75	
76	  /**
77	   * Derives and returns a key without caching it. Useful for key-wrapping.
78	   * @param {string} password
79	   * @param {string} saltHex
80	   * @returns {Promise<CryptoKey>}
81	   */
82	  async deriveKeyRaw(password, saltHex) {
83	    const salt = fromHex(saltHex);
84	    return deriveKey(password, salt);
85	  }
86	
87	  /**
88	   * Clears the in-memory session key.
89	   * Called on lock or logout.
90	   */
91	  clearSessionKey() {
92	    this._sessionKey = null;
