111	  // ── Field encryption ────────────────────────────────────────────────────────
112	
113	  /**
114	   * Encrypts a plaintext field value using the active session key.
115	   * @param {string} plaintext
116	   * @returns {Promise<{ ciphertext: string; iv: string; algorithmVersion: string }>}
117	   */
118	  async encrypt(plaintext) {
119	    if (!this._sessionKey) throw new Error('Session is locked. Cannot encrypt.');
120	    return encryptField(plaintext, this._sessionKey);
121	  }
122	
123	  /**
124	   * Decrypts a field using the active session key.
125	   * @param {string} ciphertextB64
126	   * @param {string} ivHex
127	   * @returns {Promise<string>}
128	   */
129	  async decrypt(ciphertextB64, ivHex) {
130	    if (!this._sessionKey) throw new Error('Session is locked. Cannot decrypt.');
131	    return decryptField(ciphertextB64, ivHex, this._sessionKey);
132	  }
