135	
136	  /**
137	   * Re-encrypts a collection of field envelopes from oldPassword to newPassword.
138	   * Used during password change.
139	   *
140	   * @param {Array<{ ciphertext: string; iv: string }>} envelopes
141	   * @param {string} oldPassword
142	   * @param {string} saltHex   The user's existing salt (unchanged on password change).
143	   * @param {string} newPassword
144	   * @returns {Promise<Array<{ ciphertext: string; iv: string; algorithmVersion: string }>>}
145	   */
146	  async rotateEncryptedFields(envelopes, oldPassword, saltHex, newPassword) {
147	    const salt = fromHex(saltHex);
148	    const oldKey = await deriveKey(oldPassword, salt);
149	    const newKey = await deriveKey(newPassword, salt);
150	
151	    const results = [];
152	    for (const { ciphertext, iv } of envelopes) {
153	      const plaintext = await decryptField(ciphertext, iv, oldKey);
154	      const reEncrypted = await encryptField(plaintext, newKey);
155	      results.push(reEncrypted);
