186	  /**
187	   * Encrypts the backup JSON string with the provided backup key.
188	   * @param {string} json
189	   * @param {CryptoKey} key
190	   * @returns {Promise<{ ciphertext: string; iv: string; algorithmVersion: string }>}
191	   */
192	  async encryptBackup(json, key) {
193	    return encryptField(json, key);
194	  }
195	
196	  /**
197	   * Decrypts a backup ciphertext with the provided backup key.
198	   * @param {string} ciphertextB64
199	   * @param {string} ivHex
200	   * @param {CryptoKey} key
201	   * @returns {Promise<string>}
202	   */
203	  async decryptBackup(ciphertextB64, ivHex, key) {
204	    return decryptField(ciphertextB64, ivHex, key);
205	  }
