208	
209	  /**
210	   * Returns a masked display string for a sensitive value.
211	   * @param {string} value
212	   * @returns {string}  e.g. "••••••••"
213	   */
214	  maskValue(value) {
215	    if (typeof value !== 'string' || value.length === 0) return '••••••••';
216	    return '•'.repeat(Math.min(value.length, 8));
