85	  async runBatch({ organizationId, modelVersion, actorId }) {
86	    const actor = this._requireRole(ROLES.ANALYST);
87	    await this._assertOrgScope(actor, organizationId);
88	
89	    if (!modelVersion?.trim()) throw new Error('Model version is required.');
90	
91	    const texts = await this._textRepo.findByOrg(organizationId);
92	    return this._executeRun({
