102	  /**
103	   * Runs incremental NLP analysis on texts created or updated since the last run.
104	   * Uses both createdAt AND updatedAt to find new or modified texts.
105	   * Requires: ADMINISTRATOR or ANALYST role.
106	   *
107	   * @param {{ organizationId: string; modelVersion: string; actorId: string }} params
