176	  // ── Topic clustering ─────────────────────────────────────────────────────────
177	
178	  /**
179	   * Clusters imported texts by their dominant topic using the latest run.
180	   * Returns a map of { topicName: [textId, ...] }.
181	   * If no runs exist, returns an empty object.
182	   * Requires: ADMINISTRATOR, ANALYST, or REVIEWER role.
183	   *
184	   * @param {string} organizationId
185	   * @returns {Promise<Record<string, string[]>>}
186	   */
187	  async clusterTopics(organizationId) {
188	    const actor = this._requireRole(ROLES.ANALYST, ROLES.REVIEWER);
189	    await this._assertOrgScope(actor, organizationId);
190	
191	    const runs = await this._runRepo.findByOrg(organizationId);
192	    if (runs.length === 0) return {};
193	
194	    const latestRun = runs.sort((a, b) => b.createdAt - a.createdAt)[0];
195	    const clusters = {};
196	
197	    for (const [textId, output] of Object.entries(latestRun.outputPayload)) {
198	      const topics = output.topics ?? [];
199	      const dominant = topics[0] ?? 'uncategorized';
200	      if (!clusters[dominant]) clusters[dominant] = [];
201	      clusters[dominant].push(textId);
202	    }
203	
204	    return clusters;
205	  }
