207	  // ── Entity disambiguation ─────────────────────────────────────────────────────
208	
209	  /**
210	   * Extracts and disambiguates named entities from text using context cues.
211	   * Returns entities with types: PERSON, ORG, LOCATION, PRODUCT, or PROPER_NOUN.
212	   *
213	   * @param {string} text
214	   * @returns {Array<{ text: string; type: string }>}
215	   */
216	  disambiguateEntities(text) {
217	    const rawEntities = this._extractEntities(text);
218	    const lower = text.toLowerCase();
219	
220	    const orgSuffixes = ['inc', 'corp', 'ltd', 'llc', 'co', 'group', 'enterprises', 'company', 'solutions', 'technologies'];
221	    const locationIndicators = ['street', 'avenue', 'blvd', 'road', 'city', 'town', 'county', 'district', 'park', 'plaza', 'located in', 'based in', 'store in'];
222	    const productIndicators = ['model', 'version', 'edition', 'series', 'collection', 'range', 'line', 'sku', 'product', 'item'];
223	
224	    return rawEntities.map((entity) => {
225	      const entityLower = entity.text.toLowerCase();
226	      const entityIdx = lower.indexOf(entityLower);
227	      const context = entityIdx !== -1
228	        ? lower.slice(Math.max(0, entityIdx - 30), entityIdx + entityLower.length + 30)
229	        : '';
230	
231	      if (orgSuffixes.some((s) => entityLower.endsWith(s) || context.includes(entityLower + ' ' + s))) {
232	        return { text: entity.text, type: 'ORG' };
233	      }
234	
235	      if (locationIndicators.some((indicator) => context.includes(indicator))) {
236	        return { text: entity.text, type: 'LOCATION' };
237	      }
238	
239	      if (productIndicators.some((indicator) => context.includes(indicator))) {
240	        return { text: entity.text, type: 'PRODUCT' };
241	      }
242	
243	      return { text: entity.text, type: 'PERSON' };
244	    });
245	  }
