379	  /**
380	   * Extracts top-N keywords via term frequency.
381	   * @param {string} text
382	   * @param {number} [topN=10]
383	   * @returns {string[]}
384	   */
385	  _extractKeywords(text, topN = 10) {
386	    const stopWords = new Set(['the', 'a', 'an', 'is', 'in', 'on', 'at', 'to', 'and', 'or', 'of', 'it', 'for', 'with', 'this', 'that', 'was', 'are', 'be', 'by', 'from', 'as', 'but', 'not', 'have', 'had', 'has', 'he', 'she', 'they', 'we', 'you', 'i']);
387	    const words = text.toLowerCase().match(/\b[a-z]{3,}\b/g) ?? [];
388	    const freq = new Map();
389	    for (const w of words) {
390	      if (!stopWords.has(w)) freq.set(w, (freq.get(w) ?? 0) + 1);
391	    }
392	    return [...freq.entries()]
393	      .sort((a, b) => b[1] - a[1])
394	      .slice(0, topN)
395	      .map(([w]) => w);
396	  }
397	
398	  /**
399	   * Extractive summarization: returns the top-scoring sentences by keyword density.
400	   * @param {string} text
401	   * @param {number} [numSentences=3]
402	   * @returns {string}
403	   */
404	  _extractSummary(text, numSentences = 3) {
405	    const sentences = text.match(/[^.!?]+[.!?]+/g) ?? [text];
406	    if (sentences.length <= numSentences) return text;
407	    const keywords = new Set(this._extractKeywords(text));
408	    const scored = sentences.map((s) => {
409	      const words = s.toLowerCase().match(/\b[a-z]+\b/g) ?? [];
410	      const score = words.filter((w) => keywords.has(w)).length;
411	      return { sentence: s, score };
412	    });
413	    return scored
414	      .sort((a, b) => b.score - a.score)
415	      .slice(0, numSentences)
416	      .map((s) => s.sentence.trim())
417	      .join(' ');
418	  }
