420	  /**
421	   * Topic classification via simple keyword-bag matching.
422	   * @param {string} text
423	   * @returns {string[]}
424	   */
425	  _classifyTopics(text) {
426	    const topics = {
427	      logistics: ['shipping', 'delivery', 'warehouse', 'stock', 'inventory', 'transport'],
428	      customer: ['complaint', 'refund', 'return', 'satisfaction', 'service', 'support'],
429	      finance: ['payment', 'invoice', 'price', 'discount', 'cost', 'billing'],
430	      product: ['quality', 'defect', 'style', 'size', 'color', 'brand'],
431	    };
432	    const lower = text.toLowerCase();
433	    return Object.entries(topics)
434	      .filter(([, keywords]) => keywords.some((k) => lower.includes(k)))
435	      .map(([topic]) => topic);
436	  }
437	
438	  /**
439	   * Sentiment analysis via lexicon scoring.
440	   * @param {string} text
441	   * @returns {{ label: 'positive'|'negative'|'neutral'; score: number }}
442	   */
443	  _analyzeSentiment(text) {
444	    const positive = new Set(['good', 'great', 'excellent', 'happy', 'satisfied', 'love', 'perfect', 'wonderful', 'amazing', 'outstanding', 'positive', 'best', 'helpful']);
445	    const negative = new Set(['bad', 'poor', 'terrible', 'unhappy', 'dissatisfied', 'hate', 'awful', 'horrible', 'broken', 'worst', 'negative', 'disappointing', 'failed']);
446	    const words = text.toLowerCase().match(/\b[a-z]+\b/g) ?? [];
447	    let score = 0;
