38	      if (!this.validateParentChildType(parent.type, type)) {
39	        throw new Error(`Invalid parent-child combination: ${parent.type} → ${type}`);
40	      }
41	      // Cross-link prevention: parent must belong to the same organization.
42	      if (parent.organizationId !== organizationId) {
43	        throw new Error('Cannot create a child node under a parent from a different organization.');
44	      }
45	    } else if (type !== ORG_NODE_TYPES.COMPANY) {
46	      throw new Error('Only company nodes may have no parent.');
47	    }
