44	   */
45	  async createTicket({ customerId, orderId, organizationId, storeId, subject, description, category, priority, actorId, slaHours = VALIDATION.DEFAULT_TICKET_SLA_HOURS }) {
46	    const actor = this._requireRole(ROLES.STORE_MANAGER);
47	    await this._assertOrgScope(actor, storeId);
48	
49	    // Validate store node exists and belongs to the organization.
50	    const storeNode = await this._orgRepo.findById(storeId);
51	    if (!storeNode) throw new Error(`Store '${storeId}' not found.`);
52	    if (storeNode.type !== ORG_NODE_TYPES.STORE && storeNode.type !== ORG_NODE_TYPES.COMPANY) {
53	      throw new Error(`Node '${storeId}' is of type '${storeNode.type}', expected 'store'.`);
54	    }
55	    if (storeNode.organizationId !== organizationId) {
56	      throw new Error('Store does not belong to the specified organization.');
57	    }
58	
59	    if (!subject?.trim()) throw new Error('Subject is required.');
60	    if (!description?.trim()) throw new Error('Description is required.');
61	    if (!category?.trim()) throw new Error('Category is required.');
62	    if (!isValidTicketPriority(priority)) throw new Error(`Invalid priority: '${priority}'. Valid: low, medium, high`);
63	
64	    // Validate customer exists and belongs to the same organization.
65	    if (customerId) {
66	      const customer = await this._customerRepo.findById(customerId);
67	      if (!customer) throw new Error(`Customer '${customerId}' not found.`);
68	      if (customer.organizationId !== organizationId) {
69	        throw new Error('Customer does not belong to this organization.');
70	      }
71	    }
72	
73	    const now = Date.now();
74	    const ticket = {
75	      id: generateId(),
76	      customerId,
77	      orderId: orderId ?? null,
78	      organizationId,
79	      storeId,
80	      subject,
81	      description,
82	      category,
83	      priority,
84	      status: TICKET_STATUSES.OPEN,
85	      slaDueAt: now + slaHours * 60 * 60 * 1000,
86	      isOverdue: false,
87	      assignedTo: null,
88	      createdAt: now,
89	      updatedAt: now,
90	      resolvedAt: null,
91	      closedBy: null,
92	    };
93	
94	    await this._ticketRepo.create(ticket);
95	    await this._appendEvent({ ticketId: ticket.id, type: TICKET_EVENT_TYPES.CREATED, actorId });
96	    await auditService.log({ actorId, action: 'create_ticket', entityType: 'ticket', entityId: ticket.id });
97	
98	    return ticket;
99	  }
