101	  /**
102	   * Assigns a ticket to an agent.
103	   * Requires: ADMINISTRATOR or STORE_MANAGER role.
104	   *
105	   * @param {string} ticketId
106	   * @param {string} assigneeId
107	   * @param {string} actorId
108	   * @returns {Promise<object>}
109	   */
110	  async assignTicket(ticketId, assigneeId, actorId) {
111	    const actor = this._requireRole(ROLES.STORE_MANAGER);
112	
113	    const ticket = await this._getOrThrow(ticketId);
114	    await this._assertOrgScope(actor, ticket.storeId);
115	    this._assertNotTerminal(ticket);
116	
117	    const updated = { ...ticket, assignedTo: assigneeId, status: TICKET_STATUSES.IN_PROGRESS, updatedAt: Date.now() };
118	    await this._ticketRepo.update(ticketId, updated);
119	    await this._appendEvent({ ticketId, type: TICKET_EVENT_TYPES.ASSIGNED, actorId, comment: `Assigned to ${assigneeId}` });
120	    await auditService.log({ actorId, action: 'assign_ticket', entityType: 'ticket', entityId: ticketId, metadata: { assigneeId } });
121	
122	    // Notify the assignee via EventDispatcher.
123	    await eventDispatcherService.dispatch({
124	      organizationId: ticket.organizationId,
125	      eventType: EVENT_TYPES.TICKET_ASSIGNED,
126	      sourceId: ticketId,
127	      actorId,
128	      vars: { ticketId, subject: ticket.subject, assigneeId },
129	      recipientUserIds: [assigneeId],
130	      title: 'Ticket assigned to you',
131	      body: `Ticket "${ticket.subject}" has been assigned to you.`,
132	    });
133	
134	    return updated;
135	  }
