137	  /**
138	   * Transitions a ticket to a new status.
139	   * Requires: ADMINISTRATOR or STORE_MANAGER role.
140	   *
141	   * @param {string} ticketId
142	   * @param {string} newStatus
143	   * @param {string} actorId
144	   * @param {string} [comment]
145	   * @returns {Promise<object>}
146	   */
147	  async transitionTicket(ticketId, newStatus, actorId, comment) {
148	    const actor = this._requireRole(ROLES.STORE_MANAGER);
149	
150	    const ticket = await this._getOrThrow(ticketId);
151	    await this._assertOrgScope(actor, ticket.storeId);
152	    this._assertNotTerminal(ticket);
153	
154	    const allowed = TRANSITIONS.get(ticket.status) ?? [];
155	    if (!allowed.includes(newStatus)) {
156	      throw new Error(`Invalid transition: ${ticket.status} → ${newStatus}. Allowed: ${allowed.join(', ')}`);
157	    }
158	
159	    const now = Date.now();
160	    const patch = { status: newStatus, updatedAt: now };
161	    if (newStatus === TICKET_STATUSES.RESOLVED) patch.resolvedAt = now;
162	    if (newStatus === TICKET_STATUSES.CLOSED) patch.closedBy = actorId;
163	
164	    const updated = { ...ticket, ...patch };
165	    await this._ticketRepo.update(ticketId, updated);
166	    await this._appendEvent({ ticketId, type: newStatus, actorId, comment });
167	    await auditService.log({ actorId, action: 'transition_ticket', entityType: 'ticket', entityId: ticketId, metadata: { from: ticket.status, to: newStatus } });
168	
169	    // Notify assignee of status change via EventDispatcher.
170	    if (ticket.assignedTo && ticket.assignedTo !== actorId) {
171	      await eventDispatcherService.dispatch({
172	        organizationId: ticket.organizationId,
173	        eventType: EVENT_TYPES.TICKET_STATUS_CHANGED,
174	        sourceId: ticketId,
175	        actorId,
176	        vars: { ticketId, subject: ticket.subject, newStatus },
177	        recipientUserIds: [ticket.assignedTo],
178	        title: `Ticket ${newStatus.replace('_', ' ')}`,
179	        body: `Ticket "${ticket.subject}" is now ${newStatus.replace('_', ' ')}.`,
180	      });
181	    }
182	
183	    return updated;
184	  }
