186	  /**
187	   * Evaluates all open/in-progress tickets against their SLA due times.
188	   * Marks overdue tickets and appends an overdue event.
189	   *
190	   * @returns {Promise<object[]>}  Tickets newly marked overdue.
191	   */
192	  async evaluateOverdue() {
193	    const nowMs = Date.now();
194	    const due = await this._ticketRepo.findDueForOverdueCheck(nowMs);
195	
196	    const results = [];
197	    for (const ticket of due) {
198	      const updated = { ...ticket, isOverdue: true, updatedAt: nowMs };
199	      await this._ticketRepo.update(ticket.id, updated);
200	      await this._appendEvent({ ticketId: ticket.id, type: TICKET_EVENT_TYPES.OVERDUE, actorId: 'system' });
201	
202	      // Dispatch SLA deadline notification to assignee (non-fatal).
203	      if (ticket.assignedTo) {
204	        await eventDispatcherService.dispatch({
205	          organizationId: ticket.organizationId,
206	          eventType: EVENT_TYPES.DEADLINE_APPROACHING,
207	          sourceId: ticket.id,
208	          actorId: 'system',
209	          vars: { ticketId: ticket.id, subject: ticket.subject, status: 'overdue' },
210	          recipientUserIds: [ticket.assignedTo],
211	          title: 'Ticket SLA overdue',
212	          body: `Ticket "${ticket.subject}" has exceeded its SLA deadline.`,
213	        });
214	      }
215	
216	      results.push(updated);
217	    }
218	    return results;
219	  }
