229	    const all = await this._ticketRepo.findOverdue();
230	    // Non-admin users only see overdue tickets within their org scope.
231	    if (actor.role === ROLES.ADMINISTRATOR) return all;
232	    const scoped = [];
233	    for (const t of all) {
