261	   */
262	  async getByCustomer(customerId, _organizationId) {
263	    const actor = this._requireRole(ROLES.STORE_MANAGER, ROLES.REVIEWER);
264	    // Derive org scope from actual ticket data — ignore caller-provided orgId.
265	    const tickets = await this._ticketRepo.findByCustomer(customerId);
