1	/**
2	 * BootstrapService — first-run system initialization.
3	 *
4	 * Responsibilities:
5	 *   - detect whether the system has been initialized (any users exist)
6	 *   - create the first Administrator account and root organization node
7	 *   - record a bootstrap completion marker in appConfig
8	 *   - refuse re-initialization once any user exists
9	 *
10	 * IMPORTANT: This service is deliberately exempt from the standard RBAC
11	 * pattern because it executes before any user exists. It MUST NOT be
12	 * reachable once isBootstrapped() returns true.
13	 */
14	
15	import { UserRepository } from '../repositories/implementations/UserRepository.js';
16	import { OrgRepository } from '../repositories/implementations/OrgRepository.js';
17	import { AppConfigRepository } from '../repositories/implementations/AppConfigRepository.js';
18	import { TemplateRepository } from '../repositories/implementations/TemplateRepository.js';
19	import { cryptoService } from './CryptoService.js';
20	import { auditService } from './AuditService.js';
21	import { generateId } from '../utils/idGenerator.js';
22	import { validatePassword, extractPlaceholders } from '../utils/validation.js';
23	import { ROLES, ORG_NODE_TYPES, SYSTEM_TEMPLATES } from '../utils/constants.js';
24	
25	export class BootstrapService {
26	  constructor() {
27	    this._userRepo = new UserRepository();
28	    this._orgRepo = new OrgRepository();
29	    this._configRepo = new AppConfigRepository();
30	    this._templateRepo = new TemplateRepository();
31	  }
32	
33	  /**
34	   * Returns true if at least one user account exists.
35	   * When false the system is in bootstrap mode.
36	   *
37	   * @returns {Promise<boolean>}
38	   */
39	  async isBootstrapped() {
40	    const count = await this._userRepo.count();
41	    return count > 0;
42	  }
43	
44	  /**
45	   * Performs the one-time first-run setup:
46	   *   1. Validates all inputs.
47	   *   2. Creates the root company organization node.
48	   *   3. Creates the first Administrator user with a properly derived key.
49	   *   4. Stores the bootstrap completion record in appConfig.
50	   *
51	   * Throws if the system is already bootstrapped.
52	   *
53	   * @param {{ adminUsername: string; adminPassword: string; orgName: string }} params
54	   * @returns {Promise<{ admin: object; org: object }>}
55	   */
56	  async bootstrap({ adminUsername, adminPassword, orgName }) {
57	    if (await this.isBootstrapped()) {
58	      throw new Error('System is already initialized. Bootstrap cannot be re-triggered.');
59	    }
60	
61	    // Validate inputs before any writes.
62	    if (!adminUsername?.trim()) throw new Error('Administrator username is required.');
63	    if (!orgName?.trim()) throw new Error('Organization name is required.');
64	
65	    const pwCheck = validatePassword(adminPassword);
66	    if (!pwCheck.valid) throw new Error(pwCheck.errors.join(' '));
67	
68	    // 1. Create root organization node.
69	    const orgId = generateId();
70	    const org = {
71	      id: orgId,
72	      name: orgName.trim(),
73	      type: ORG_NODE_TYPES.COMPANY,
74	      parentId: null,
75	      organizationId: orgId,
76	      createdAt: Date.now(),
77	    };
78	    await this._orgRepo.create(org);
79	
80	    // 2. Create first Administrator.
81	    const { hash, salt } = await cryptoService.hashNewPassword(adminPassword);
82	    const adminId = generateId();
83	    const adminUser = {
84	      id: adminId,
85	      username: adminUsername.trim(),
86	      passwordHash: hash,
87	      passwordSalt: salt,
88	      role: ROLES.ADMINISTRATOR,
89	      organizationNodeId: orgId,
90	      isActive: true,
91	      isGuest: false,
92	      guestExpiresAt: null,
93	      failedLoginAttempts: 0,
94	      lockoutUntil: null,
95	      unlockAttempts: 0,
96	      createdAt: Date.now(),
97	      updatedAt: Date.now(),
98	    };
99	    await this._userRepo.create(adminUser);
100	
101	    // 3. Seed system notification templates for every event type.
102	    for (const def of Object.values(SYSTEM_TEMPLATES)) {
103	      await this._templateRepo.create({
104	        id: generateId(),
105	        organizationId: orgId,
106	        name: def.name,
107	        body: def.body,
108	        placeholders: extractPlaceholders(def.body),
109	        isCompact: false,
110	        createdAt: Date.now(),
111	        updatedAt: Date.now(),
112	      });
113	    }
114	
115	    // 4. Mark bootstrap as completed + generate org-level encryption salt.
116	    const orgSalt = cryptoService.generateOrgSalt();
117	    await this._configRepo.create({
118	      id: generateId(),
119	      organizationId: orgId,
120	      orgEncryptionSalt: orgSalt,
121	      bootstrappedAt: Date.now(),
122	      bootstrappedBy: adminId,
123	    });
124	
125	    // 5. Audit trail (does not require auth).
126	    await auditService.log({
127	      actorId: adminId,
128	      action: 'system_bootstrap',
129	      entityType: 'system',
130	      entityId: 'bootstrap',
131	      metadata: { orgId, adminId },
132	    });
133	
134	    return { admin: adminUser, org };
135	  }
136	}
