{"file_path": "/Users/tsiontesfaye/Projects/EaglePoint/retail-ops/repo/tests/API_tests/orgPassphrase.test.js", "content": "/**
 * Org passphrase encryption model tests.
 */

import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import { IDBFactory } from 'fake-indexeddb';
import { initDB, closeDB } from '../../src/infrastructure/db/db.js';
import { authService } from '../../src/services/AuthService.js';
import { cryptoService } from '../../src/services/CryptoService.js';
import { customerService } from '../../src/services/CustomerService.js';
import { BootstrapService } from '../../src/services/BootstrapService.js';
import { setBroadcastService, closeAll } from '../../src/infrastructure/broadcast/broadcastManager.js';
import { MockBroadcastService } from '../../src/infrastructure/broadcast/MockBroadcastService.js';
import { ROLES } from '../../src/utils/constants.js';

const ADMIN_PASS = 'OrgPassphrase@1234';
const ORG_PASSPHRASE = 'SharedSecret@2024';
const WRONG_PASSPHRASE = 'WrongSecret@2024';
let orgId, adminUser;

beforeEach(async () => {
  setBroadcastService(new MockBroadcastService());
  await initDB(new IDBFactory());
  const bs = new BootstrapService();
  const { admin, org } = await bs.bootstrap({
    adminUsername: 'pp_admin', adminPassword: ADMIN_PASS, orgName: 'PassphraseCo',
  });
  orgId = org.id;
  adminUser = admin;
  await authService.login('pp_admin', ADMIN_PASS);
});

afterEach(() => {
  cryptoService.clearSessionKey();
  authService._currentUser = null;
  closeDB();
  closeAll();
});

// ══════════════════════════════════════════════════════════════════════════════
// 1. SETUP ORG PASSPHRASE
// ══════════════════════════════════════════════════════════════════════════════

describe('Org passphrase — setup', () => {
  it('admin can set org passphrase', async () => {
    await authService.setupOrgPassphrase(ORG_PASSPHRASE);
    const model = await authService.getEncryptionModel();
    expect(model).toBe('passphrase');
  });

  it('short passphrase is rejected', async () => {
    await expect(authService.setupOrgPassphrase('short'))
      .rejects.toThrow(/at least 12/i);
  });

  it('non-admin cannot set passphrase', async () => {
    // Create store_manager user
    await authService.createUser({
      username: 'sm_user', password: 'SmUserPass@1234',
      role: ROLES.STORE_MANAGER, organizationNodeId: orgId,
    });
    await authService.logout();
    await authService.login('sm_user', 'SmUserPass@1234');
    await expect(authService.setupOrgPassphrase(ORG_PASSPHRASE))
      .rejects.toThrow(/permission denied/i);
  });
});

// ══════════════════════════════════════════════════════════════════════════════
// 2. CROSS-USER DECRYPTION WITH PASSPHRASE
// ══════════════════════════════════════════════════════════════════════════════

describe('Org passphrase — cross-user decryption', () => {
  it('user A encrypts, user B decrypts with same org passphrase', async () => {
    // Admin creates a customer (encrypted with password-derived key for now)
    const cust = await customerService.createCustomer({
      organizationId: orgId, name: 'PassTest', storedValue: 42.50,
      allergies: 'peanuts', actorId: adminUser.id, reasonNote: 'cross-user encryption test',
    });

    // Migrate to passphrase model
    await authService.migrateToOrgPassphrase(ADMIN_PASS, ORG_PASSPHRASE);

    // Verify admin can decrypt with passphrase
    const revealed = await customerService.revealSensitiveFields(cust.id);
    expect(revealed.storedValue).toBe('42.50');
    expect(revealed.allergies).toBe('peanuts');

    // Create a second user with a DIFFERENT password
    await authService.createUser({
      username: 'user_b', password: 'DifferentPass@1234',
      role: ROLES.STORE_MANAGER, organizationNodeId: orgId,
    });

    // Logout admin, login as user B
    await authService.logout();
    await authService.login('user_b', 'DifferentPass@1234');

    // In passphrase model, login doesn't derive key
    expect(cryptoService.isUnlocked()).toBe(false);

    // Unlock with org passphrase
    const ok = await authService.unlockProtectedData(ORG_PASSPHRASE);
    expect(ok).toBe(true);
    expect(cryptoService.isUnlocked()).toBe(true);

    // User B can now decrypt the same data
    const revealedB = await customerService.revealSensitiveFields(cust.id);
    expect(revealedB.storedValue).toBe('42.50');
    expect(revealedB.allergies).toBe('peanuts');
  });
});

// ══════════════════════════════════════════════════════════════════════════════
// 3. WRONG PASSPHRASE FAILS SAFELY
// ══════════════════════════════════════════════════════════════════════════════

describe('Org passphrase — wrong passphrase', () => {
  it('wrong passphrase does not unlock', async () => {
    await authService.setupOrgPassphrase(ORG_PASSPHRASE);

    // Clear key to simulate locked state
    cryptoService.clearSessionKey();

    const result = await authService.unlockProtectedData(WRONG_PASSPHRASE);
    expect(result).toBe(false);
    expect(cryptoService.isUnlocked()).toBe(false);
  });
});

// ══════════════════════════════════════════════════════════════════════════════
// 4. LOGOUT/LOCK CLEARS UNLOCKED STATE
// ══════════════════════════════════════════════════════════════════════════════

describe('Org passphrase — session lifecycle', () => {
  it('logout clears encryption state', async () => {
    await authService.setupOrgPassphrase(ORG_PASSPHRASE);
    expect(cryptoService.isUnlocked()).toBe(true);

    await authService.logout();
    expect(cryptoService.isUnlocked()).toBe(false);
  });

  it('lock clears encryption state', async () => {
    await authService.setupOrgPassphrase(ORG_PASSPHRASE);
    expect(cryptoService.isUnlocked()).toBe(true);

    authService.lockSession();
    expect(cryptoService.isUnlocked()).toBe(false);
  });
});

// ══════════════════════════════════════════════════════════════════════════════
// 5. MIGRATION FROM OLD MODEL
// ══════════════════════════════════════════════════════════════════════════════

describe('Org passphrase — migration', () => {
  it('migrated records can be decrypted with new passphrase', async () => {
    // Create customer with old (password-derived) encryption
    const cust = await customerService.createCustomer({
      organizationId: orgId, name: 'MigrateTest', storedValue: 100.00,
      allergies: 'shellfish', materialRestrictions: 'latex',
      actorId: adminUser.id, reasonNote: 'migration test record',
    });

    // Verify old model works
    const before = await customerService.revealSensitiveFields(cust.id);
    expect(before.storedValue).toBe('100.00');

    // Migrate
    const count = await authService.migrateToOrgPassphrase(ADMIN_PASS, ORG_PASSPHRASE);
    expect(count).toBe(1);

    // Verify passphrase model is active
    const model = await authService.getEncryptionModel();
    expect(model).toBe('passphrase');

    // Verify data still readable
