66	  // ── Login / logout ───────────────────────────────────────────────────────────
67	
68	  /**
69	   * Authenticates a user with username and password.
70	   * Derives the session encryption key on success.
71	   * Tracks failed attempts; locks account for 15 minutes after 5 failures.
72	   *
73	   * @param {string} username
74	   * @param {string} password
75	   * @returns {Promise<object>}  The authenticated user record.
76	   * @throws {Error} On invalid credentials, deactivated account, or lockout.
77	   */
78	  async login(username, password) {
79	    const user = await this._userRepo.findByUsername(username);
80	
81	    // All failure paths return the same generic message to prevent enumeration.
82	    if (!user) throw new Error('Invalid credentials.');
83	    if (!user.isActive) throw new Error('Invalid credentials.');
84	
85	    const now = Date.now();
86	    if (user.lockoutUntil && now < user.lockoutUntil) {
87	      throw new Error('Invalid credentials.');
88	    }
89	
90	    const valid = await cryptoService.verifyPassword(password, user.passwordSalt, user.passwordHash);
91	
92	    if (!valid) {
93	      const failedAttempts = (user.failedLoginAttempts ?? 0) + 1;
94	      const lockoutUntil = failedAttempts >= MAX_FAILED_ATTEMPTS
95	        ? Date.now() + LOCKOUT_DURATION_MS
96	        : null;
97	
98	      await this._userRepo.update(user.id, {
99	        ...user,
100	        failedLoginAttempts: failedAttempts,
101	        lockoutUntil,
102	        updatedAt: Date.now(),
103	      });
104	
105	      // Generic error — same message regardless of lockout to prevent enumeration.
106	      throw new Error('Invalid credentials.');
107	    }
108	
109	    // Success: clear failure state.
110	    const freshUser = {
111	      ...user,
112	      failedLoginAttempts: 0,
113	      lockoutUntil: null,
114	      updatedAt: Date.now(),
115	    };
116	    await this._userRepo.update(user.id, freshUser);
117	
118	    // Derive session key: if org has a passphrase-based encryption model,
119	    // do NOT derive key from login password — user must unlock separately.
120	    // Otherwise, fall back to the legacy password-derived key model.
121	    const { config: orgConfig, rootOrgId } = await this._resolveOrgConfig(user);
122	    if (orgConfig?.encryptionModel === 'passphrase') {
123	      // Passphrase model: login does NOT unlock protected data.
124	      // User must call unlockProtectedData(orgPassphrase) separately.
125	    } else {
126	      // Legacy model: derive key from login password + org salt.
127	      let keySalt = user.passwordSalt;
128	      if (orgConfig?.orgEncryptionSalt) {
129	        keySalt = orgConfig.orgEncryptionSalt;
130	      }
131	      await cryptoService.deriveSessionKey(password, keySalt);
132	    }
133	
134	    this._currentUser = freshUser;
135	    this._isLocked = false;
136	    this._isGuestSession = false;
137	    this._unlockAttempts = 0; // reset on any successful login
138	
139	    this._resetLockTimer();
140	
141	    await auditService.log({
142	      actorId: user.id,
143	      action: 'login',
144	      entityType: 'user',
145	      entityId: user.id,
146	    });
147	
148	    return freshUser;
149	  }
150	
151	  /**
152	   * Logs out the current user and clears all session state.
153	   * @returns {Promise<void>}
154	   */
155	  async logout() {
156	    if (this._currentUser) {
157	      await auditService.log({
158	        actorId: this._currentUser.id,
159	        action: 'logout',
160	        entityType: 'user',
161	        entityId: this._currentUser.id,
162	      });
163	    }
164	
165	    cancel(LOCK_TIMER_KEY);
166	    cancel(GUEST_TIMER_KEY);
167	    cryptoService.clearSessionKey();
168	
169	    this._currentUser = null;
170	    this._isLocked = false;
171	    this._isGuestSession = false;
172	
173	    broadcast(CHANNEL_NAMES.STATE, EVENT_TYPES.SESSION_LOGGED_OUT);
174	  }
