176	  // ── Guest session ────────────────────────────────────────────────────────────
177	
178	  /**
179	   * Creates a temporary read-only guest session.
180	   * Hard-expires after 30 minutes and auto-redirects to login.
181	   *
182	   * @param {(reason: string) => void} onExpiry  Called when the guest session expires.
183	   * @returns {{ id: string; role: string; isGuest: true }}
184	   */
185	  async createGuestSession(onExpiry) {
186	    // Attach guest to the root org so they can explore read-only data.
187	    const allUsers = await this._userRepo.findAll();
188	    const adminUser = allUsers.find((u) => u.role === ROLES.ADMINISTRATOR);
189	    const guestOrgId = adminUser?.organizationNodeId ?? null;
190	
191	    const guestUser = {
192	      id: `guest_${Date.now()}`,
193	      username: 'guest',
194	      role: ROLES.GUEST,
195	      organizationNodeId: guestOrgId,
196	      isActive: true,
197	      isGuest: true,
198	      guestExpiresAt: Date.now() + VALIDATION.GUEST_TRIAL_MINUTES * 60_000,
199	    };
200	
201	    this._currentUser = guestUser;
202	    this._isGuestSession = true;
203	
204	    schedule(
205	      GUEST_TIMER_KEY,
206	      async () => {
207	        onExpiry('Guest trial expired after 30 minutes.');
208	        await this.logout();
209	      },
210	      VALIDATION.GUEST_TRIAL_MINUTES * 60_000,
211	    );
212	
213	    return guestUser;
214	  }
