217	
218	  /**
219	   * Resets the inactivity auto-lock timer.
220	   * Must be called on every user interaction.
221	   */
222	  resetInactivityTimer() {
223	    if (!this._currentUser || this._isGuestSession) return;
224	    this._resetLockTimer();
225	  }
226	
227	  /** @private */
228	  _resetLockTimer() {
229	    schedule(
230	      LOCK_TIMER_KEY,
231	      () => {
232	        this.lockSession();
233	      },
234	      VALIDATION.AUTO_LOCK_MINUTES * 60_000,
235	    );
236	  }
