238	  /**
239	   * Locks the session — encrypted data becomes inaccessible until unlock.
240	   */
241	  lockSession() {
242	    cryptoService.clearSessionKey();
243	    this._isLocked = true;
244	    broadcast(CHANNEL_NAMES.STATE, EVENT_TYPES.SESSION_LOCKED);
245	  }
246	
247	  /**
248	   * Unlocks the session by re-deriving the encryption key.
249	   *
250	   * @param {string} password
251	   * @returns {Promise<boolean>}
252	   */
253	  async unlockSession(password) {
254	    if (!this._currentUser) throw new Error('No active session to unlock.');
255	
256	    const user = await this._userRepo.findById(this._currentUser.id);
257	    if (!user) throw new Error('User record not found.');
258	
259	    const valid = await cryptoService.verifyPassword(password, user.passwordSalt, user.passwordHash);
260	
261	    if (!valid) {
262	      this._unlockAttempts += 1;
263	      if (this._unlockAttempts >= MAX_UNLOCK_ATTEMPTS) {
264	        // Too many wrong attempts — force full logout to prevent brute-force.
265	        await this.logout();
266	        throw new Error(
267	          `Too many failed unlock attempts (${MAX_UNLOCK_ATTEMPTS}). ` +
268	            'Session has been terminated. Please log in again.',
269	        );
270	      }
271	      return false;
272	    }
273	
274	    // Successful unlock — reset counter, clear lock.
275	    this._unlockAttempts = 0;
276	
277	    const { config: orgConfig } = await this._resolveOrgConfig(user);
278	    if (orgConfig?.encryptionModel === 'passphrase') {
279	      // Passphrase model: unlock screen only, do NOT derive key from login password.
280	      // Protected data remains locked until unlockProtectedData() is called.
281	    } else {
282	      // Legacy model: re-derive key from login password + org salt.
283	      let unlockSalt = user.passwordSalt;
284	      if (orgConfig?.orgEncryptionSalt) unlockSalt = orgConfig.orgEncryptionSalt;
285	      await cryptoService.deriveSessionKey(password, unlockSalt);
286	    }
287	    this._isLocked = false;
288	    this._resetLockTimer();
289	    broadcast(CHANNEL_NAMES.STATE, EVENT_TYPES.SESSION_UNLOCKED);
290	    return true;
291	  }
