295	  /**
296	   * Creates a new user account.
297	   * Requires administrator role.
298	   *
299	   * @param {{ username: string; password: string; role: string; organizationNodeId: string }} params
300	   * @returns {Promise<object>}
301	   */
302	  async createUser({ username, password, role, organizationNodeId }) {
303	    this._assertPermission('administrator');
304	
305	    const pwValidation = validatePassword(password);
306	    if (!pwValidation.valid) throw new Error(pwValidation.errors.join(' '));
307	    if (!isValidRole(role)) throw new Error(`Invalid role: ${role}`);
308	
309	    // Non-admin/non-guest roles require a valid org node assignment.
310	    if (role !== ROLES.ADMINISTRATOR && role !== ROLES.GUEST) {
311	      if (!organizationNodeId) {
312	        throw new Error(`Role '${role}' requires an organizationNodeId.`);
313	      }
314	      const { OrgRepository } = await import('../repositories/implementations/OrgRepository.js');
315	      const orgRepo = new OrgRepository();
316	      const node = await orgRepo.findById(organizationNodeId);
317	      if (!node) {
318	        throw new Error(`Organization node '${organizationNodeId}' not found.`);
319	      }
320	    }
321	
322	    const { hash, salt } = await cryptoService.hashNewPassword(password);
323	
324	    const user = {
325	      id: generateId(),
326	      username,
327	      passwordHash: hash,
328	      passwordSalt: salt,
329	      role,
330	      organizationNodeId,
331	      isActive: true,
332	      isGuest: false,
333	      guestExpiresAt: null,
334	      failedLoginAttempts: 0,
335	      lockoutUntil: null,
336	      createdAt: Date.now(),
337	      updatedAt: Date.now(),
338	    };
339	
340	    await this._userRepo.create(user);
341	    await auditService.log({
342	      actorId: this._currentUser?.id ?? 'system',
343	      action: 'create_user',
344	      entityType: 'user',
345	      entityId: user.id,
346	      metadata: { username, role },
347	    });
348	
349	    return user;
350	  }
