352	  /**
353	   * Links two user accounts. Persisted to the linkedAccounts store.
354	   * Prevents duplicates (A-B == B-A) and self-links.
355	   * Requires: ADMINISTRATOR role.
356	   *
357	   * @param {{ userIdA: string; userIdB: string; reason: string }} params
358	   * @returns {Promise<object>}
359	   */
360	  async linkUserAccounts({ userIdA, userIdB, reason }) {
361	    this._assertPermission('administrator');
362	    if (!userIdA || !userIdB) throw new Error('Both user IDs are required.');
363	    if (userIdA === userIdB) throw new Error('Cannot link a user to themselves.');
364	    if (!reason?.trim() || reason.trim().length < 10) throw new Error('Reason must be at least 10 characters.');
365	
366	    const a = await this._userRepo.findById(userIdA);
367	    const b = await this._userRepo.findById(userIdB);
368	    if (!a) throw new Error(`User '${userIdA}' not found.`);
369	    if (!b) throw new Error(`User '${userIdB}' not found.`);
370	
371	    // Duplicate check (A-B == B-A)
372	    const { LinkedAccountRepository } = await import('../repositories/implementations/RiskRepository.js');
373	    const linkRepo = new LinkedAccountRepository();
374	    const existingA = await linkRepo.findAllLinksForUser(userIdA);
375	    const isDuplicate = existingA.some(
376	      (l) => (l.primaryUserId === userIdB || l.linkedUserId === userIdB),
377	    );
378	    if (isDuplicate) throw new Error('These users are already linked.');
379	
380	    const link = {
381	      id: generateId(),
382	      primaryUserId: userIdA,
383	      linkedUserId: userIdB,
384	      evidenceType: 'admin_link',
385	      evidenceDetails: reason,
386	      organizationId: a.organizationNodeId,
387	      createdAt: Date.now(),
388	    };
389	    await linkRepo.create(link);
390	
391	    await auditService.log({
392	      actorId: this._currentUser?.id ?? 'system',
393	      action: 'link_user_accounts',
394	      entityType: 'user',
395	      entityId: userIdA,
396	      metadata: { linkedTo: userIdB, reason },
397	    });
398	
399	    return link;
400	  }
