436	  /**
437	   * Changes a user's password and re-encrypts all their sensitive data.
438	   *
439	   * @param {string} userId
440	   * @param {string} oldPassword
441	   * @param {string} newPassword
442	   * @param {Array<{ ciphertext: string; iv: string }>} encryptedFields
443	   * @returns {Promise<Array<{ ciphertext: string; iv: string; algorithmVersion: string }>>}
444	   */
445	  async changePassword(userId, oldPassword, newPassword, encryptedFields = []) {
446	    const pwValidation = validatePassword(newPassword);
447	    if (!pwValidation.valid) throw new Error(pwValidation.errors.join(' '));
448	
449	    const user = await this._userRepo.findById(userId);
450	    if (!user) throw new Error('User not found.');
451	
452	    const valid = await cryptoService.verifyPassword(oldPassword, user.passwordSalt, user.passwordHash);
453	    if (!valid) throw new Error('Old password is incorrect.');
454	
455	    const { hash, salt } = await cryptoService.hashNewPassword(newPassword);
456	
457	    // Re-encrypt all sensitive fields before committing the password change.
458	    const reEncrypted = await cryptoService.rotateEncryptedFields(
459	      encryptedFields,
460	      oldPassword,
461	      user.passwordSalt,
462	      newPassword,
463	    );
464	
465	    await this._userRepo.update(userId, {
466	      ...user,
467	      passwordHash: hash,
468	      passwordSalt: salt,
469	      updatedAt: Date.now(),
470	    });
471	
472	    // Re-derive session key with new password.
473	    await cryptoService.deriveSessionKey(newPassword, salt);
474	
475	    await auditService.log({
476	      actorId: userId,
477	      action: 'change_password',
478	      entityType: 'user',
479	      entityId: userId,
480	    });
481	
482	    return reEncrypted;
483	  }
