567	  // ── Org passphrase management ────────────────────────────────────────────────
568	
569	  /**
570	   * Sets up or updates the org-level passphrase for protected data encryption.
571	   * Derives the encryption key from orgPassphrase + orgSalt and stores a verifier.
572	   * Requires: ADMINISTRATOR role.
573	   *
574	   * @param {string} orgPassphrase  The new org passphrase.
575	   * @returns {Promise<void>}
576	   */
577	  async setupOrgPassphrase(orgPassphrase) {
578	    this._assertPermission('administrator');
579	    if (!orgPassphrase || orgPassphrase.length < 12) {
580	      throw new Error('Org passphrase must be at least 12 characters.');
581	    }
582	
583	    const user = this._currentUser;
584	    const { config, rootOrgId } = await this._resolveOrgConfig(user);
585	    if (!config) throw new Error('Organization config not found.');
586	
587	    // Hash the passphrase for future verification.
588	    const { hash, salt } = await cryptoService.hashNewPassword(orgPassphrase);
589	
590	    // Update config with passphrase verifier and encryption model flag.
591	    const { AppConfigRepository } = await import('../repositories/implementations/AppConfigRepository.js');
592	    const configRepo = new AppConfigRepository();
593	    await configRepo.update(config.id, {
594	      ...config,
595	      orgPassphraseHash: hash,
596	      orgPassphraseSalt: salt,
597	      encryptionModel: 'passphrase',
598	    });
599	
600	    // Derive and set session key from orgPassphrase + orgEncryptionSalt.
601	    await cryptoService.deriveSessionKey(orgPassphrase, config.orgEncryptionSalt);
602	
603	    await auditService.log({
604	      actorId: user.id,
605	      action: 'setup_org_passphrase',
606	      entityType: 'system',
607	      entityId: rootOrgId,
608	    });
609	  }
610	
611	  /**
612	   * Unlocks protected data using the org passphrase.
613	   * Used when encryption model is 'passphrase' — login/unlock only authenticates
614	   * the user but does not derive the data encryption key.
615	   *
616	   * @param {string} orgPassphrase
617	   * @returns {Promise<boolean>}
618	   */
619	  async unlockProtectedData(orgPassphrase) {
620	    this._assertPermission('store_manager');
621	
622	    const { config } = await this._resolveOrgConfig(this._currentUser);
623	    if (!config) throw new Error('Organization config not found.');
624	    if (config.encryptionModel !== 'passphrase') {
625	      throw new Error('Organization does not use passphrase-based encryption.');
626	    }
627	    if (!config.orgPassphraseHash || !config.orgPassphraseSalt) {
628	      throw new Error('Org passphrase not configured.');
629	    }
630	
631	    const valid = await cryptoService.verifyPassword(
632	      orgPassphrase,
633	      config.orgPassphraseSalt,
634	      config.orgPassphraseHash,
635	    );
636	    if (!valid) return false;
637	
638	    await cryptoService.deriveSessionKey(orgPassphrase, config.orgEncryptionSalt);
639	    return true;
640	  }
641	
642	  /**
643	   * Migrates encrypted records from the old password-derived model to the new
644	   * org-passphrase model. Decrypts all sensitive customer fields with the old
645	   * key and re-encrypts them with the new passphrase-derived key.
646	   * Requires: ADMINISTRATOR role.
647	   *
648	   * @param {string} oldLoginPassword  The admin's login password (old key source).
649	   * @param {string} orgPassphrase     The new org passphrase.
650	   * @returns {Promise<number>}  Number of records migrated.
651	   */
652	  async migrateToOrgPassphrase(oldLoginPassword, orgPassphrase) {
653	    this._assertPermission('administrator');
654	    if (!orgPassphrase || orgPassphrase.length < 12) {
655	      throw new Error('Org passphrase must be at least 12 characters.');
