import os, re

test_dirs = ['tests/API_tests', 'tests/e2e_tests', 'tests/unit_tests', 'tests/browser_tests']
modified = []

for test_dir in test_dirs:
    if not os.path.isdir(test_dir):
        continue
    for fname in os.listdir(test_dir):
        if not fname.endswith('.test.js'):
            continue
        fpath = os.path.join(test_dir, fname)
        with open(fpath, 'r') as f:
            content = f.read()

        # Skip files that don't use authService.login
        if 'authService.login(' not in content:
            continue

        # Pattern: await authService.login(args);
        # Add: await authService.unlockProtectedData(PASSWORD); after it
        # where PASSWORD is the second argument to login

        new_content = re.sub(
            r'(await authService\.login\([^,]+,\s*([^)]+)\);)',
            r'\1\n    await authService.unlockProtectedData(\2);',
            content
        )

        if new_content != content:
            with open(fpath, 'w') as f:
                f.write(new_content)
            modified.append(fpath)

print(f'Modified {len(modified)} files:')
for f in sorted(modified):
    print(f'  {f}')
"
