1	/**
2	 * Integration tests — Customer protected-field encryption/decryption.
3	 *
4	 * Covers:
5	 *   - create customer with encrypted fields
6	 *   - reveal sensitive fields round-trip
7	 *   - stored value adjust with encrypted read/write
8	 *   - session-locked access blocked
9	 *   - ANALYST can reveal but not modify financial fields
10	 *
11	 * Session key is derived via a full authService.login() call (real PBKDF2 path),
12	 * NOT by injecting cryptoService._sessionKey directly.
13	 */
14	
15	import { describe, it, expect, beforeEach, afterEach } from 'vitest';
16	import { IDBFactory } from 'fake-indexeddb';
17	import { initDB, closeDB } from '../../src/infrastructure/db/db.js';
18	import { AuthService, authService } from '../../src/services/AuthService.js';
19	import { CustomerService } from '../../src/services/CustomerService.js';
20	import { cryptoService } from '../../src/services/CryptoService.js';
21	import { setBroadcastService, closeAll } from '../../src/infrastructure/broadcast/broadcastManager.js';
22	import { MockBroadcastService } from '../../src/infrastructure/broadcast/MockBroadcastService.js';
23	import { ROLES } from '../../src/utils/constants.js';
24	
25	const ORG_ID = 'store-001';
26	const ADMIN_PASSWORD = 'AdminCrypto12!';
27	const ADMIN_USERNAME = 'cryptoadmin';
28	
29	/**
30	 * Seeds a real admin user and logs in via authService.login(), which performs
31	 * the full PBKDF2 derivation and sets cryptoService._sessionKey properly.
32	 * This avoids any direct injection of the session key.
33	 */
34	async function loginAsAdmin() {
