1	/**
2	 * Unit tests — AuthService.
3	 *
4	 * Tests cover:
5	 *   - password validation rules
6	 *   - user creation and login
7	 *   - session lock / unlock
8	 *   - guest session creation
9	 *   - account deactivation
10	 *   - RBAC role checks
11	 */
12	
13	import { describe, it, expect, beforeEach, afterEach, vi } from 'vitest';
14	import { IDBFactory } from 'fake-indexeddb';
15	import { initDB, closeDB } from '../../src/infrastructure/db/db.js';
16	import { AuthService } from '../../src/services/AuthService.js';
17	import { validatePassword } from '../../src/utils/validation.js';
18	import { ROLES } from '../../src/utils/constants.js';
19	import { setBroadcastService, closeAll } from '../../src/infrastructure/broadcast/broadcastManager.js';
20	import { MockBroadcastService } from '../../src/infrastructure/broadcast/MockBroadcastService.js';
21	import { OrgRepository } from '../../src/repositories/implementations/OrgRepository.js';
22	
23	// All passwords used in tests must be ≥12 chars with ≥1 digit and ≥1 symbol.
24	const VALID_PW  = 'ValidPass12!';   // 12 chars ✓
25	const LOCK_PW   = 'LockTest123!';   // 12 chars ✓
26	const WRONG_PW  = 'WrongPass12!';   // 12 chars ✓
27	const DEACT_PW  = 'ValidPass12!';   // same as VALID_PW
28	
29	let authService;
30	
31	beforeEach(async () => {
32	  setBroadcastService(new MockBroadcastService());
33	  const idbFactory = new IDBFactory();
34	  await initDB(idbFactory);
35	  authService = new AuthService();
36	
37	  // Seed org nodes for createUser validation.
38	  const orgRepo = new OrgRepository();
39	  await orgRepo.create({
40	    id: 'org-001', name: 'Test Org', type: 'company', parentId: null,
41	    organizationId: 'org-001', createdAt: Date.now(), updatedAt: Date.now(),
42	  });
43	  await orgRepo.create({
44	    id: 'store-001', name: 'Test Store', type: 'store', parentId: 'org-001',
45	    organizationId: 'org-001', createdAt: Date.now(), updatedAt: Date.now(),
46	  });
47	  await orgRepo.create({
48	    id: 'org-1', name: 'Test Org 1', type: 'company', parentId: null,
49	    organizationId: 'org-1', createdAt: Date.now(), updatedAt: Date.now(),
50	  });
51	});
52	
53	afterEach(() => {
54	  closeDB();
55	  closeAll();
56	  vi.useRealTimers();
57	});
58	
59	// ── Password validation (pure function — no DB) ───────────────────────────────
60	
61	describe('validatePassword', () => {
62	  it('accepts a valid password', () => {
63	    const { valid } = validatePassword('SecurePass1!');
64	    expect(valid).toBe(true);
65	  });
66	
67	  it('rejects a password shorter than 12 characters', () => {
68	    const { valid, errors } = validatePassword('Short1!');
69	    expect(valid).toBe(false);
70	    expect(errors.some((e) => e.includes('12'))).toBe(true);
71	  });
72	
73	  it('rejects a password without a number', () => {
74	    const { valid, errors } = validatePassword('NoNumberHere!');
75	    expect(valid).toBe(false);
76	    expect(errors.some((e) => e.includes('number'))).toBe(true);
77	  });
78	
79	  it('rejects a password without a symbol', () => {
80	    const { valid, errors } = validatePassword('NoSymbolHere12');
81	    expect(valid).toBe(false);
82	    expect(errors.some((e) => e.includes('symbol'))).toBe(true);
83	  });
84	
85	  it('rejects an empty string', () => {
86	    const { valid } = validatePassword('');
87	    expect(valid).toBe(false);
88	  });
89	
90	  it('accepts a password that is exactly 12 characters with digit and symbol', () => {
91	    const { valid } = validatePassword('Exactly12Ch1!');
92	    expect(valid).toBe(true);
93	  });
94	});
95	
96	// ── User creation ─────────────────────────────────────────────────────────────
97	
98	describe('AuthService.createUser', () => {
99	  it('creates a user and returns a record with the correct role', async () => {
100	    // Simulate an admin session so permission check passes.
101	    authService._currentUser = { id: 'admin-001', role: ROLES.ADMINISTRATOR };
102	
103	    const user = await authService.createUser({
104	      username: 'alice',
105	      password: 'SecurePass12!',
106	      role: ROLES.STORE_MANAGER,
107	      organizationNodeId: 'store-001',
108	    });
109	
110	    expect(user.username).toBe('alice');
111	    expect(user.role).toBe(ROLES.STORE_MANAGER);
112	    expect(user.isActive).toBe(true);
113	    expect(user.passwordHash).toBeDefined();
114	    expect(user.passwordSalt).toBeDefined();
115	    // Password must never be stored in plaintext.
116	    expect(user.passwordHash).not.toBe('SecurePass1!');
117	  });
118	
119	  it('throws if password does not meet rules', async () => {
120	    authService._currentUser = { id: 'admin-001', role: ROLES.ADMINISTRATOR };
121	    await expect(
122	      authService.createUser({
123	        username: 'bob',
124	        password: 'weak',
125	        role: ROLES.ANALYST,
126	        organizationNodeId: 'store-001',
127	      }),
128	    ).rejects.toThrow();
129	  });
130	
131	  it('throws if called without admin role', async () => {
132	    authService._currentUser = { id: 'user-001', role: ROLES.STORE_MANAGER };
133	    await expect(
134	      authService.createUser({
135	        username: 'charlie',
136	        password: 'SecurePass12!',
137	        role: ROLES.ANALYST,
138	        organizationNodeId: 'store-001',
139	      }),
140	    ).rejects.toThrow('Permission denied');
141	  });
142	});
143	
144	// ── Login / logout ────────────────────────────────────────────────────────────
145	
146	describe('AuthService.login', () => {
147	  beforeEach(async () => {
148	    authService._currentUser = { id: 'admin-001', role: ROLES.ADMINISTRATOR };
149	    await authService.createUser({
150	      username: 'diana',
151	      password: VALID_PW,
152	      role: ROLES.ANALYST,
153	      organizationNodeId: 'org-1',
154	    });
155	    authService._currentUser = null;
156	  });
157	
158	  it('logs in with correct credentials', async () => {
159	    const user = await authService.login('diana', VALID_PW);
160	    await authService.unlockProtectedData(VALID_PW);
161	    expect(user.username).toBe('diana');
162	    expect(authService.isAuthenticated()).toBe(true);
163	    expect(authService.isLocked()).toBe(false);
164	  });
165	
166	  it('throws on wrong password', async () => {
167	    await expect(authService.login('diana', WRONG_PW)).rejects.toThrow(
168	      'Invalid credentials',
169	    );
170	  });
171	
172	  it('throws on unknown username', async () => {
173	    await expect(authService.login('nobody', VALID_PW)).rejects.toThrow(
174	      'Invalid credentials',
175	    );
176	  });
177	
178	  it('rejects login for a deactivated account', async () => {
179	    const admin = { id: 'admin-001', role: ROLES.ADMINISTRATOR };
180	    authService._currentUser = admin;
181	    const created = await authService.createUser({
182	      username: 'deactivated_user',
183	      password: DEACT_PW,
184	      role: ROLES.REVIEWER,
185	      organizationNodeId: 'org-1',
186	    });
187	    await authService.deactivateAccount(created.id);
188	    authService._currentUser = null;
189	
190	    await expect(authService.login('deactivated_user', DEACT_PW)).rejects.toThrow(
191	      'Invalid credentials',
192	    );
193	  });
194	});
195	
196	// ── Session lock / unlock ─────────────────────────────────────────────────────
197	
198	describe('AuthService lock / unlock', () => {
199	  beforeEach(async () => {
200	    authService._currentUser = { id: 'admin-001', role: ROLES.ADMINISTRATOR };
201	    await authService.createUser({
202	      username: 'edgar',
203	      password: LOCK_PW,
204	      role: ROLES.ANALYST,
205	      organizationNodeId: 'org-1',
206	    });
207	    authService._currentUser = null;
208	    await authService.login('edgar', LOCK_PW);
209	    await authService.unlockProtectedData(LOCK_PW);
210	  });
211	
212	  it('isLocked returns false after login', () => {
213	    expect(authService.isLocked()).toBe(false);
214	  });
215	
216	  it('lockSession marks the session as locked', () => {
217	    authService.lockSession();
218	    expect(authService.isLocked()).toBe(true);
219	  });
220	
221	  it('unlockSession with correct password unlocks', async () => {
222	    authService.lockSession();
223	    const result = await authService.unlockSession(LOCK_PW);
224	    expect(result).toBe(true);
225	    expect(authService.isLocked()).toBe(false);
226	  });
227	
228	  it('unlockSession with wrong password returns false', async () => {
229	    authService.lockSession();
230	    const result = await authService.unlockSession(WRONG_PW);
231	    expect(result).toBe(false);
232	    expect(authService.isLocked()).toBe(true);
233	  });
234	});
235	
236	// ── Guest session ─────────────────────────────────────────────────────────────
237	
238	describe('AuthService guest session', () => {
239	  it('creates a guest session with read-only role', async () => {
240	    const expiryCalled = vi.fn();
241	    const guest = await authService.createGuestSession(expiryCalled);
242	
243	    expect(guest.isGuest).toBe(true);
244	    expect(guest.role).toBe(ROLES.GUEST);
245	    expect(authService.isGuest()).toBe(true);
246	    expect(authService.isAuthenticated()).toBe(false);
247	  });
248	
249	  it('calls the expiry callback after 30 minutes', async () => {
250	    vi.useFakeTimers();
251	    const expiryCalled = vi.fn();
252	
253	    // Create a fresh service so the BroadcastChannel subscribe from the
254	    // constructor is registered after fake timers are set up.
255	    const svc = new AuthService();
256	    await svc.createGuestSession(expiryCalled);
257	
258	    // runAllTimersAsync advances fake timers AND flushes all resulting promises.
259	    await vi.runAllTimersAsync();
260	
261	    expect(expiryCalled).toHaveBeenCalledOnce();
262	  });
263	});
264	
265	// ── RBAC ──────────────────────────────────────────────────────────────────────
266	
267	describe('AuthService RBAC', () => {
268	  it('administrator has all roles', () => {
269	    authService._currentUser = { id: 'a', role: ROLES.ADMINISTRATOR };
270	    expect(authService.hasRole(ROLES.STORE_MANAGER)).toBe(true);
271	    expect(authService.hasRole(ROLES.ANALYST)).toBe(true);
272	    expect(authService.hasRole(ROLES.REVIEWER)).toBe(true);
273	  });
274	
275	  it('store_manager does not have admin role', () => {
276	    authService._currentUser = { id: 'b', role: ROLES.STORE_MANAGER };
277	    expect(authService.hasRole(ROLES.ADMINISTRATOR)).toBe(false);
278	    expect(authService.hasRole(ROLES.STORE_MANAGER)).toBe(true);
279	  });
280	
281	  it('hasRole returns false when no user', () => {
282	    authService._currentUser = null;
283	    expect(authService.hasRole(ROLES.ANALYST)).toBe(false);
284	  });
285	});
