2	  /**
3	   * Generic data table component.
4	   *
5	   * Props:
6	   *   columns  - Array<{ key: string; label: string; sortable?: boolean; width?: string }>
7	   *   rows     - Array<object>  (each object must have a unique `id` field)
8	   *   loading  - boolean
9	   *   empty    - string (message shown when rows.length === 0 and !loading)
10	   */
11	
12	  /** @type {Array<{ key: string; label: string; sortable?: boolean; width?: string }>} */
13	  export let columns = [];
14	
15	  /** @type {object[]} */
16	  export let rows = [];
17	
18	  /** @type {boolean} */
19	  export let loading = false;
20	
21	  /** @type {string} */
22	  export let empty = 'No records found.';
23	
24	  let sortKey = '';
25	  let sortDir = 'asc'; // 'asc' | 'desc'
26	
27	  function toggleSort(key) {
28	    if (sortKey === key) {
29	      sortDir = sortDir === 'asc' ? 'desc' : 'asc';
30	    } else {
31	      sortKey = key;
32	      sortDir = 'asc';
33	    }
34	  }
35	
36	  $: sortedRows = sortKey
37	    ? [...rows].sort((a, b) => {
38	        const av = a[sortKey] ?? '';
39	        const bv = b[sortKey] ?? '';
40	        const cmp = String(av).localeCompare(String(bv), undefined, { numeric: true });
41	        return sortDir === 'asc' ? cmp : -cmp;
42	      })
43	    : rows;
44	</script>
