52	            class="th"
53	            style={col.width ? `width:${col.width}` : ''}
54	            aria-sort={sortKey === col.key ? (sortDir === 'asc' ? 'ascending' : 'descending') : 'none'}
55	          >
56	            {#if col.sortable}
57	              <button class="sort-btn" on:click={() => toggleSort(col.key)}>
58	                {col.label}
59	                <span class="sort-icon" aria-hidden="true">
60	                  {sortKey === col.key ? (sortDir === 'asc' ? '↑' : '↓') : '↕'}
61	                </span>
62	              </button>
63	            {:else}
64	              {col.label}
65	            {/if}
66	          </th>
67	        {/each}
68	        <!-- Slot for action column header -->
69	        {#if $$slots.actions}
70	          <th class="th th--actions"><span class="sr-only">Actions</span></th>
71	        {/if}
72	      </tr>
73	    </thead>
74	    <tbody>
75	      {#if loading}
76	        <tr>
77	          <td colspan={columns.length + ($$slots.actions ? 1 : 0)} class="td td--center">
78	            <span class="spinner" aria-label="Loading"></span>
79	          </td>
80	        </tr>
81	      {:else if sortedRows.length === 0}
82	        <tr>
83	          <td colspan={columns.length + ($$slots.actions ? 1 : 0)} class="td td--empty">
84	            {empty}
85	          </td>
86	        </tr>
87	      {:else}
88	        {#each sortedRows as row (row.id)}
89	          <tr class="tr">
90	            {#each columns as col (col.key)}
91	              <td class="td">
