41	  let channels = [];
42	  let channelsLoading = false;
43	  let showChannelForm = false;
44	  let channelName = '';
45	  let channelError = '';
46	  let channelLoading = false;
47	
48	  // Subscriptions
49	  let subscriptions = [];
50	  let subscriptionsLoading = false;
51	  let subEventType = '';
52	  let subChannelId = '';
53	  let subError = '';
54	  let subLoading = false;
55	  let deletingSubId = null;
