66	  $: actorId = $currentUser?.id ?? '';
67	  $: orgId = resolveOrgContext($currentUser, $orgTree).organizationId || ($currentUser?.organizationNodeId ?? '');
68	  $: canManage = $currentRole === ROLES.ADMINISTRATOR || $currentRole === ROLES.STORE_MANAGER;
69	
