74	  async function loadInbox() {
75	    if (!actorId) return;
76	    inboxLoading = true;
77	    try {
78	      notifications = await notificationService.getInbox(actorId);
79	    } catch (err) {
80	      showToast('error', err.message);
81	    } finally {
82	      inboxLoading = false;
83	    }
84	  }
