86	  async function loadQueue() {
87	    if (!orgId) return;
88	    queueLoading = true;
89	    try {
90	      queueItems = await notificationService.getQueueByOrg(orgId);
91	    } catch (err) {
92	      showToast('error', err.message);
93	    } finally {
94	      queueLoading = false;
95	    }
96	  }
97	
98	  function openRequeueModal(item) {
99	    requeueItem = item;
100	    requeueVarsJson = JSON.stringify(item.payload ?? {}, null, 2);
101	    requeueError = '';
102	    showRequeueModal = true;
103	  }
104	
105	  async function handleRequeue() {
106	    requeueError = '';
107	    let vars;
108	    try { vars = JSON.parse(requeueVarsJson); } catch { requeueError = 'Invalid JSON.'; return; }
109	    requeueLoading = true;
110	    try {
111	      await notificationService.requeueDraft(requeueItem.id, vars);
112	      showRequeueModal = false;
113	      showToast('success', 'Draft requeued for delivery.');
114	      await loadQueue();
115	    } catch (err) {
116	      requeueError = err.message;
117	    } finally {
118	      requeueLoading = false;
119	    }
120	  }
121	
122	  async function loadTemplates() {
123	    if (!orgId) return;
124	    templatesLoading = true;
125	    try {
126	      templates = await templateService.getByOrg(orgId);
127	    } catch (err) {
128	      showToast('error', err.message);
129	    } finally {
130	      templatesLoading = false;
131	    }
132	  }
133	
134	  async function loadChannels() {
135	    if (!orgId) return;
136	    channelsLoading = true;
137	    try {
138	      channels = await notificationService.getChannels(orgId);
139	    } catch (err) {
140	      showToast('error', err.message);
141	    } finally {
142	      channelsLoading = false;
143	    }
144	  }
145	
146	  async function loadSubscriptions() {
147	    if (!actorId) return;
148	    subscriptionsLoading = true;
149	    try {
150	      subscriptions = await notificationService.getSubscriptions(actorId);
151	    } catch (err) {
152	      showToast('error', err.message);
153	    } finally {
154	      subscriptionsLoading = false;
155	    }
156	  }
157	
158	  async function handleSubscribe() {
159	    subError = '';
160	    if (!subEventType?.trim()) {
161	      subError = 'Please select an event type.';
162	      return;
163	    }
164	    subLoading = true;
165	    try {
166	      const created = await notificationService.subscribe({
167	        userId: actorId,
168	        channelId: subChannelId || null,
169	        eventType: subEventType,
170	        organizationId: orgId,
171	        filters: {},
172	      });
173	      subscriptions = [...subscriptions, created];
174	      subEventType = '';
175	      subChannelId = '';
176	      showToast('success', 'Subscribed.');
177	    } catch (err) {
178	      subError = err.message;
179	    } finally {
180	      subLoading = false;
181	    }
182	  }
183	
184	  async function handleDeleteSubscription(id) {
185	    deletingSubId = id;
186	    try {
187	      await notificationService.deleteSubscription(id, actorId);
188	      subscriptions = subscriptions.filter((s) => s.id !== id);
189	      showToast('success', 'Subscription removed.');
190	    } catch (err) {
191	      showToast('error', err.message);
192	    } finally {
193	      deletingSubId = null;
194	    }
195	  }
196	
197	  async function handleSimulateDispatch() {
198	    simLoading = true;
199	    simResult = '';
200	    try {
201	      await eventDispatcherService.dispatch({
202	        organizationId: orgId,
203	        eventType: simEventType,
204	        sourceId: simSourceId || `sim-${Date.now()}`,
205	        actorId,
206	        title: simTitle,
207	        body: simBody,
208	        recipientUserIds: [actorId],
209	      });
210	      simResult = 'Event dispatched.';
211	      showToast('success', 'Event dispatched.');
212	    } catch (err) {
213	      simResult = err.message;
214	      showToast('error', err.message);
215	    } finally {
216	      simLoading = false;
217	    }
218	  }
219	
220	  async function switchTab(tab) {
221	    activeTab = tab;
222	    if (tab === 'inbox') await loadInbox();
223	    if (tab === 'queue') await loadQueue();
224	    if (tab === 'templates') await loadTemplates();
225	    if (tab === 'channels') await loadChannels();
226	    if (tab === 'subscriptions') await loadSubscriptions();
227	  }
228	
229	  async function markRead(notif) {
230	    markReadLoading = new Set([...markReadLoading, notif.id]);
231	    try {
232	      await notificationService.markRead(notif.id);
233	      notifications = notifications.map((n) => n.id === notif.id ? { ...n, read: true } : n);
234	    } catch (err) {
235	      showToast('error', err.message);
236	    } finally {
237	      markReadLoading = new Set([...markReadLoading].filter((id) => id !== notif.id));
238	    }
239	  }
240	
241	  function hasInvalidPlaceholders(body) {
242	    return /\{\{[^}]+\}\}/.test(body);
243	  }
244	
245	  async function handleCreateTemplate() {
246	    tplError = '';
247	    if (hasInvalidPlaceholders(tplBody)) {
248	      tplError = 'Use single braces {varName}, not double {{varName}}.';
249	      return;
250	    }
251	    tplLoading = true;
252	    try {
253	      const created = await templateService.createTemplate({
254	        organizationId: orgId,
255	        name: tplName,
256	        body: tplBody,
257	        isCompact: tplIsCompact,
258	        actorId,
259	      });
260	      templates = [...templates, created];
261	      showTemplateForm = false;
262	      tplName = '';
263	      tplBody = '';
264	      tplIsCompact = false;
265	      showToast('success', 'Template created.');
266	    } catch (err) {
267	      tplError = err.message;
268	    } finally {
269	      tplLoading = false;
270	    }
271	  }
272	
273	  async function handleDeleteTemplate(id) {
274	    deletingTemplateId = id;
275	    try {
276	      await templateService.deleteTemplate(id, actorId);
277	      templates = templates.filter((t) => t.id !== id);
278	      showToast('success', 'Template deleted.');
279	    } catch (err) {
280	      showToast('error', err.message);
281	    } finally {
282	      deletingTemplateId = null;
283	    }
284	  }
285	
286	  async function handleCreateChannel() {
287	    channelError = '';
288	    channelLoading = true;
289	    try {
290	      await notificationService.upsertChannel({ organizationId: orgId, name: channelName });
291	      await loadChannels();
292	      showChannelForm = false;
293	      channelName = '';
294	      showToast('success', 'Channel created.');
295	    } catch (err) {
296	      channelError = err.message;
297	    } finally {
298	      channelLoading = false;
299	    }
300	  }
301	
302	  function statusColor(status) {
303	    const map = {
304	      Draft: '#f1f5f9',
305	      Queued: '#dbeafe',
306	      Sent: '#dcfce7',
307	      Failed: '#fee2e2',
308	    };
309	    return map[status] ?? '#f1f5f9';
310	  }
311	
312	  function formatDate(ms) {
313	    return ms ? new Date(ms).toLocaleString() : '—';
314	  }
315	</script>
