1	/**
2	 * Component tests — Table.svelte
3	 *
4	 * Covers:
5	 *   - renders column headers
6	 *   - renders row data
7	 *   - shows empty state when no rows
8	 *   - shows loading spinner when loading=true
9	 *   - empty state hidden when loading
10	 *   - custom empty message rendered
11	 *   - sortable column header has sort button
12	 *   - non-sortable column has no button
13	 *   - clicking sort toggles sort direction
14	 */
15	
16	import { describe, it, expect } from 'vitest';
17	import { render, fireEvent } from '@testing-library/svelte';
18	import Table from '../../../src/components/Table.svelte';
19	
20	const COLUMNS = [
21	  { key: 'name',   label: 'Name',   sortable: true },
22	  { key: 'status', label: 'Status', sortable: false },
23	];
24	
25	const ROWS = [
26	  { id: '1', name: 'Alice', status: 'active' },
27	  { id: '2', name: 'Bob',   status: 'inactive' },
28	  { id: '3', name: 'Carol', status: 'active' },
29	];
30	
31	describe('Table', () => {
32	  it('renders column headers', () => {
33	    const { getByText } = render(Table, { props: { columns: COLUMNS, rows: ROWS } });
34	    expect(getByText('Name')).toBeTruthy();
35	    expect(getByText('Status')).toBeTruthy();
36	  });
37	
38	  it('renders row data for each column', () => {
39	    const { getByText } = render(Table, { props: { columns: COLUMNS, rows: ROWS } });
40	    expect(getByText('Alice')).toBeTruthy();
41	    expect(getByText('Bob')).toBeTruthy();
42	    expect(getByText('Carol')).toBeTruthy();
43	  });
44	
45	  it('shows default empty state when rows is empty', () => {
46	    const { getByText } = render(Table, { props: { columns: COLUMNS, rows: [] } });
47	    expect(getByText('No records found.')).toBeTruthy();
48	  });
49	
50	  it('shows custom empty message', () => {
51	    const { getByText } = render(Table, { props: { columns: COLUMNS, rows: [], empty: 'Nothing here yet.' } });
52	    expect(getByText('Nothing here yet.')).toBeTruthy();
53	  });
54	
55	  it('hides rows and shows spinner when loading=true', () => {
56	    const { queryByText, getByLabelText } = render(Table, {
57	      props: { columns: COLUMNS, rows: ROWS, loading: true },
58	    });
59	    expect(getByLabelText('Loading')).toBeTruthy();
60	    expect(queryByText('Alice')).toBeNull();
61	  });
62	
63	  it('does not show empty state when loading', () => {
64	    const { queryByText } = render(Table, {
65	      props: { columns: COLUMNS, rows: [], loading: true },
66	    });
67	    expect(queryByText('No records found.')).toBeNull();
68	  });
69	
70	  it('sortable column has a button', () => {
71	    const { getAllByRole } = render(Table, { props: { columns: COLUMNS, rows: ROWS } });
72	    const buttons = getAllByRole('button');
73	    // Only 'Name' column is sortable.
74	    expect(buttons.some((b) => b.textContent.includes('Name'))).toBe(true);
75	  });
76	
77	  it('non-sortable column does not have a button in its header', () => {
78	    const { queryByRole, getAllByRole } = render(Table, { props: { columns: COLUMNS, rows: ROWS } });
79	    const buttons = getAllByRole('button');
80	    // 'Status' should not be a button.
81	    expect(buttons.some((b) => b.textContent.trim() === 'Status')).toBe(false);
82	  });
83	
84	  it('clicking sort button on Name column changes aria-sort', async () => {
85	    const { getByText, getAllByRole } = render(Table, { props: { columns: COLUMNS, rows: ROWS } });
86	    const sortButton = getAllByRole('button').find((b) => b.textContent.includes('Name'));
87	    await fireEvent.click(sortButton);
88	    // After one click, should sort ascending.
89	    const nameHeader = getByText('Name', { exact: false }).closest('th');
90	    expect(nameHeader.getAttribute('aria-sort')).toBe('ascending');
91	  });
92	
93	  it('clicking sort button twice reverses direction', async () => {
94	    const { getByText, getAllByRole } = render(Table, { props: { columns: COLUMNS, rows: ROWS } });
95	    const sortButton = getAllByRole('button').find((b) => b.textContent.includes('Name'));
96	    await fireEvent.click(sortButton);
97	    await fireEvent.click(sortButton);
98	    const nameHeader = getByText('Name', { exact: false }).closest('th');
99	    expect(nameHeader.getAttribute('aria-sort')).toBe('descending');
100	  });
101	});
102	
